    "title": "蒹葭",
    "poem_notes": "【字詞與白話】\n 蒹葭：蘆葦，蒹是沒長穗的蘆，葭是初生的蘆。伊人：那個人，泛指所思慕、追尋的對象，不一定是戀人。溯洄：逆著水流往上游走。溯游：順著水流往下游走。\n 白話：蘆葦一片蒼翠，白露凝結成霜。我所思念的那個人，就在水的那一邊。逆流而上去找她，道路艱險又漫長；順流而下去找她，她卻好像就在水中央，可望而不可即。三章反覆詠唱同一件事，只換了幾個字，道路時而崎嶇時而難行，那人的身影時而在水中小洲、時而在水邊沙灘，怎麼追都追不到眼前。\n \n 【背後的小故事】\n 蒹葭出自《詩經·秦風》，作者已不可考，相傳是周代采詩官從秦地民間採集回來的歌謠。詩裡沒有寫清楚伊人到底是誰，兩千多年來有人說是戀人，也有人說是賢士或理想的象徵。三章疊詠、逆流順流都追不到的結構，把求而不得寫到了極致，你知道那個人就在那裡，你怎麼走都走不到跟前。這首沒有署名的秦地情歌，後來成了《詩經》裡最纏綿的一篇，替後世每一個追不到目標的人，先唱出了心聲。",
