    "poem_notes": "【字詞與白話】\n 澹澹：水波蕩漾的樣子。竦峙：高高聳立。幸甚至哉，歌以詠志：這是漢樂府詩固定的結尾套語，表示慶幸之意，與正文內容無直接關聯，同組其他詩篇也都用同一句收尾。\n 白話：東行來到碣石山，登高觀看蒼茫的大海。海水蕩漾起伏，山島高高聳立。島上樹木叢生，百草豐茂茁壯。秋風蕭瑟吹來，掀起洶湧的波浪。太陽和月亮的運行，好像是從這片大海裡升起；燦爛的銀河星辰，也好像是從這片大海中湧出。太幸運了，就用詩歌來抒發我的心志吧。\n \n 【背後的小故事】\n 建安十二年，曹操遠征烏桓，大軍走祕密小路穿越缺水沙漠，一度糧盡水絕，是他軍事生涯中最兇險的一戰之一。凱旋歸來途經碣石山，他登山望海，這是他生平少見大海的一次經歷。眼前浩瀚的海景讓他忽然覺得自己半生打下的地盤都變得渺小，胸中的野心卻反而被撐得更大。詩眼是打完最狠一仗後見到大海，野心不減反增的那種震撼。",
