    "poem_notes": "【字詞與白話】\n 全詩較長（32句），節錄關鍵句意。杜康：借指酒。全詩寫於赤壁之戰前夕、曹操橫槊賦詩的宴席上。\n 白話：對著酒應當高歌，人生能有多長？就像早晨的露水，逝去的日子已經很多。慷慨激昂，心中憂思難忘，靠什麼來解憂？只有靠酒。渴望賢才，如渴望戀人般深切。只要有賓客來投奔，我會像周公一樣，吃飯時多次吐出口中食物去接待，只求天下人心歸附。\n \n 【背後的小故事】\n 這首詩寫於赤壁之戰前夕，曹操率八十萬大軍南下，在戰船上設宴，喝醉後手持長矛，對著長江即興朗誦此詩，史稱「橫槊賦詩」。當時他五十四歲，北方已統一，正躊躇滿志——但詩的第一句想的卻是「人生能有多少時間」。他用《詩經》情詩比喻自己求才若渴，又以周公吐哺自比，公開向部下招賢。宴席上全場歡呼，但沒多久赤壁一戰曹操慘敗，從此再也沒能統一天下——那一夜的豪情，成了他一生最大挫敗前的絕響。",
