    "title": "三五七言-秋風詞",
    "poem_notes": "【字詞與白話】\n 三五七言：指這首詩由三言、五言、七言句式混合組成的雜言體，是詩題也是體裁名。難為情：此處指難以承受這樣的心情，不是現代口語的害羞之意。\n 白話：秋風清爽，秋月明亮，落葉聚了又散，寒鴉棲息又被驚起。彼此相思，卻不知何時才能再相見，此時此刻，這樣的夜晚實在讓人難以承受。一旦踏入這相思的門，就明白這相思有多苦。長久的相思啊，長久的思念；短暫的相思啊，也沒有盡頭。早知道相思這麼折磨人心，不如當初就別認識。\n \n 【背後的小故事】\n 這首詩雖然掛在李白名下傳唱千年，但學者對它是否真為李白親筆其實一直有爭議，最早的版本出現得相當晚。姑且依相傳的說法，想像那是一個秋夜，太白想起一個很久沒見的人，把相思寫得直白坦蕩，沒有拐彎抹角。結尾早知如此絆人心、何如當初莫相識不是後悔認識對方，而是相思太重，重到讓人願意用沒認識過去換一個不痛的自己，這份重量，不管是不是太白親手寫下的，都騙不了人。",
