    "title": "長歌行",
    "poem_notes": "【字詞與白話】\n 焜黃：形容草木枯黃的樣子。「少壯不努力，老大徒傷悲」是全詩最廣為流傳的警句。\n 白話：園中葵菜一片青翠，清晨的露水等待陽光照耀曬乾。春天散布著恩澤，讓萬物都生機蓬勃、閃耀光輝。常常擔心秋天一到，草木花葉就會枯黃衰敗。千百條河川向東流入大海，何時才能再往西流回來呢？年少力壯時不努力，等到年老只能白白傷心悲嘆。\n \n 【背後的小故事】\n 這首漢代樂府詩沒有留下作者姓名，相傳是漢代採詩官從民間歌謠中採集記錄下來的。詩中描寫的是尋常人家教導孩子的畫面——母親指著葵葉上的朝露，告訴孩子陽光一出來露水就會消失；到了秋天，又拔起枯黃的葉子讓孩子明白萬物盛衰的道理。詩中的「少壯」不是特定的某個人，而是每一個曾經聽過長輩叮嚀、卻要等到自己也老去時才真正聽懂的孩子。兩千年來，這首無名者寫下的歌謠，仍在提醒每一個看見朝露的人：珍惜當下的年輕歲月。",
