    "poem_notes": "【字詞與白話】\n 心遠地自偏：只要內心超脫，所居之地自然顯得僻靜。「悠然見南山」的「見」字是全詩關鍵，是不經意瞥見，而非刻意眺望。\n 白話：把房子蓋在人來人往之地，卻聽不到車馬的喧鬧。問我怎麼能做到？只要內心遠離俗世，所處之地自然變得僻靜。在東籬下採菊，悠然間看見南山。山中氣象在傍晚時分格外美好，飛鳥結伴歸巢。這裡面有真正的意趣，想要說清楚，卻已經忘了該怎麼表達。\n \n 【背後的小故事】\n 陶淵明四十一歲時當彭澤縣令僅八十多天，因不願「為五斗米折腰」向上級卑躬屈膝，當天辭官返鄉，從此不再出仕。這首詩寫於他辭官後、生活其實相當清苦的一段日子。那天他到院子東邊籬笆採菊準備泡酒，直起腰時無意間望見遠方的南山——不是刻意眺望，是南山自己撞進了他的視線。他心裡湧起說不清的感悟，張口卻忘了該怎麼講。「悠然見南山」教會後世的不是歸隱，是不刻意追求時，美好反而會自己撞上門來。",
