    "poem_notes": "【字詞與白話】\n 三珠樹：傳說中的珍貴神木，此處比喻朝中顯貴的高位。金丸：彈弓用的金屬彈丸，古人常用彈弓打鳥，此處比喻暗中傷人的手段。冥冥：遼遠幽深之處，指遠離是非之地。\n 白話：一隻孤鴻從海上飛來，連水塘邊都不敢靠近停留。牠側頭看見兩隻翠鳥，把巢築在珍貴的三珠樹梢。高高在上、姿態顯眼的鳥啊，難道不怕金彈丸射來嗎？穿著華美的衣服容易招人指點，站得太高太耀眼也會招來嫉恨。如今我遠飛到幽遠之處，打鳥的獵人還羨慕得到什麼呢？\n \n 【背後的小故事】\n 張九齡是開元名相，曾當面提醒唐玄宗，安祿山面有反相、將來必成禍患，玄宗沒有採納，二十年後安史之亂爆發，應驗了他的警告。開元二十四年，他被李林甫排擠罷相，貶為荊州長史。這首詩就寫於那段時期，他把自己比作遠飛避禍的孤鴻，把得勢的政敵比作築巢在高處、渾然不覺危險的翠鳥，爬得越高，越靠近能打下你的弓箭。這封沒有收件人的警告信，可惜當時沒人聽懂。",
