    "poem_notes": "【字詞與白話】\n 葳蕤：草木茂盛、枝葉繁密下垂的樣子。坐相悅：因此而心生喜愛，坐在此處作因而解，不是坐下的意思。本心：草木與生俱來的天性，此處喻指人不求回報的本性。\n 白話：蘭花的葉子在春天長得繁茂，桂花在秋天顯得潔白芬芳。這樣欣欣向榮的生機，自然而然就成就了各自的好時節。誰知道住在山林裡的人，聞到香氣因而心生喜愛。草木原本就有自己的天性，何嘗是為了讓美人來採折呢？\n \n 【背後的小故事】\n 張九齡的家鄉廣東韶州曲江，山裡自古就長著蘭桂，是他從小看慣的景色。被李林甫排擠出朝廷、貶為荊州長史之後，他把這些家鄉常見的花草種進院子裡。他終於想通，朝堂上的賞識跟山裡的蘭花完全是兩回事，蘭花開得好，不是為了等誰來摘，是它自己活該這樣開。這首詩把清高寫成了具體的畫面，草木從不討好誰，人也可以不必看誰的臉色，活出自己的好時節。",
    "zhuyin": "葳蕤(ㄨㄟ ㄖㄨㄟˊ)(wēi ruí)發音同\"威蕤\"，：繁花盛開下垂的樣子。《說文解字．艸部》：「蕤，艸木花垂貌。」",
    "rating": 4,
