    "poem_notes": "【字詞與白話】\n 丹橘：紅色的橘子，江南特產。豈伊：哪裡是，難道是。歲寒心：耐得住寒冬的心志，語出松柏耐寒的傳統比喻，這裡用在橘樹身上。薦：進獻、呈上。阻重深：被層層山水阻隔，又深又重。循環不可尋：命運像循環一樣轉來轉去，說不清規律。\n 白話：江南有一種紅橘，經過整個冬天照樣是一片綠，難道是因為那裡氣候暖和嗎，其實是它自己本來就有耐得住寒冬的心志。這麼好的果子，本可以拿去獻給尊貴的客人，可惜山水層層阻隔，送不出去。命運不過是碰上了什麼人和時候，一圈一圈轉，怎麼想也想不透。人人只顧著誇讚桃樹李樹好看又好吃，卻沒想過，這棵橘樹難道就沒有一片樹蔭可以遮人嗎。\n \n 【背後的小故事】\n 張九齡是開元年間有名的賢相，以敢言直諫著稱。相傳安祿山曾因違反軍令論罪當斬，張九齡堅持要處死他以除後患，玄宗卻赦免了他。後來張九齡被李林甫排擠出朝，貶到荊州，寫下感遇十二首寄託心志，這是其中一首。多年後安祿山果然起兵反叛，釀成安史之亂，徹底改變了大唐的命運。這棵在寒冬裡依然翠綠的丹橘，寫的既是他自己不改的節操，也悄悄藏著一句沒能被聽進去的忠告。",
