    "title": "下終南山過斛斯山人宿置酒",
    "poem_notes": "【字詞與白話】\n 忘機：忘卻算計、心機，是全詩最關鍵的兩個字。斛斯山人是複姓斛斯的一位普通山民，生平不詳。\n 白話：傍晚從青翠的山頭下來，山月一路跟隨我回家。回頭望向來時的山路，蒼翠一片橫在山腰。和朋友一起走到他的田家，孩童跑出來打開柴門。綠竹夾著幽深小徑，藤蘿輕拂我的衣裳。歡談中得到歇息之處，美酒與友人一同暢飲。放聲歌唱，和著松風，一曲唱完，銀河的星星都已稀疏。我醉了，你也開心，兩人陶然忘卻了一切算計。\n \n 【背後的小故事】\n 李白在長安當翰林待詔時，本以為能一展抱負，卻只被當成宮廷裡寫詩助興的角色，處處碰壁。他跑到終南山散心，某個傍晚下山，遇到一位普通山民朋友斛斯山人，被熱情邀去家中作客。院子裡有孩子開門迎接，主人端出自釀濁酒，兩人一路喝到星稀天將亮。這一夜的李白很收斂，沒有「將進酒」式的狂放，只是安靜地與朋友喝酒、唱歌、聽風——沒多久他就被賜金放還離開長安，這個平凡溫暖的夜晚，是他在浮華宮廷生活裡難得卸下心防的片刻。",
    "zhuyin": "荊(ㄐㄧㄥ)(jīng)發音同\"經\"，扉(ㄈㄟ)(fēi)發音同\"飛\"，：柴門。\n 蘿(ㄌㄨㄛˊ)(luó)發音同\"羅\"，\n 憩(ㄑㄧˋ)(qì)發音同\"氣\"，休息。",
