    "title": "月下獨酌",
    "poem_notes": "【字詞與白話】\n 無情遊：不涉及世俗情感糾葛的交往，指月亮與影子不會背叛、不會嘲笑他。全詩寫於李白在長安任翰林待詔、實則孤立無援的時期。\n 白話：花叢間擺一壺酒，獨自斟酌，沒有人陪伴。舉起酒杯邀請明月，加上自己的影子，正好湊成三人。月亮不懂得喝酒，影子也只是徒然跟著我。暫且伴著月與影子，及時行樂要趁著春光。我唱歌時月亮徘徊不去，我起舞時影子隨之零亂。清醒時我們一同歡樂，醉了以後各自分散。願與他們結下這段不涉俗情的交遊，來日相約在遙遠的雲河之上。\n \n 【背後的小故事】\n 李白在長安當翰林待詔期間，表面風光，實際上跟宮廷派系格格不入，得罪了不少掌權者，有名氣卻沒有真正的朋友。某個春夜，他在花園獨自擺酒，舉杯邀月、對影成三人，唱歌跳舞，自己陪自己玩了一整晚。這首詩流傳千年最動人的地方，不是「舉杯邀明月」有多浪漫，而是揭穿了一個秘密——最豪放的人，往往也最孤獨。那個號稱斗酒詩百篇的李白，心裡最深處，也曾只是一個人在夜裡跟自己的影子跳舞。",
    "zhuyin": "酌(ㄓㄨㄛˊ)(zhuó)發音同\"琢\"，：斟酒、飲酒。\n 邈(ㄇㄧㄠˇ)(miǎo)發音同\"秒\"，：凌駕。\n 雲漢：天河。",
