    "poem_notes": "【字詞與白話】\n 燕草：燕地（今河北北方）的春草，因氣候偏寒，發芽較晚。秦桑：秦地（今陝西一帶）的桑樹，氣候較暖，枝葉已茂密。羅幃：絲織的帳幔，古代女子閨房常用來遮擋床榻。\n 白話：燕地的春草才剛長得像碧綠的細絲，秦地的桑樹枝葉已經茂密得垂低了枝條。當你終於想起該回家的那一天，正是我斷腸思念到了極點的時候。春風跟我素不相識，為什麼要闖進我的絲帳裡來呢？\n \n 【背後的小故事】\n 這是李白假借一位秦地女子的口吻寫的閨怨詩，丈夫遠在燕地當兵，兩人相隔幾千里。他替她算了一筆時差，燕地天冷春天來得晚，秦地已經桑葉低垂。同樣是想家，對方的季節永遠慢半拍，連思念都要等他先想起來。李白自己這輩子也四處漂泊，家裡人沒少等過他，或許正因為如此，他才寫得出春風不相識、何事入羅幃這種又氣又酸的委屈，連風都是外人，卻比人先闖進她的房間。",
