    "title": "關山月",
    "poem_notes": "【字詞與白話】\n 戍客：駐守邊疆的士兵。這首詩沿用樂府舊題「關山月」，寫的是李白想像中戍邊士兵與家中妻子隔著同一輪明月的思念。\n 白話：一輪明月從天山後升起，穿行在蒼茫的雲海之間。長風吹拂幾萬里，一路吹過玉門關。這裡自古是漢朝與匈奴征戰之地，白登、青海灣都曾烽火連天。自古以來的征戰之地，很少見到有人活著回來。戍守邊關的士兵望著邊塞的景色，思念故鄉，滿臉盡是愁苦之色。今夜家鄉的高樓上，妻子也對著同一輪明月，嘆息聲久久不曾停歇。\n \n 【背後的小故事】\n 李白從未親自到過玉門關以西，這首詩是他在長安一場宴席上，聽樂師演唱舊題〈關山月〉後，憑著史書記載與老兵口中的邊塞見聞，在腦海中搭建出的戰場景象。寫到一半，他忽然想起自己二十五歲離開四川後就再也沒回去過，某種程度上也是另一種「不見有人還」的人——只是他打的不是戰爭，而是自己的抱負與名聲。他把戍卒的思鄉之苦與妻子深夜的嘆息一併寫下，替那些沒有機會發聲的邊塞士兵與思婦，留下了這段千古共鳴的夜晚。",
    "zhuyin": "戍(ㄕㄨˋ)(shù)發音同\"樹\"，守衛的人。",
