    "title": "子夜四時歌(春歌)",
    "poem_notes": "【字詞與白話】\n 秦地：指長安一帶的關中地區。羅敷：漢樂府陌上桑裡的採桑女，以美貌與機智拒絕太守搭訕聞名，李白借用這個名字重寫故事。素手：形容手白皙乾淨。五馬：太守級官員的車駕以五匹馬拉車，這裡代指路過搭訕的權貴。留連：逗留、耽誤。\n 白話：秦地有個採桑女子叫羅敷，在綠水邊採著桑葉。她白皙的手伸進青綠的桑條裡，身上那件紅妝在陽光下格外鮮亮。家裡的蠶餓著等她回去餵食，她想要離開了，那位五馬顯貴的大人，就別再耽誤她了。\n \n 【背後的小故事】\n 李白這首春歌改寫自漢代樂府陌上桑的故事框架，原本的羅敷面對太守搭訕，靠著誇讚丈夫的機智把對方擋走，李白這個版本更直接，讓羅敷用蠶要吃飯這件瑣事，乾脆利落地拒絕權貴的糾纏。李白本人終其一生都以不肯向權貴低頭聞名，曾在長安拂袖離開權貴的宴席，也寫過安能摧眉折腰事權貴這樣的名句。重寫這個古老的採桑女故事，某種程度上也是他借別人的口，說出自己心裡一直沒改變過的那份硬氣。",
    "zhuyin": "羅敷(ㄌㄨㄛˊ ㄈㄨ)(luó fū)發音同\"羅夫\"，人名。戰國時趙王家令王仁妻。邯鄲人，姓秦，採桑陌上，使君見而悅之，欲奪為妾，羅敷彈箏作陌上桑以自明。後比喻貌美而貞潔的女子。",
