    "poem_notes": "【字詞與白話】\n 鏡湖：今浙江紹興的鑑湖。菡萏：荷花的別稱，指還沒完全開放的花苞。若耶：若耶溪，傳說西施浣紗的地方。隘：狹窄、擁擠到堵住的意思。越王家：指越國宮廷，這裡暗指她被選入宮中準備獻給吳國的命運。\n 白話：鏡湖方圓三百里，荷花開得滿湖都是。五月裡西施下水採荷，岸上看她的人擠得把若耶溪兩岸都堵住了。她划著船不等月亮升起，就急急忙忙回到越王的宮裡去了。\n \n 【背後的小故事】\n 相傳西施本是若耶溪邊的浣紗女，因為容貌出眾被范蠡發現，帶回越國宮中訓練禮儀歌舞，準備送給吳王夫差當作削弱吳國的美人計，這段故事流傳千年，細節多屬傳說，史料難以完全印證。李白這首夏歌只寫到她划船回宮的那個黃昏就收筆，沒有多說一句後來的事，但讀者只要知道西施的結局，就會明白這趟看似平常的歸家路，其實是她告別自己、走向另一種身分的起點。",
