    "author": "李白",
    "title": "子夜四時歌(秋歌)",
    "poem_notes": "【字詞與白話】\n 良人：古代妻子對丈夫的敬稱。擣衣：把布料放在石頭上以木杵搗打使其柔軟，再縫製寒衣寄給遠征的丈夫，是唐代婦女每年秋天的集體勞動。\n 白話：長安城籠罩在一片月光下，家家戶戶傳來搗衣的聲音。秋風怎麼吹也吹不散，那總是牽掛玉門關外征人的心情。什麼時候才能平定胡虜，讓丈夫結束遠征歸來。\n \n 【背後的小故事】\n 這首詩寫的不是李白自己，而是長安城裡千千萬萬等待丈夫從邊疆歸來的女人。某個秋夜，李白走在長安巷弄間，聽見一整片街坊此起彼落的搗衣聲——那是女人們為遠征丈夫縫製寒衣的聲音。他抬頭看見滿城月光，忽然明白秋風怎麼吹也吹不散這些思念。全詩沒有一句華麗辭藻，也沒有反戰口號，只是老實寫下一個等待丈夫的女人心裡的話。向來寫豪情壯志的李白，這次把筆借給了千萬個沉默的女性，問了一句：這一切到底是為了什麼。",
    "zhuyin": "胡虜(ㄏㄨˊ ㄌㄨˇ)(hú lǔ)發音同\"湖魯\"，北方異族，對敵人輕蔑的稱呼。",
