    "id": 19,
    "dynasty": "盛唐",
    "type": "五言古詩",
    "author": "李白",
    "title": "俠客行",
    "poem_notes": "【字詞與白話】\n 信陵君、朱亥、侯嬴：戰國時期魏國信陵君門下的義士，朱亥揮鎚擊殺魏將晉鄙、奪兵救趙的故事出自《史記》。全詩是李白年輕時讀史記有感而發之作。\n 白話：趙國的俠客頭戴縵胡冠纓，腰間吳鉤劍寒光如霜雪般明亮。銀鞍照映著白馬，馳騁而過快如流星。十步之內就能取人性命，行走千里也不留痕跡。事情辦完便拂衣離去，深深隱藏自己的姓名與功勞。閒時到信陵君家中飲酒，解下佩劍橫放在膝前。接過烤肉大口分給朱亥，舉起酒杯勸侯嬴同飲。三杯酒下肚，一諾千金的承諾說出口，五嶽都顯得輕如鴻毛。酒酣耳熱之後，豪邁的意氣直沖雲霄。揮動鐵鎚拯救趙國，邯鄲城為之震動。這兩位壯士名留千秋，聲威顯赫於大梁城。即使犧牲，俠義之骨依然留香，絲毫不遜色於世間的英雄豪傑。又有誰願意皓首窮經、埋首在書閣裡，寫一輩子沒人看的《太玄經》呢？\n \n 【背後的小故事】\n 李白二十多歲尚未進入長安、還未成名時，某個雨夜在洛陽旅館讀《史記·信陵君列傳》，讀到朱亥揮鎚擊殺晉鄙、助信陵君奪兵救趙的段落，激動得拔劍起舞。他把自己想像成宴席上那個與朱亥同席、替侯嬴斟酒的俠客，一氣呵成寫下這首詩，末尾更以終生埋首書齋、寫《太玄經》的揚雄作對比，直言自己嚮往的不是皓首窮經的功名，而是俠義救國的快意人生。這首詩寫於他人生尚未展開之前，卻預告了他一輩子渴望建功立業、任俠尚義的精神底色。",
    "zhuyin": "縵(ㄇㄢˋ)(màn)發音同\"慢\"，沒有花紋圖案的絲綢。\n 纓(ㄧㄥ)(yīng)發音同\"英\"，繫帽子的帶子，泛指綵帶、裝飾性的穗子（如紅纓）\n 颯(ㄙㄚˋ)(sà)發音同\"薩\"，風聲、疾速。\n 沓(ㄊㄚˋ)(tà)發音同\"踏\"，眾多、繁雜。\n 颯沓-眾多而盛大、群集飛翔或疾風的樣子。\n 炙(ㄓˋ)(zhì)發音同\"志\"，烤肉。\n 啖(ㄉㄢˋ)(dàn)發音同\"但\"，吃、拿食物給人吃。\n 亥(ㄏㄞˋ)(hài)發音同\"害\"，朱亥-人名，戰國時期魏國勇士。\n 觴(ㄕㄤ)(shāng)發音同\"商\"，古代的酒杯。\n 邯(ㄏㄢˊ)(hán)發音同\"寒\"，鄲(ㄉㄢ)(dān)發音同\"單\"，邯鄲-地名，位於中國河北省西南部。\n 烜(ㄒㄩㄢˇ)(xuān)發音同\"選\"，赫(ㄏㄜˋ)(hè)發音同\"賀\"，烜赫-形容名聲、威望或權勢極大。今常用顯赫。",
