    "id": 20,
    "dynasty": "盛唐",
    "type": "五言古詩",
    "author": "李白",
    "title": "長干行",
    "poem_notes": "【字詞與白話】\n 遶床弄青梅：遶同繞，床指的是庭院裡的井欄，不是睡覺的床；弄青梅指男孩拿著青梅逗鬧。抱柱信：典出《莊子》，尾生與女子約在橋下，女子未到而水漲，尾生守信抱橋柱溺死，喻堅守承諾。灩澦堆：長江瞿塘峽口的險惡暗礁。\n 白話：我的頭髮剛蓋過額頭時，常在門前折花玩耍；你騎著竹竿當馬跑來，繞著井欄丟青梅逗我。我們一起在長干里長大，兩小無猜從沒起過嫌隙。十四歲嫁給你，羞得從沒展開過眉頭，低頭對著牆壁，喚我千次也不回一次頭。十五歲才漸漸敞開心，發誓與你化成同一捧塵土，像尾生抱柱那樣守信，哪裡會想到有一天要爬上望夫臺張望。十六歲你遠行經商，要過瞿塘峽凶險的灩澦堆，五月水漲根本不能靠近，猿猴在兩岸哀啼。你出門時留下的腳印，如今一個個都長滿了青苔，青苔太深掃不動，秋風一起落葉比往年更早。八月蝴蝶雙雙飛進西邊的園子，看著牠們成雙，我心裡難過，容顏都要在等待裡老去。你不管什麼時候要下三巴回來，提前寫封信告訴我，我一定去接你，哪怕遠到長風沙，我都去。\n \n 【背後的小故事】\n 青梅竹馬這個成語就出自這首詩，但成語背後其實是一個女人從兩小無猜到獨守空閨的完整人生。長干里是金陵城外商人聚居的街坊，李白假借一位商婦的口吻，寫她從折花嬉戲的童年、羞怯的新婚，到丈夫遠行經商、天天數著門前青苔有多深的等待。你以為青梅竹馬是甜蜜的開頭，其實這首詩寫的是甜蜜之後，綿長到讓人心焦的漫長等待。",
    "zhuyin": "瞿塘(ㄑㄩ ㄊㄤˊ)(qú táng)發音同\"區唐\"，地名。位於四川省奉節縣東的白帝城，至巫山縣的黛溪鎮，長約八公里，為長江三峽之一。兩岸岩壁高峙，江水怒激，峽口灩澦堆，矗立江心，形勢險惡，為全蜀江路的門戶。也稱為「廣溪峽」、「夔峽」。\n 灩澦堆(ㄧㄢˋ ㄩˋ ㄉㄨㄟ)(yàn yù duī)發音同\"驗育堆\"，地名。在四川省奉節縣東十里瞿塘峽口。巉崖矗立江中，堆旁水勢湍急，湍成漩渦，往往為舟行之患。也稱為「英武石」。",
    "rating": 4,
