    "type": "五言古詩",
    "author": "李白",
    "title": "妾薄命",
    "poem_notes": "【字詞與白話】\n 阿嬌：漢武帝劉徹的表姐，第一任皇后陳氏的小名。金屋：典出金屋藏嬌，劉徹幼時許諾要蓋金屋子安置阿嬌。長門：陳皇后被廢後幽居的長門宮。\n 白話：漢武帝曾經寵愛阿嬌，把她安置在金屋子裡。她咳嗽吐痰，旁人都覺得像珠玉從天上灑落，隨風而生。可是恩寵到了極點就會消退，妒忌太深，情意也就漸漸疏遠了。長門宮明明只隔一步之遙，他卻不肯把車駕暫時往那個方向轉一轉。雨落下來不會再飛回天上，水潑出去也難以再收回。你的情意和我的心意，終究像水一樣，各自往東往西流去了。昔日盛開的芙蓉花，如今成了斷根的枯草。單靠美色去侍奉他人，能得到幾時的好日子呢？\n \n 【背後的小故事】\n 金屋藏嬌是眾所皆知的甜蜜故事，大家卻很少記得後半段，陳阿嬌後來失寵，被廢入長門宮，終生沒能再見漢武帝一面。李白借這段舊事寫下這首詩，有人認為他寫的不只是阿嬌，也是他自己，當年他被召入長安，玄宗降階相迎，命他當翰林待詔，風光一時，可是沒幾年就因權貴排擠被賜金放還。曾經被捧到最高處，轉眼被放棄，恩寵和才氣一樣，說斷就斷。",
    "zhuyin": "貯(ㄓㄨˇ)(zhù)發音同\"主\"，積藏、儲蓄。\n 咳唾(ㄎㄜˊ ㄊㄨㄛˋ)(hāi tuò)發音同\"殼脫\"，咳嗽而噴吐唾液。稱讚對方的言論、談吐。\n 妒(ㄉㄨˋ)(dù)發音同\"度\"，因別人勝過自己而內心忌恨。",
