    "author": "杜甫",
    "title": "望嶽",
    "poem_notes": "【字詞與白話】\n 岱宗：泰山的別稱。「會當凌絕頂，一覽眾山小」是杜甫青年時期豪情壯志的宣言，與他晚年詩作的沉鬱風格形成強烈對比。\n 白話：五嶽之首的泰山究竟是什麼樣子呢？齊魯大地上，那一片青翠延綿不絕。天地造化將神奇秀麗都聚集在這裡，山的南北兩側彷彿把黃昏與拂曉分割開來。層層雲氣升騰，盪滌著我的胸懷；極目遠望，歸巢的飛鳥正好映入眼底。終有一天我要登上泰山的最高峰，俯瞰四周所有的山巒，都變得渺小。\n \n 【背後的小故事】\n 這首詩寫於杜甫二十四歲科舉落第後，他並未因此氣餒，反而與朋友在齊魯大地騎馬打獵、寫詩飲酒，過了幾年逍遙日子。一次與友人望見泰山，朋友問他將來的志向，他望著山頂立下豪語：將來一定要登上絕頂，俯瞰群山變小。這是杜甫詩作中少見的意氣風發之作，與他晚年顛沛流離、憂國憂民的沉鬱詩風截然不同。三十年後他在江上寫下「天地一沙鷗」時，或許早已忘了齊魯那個豪情萬丈的午後，但那個相信自己終將登頂的青年杜甫，千百年來一直在泰山腳下，替每個仰望高山的年輕人撐住那股志氣。",
    "zhuyin": "眥(ㄗˋ)(zì)發音同\"自\"，：眼眶。\n 決眥：張開眼睛。",
