    "title": "佳人",
    "poem_notes": "【字詞與白話】\n 合昏：合歡樹，又稱夜合花，傳說葉子晚上會閉合。「在山泉水清，出山泉水濁」是全詩最富哲理的一句，以泉水比喻堅守與變節的分別。\n 白話：有位絕世佳人，獨自隱居在空寂的山谷。她說自己本是良家子女，如今流落到只能依傍草木為生。當年關中戰亂，兄弟們慘遭殺害，官職再高也無濟於事，連骨肉的屍骨都無法收回。世情總是厭棄衰敗的人，萬事就像風中搖曳的燭火般無常。丈夫是個輕薄之人，已經另娶了美如玉的新人。合歡花尚且懂得依時開合，鴛鴦也不會單獨棲宿，可他卻只看得見新人的歡笑，哪裡聽得見舊人的哭聲。泉水留在山裡是清澈的，一旦流出山外便渾濁了。侍女賣掉珠寶回來，只能牽起藤蘿修補茅屋。她摘了花卻不插上髮髻，採了滿把的柏葉。天氣寒冷，翠色的衣袖顯得單薄，日暮時分，她只能倚靠著修長的竹子。\n \n 【背後的小故事】\n 杜甫辭官帶著家人逃難至秦州途中，在山谷外遇見一位獨居的女子，得知她出身良家，兄弟死於戰亂，丈夫又嫌棄她家道中落而另娶新人，只能帶著一名侍婢隱居山谷、靠變賣首飾維生。杜甫望著她在寒風中倚竹佇立的身影，看見的其實也是自己——同樣出身尚可的家庭，同樣因為時局而落魄逃難。他把她的遭遇寫成詩，那句「在山泉水清，出山泉水濁」既是寫她堅守自身的清白，也是杜甫對自己選擇留在困境中、不隨波逐流的自我期許。",
