    "title": "夢李白二首之一",
    "poem_notes": "【字詞與白話】\n 逐客：被放逐的人，這裡指李白被流放夜郎。羅網：比喻官司牢籠，指李白當時因永王案下獄受審。蛟龍：傳說中水中的凶猛異獸，這裡用來擔憂李白路途遇險。\n 白話：死別已經讓人哭到說不出話，活著的分離更是常常令人傷心悲惻。江南是瘴癘瀰漫之地，被流放的人卻連消息都傳不出來。故人走進我的夢裡，可見他也明白我天天在想念他。你如今應困在官司羅網裡，怎麼可能長出翅膀飛來見我？恐怕這不是你活著的魂魄，路途太過遙遠，難以測知真假。魂魄來時，楓林還是青綠的；魂魄歸去時，關塞已是一片昏黑。月光灑滿了屋梁，恍惚間彷彿還照著你的容顏。水深浪闊，千萬別讓蛟龍把人加害了。\n \n 【背後的小故事】\n 安史之亂中，李白因牽連永王李璘謀反案下獄，後被判流放夜郎，生死不明，消息斷斷續續傳到流落秦州的杜甫耳中。兩人十幾年前曾在梁宋一帶策馬同遊、情同兄弟，此後天各一方。杜甫憂心如焚，連夜夢見李白，卻分不清夢中人是活著的老友還是他的魂魄，忍不住在夢裡發問。詩眼是分不清生死卻還是忍不住惦念詢問的深厚情誼。",
    "zhuyin": "瘴癘(ㄓㄤˋ ㄌㄧˋ)(zhàng lì)發音同\"丈力\"，：接觸到山林間溼熱蒸發毒氣所生的疾病。",
