    "id": 26,
    "dynasty": "盛唐",
    "type": "五言古詩",
    "author": "杜甫",
    "title": "夢李白二首之二",
    "poem_notes": "【字詞與白話】\n 局促：匆忙不安的樣子。這首詩寫於杜甫誤傳李白已死於流放途中之時，連續三夜夢見李白而寫下的悼念之作。\n 白話：浮雲整天飄行不定，遠遊的人卻久久沒有音訊。連續三夜頻頻夢見你，可見你我情誼深厚。夢中你告別時總是神色匆忙，一再訴說著來一趟多麼不容易。江湖上風波險惡，深怕船隻會翻覆沉沒。你出門時搔著滿頭白髮，彷彿辜負了平生的志向。京城裡到處是達官貴人的車馬冠蓋，唯獨你一個人憔悴落魄。誰說天網恢恢、疏而不漏？你都要老了，反而還被牽連拖累。就算將來留下千秋萬世的名聲，那也只是你死後才有的寂寞之事了。\n \n 【背後的小故事】\n 李白因牽連永王之亂被判流放夜郎，音訊斷絕，杜甫在秦州聽聞傳言，誤以為好友已死於流放途中，接連三夜夢見李白，夢中李白總是行色匆匆、搔首告別，訴說路途艱險、江上風浪凶險。杜甫醒來看著天邊浮雲飄過，想起長安城裡達官貴人車馬雲集，唯獨才華橫溢的李白流落天涯、憔悴不堪，忍不住寫下這首詩，替他提前辦了一場心裡的告別。事實上，李白當時已在白帝城遇赦，正順江東下、意氣風發地寫著〈下江陵〉，只是消息還沒傳到偏遠的秦州——這首詩，成了兩位大詩人友情最深刻的見證。",
    "zhuyin": "楫(ㄐㄧˊ)(jí)發音同\"及\"，：行船划水用的槳。如：「舟楫」。",
