    "poem_notes": "【字詞與白話】\n 何所之：之是動詞「去、往」，問你要去哪裡。不得意：不是隨口的謙虛話，是仕途或心事上真正的失意、不順遂。南山陲：終南山邊緣一帶，唐人常在此隱居。\n 白話：翻身下馬，陪你喝一杯送行酒，問你這是要去哪裡。你說自己並不得意，準備回終南山邊歸隱度日。你這一去，我不再多問，因為那片白雲，什麼時候去看都在，沒有窮盡的一天。\n \n 【背後的小故事】\n 王維自己曾因屬下舞獅子出錯被連坐貶到濟州當司倉參軍，一貶就是四五年，深知仕途失意的滋味。多年後在輞川，一位不得志的朋友前來辭行，要回終南山隱居。王維沒有多問失意的原因，也沒有出言安慰，那些場面話他年輕時聽過太多，早就知道沒有用。他只是遞上一杯酒，說你去吧，白雲無盡時。不追問、不阻攔，由著朋友去過自己選的日子，這份剋制，其實是他能給的最深的尊重。",
