    "title": "送綦毋潛落第還鄉",
    "poem_notes": "【字詞與白話】\n 聖代：指政治清明的當代，是說給落第朋友聽的鼓勵話。東山客、採薇：借用典故指隱居不出的人。金門：指朝廷、宮廷。吾謀適不用：我的計策、才能剛好沒被用上，不是能力不夠。\n \n 白話：清明的時代不會留下隱士，有才華的人最終都會被朝廷收用。所以像你這樣本該隱居山林的人，也不必再堅持隱居了。可是這次到了朝廷卻與功名擦身而過，誰能說是你的方向錯了呢。你在江淮一帶過了寒食節，又在京城趕著縫好春天的衣裳。我在長安路邊擺酒送你，偏偏這次我們的心願都沒能實現。你即將乘船南歸，不久就能推開家鄉的門。遠處的樹伴著你這位遠行的旅人，孤城正對著落日餘暉。這次計謀沒有被用上，不要以為懂你的人很少。\n \n 【背後的小故事】\n 王維年輕時曾因宮廷舞黃獅子事件牽連被貶到濟州當小官，親身嚐過懷才不遇的滋味。這首詩相傳寫於他送別落第友人綦毋潛還鄉的那次餞別，他沒有說空泛的安慰話，而是用自己也曾被貶謫的經歷，告訴朋友這次沒被用上不代表沒有知音。這種同病相憐的真誠，讓這首送別詩讀來格外厚實。",
    "zhuyin": "孰(ㄕㄨˊ)(shú)發音同\"淑\"，：成熟。熟的本字。\n 棹(ㄓㄠˋ)(zhào)發音同\"照\"，：船槳",
