    "author": "王維",
    "title": "青谿",
    "poem_notes": "【字詞與白話】\n 黃花川、青谿：陝西境內的地名，青谿是黃花川附近的一條溪流。逐：順著、跟隨。萬轉：形容溪水隨山勢彎曲極多。澹：水面平靜的樣子。盤石：大而平的石頭，可供人坐臥。已矣：算了、就這樣吧，這裡表示打定主意不再他求。\n 白話：沿著黃花川往前走，一路跟著青谿的水。溪水隨著山勢彎彎繞繞，走不到百里路。水聲在亂石堆裡喧鬧，顏色流進深深的松林裡卻很沉靜。水面上漂著菱角荇菜，清澄的水映著蘆葦。我的心早已很平靜，眼前這條清澄的溪水正好如此。就讓我留在這塊大石頭上垂釣吧，這樣就足夠了。\n \n 【背後的小故事】\n 相傳周朝開國功臣姜太公早年隱居磻溪，用直鉤垂釣，並非真想釣魚，而是等待周文王路過發現他的才華，後來果然被請去輔佐周室，成就一代功業。磻溪垂釣因此成為讀書人心中等待賞識、盼望出仕的典故。王維一生在官場與山林之間搖擺，寫下這首青谿時，卻反過來用同一個垂釣的姿勢，表達完全相反的心願，他不求被誰發現，只求能安安靜靜留在這片清澄的溪水邊。",
    "zhuyin": "谿(ㄒㄧ)(xī)發音同\"西\"，山間的河流。同「溪」。\n 荇(ㄒㄧㄥˋ)(xìng)發音同\"性\"，浮萍科「浮萍」之古名，語出《唐本草》。\n 葭(ㄐㄧㄚ)(jiā)發音同\"加\"，蘆葦。或特指初生的蘆葦。\n 澹(ㄉㄢˋ)(dàn)發音同\"但\"，安靜。《老子》第二○章：「澹兮其若海，飂兮若無止。」",
