    "id": 30,
    "dynasty": "盛唐",
    "type": "五言古詩",
    "author": "王維",
    "title": "渭川田家",
    "poem_notes": "【字詞與白話】\n 墟落：村落。荊扉：用樹枝編成的簡陋門，代指農家的家門。雉雊：野雞鳴叫。式微：出自詩經，式微式微，胡不歸意思是天快黑了為什麼還不回家，常用來表達歸隱的念頭。\n \n 白話：斜陽照著荒僻的村落，牛羊沿著窮巷歸來。老人惦記著放牧的孩童，拄著拐杖在柴門邊等候。野雞在麥苗抽穗時鳴叫，桑葉被春蠶吃得稀疏。田裡的農夫扛著鋤頭站著，跟人相見說話，捨不得分開。看著這一切，我羨慕這種閒適安逸的生活，悵然地吟起式微那句古老的歌。\n \n 【背後的小故事】\n 王維寫這首詩時，正處在官場浮沉的階段，見慣了升遷貶謫的無常。渭水邊一個尋常的黃昏，牛羊歸家、老人候門、農夫閒話的畫面，讓他心裡那個想要歸隱的念頭浮上來。多年以後，他真的在輞川買下一片山水，過著亦官亦隱的生活。這首詩裡的柴門與麥田，後來變成了他人生下半場真正走進去的地方。",
    "zhuyin": "雊(ㄍㄡˋ)(gòu)發音同\"夠\"，雄雉鳴叫。\n 悵(ㄔㄤˋ)(chàng)發音同\"唱\"，憂思失意的樣子。",
