    "title": "西施詠",
    "poem_notes": "【字詞與白話】\n 寧久微：怎麼會長久卑微。賤日豈殊眾：卑賤的時候容貌難道跟別人不一樣嗎。效顰：模仿別人皺眉的樣子，出自西施捧心皺眉、鄰女東施仿效卻更醜的典故。\n 白話：美色向來被天下人看重，西施怎麼可能長久卑微下去。早上還是越溪邊的浣紗女，晚上就成了吳王宮裡的寵妃。她卑賤時容貌難道跟眾人不同嗎？富貴以後人們才驚覺她原來如此稀世。有人爭著替她塗脂抹粉，她連衣服都不用自己穿。得到君王寵愛後，她的嬌態更受喜愛，君王憐惜她，連是非對錯也不再計較。當年一起浣紗的同伴，卻沒有一個能跟她同車回宮。奉勸那學她皺眉的鄰家女孩，這種模仿又怎麼能學得到呢。\n \n 【背後的小故事】\n 王維二十出頭便靠才藝與岐王、玉真公主的賞識一步登天、年少中舉，與同輩許多懷才不遇者的處境形成強烈對照。他借西施從浣紗女一夕變吳宮寵妃的際遇，寫出貧賤與富貴之間人心的勢利與落差，暗喻自己與那些沒被看見的讀書人之間，差的往往只是一次被抬舉的機會。詩眼是同一張臉，貧賤時無人正眼看，富貴後連缺點都成了風情。",
    "zhuyin": "效顰(ㄒㄧㄠˋ ㄆㄧㄣˊ)(xiào pín)發音同\"笑貧\"，形容拙劣的模仿，反弄巧成拙。",
