    "title": "秋登蘭山寄張五",
    "poem_notes": "【字詞與白話】\n 隱者自怡悅：山裡的隱士自得其樂，暗指自己也是這樣的人。心隨雁飛滅：心思跟著雁群一直望到牠們消失，暗喻思念朋友之切。薄暮：黃昏。天邊樹若薺：遠處的樹小得像薺菜一樣，形容登高望遠所見。\n \n 白話：北山籠在白雲裡，隱居的人自有一份怡然自得。我登高眺望，心思跟著雁群一路飛到看不見的遠方。黃昏漸近，愁緒也跟著升起；清秋的興致，正好在這時發作。偶爾看見歸家的村人，走到渡口邊歇腳。天邊的樹小得像薺菜，江畔的沙洲彷彿一片月亮。什麼時候能載著酒來，一起在重陽節痛快醉一場。\n \n 【背後的小故事】\n 孟浩然與張子容詩中的張五是襄陽同鄉，年輕時一起隱居鹿門山讀書。後來張子容考中進士出仕，孟浩然卻始終沒有走上仕途，兩人從朝夕相處變成天各一方。這首詩寫於一個秋天的黃昏，孟浩然登上蘭山，望著北飛的雁群，想起遠方的老友，最後把思念收進一個約定裡，等重陽節，再像從前那樣，一起喝一場酒。",
    "zhuyin": "薺(ㄐㄧˋ)(jì)發音同\"記\"，植物名。十字花科薺屬，「薺菜」之簡稱。",
