    "title": "夏日南亭懷辛大",
    "poem_notes": "【字詞與白話】\n 散髮：把束起的頭髮放下來，形容悠閒不拘禮節的樣子。開軒：打開窗子。恨無知音賞：遺憾沒有真正懂音樂的人能欣賞。中宵：半夜。勞夢想：辛苦地在夢裡想念，形容思念深切到夜裡都不得安寧。\n 白話：山邊的日光忽然西沉，池塘上的月亮漸漸東升。我把頭髮放開，乘著夜涼，打開窗子躺在敞開通風的地方。荷花的香氣隨風送來，竹葉上的露水滴落發出清脆聲響。想拿起琴來彈，卻遺憾這裡沒有真正懂音樂的人可以欣賞。想到這裡不禁懷念起老朋友，這份思念一直到半夜都還在心裡翻騰，難以入睡。\n \n 【背後的小故事】\n 孟浩然終身沒有做官，長年隱居襄陽鹿門山，相傳他曾有機會被引薦給唐玄宗，卻因緊張唸出不才明主棄一句而錯失機會，這段軼事史料記載簡略，真實性難以完全考證。辛大是他少數往來密切的友人，具體身分史書留下不多。這首詩借伯牙絕弦的典故，寫一個夏夜想彈琴卻找不到知音欣賞的心情，最後只能把滿腔思念寄託在對老友的懷念裡，直到半夜還輾轉難眠。",
