    "title": "同從弟南齋翫月憶山陰崔少府",
    "poem_notes": "【字詞與白話】\n 南齋：南邊的書房或臥室。苒苒幾盈虛：月亮一次次由虧轉盈、由盈轉虧，形容時間流逝。越吟苦：借用古越地哀怨的歌調，暗指崔少府身在越地山陰，心裡也有愁思。蘭杜：蘭草與杜若，兩種香草，代表清雅的夜間氣息。\n \n 白話：躺在南齋裡的時候，掀開帷帳，月亮剛剛升起。清冷的月光灑在水面與樹梢上，晃動的光影映進窗戶裡。月亮一次次盈虧，看盡古今變化卻依然澄澈。那位友人此刻正在清澄的江邊，這一夜大概也在低吟著越地哀愁的曲調。相隔千里，他過得怎麼樣呢，一陣微風正吹過蘭草與杜若。\n \n 【背後的小故事】\n 王昌齡一生仕途起伏，交遊卻十分廣闊。這首詩寫他與堂弟在南齋賞月的一個尋常夜晚，因為堂弟隨口一句關於月亮盈虧的話，讓他想起遠在山陰當縣尉的朋友崔少府。他猜想此刻對方大概也望著同一片月光，心裡有著相似的鄉愁曲調。整首詩沒有華麗的辭藻，只是把一份隔著千里也想傳達的掛念，安安靜靜地寫進了月光裡。",
    "zhuyin": "帷(ㄨㄟˊ)(wéi)發音同\"圍\"，帳幕。\n 苒(ㄖㄢˇ)(rǎn)發音同\"染\"，草茂盛的樣子。",
