    "title": "塞上曲",
    "poem_notes": "【字詞與白話】\n 幽并客：幽州、并州一帶出身的人，古來以民風尚武聞名。紫騮：一種紫紅色的駿馬，這裡指年輕遊俠兒炫耀的名貴坐騎。矜誇：驕傲地誇耀。\n 白話：秋蟬在空曠的桑林裡鳴叫，八月的蕭關道已一片蕭瑟。軍隊反覆出塞又入塞，一路上到處都是枯黃的蘆草。歷來幽州并州出身的戍邊子弟，大多都是在沙場上一直守到老去。奉勸年輕人別學那些遊俠兒，只顧著誇耀自己的紫騮馬多麼神氣。\n \n 【背後的小故事】\n 王昌齡早年曾親赴河西、隴右一帶邊塞遊歷，見過真正戍守邊關、大半輩子耗死在沙場上的老兵。相傳他曾聽一位老兵指著招搖過市的年輕遊俠兒搖頭嘆息，告誡人別只顧炫耀寶馬英姿，因為真正的邊關生活只有反覆的荒涼與袍澤的犧牲。他把這份告誡寫進詩裡，詩眼是老兵對浮誇少年的告誡，替所有沒沒無聞老死沙場的戍卒說一句公道話。",
    "zhuyin": "幽并(ㄅㄧㄥ)(yōu bìng)發音同\"兵\"，古代幽州和并州，今河北山西。\n 矜(ㄐㄧㄣ)(jīn)發音同\"金\"，自誇、自負。\n 騮(ㄌㄧㄡˊ)(liú)發音同\"留\"，駿馬。",
