    "title": "尋西山隱者不遇",
    "poem_notes": "【字詞與白話】\n 茅茨:茅草蓋的屋頂,代指隱者的簡陋居所。扣關:敲門。黽勉:勉力、費力,這裡指一路辛苦仰慕而來。\n 白話:山頂上有一間茅屋,他一口氣往上爬了三十里。敲門卻沒有僮僕應聲,探頭往屋裡看,只有一張桌案。猜想主人若不是駕著柴車外出,就是正在秋水邊釣魚。錯過了沒能相見,白費了這一路的仰慕。但雨後的草色格外清新,傍晚松風在窗邊作響,這樣幽靜的境界已經夠洗滌人心,雖然沒有主客對飲的熱鬧,卻也嚐到了清淨的道理。興致盡了才下山,何必一定要等到那個人。\n \n 【背後的小故事】\n 邱為以孝聞名,終生為侍奉高齡母親而婉拒外調,難得有機會遠行。這趟少有的登山訪友,他一口氣爬了三十里,結果隱者不在家,連句招呼都沒能打上。他原以為會失落,卻在門前坐下,看著雨後的草色與晚窗的松聲,忽然覺得沒見到人也沒關係——這份幽靜本身已經足夠。他起身下山時想的是:何必一定要等到那個人,就像他這些年留在母親身邊,有些路走過就值得,不必走到終點見到誰。",
