    "title": "春泛若耶溪",
    "poem_notes": "【字詞與白話】\n 幽意：歸隱山林的心意。隨所偶：隨遇而安，遇到什麼就是什麼。際夜：入夜的時候。溶溶：形容煙霧瀰漫、緩緩流動的樣子。生事：人生的事務、俗世的營生。持竿叟：拿著釣竿的老人，指隱居垂釣的漁夫。\n 白話：歸隱的心意從沒斷過，這一路走到哪裡就隨遇而安。晚風吹著船前行，兩岸的花一路開到溪口。入夜後船轉進西邊的山谷，隔著山頭還能望見南斗星。水面上的煙霧溶溶地飄著，林間的月亮低低地垂在船後。人世間的事情就讓它一片模糊吧，我只願做一個拿著釣竿的老人。\n \n 【背後的小故事】\n 綦毋潛的生平記載相當有限，只知他是荊南人，開元年間進士出身，曾任官職但不算顯達，相傳與王維交情深厚，王維曾寫詩相贈，晚年行蹤史料語焉不詳，只能誠實以相傳處理。若耶溪自古便與西施浣紗的傳說相連，也是文人歸隱嚮往之地。這首詩寫的正是他在功名與山林之間搖擺不定時，一個春夜順水漂流所生出的念頭，想放下一切紛擾，做一個安靜垂釣的老人。",
    "zhuyin": "壑(ㄏㄨㄛˋ)(hè)發音同\"或\"，谷、溝。",
