    "title": "賊退示官吏并序",
    "poem_notes": "【字詞與白話】\n 井稅有常期：按規矩定期繳納賦稅，是太平時期的常態。日晏猶得眠：太陽升老高了才起床，睡到自然醒，形容日子安穩。城小賊不屠：城池小，盜賊沒有屠殺劫掠的興致，因為太窮不值得搶。使臣將王命：官方派來的使者，奉皇帝命令辦事。委符節：交還官印與符節，也就是辭官。引竿自刺船：撐著竹竿自己划船。\n 白話：從前太平時候，我在山林裡隱居了二十年，泉水就在庭院裡，山洞就在門前，按規矩交稅，天亮很久了還能安睡。忽然時局大變，我被徵召從軍好幾年。如今我來管這個郡，山賊又鬧得凶。城小，賊人懶得屠殺搶劫，百姓窮困到令人心疼，因此鄰近州縣都陷落了，只有這個州獨獨保全。可是奉皇命辦事的使者，難道不比盜賊更狠嗎？叫底下的人去催稅，逼得像用火在煎熬百姓一樣。誰能忍心斷絕人命去換取當世的美名？我真想乾脆辭官，撐一根竹竿自己划船，帶著家人去有魚有麥的地方，回到江湖邊終老。\n \n 【背後的小故事】\n 這首詩寫於元結任道州刺史期間，安史之亂餘波未平，西原蠻連年侵擾附近州縣，唯獨道州因貧窮弱小逃過劫掠，朝廷催稅的使者卻仍然不留情面。元結把這首詩和序文一起抄送給轄下官吏，等於公開斥責。杜甫後來讀到此詩深受感動，寫詩盛讚，並抄錄下來教導後人。",
    "zhuyin": "日晏(ㄖˋ ㄧㄢˋ)(rì yàn)發音同\"日驗\"，太陽昇起很高，表示時候不早。\n 戎旃(ㄖㄨㄥˊ ㄓㄢ)(róng zhān)發音同\"容沾\"，軍旗、軍帳。亦指軍旅、戰事。\n 徵歛(ㄓㄥ ㄌㄧㄢˋ)(zhǐ liǎn)發音同\"爭練\"，徵收賦稅，「斂」的異體字。",
