    "id": 43,
    "dynasty": "中唐",
    "type": "五言古詩",
    "author": "韋應物",
    "title": "郡齋雨中與諸文士燕集",
    "poem_notes": "【字詞與白話】\n 兵衛森畫戟：門外儀仗兵持著彩繪的戟，排列森嚴，顯示官署威儀。宴寢凝清香：內室裡薰香凝結，氣氛清雅。煩痾：煩心的病痛。自慚居處崇：自己覺得慚愧，因為住的地方太高太好。未睹斯民康：還沒看見治下的百姓過上安康日子。理會是非遣：把是非道理想通了，煩惱就消散。性達形跡忘：性情通達，就不拘泥表面形式。鮮肥屬時禁：新鮮肥美的葷食正逢時令禁忌，不宜食用。\n 白話：門外儀仗森嚴，彩戟林立；內室薰香繚繞，清雅安靜。海上忽然刮來風雨，池畔樓閣卻涼爽宜人。這幾天煩心的病痛總算消散了些，嘉賓又滿座而來。想通了道理，是非煩惱自然消遣；性情通達，就不必拘泥表面形跡。這時節不宜上葷腥，幸好還有蔬果可以招待。俯身飲一杯酒，抬頭聽賓客吟詩作賦。精神暢快，身體都覺得輕盈，彷彿要乘風飛起來。吳地向來文風興盛，如今在座的才俊多如汪洋大海，這才明白，一個地方的富強不在錢財多寡。可是我自己住得這麼高，卻還沒讓治下的百姓過上安康的日子，心裡實在慚愧。\n \n 【背後的小故事】\n 韋應物早年是唐玄宗身邊的侍衛，年少放縱不學無術。安史之亂後失去靠山，才發憤讀書，轉型成為以清廉勤政聞名的地方官。這首詩相傳寫於他任蘇州或滁州刺史期間，一場文士雅集上，他在賓主盡歡之際忽然反躬自省，寫下自慚居處崇、未睹斯民康這句流傳後世的名句。",
