    "title": "初發揚子寄元大校書",
    "poem_notes": "【字詞與白話】\n 揚子:即揚子津,唐代長江北岸的重要渡口,在今揚州附近。校書:校書郎,掌管典籍校勘的官職,元大即擔任此職。沿洄:順流和逆流,泛指水流的起伏漂盪。\n 白話:悽悽然地離開親愛的朋友,船隻茫茫然地駛入江面的煙霧裡。搖著船棹返回洛陽,身後只剩下廣陵樹林間傳來的殘鐘聲。今天早上就此一別,不知道日後要在何處才能重逢。世間的事就像水面上的一艘船,無論順流或逆流,都不可能停在原地。\n \n 【背後的小故事】\n 韋應物早年是唐玄宗身邊恃寵而驕的侍衛,安史之亂後靠山盡失,才收起狂氣、輾轉各地任官,也因此重新學會了與人真心相交,元大便是他在廣陵結識的知己。這回北返洛陽,他站在船頭看著元大和廣陵的樹影一起被晨霧吞沒,只剩殘鐘斷續追來。他忽然說不準下次重逢會在哪裡——這些年輾轉不定的官途,讓他比誰都清楚,人就像水上的船,順流逆流都由不得自己停下。",
