    "poem_notes": "【字詞與白話】\n 郡齋：郡守辦公居住的官署。澗底束荊薪：到山谷底下撿拾荊棵當柴燒。煮白石：傳說中道士修煉的一種說法，把白石頭煮熟當糧食吃，相傳出自仙人黃初平的故事。瓢：舀酒用的瓠瓜殼，這裡代指一壺酒。遠慰：從遠處去安慰、陪伴。行跡：行走留下的痕跡、蹤影。\n 白話：今天早上郡裡的官署格外冷清，忽然想起山中那位隱居的朋友。他大概正在山谷底下撿柴，回來後煮著白石頭當飯吃。我想帶一瓢酒去，在這樣風雨交加的夜晚陪他暖暖身子。可是滿山落葉鋪滿了整座空山，我要到哪裡才能找到他的蹤跡呢。\n \n 【背後的小故事】\n 韋應物年少時曾是唐玄宗身邊的三衛侍從，仗著身分驕縱不羈，史書記載他當時是個不學無術的紈褲少年。安史之亂爆發後，長安淪陷，他失去依靠，家道中落，從此性情大變，轉而勤奮讀書，後來出任滁州、蘇州等地刺史，以清簡勤政著稱。這首詩寫在他任滁州刺史期間，思念一位隱居全椒山中的道士朋友，想送酒相慰卻苦於找不到行蹤。從橫行街市的紈褲少年到惦念山中隱士冷暖的地方官，這份轉變本身就是他人生最深的注腳。",
