    "poem_notes": "【字詞與白話】\n 灞陵：長安城東的一處地名，古人送別常在此折柳道別。采山因買斧：到山裡採藥砍柴，因此進城買一把斧頭。冥冥：昏暗、影影綽綽的樣子。颺颺：飛舞、輕盈飄動的樣子。燕新乳：燕子剛剛哺育雛燕。\n 白話：朋友從東邊來，衣服上還帶著灞陵那邊的雨。我問他這趟來做什麼，他說是因為要進山採藥砍柴，斧頭鈍了，進城買一把新的。這時節花開得影影綽綽，燕子正忙著飛進飛出哺育雛燕。昨天才剛道別，一轉眼又是春天了，你鬢角上不知不覺又添了幾縷白髮。\n \n 【背後的小故事】\n 馮著是韋應物的老朋友，屢次仕途受挫後選擇半隱居的生活，靠採藥打柴為生，難得進城。這首詩沒有寫兩人重逢時的激動或傷感，只用買斧頭這樣一件瑣事帶過，把仕途失意後的心照不宣，藏進日常對話裡。",
    "zhuyin": "颺颺(ㄧㄤˊ ㄧㄤˊ)(yáng yáng)發音同\"洋洋\"，飛翔的樣子。",
