    "title": "溪居",
    "poem_notes": "【字詞與白話】\n 久為簪組累：長久被官員的冠簪與印綬所拖累，代指官職纏身。幸此南夷謫：慶幸自己被貶到這南方偏遠之地，是反話，苦中作樂。閑依農圃鄰：閒來與種田人家為鄰。曉耕翻露草：清晨下田翻整帶著露水的雜草。夜榜響溪石：夜裡划船回來，船槳碰撞溪石發出聲響。長歌楚天碧：對著碧藍的楚地天空放聲高歌。\n 白話：長久以來被官場的冠帶印綬所拖累，如今被貶到這南方蠻荒之地，倒覺得慶幸。閒來與種田人家做鄰居，偶爾覺得自己像個山林隱士。清晨下田翻整帶露水的雜草，夜裡划船回家，船槳觸碰溪石發出聲響。來來去去很少遇見人，只能對著碧藍的楚天放聲高歌。\n \n 【背後的小故事】\n 柳宗元被貶永州期間，先是借住在龍興寺多年，後來才在溪邊蓋了這間小屋，終於有了自己的落腳處。當地人因他是獲罪貶謫的官員，多半不敢與他往來，他常常一整天遇不到一個人說話。這首詩把苦難寫成慶幸，是他在孤獨處境裡替自己找的一種活下去的方式。",
