    "title": "烈女操",
    "poem_notes": "【字詞與白話】\n 操：樂府詩體的一種，多用於敘述堅貞、悲苦的心志。殉夫：舊時觀念裡，妻子為亡夫守節到底、不再改嫁。井中水：水看似毫無波紋，其實深不見底，比喻心志堅定、外人看不透。\n 白話：梧桐樹要一起種下、一起老去，鴛鴦要成雙成對、同生共死。貞節的婦人重的是對丈夫的心意始終如一，就算要她付出一切也甘願。我發誓心裡絕不再起波瀾，就像深井裡的水，平靜無波。\n \n 【背後的小故事】\n 相傳這首詩是孟郊替一位年輕守寡的婦人寫的。婦人丈夫早逝，成親不過三四年，娘家有意勸她趁早改嫁，婆家則想替她向官府申請旌表，好護她安穩留下、不受人指指點點。孟郊見她照常打水、做針線，問她怎麼想，她只淡淡說了句不想，指尖被針扎了也不吭聲。他想起院裡那口深井，水面平靜，底下的心思外人看不透，便提筆寫下這首詩，替她擋下逼嫁的壓力。",
    "zhuyin": "殉(ㄒㄩㄣˋ)(xùn)發音同\"訊\"，用人或器物陪葬。",
