    "title": "遊子吟",
    "poem_notes": "【字詞與白話】\n 三春暉：春天的陽光，比喻母親的恩情。原詩題下還有「迎母溧上作」四字，說明這其實是重逢詩，不是離別詩。\n 白話：慈母手中的針線，縫成了遊子身上的衣裳。臨行前一針一線縫得密密的，是擔心孩子遲遲不能回家。誰能說小草的心意，能報答得了春天陽光般的恩情呢。\n \n 【背後的小故事】\n 孟郊考進士考到四十六歲才中，五十歲才被派任溧陽縣尉，做的第一件事就是把年邁的母親從湖州武康接來同住。安頓下來的某個夜晚，他看見母親一如往常坐在燈下替他縫補舊衣，針腳收得特別密——那是他年輕時嫌瑣碎、從未懂得的細節。這一刻他忽然明白：母親縫得越密，是因為不知道這一別要幾年，只能盼衣服撐得夠久，撐到兒子回來。這首詩其實不是離別詩，而是一封遲到三十年的感謝，寫在終於能報答母親的重逢時刻。",
    "zhuyin": "春暉(ㄔㄨㄣ ㄏㄨㄟ)(chūn huī)發音同\"春揮\"，春天的陽光。比喻慈母的恩惠。",
