    "title": "無題",
    "poem_notes": "【字詞與白話】\n 樊素、小蠻：白居易晚年家中的歌伎與舞伎，樊素擅唱，小蠻擅舞。凝脂：形容皮膚像凝結的油脂一樣白皙細膩。\n 白話：樊素的嘴像櫻桃一樣紅潤小巧，小蠻的腰像楊柳一樣柔軟纖細。眉毛用青黛描過，皮膚白得像雪一樣凝脂細滑。她回頭一笑，那模樣美得能讓整座城、整個國家都為之傾倒。\n \n 【背後的小故事】\n 白居易晚年多病，先是腳氣反覆發作，走幾步就氣喘，後又中風，半身一度不能動，連握筆都要歇好幾次。家中的樊素與小蠻常年伴他消磨長夜，他心裡清楚自己撐不了太久，捨不得放，卻更明白把兩個正當年紀的女子綁在病弱老人身邊並不公平。這兩句誇讚她們美貌的詩寫於此時，幾年後他真的把老馬賣了，把樊素也放了，兌現了詩裡藏著的那份不忍與成全。",
