    "poem_notes": "【字詞與白話】\n 悠悠：形容時間、空間的無窮遙遠。幽州臺又稱黃金臺，相傳是戰國燕昭王築臺招賢之處。\n 白話：向前望不見古代求賢的明君，向後望也見不到未來能賞識我的人。想到天地如此廣大悠久，獨自一人不禁悲傷落淚。\n \n 【背後的小故事】\n 陳子昂隨軍北伐契丹，統帥武攸宜不懂軍事卻屢戰屢敗，他多次獻策都被拒絕，還被貶為更小的官，徹底被邊緣化。他登上相傳燕昭王築臺招賢的幽州臺，往前看不到能賞識人才的古代明君，往後也望不見未來的知音，天地如此遼闊悠久，自己卻孤獨得無處可去，忍不住落淚。這首詩只有二十二個字，沒有典故堆疊，卻把「懷才不遇」寫到了極致。幾年後他辭官返鄉，竟被貪財的縣令誣陷下獄，憂憤而死，年僅四十一歲。",
    "zhuyin": "愴然(ㄔㄨㄤˋ ㄖㄢˊ)(chuàng rán)發音同\"創然\"，悲傷哀痛的樣子。\n 涕(ㄊㄧˋ)(tì)發音同\"替\"，眼淚。",
