    "id": 56,
    "dynasty": "初唐",
    "type": "七言古詩",
    "author": "張若虛",
    "title": "春江花月夜",
    "poem_notes": "【字詞與白話】\n 全詩共三十六句，被聞一多譽為「詩中的詩，頂峰上的頂峰」。張若虛一生僅存兩首詩，此詩以春、江、花、月、夜五種意象貫串全篇。\n 白話：春天的江潮水勢浩蕩，與大海連成一片，一輪明月正隨著潮水一同升起。月光閃耀著隨波蕩漾千萬里，哪一處春江沒有這皎潔的月色呢？江水曲折繞過芬芳的原野，月光照著花林彷彿灑滿雪珠。江畔是誰最初看見這輪明月？江月又是哪一年最初照耀著人？人生一代代無窮無盡地延續，江上的月亮年年看起來都相似。不知這江月在等待著什麼人，只見長江不斷送走滔滔流水。（中略）今夜遊子乘著小舟在何處漂泊？又是誰家的妻子在明月照耀的樓上相思？（末句）不知有幾人能趁著月色歸來，唯有那西沉的月光搖曳著離情，灑滿了江邊的樹林。\n \n 【背後的小故事】\n 張若虛一生僅留下兩首詩，這首寫於他在揚州江邊獨自賞月的一個春夜。他望著潮水托起明月的壯闊景象，忽然想到：此刻同一輪月光，也正照著江上漂泊的遊子與樓中相思的妻子——他們彼此看得見月亮，卻聽不見對方的聲音，唯一共享的只有這片月色。他把眼前的江天景色，一路寫到宇宙初始第一個看月的人、寫到千里相思的閨中女子，將個人的感受擴展成人類共同的鄉愁與思念。這首詩生前並不出名，卻在千年後被譽為「孤篇蓋全唐」，是張若虛留給後世最珍貴的一夜。",
    "zhuyin": "灩(ㄧㄢˋ)(yàn)發音同\"驗\"，波光映照。\n 芳甸(ㄉㄧㄢˋ)(fāng diàn)發音同\"電\"，長滿芳草的郊野。\n 霰(ㄒㄧㄢˋ)(xiàn)發音同\"現\"，雨點遇冷空氣凝成的雪珠，降落時呈白色不透明的小冰粒，常呈球形或圓錐形，多降於下雪之前。\n 砧(ㄓㄣ)(zhēn)發音同\"真\"，洗衣時用來輕搥衣服的石塊。\n 碣(ㄐㄧㄝˊ)(jié)發音同\"節\"，刻有文字的圓形石碑，用以記載事蹟或頌揚功德等。",
