    "title": "廬山謠寄盧侍御虛舟",
    "poem_notes": "【字詞與白話】\n 盧侍御虛舟:李白友人盧虛舟,時任侍御史。楚狂人:春秋隱士接輿,曾唱歌譏笑孔丘四處奔走求官,李白以此自比狂放不羈。盧敖:傳說中秦代求仙訪道之人,遇仙於九垓之上,李白借與友人同姓,把他接進求仙的想像裡。\n 白話:我本就是楚國那個唱著鳳歌譏笑孔丘的狂人,手持綠玉杖,清晨從黃鶴樓出發。我一生最愛遍遊名山,如今來到秀出於南斗旁的廬山,把它的雲錦山勢、瀑布石梁一一寫盡。早服丹藥便無世俗牽掛,如今道業將成,願與友人盧虛舟一同飛升九天,遨遊於太清之境。\n \n 【背後的小故事】\n 李白因捲入永王李璘謀反案被判流放夜郎,途中行至巫山一帶忽獲赦令重獲自由。他沒有從此收斂,反而掉頭直奔廬山,寫信給友人盧虛舟,開篇便以譏笑孔丘的楚狂接輿自比,張狂依舊。信末他更藉友人同姓,把他接進秦代求仙者盧敖的傳說裡,說要與他一同遨遊九天太清之境。這封信與其說是遊記,不如說是劫後餘生的李白,用最狂放的姿態向世界證明自己沒有被打垮。",
    "zhuyin": "好(ㄏㄠˋ)(hǎo)發音同\"號\"，\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。\n 厓(ㄧㄚˊ)(yá)發音同\"牙\"，\n 沓(ㄊㄚˋ)(tà)發音同\"踏\"，\n 綵(ㄘㄞˇ)(cǎi)發音同\"採\"，\n 垓(ㄍㄞ)(gāi)發音同\"該\"，",
