    "title": "夢遊天姥吟留別",
    "poem_notes": "【字詞與白話】\n 天姥山：位於今浙江新昌，李白年輕時嚮往卻未曾親至的名山。「安能摧眉折腰事權貴，使我不得開心顏」是全詩最著名、最能代表李白性格的一句。\n 白話：（節錄）航海的人談論瀛洲仙島，煙波渺茫實在難以尋求；越地的人談起天姥山，雲霞忽明忽滅，或許還能看見。天姥山高聳連天，橫亙天際，山勢超越五嶽，遮蔽了赤城山……（中略：夢中飛渡鏡湖，攀登天姥，見識仙境奇景）忽然魂魄震動、驚醒過來，只覺長嘆一聲。醒來時只剩眼前的枕蓆，方才夢中的雲霞煙霧全都消失無蹤。人世間的行樂也不過如此，自古以來萬事都像東流的江水一去不返。與各位朋友告別，不知何時才能歸來？暫且把白鹿放牧在青翠山崖之間，等到要出行時就騎著牠去探訪名山。我怎麼能夠低眉彎腰去侍奉權貴，讓自己不能開懷歡笑呢！\n \n 【背後的小故事】\n 李白在長安當翰林待詔三年，每天陪侍皇帝身邊寫應制詩，終被「賜金放還」逐出長安。這首詩寫於他寄居山東友人家中時，一夜夢見自己飛越鏡湖、攀登嚮往已久的天姥山，見識到雲霞仙境的奇幻景象，卻在最絢爛之時忽然驚醒，眼前只剩下平凡的枕蓆。他忽然體悟：長安三年的富貴榮華，就像這場夢一樣，睜眼就消散無蹤。既然世間萬事都如東流之水，他何必再回頭向權貴低頭？這首詩末句的宣言，成了李白一生最鮮明的精神寫照。",
    "zhuyin": "天姥(ㄊㄧㄢ ㄇㄨˇ)(tiān lǎo)發音同\"天母\"，山名。在浙江省紹興市新昌縣和嵊州市之間。東接天台山華頂峰，西連沃洲山，最高峰為撥雲尖。\n 剡溪( ㄕㄢˋ ㄒㄧ)(yǎn xī)發音同\"善西\"，河川名。位於浙江省嵊縣南，為曹娥江的上游。有二源，一出天台縣，一出武義縣，晉時王徽之嘗雪夜訪戴逵於此。\n 淥(ㄌˋㄨ)(lù)，清澈的水。\n 壑(ㄏㄨㄛˋ)(hè)發音同\"或\"，谷、溝。\n 暝(ㄇㄧㄥˊ)(míng)發音同\"名\"，天晚的。唐．李白〈菩薩蠻．平林漠漠煙如織〉詞：「暝色入高樓，有人樓上愁。」\n 慄(ㄌˋㄧ)(lì)，因恐懼而發抖。如：「戰慄」、「不寒而慄」。\n 澹澹(ㄉㄢˋ ㄉㄢˋ)(dàn dàn)發音同\"但但\"，水搖蕩的樣子。\n 訇(ㄏㄨㄥ)(hōng)，形容巨大的聲音。\n 怳(ㄏㄨˇㄤ)(huǎng)，通「恍」。\n 嗟(ㄐㄧㄝ)(jiē)發音同\"接\"，表示感傷、哀痛的語氣。",
    "rating": 5,
