    "type": "七言古詩",
    "author": "李白",
    "title": "金陵酒肆留別",
    "poem_notes": "【字詞與白話】\n 吳姬：長江下游吳地一帶酒館裡賣酒的女子。壓酒：新酒釀成後榨出酒汁的工序。金陵子弟：金陵當地與李白結交的年輕人。\n 白話：風吹著柳絮，滿店都是香氣，賣酒的吳地女子正壓好新酒招呼客人品嘗。金陵城裡結交的年輕朋友都來相送，想走又捨不得走，各自乾了一杯又一杯。你們若不信，去問問那向東流去的江水，我們這場離別的情意，跟江水比起來，究竟誰更長。\n \n 【背後的小故事】\n 二十五歲的李白初離蜀地遠遊，在金陵結交了一批年輕朋友。離開那天，眾人一早就在酒館占位等他，誰也不提你什麼時候走，只顧著一杯接一杯地敬酒，好像沒人開口，這場酒局就能一直喝下去。酒酣時有人起鬨，要拿門外的秦淮江水比一比離情的長短，李白借著酒意脫口寫下這兩句，把一群人不敢言明的不捨，變成了一場俏皮的較量。",
    "zhuyin": "觴(ㄕㄤ)(shāng)發音同\"商\"，[動]飲酒，或勸人飲酒、敬酒。[名]酒杯、酒器。",
