    "title": "宣州謝朓樓餞別校書叔雲",
    "poem_notes": "【字詞與白話】\n 抽刀斷水水更流，舉杯消愁愁更愁：純粹的物理比喻，不帶任何情感形容詞，是全詩最有名的兩句。\n 白話：拋棄我而去的昨天，已經留不住了；擾亂我心緒的今天，充滿了煩憂。萬里長風吹送秋雁南飛，面對此景正可以在高樓上暢飲。你的文章兼具漢代典籍的深厚與建安風骨，中間又帶著謝朓般的清新俊逸。我們都懷著飛揚的逸興壯思，想飛上青天摘取明月。拔刀砍向流水，水依然奔流；舉杯澆灌憂愁，愁緒反而更深。人生在世如果不稱心如意，不如明天就披散頭髮，划一葉小舟離去。\n \n 【背後的小故事】\n 李白四十四歲被玄宗「賜金放還」，體面地被趕出長安，此後十年四處漂泊。五十五歲那年在宣州謝朓樓為族叔李雲餞行，酒酣時吐露心聲：昨日的風光已留不住，今日的失意揮之不去。他讚美族叔文采之餘，也道出千古名句「抽刀斷水水更流，舉杯消愁愁更愁」——單純的物理事實，比任何抒情都更狠地說明：他的失意，酒解決不了。詩末說要「明朝散髮弄扁舟」，可他嘴上說放下，身體卻一步沒退——沒多久又投身永王幕府，慘遭流放。這種矛盾，正是李白最真實的樣子。",
    "zhuyin": "酣(ㄏㄢ)(hān)發音同\"憨\"，喝醉酒。\n 逸興(ㄧˋ ㄒㄧㄥˋ)(yì xīng)發音同\"意性\"，超脫世俗的意興。",
