    "title": "把酒問月",
    "poem_notes": "【字詞與白話】\n 「今人不見古時月，今月曾經照古人」以月亮的恆常，映照人世的短暫流轉，是全詩哲理最深的兩句。\n 白話：青天上的明月是從什麼時候開始存在的呢？我今天停下酒杯來問一問它。人想要攀上明月是辦不到的，可是月亮行走時卻總跟隨著人。它皎潔得像一面剛擦亮的鏡子，映照著紅色的宮闕，周圍的雲霧散盡後，清朗的光輝便顯露出來。只見它夜晚從海上升起，卻不知道它清晨要沉沒到哪片雲間。傳說月中白兔搗藥，從秋天搗到春天；嫦娥孤獨地住在月宮，又能與誰為鄰呢？今天的人見不到古時候的月亮，可今天的月亮卻曾經照耀過古人。古人和今人就像流水一樣，一代代逝去，可大家看到的明月卻始終是同一輪。只願在對酒高歌的時候，月光能夠長久地照進我們的酒杯裡。\n \n 【背後的小故事】\n 這首詩寫於一場酒宴上，友人賈淳半開玩笑地問李白：你寫了一輩子月亮，倒是替我們問問它到底什麼時候開始掛在天上的？李白望著月亮沉思良久，想起自己一生從蜀中到長安、從宮廷到江湖，月亮始終追隨著他，卻從不解釋自己從何而來、又將去向何方。他由此聯想到古今人事如流水般更迭，唯有明月始終如一，寫下「今人不見古時月，今月曾經照古人」的千古哲思。三百多年後，蘇軾在中秋夜寫下「明月幾時有，把酒問青天」，正是接續著李白在這場酒宴上問出的那個問題。",
    "zhuyin": "皎(ㄐㄧㄠˇ)(jiǎo)發音同\"腳\"， 潔白明亮。\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。\n 擣(ㄉㄠˇ)(dǎo)發音同\"倒\"，舂、撞擊。\n 樽(ㄗㄨㄣ)(zūn)發音同\"尊\"，酒器。",
