    "title": "南陵別兒童入京",
    "poem_notes": "【字詞與白話】\n 蓬蒿人：長在荒野蓬草中的人，比喻沒有出息、埋沒草野之人。「仰天大笑出門去，我輩豈是蓬蒿人」是李白得到徵召詔書後狂喜之情的宣洩。\n 白話：新釀的白酒剛從山中帶回來，黃雞啄食著黍米，秋天正養得肥美。喊孩童來烹雞斟酒，兒女們嬉笑著拉扯我的衣裳。放聲高歌、盡情醉飲來自我安慰，起身起舞，與落日爭輝。遊說天子這件事苦於來得太晚，如今終於可以揚鞭跨馬，踏上遙遠的路途。會稽那個看輕朱買臣的愚昧婦人，我也要辭別家人西入長安了。仰天大笑著走出家門，我們這樣的人，豈是終老荒野、埋沒草莽的人呢！\n \n 【背後的小故事】\n 李白四十二歲那年，因道士吳筠與玉真公主在玄宗面前引薦，終於等到徵召入京的詔書，當時他正好從山中帶著新釀白酒回到南陵家中，兒女歡喜地拉著他的衣角。他喊人烹雞置酒，與妻兒歡慶了一整個下午，酒酣之際引用漢代朱買臣的典故——當年朱妻嫌貧離去，後來丈夫顯貴才後悔莫及——似是在回應多年來妻子對他不事生產的埋怨。他一氣呵成寫下這首詩，仰天大笑著出門赴京。他當時並不知道，這趟長安之行只維持了三年，最終仍被「賜金放還」，重新回到江湖漂泊，但那個與兒女同樂、與落日爭輝的下午，早已被他自己寫進了詩裡。",
    "zhuyin": "黍(ㄕㄨˇ)(shǔ)發音同\"暑\"，植物名。禾本科稷屬，一年生草本。葉細長而尖，有粗毛，平行脈。果實呈淡黃白色，帶黏性。宜於大暑時植於旱田。\n 酌(ㄓㄨㄛˊ)(zhuó)發音同\"琢\"，斟酒、飲酒。\n 會稽(ㄍㄨㄟˋ ㄐㄧ\n 蓬蒿(ㄆㄥˊ ㄏㄠ)(péng hāo)發音同\"朋蒿\"，蓬、蒿，皆野草名。蓬蒿，借指野地。",
