    "type": "七言古詩",
    "author": "李白",
    "title": "長相思二首之一",
    "poem_notes": "【字詞與白話】\n 絡緯：一種秋天鳴叫的昆蟲，俗稱紡織娘。金井闌：井欄上裝飾金屬，指精緻的水井。簟：竹席。\n 白話：日夜思念，人在長安。秋夜裡紡織娘在井欄邊啼叫，薄霜淒冷，竹席也帶著寒意。孤燈幽暗，思念濃得幾乎要斷魂，捲起窗簾望向月亮，卻只是徒然嘆息。那如花的人，遠隔在雲端那頭，上有青冥般高遠的天，下有波瀾起伏的水，天長路遠，夢魂也難以飛越這重重關山，這樣的思念，讓人肝腸寸斷。\n \n 【背後的小故事】\n 天寶三載，李白被唐玄宗客氣地賜金放還，離開他曾三年近侍天子身邊的翰林院。那年秋天他借宿異地客棧，半夜被井邊蟲鳴吵醒，竹席已結薄霜，孤燈搖曳不明。他捲簾望月，心裡想的那個人，是美人也好，是長安本身也好，對他來說其實是同一件事，那是他曾經觸手可及、如今卻隔在雲端那頭的一切，天高水遠，夢魂也飛不過那道看不見的關山，怎麼也回不去了。",
    "zhuyin": "簟(ㄉㄧㄢˋ)(diàn)發音同\"電\"，竹席。\n 淥水(ㄌㄨˋ ㄕㄨㄟˇ)(lù shuǐ)發音同\"路水\"，清澈的水。",
    "rating": 4,
