    "title": "長相思二首之二",
    "poem_notes": "【字詞與白話】\n 日色已盡花含煙：太陽已經下山，花朵籠罩在暮色的煙靄裡。趙瑟、蜀琴：分別代指趙地、蜀地製作的兩種樂器，此處泛指她面前的琴瑟。鳳凰柱、鴛鴦絃：瑟上刻鳳凰圖案的弦柱、琴上鴛鴦圖案的絃，皆暗喻成雙成對。燕然：漢代竇憲大破匈奴後刻石記功之處，泛指遙遠的北方邊塞。橫波目：形容眼波流轉、顧盼生輝的美目。\n 白話：天色已暗，花朵籠在煙霧裡，月光皎潔得像鋪了一層白霜，她滿懷愁緒睡不著。趙地的瑟才剛停下，蜀地的琴又想彈起，弦柱上刻著鳳凰，琴絃上刻著鴛鴦，都是成雙成對的圖案，偏偏她形單影隻。這支曲子滿懷心意，卻沒有人能替她傳遞，只盼望能隨著春風寄到遙遠的燕然。思念的人隔著千里青天，音信不通。從前那雙顧盼生輝的眼睛，如今變成了終日流淚的泉水。如果你不相信我心裡如此難受，那就回來，親自站在明鏡前看看我現在的模樣。\n \n 【背後的小故事】\n 這首詩以思婦的口吻寫成，是李白早期常用的樂府舊題之一。有學者認為，李白寫這類詩時，正值他在長安求仕屢屢碰壁的時期，詩中那個等不到丈夫歸來的女子，某種程度上也投射了他自己等不到君王重用的心境，但這僅是一種解讀角度，並無確切史料佐證。",
