    "title": "行路難三首之一",
    "poem_notes": "【字詞與白話】\n 「長風破浪會有時，直掛雲帆濟滄海」是全詩最著名的一句，展現李白在困境中仍懷抱希望的豪情。\n 白話：金杯裡盛著昂貴的清酒，一斗值萬錢；玉盤中裝著珍貴的佳餚，一頓價值萬金。可我放下酒杯、丟下筷子，什麼也吃不下，拔出寶劍環顧四周，心中一片茫然。想渡過黃河，河面卻結冰阻塞；想登上太行山，山上卻積雪封路。閒來無事到碧溪邊垂釣，忽然又夢見自己乘船經過太陽旁邊。前路多麼艱難啊，多麼艱難！岔路那麼多，如今我該往哪裡走？但終有一天，我會乘長風、破巨浪，掛起高高的雲帆，橫渡這片滄海。\n \n 【背後的小故事】\n 李白在長安當翰林待詔三年，本以為能一展抱負，卻只被當成寫詩助興的宮廷寵物，終被「賜金放還」逐出長安。這首詩寫於朋友為他餞行的酒席上，滿桌珍饈美酒，他卻食不下嚥，拔劍環顧四周，心中充滿茫然。他想起姜太公垂釣磻溪、伊尹夢乘船經日的典故，明白古人也曾卡在人生的路口，最終翻身而起，於是連呼兩聲「行路難」，在絕望中寫下「長風破浪會有時」的自我期許。這股信念支撐著他走過此後十幾年的流放與漂泊，直到客死當塗。",
    "zhuyin": "樽(ㄗㄨㄣ)(zūn)發音同\"尊\"，酒器。\n 箸(ㄓㄨˋ)(zhù)發音同\"住\"，筷子。",
