    "title": "行路難三首之二",
    "poem_notes": "【字詞與白話】\n 曳裾王門：拖著衣裾在權貴家門前徘徊，指依附權貴、寄人籬下求引薦。黃金臺：相傳燕昭王築臺置金，招攬天下賢才。\n 白話：大路像青天一樣寬闊，我卻偏偏走不出去。我羞於跟長安城裡鬥雞走狗、賭梨栗的富家子弟為伍，卻也不情願拖著衣袍在權貴門前徘徊求人引薦，那滋味太不痛快。你沒看見，當年燕昭王重用郭隗，劇辛、樂毅這些人才因此感恩效命；如今昭王早已屍骨化為蔓草，還有誰會再去打掃那座黃金臺呢。\n \n 【背後的小故事】\n 李白離開長安後，想起自己這些年四處投書求人引薦、在權貴門外拖著衣袍苦等的日子，也想起自己曾被玄宗降輦相迎、傳說還親手為他調羹的風光時刻。從天子座上客到如今又要低聲下氣求人賞臉，這中間的落差讓他夜裡輾轉難眠。他想起韓信、賈誼都曾被輕視過，最終才想起燕昭王築黃金臺招賢的往事，感嘆這樣珍惜人才的君王，如今上哪裡去找。",
    "zhuyin": "曳裾王門(ㄧˋ ㄐㄩ ㄨㄤˊ ㄇㄣˊ)(yè jū wáng mén)發音同\"意居王門\"，指依附權貴門下，仰承鼻息。\n 隗(ㄨㄟˇ)(wěi)發音同\"委\"，高。同「嵬」。\n 擁篲(ㄩㄥˇ ㄏㄨㄟˋ)(yōng huì)發音同\"勇會\"，拿著掃帚清理環境，以等候貴客的降臨。用以表示對貴客的敬意。\n 縈(ㄧㄥˊ)(yíng)發音同\"迎\"，圍繞、纏繞。如：「縈繞」。",
