    "id": 68,
    "dynasty": "盛唐",
    "type": "七言古詩",
    "author": "李白",
    "title": "行路難三首之三",
    "poem_notes": "【字詞與白話】\n 全詩列舉伍子胥、屈原、陸機、李斯等古代賢達功成而不得善終的例子，最後以西晉張翰「蓴鱸之思」辭官歸鄉作對比。「且樂生前一杯酒，何須身後千載名」是李白對名利的一次自我勸解。\n 白話：不要學許由去潁川水邊洗耳朵，也不要學伯夷叔齊去首陽山吃野菜充饑。與世無爭、深藏光芒、不求聞名才是可貴的，何必像雲月那樣孤高自賞呢？我看自古以來賢達之人，功成名就卻不肯及時隱退的，大多都難逃殺身之禍。伍子胥的屍體被拋棄在吳江之上，屈原最終投江於湘水之濱。陸機那樣的雄才，臨刑前又豈能保全自己？李斯感嘆退隱太遲，被腰斬時，華亭的鶴鳴再也聽不到了，上蔡東門的黃犬追兔又有什麼值得留戀？你難道沒聽說，吳地的張翰是個通達之人，秋風一起便想起江東的家鄉，立刻辭官歸去。不如及時行樂、痛飲一杯，何必追求死後千年的名聲呢？\n \n 【背後的小故事】\n 這首詩寫於李白離開長安後，借宿洛陽友人家中的一個秋日午後。他信手翻閱古籍，一一想起伍子胥、屈原、陸機、李斯等功成卻不得善終的歷史人物，又想起西晉張翰因思念家鄉美食而毅然辭官的故事，兩相對照，寫下「且樂生前一杯酒，何須身後千載名」的自我寬慰。與稍早前那首「長風破浪會有時」的豪情相比，這首詩流露出截然不同的心境——同一個李白，在同一段路上，時而堅信理想終將實現，時而又想及時行樂、放下執念。十年後，他仍未能徹底放下，又因投身永王幕府而幾乎丟了性命。",
    "zhuyin": "潁川(ㄧㄥˇ ㄔㄨㄢ)(yǐng chuān)發音同\"影穿\"，郡名。秦朝設置，漢、晉均沿置，轄境約今河南省中部及南部等地。漢治陽翟，即今河南省禹縣治；晉移治許昌，為今河南省許昌縣東北。唐廢郡，改曰許州。\n 唳(ㄌㄧˋ)(lì)發音同\"力\"，鳥類高聲鳴叫。\n 詎(ㄐㄩˋ)(jù)發音同\"具\"，豈、何，表示反問的語氣。",
