    "id": 69,
    "dynasty": "盛唐",
    "type": "七言古詩",
    "author": "李白",
    "title": "將進酒",
    "poem_notes": "【字詞與白話】\n 岑夫子、丹丘生：李白的兩位好友，隱士岑勳與道士元丹丘。「天生我材必有用」是全詩最著名的自我打氣。\n 白話：你沒看見嗎？黃河之水從天上奔流而來，奔向大海就再也不回頭。你沒看見嗎？高堂上明鏡照見的白髮令人悲傷，早晨還是黑髮，傍晚就已如雪。人生得意時就該盡情歡樂，別讓金杯空對著月亮。老天既然生下我這樣的人才，必定會有用得上的時候；千金散盡了，還會再回來。（中略）古來的聖賢都寂寞無聞，只有愛喝酒的人才留下名聲。（末句）願與你們共同消解這萬古以來的憂愁。\n \n 【背後的小故事】\n 這年李白四十七歲，仕途早已斷絕，妻子過世，錢財也花得差不多，跑去河南找兩位老友元丹丘、岑勳喝酒。酒過三巡，他喊出「天生我材必有用，千金散盡還復來」——聽起來豪氣萬千，其實是他自己都不確定的自我安慰，因為一旦承認沒用，他就徹底完了。他越喝越狂，把值錢的寶馬、貂裘都叫人拿去換酒，最後才吐露真心話：「與爾同銷萬古愁」——前面所有豪言壯語，原來都是為了遮掩心底那一份化不開的愁。",
    "zhuyin": "樽(ㄗㄨㄣ)(zūn)發音同\"尊\"，酒器。\n 岑夫子(ㄘㄣˊ)(cén fū zǐ)，岑勛，唐朝詩人李白的好友，生平不詳，多次出現在李白的詩作當中，與著名的隱士元丹丘也素有往來，後來隱居鳴皋山。\n 恣(ㄗˋ)(zì)發音同\"自\"，放縱。如：「恣情作樂」。\n 讙(ㄏㄨㄢ)(huān)發音同\"歡\"，喧譁。\n 謔(ㄋㄩㄝˋ)(xuè)發音同\"虐\"，開玩笑、戲弄調笑。",
