    "poem_notes": "【字詞與白話】\n 南熏殿：唐代宮中收藏功臣畫像之處。玉花驄：唐玄宗最鍾愛的御馬名。俗眼白：世俗的眼光冷淡、輕視。\n 白話（摘要）：曹霸出身曹魏皇族後裔，如今淪為平民。他丹青技藝高超，開元年間常被召入宮中，替凌煙閣褪色的功臣畫像重新上彩。玄宗愛馬玉花驄，滿朝畫工都畫不像，唯獨曹霸一落筆，真馬與畫馬彷彿相互對望，皇帝含笑賞金。他的學生韓幹雖也擅畫馬，卻只得其肉不得其骨。如今戰亂流離，曹霸淪落街頭替路人畫像維生，一身盛名換來的，卻是終日困頓。\n \n 【背後的小故事】\n 安史之亂後，杜甫流落成都，一家老小擠在草堂裡度日，在街角認出一位替路人畫像維生的佝僂老人，竟是當年玄宗座前的宮廷畫師曹霸。曹霸曾讓御馬玉花驄在畫紙上與真馬相互對望，滿殿驚嘆；如今卻要看窮眼睛看人的臉色，連個像樣的畫室都沒有。同樣困頓在亂世裡的杜甫，寫下這首長詩記錄兩人的相遇，最後感嘆自古盛名之下，往往纏著一生的坎坷困頓。",
