    "poem_notes": "【字詞與白話】\n 孔明廟:諸葛亮祠廟,此指夔州(今重慶奉節)武侯祠。四十圍、二千尺:形容古柏樹幹粗大、樹身高聳,非實測數字。材大難為用:才能出眾者反而難被世間所用,是全詩的核心感嘆。\n 白話:孔明廟前有一棵老柏樹,樹皮如青銅、樹根如頑石,粗要四十人合抱,高近兩千尺,黛青色直插雲天。君臣際會的時代早已過去,這棵樹仍被後人愛惜留存。雲氣連接巫峽,月色映著雪山,如此正直挺立卻無人敢砍伐使用——志士幽人不必怨嘆,自古以來材質太大反而難被世間所用。\n \n 【背後的小故事】\n 杜甫晚年病困夔州,已牙齒脫落、聽力衰退,卻仍拄杖走到武侯祠前,在孔明廟前那棵兩千年古柏下站了很久。幾年前他在成都寫過懷念諸葛亮的〈蜀相〉,這回他把目光轉向廟前這棵活了兩千年、粗壯高聳卻始終沒人敢砍下使用的老柏樹,忽然覺得它跟自己太像——空有濟世的才具與抱負,卻終生沒有真正被朝廷任用過。這棵樹活得越久越大,反而越沒人敢用,正如他自己越老越明白,才學再大,也可能一輩子只能被人瞻仰,不會被真正用上。",
