    "dynasty": "盛唐",
    "type": "七言古詩",
    "author": "杜甫",
    "title": "麗人行",
    "poem_notes": "【字詞與白話】\n 麗人：美麗的女子，此處特指楊貴妃的姐姐們。蹙金孔雀銀麒麟：用金線繡出孔雀、用銀線繡出麒麟的花紋。雲幕椒房親：雲錦搭起的帳幕，是皇親國戚才有資格使用的規格。紫駝之峰、水精之盤：駱駝峰肉做的珍饈，盛裝在水晶盤中。犀箸饜飫：用犀牛角做的筷子，吃得心不在焉、意興闌珊。炙手可熱：手一靠近就會被燙傷，形容權勢極盛，無人敢招惹。\n 白話：三月三日天氣清朗，長安曲江邊有許多美麗的女子出遊。她們神情濃豔而又疏離，肌膚細膩、身材勻稱，身上的羅衣在暮春陽光下閃著光，金線繡著孔雀、銀線繡著麒麟。她們頭上戴著翠玉葉片的頭飾垂到鬢邊，背後的珠飾把裙擺壓得妥貼合身。當中還有雲錦帳幕下的皇親國戚，被賜名為虢國、秦國夫人。廚子端出駱駝峰做的湯放在翠玉鍋中，水晶盤子裡盛著切好的魚片，她們拿著犀角筷子卻吃得意興闌珊，廚子拿鸞刀細細切著肉，忙了半天沒人動幾口。宮中派人騎馬送御膳來，馬蹄輕快不揚塵土，山珍海味絡繹不絕地送達。簫鼓聲震天，連鬼神聽了都要感動。賓客隨從眾多，都是要津顯貴之人。後來者是誰，竟姍姍來遲，到了帳前才下馬，直接踏上錦繡地毯。楊花像雪一樣落在白蘋草上，一隻青鳥叼著紅巾飛走，彷彿在替誰傳話。這個人權勢熏天，無人能及，千萬別靠近前去，免得惹丞相動怒。\n \n 【背後的小故事】\n 此詩寫於天寶十二載上巳節，杜甫親眼目睹楊貴妃姐姐虢國夫人、秦國夫人曲江遊春的奢靡場面，詩末暗諷楊國忠與虢國夫人之間人盡皆知卻無人敢言的曖昧關係。兩年多後安史之亂爆發，詩中這些人物多死於馬嵬坡兵變，這場宴席竟成了盛唐由盛轉衰前最後的縮影。",
