    "poem_notes": "【字詞與白話】\n 洛陽女兒:泛指洛陽城裡的富貴人家女子。越女:代指西施,傳說她原是若耶溪邊浣紗的貧女,後被發現送入吳宮。石崇:西晉巨富,以奢靡鬥富聞名。\n 白話:洛陽有個女兒住在對門,年方十五出頭,丈夫騎著玉勒駿馬,侍女用金盤端上鯉魚膾。她家畫閣朱樓相望,紅桃綠柳垂到屋簷,出門坐七香車,回家有九華帳迎接。丈夫富貴而驕奢,比石崇還誇張,她親自教人跳舞,珊瑚也隨手送人。夜夜笙歌到天明,妝成了也只是坐著熏香,來往的全是豪門權貴。可是誰又憐惜那容貌如玉的越國女子,貧賤地在江邊自顧自地浣紗呢?\n \n 【背後的小故事】\n 王維二十出頭尚未考取功名時,靠音樂繪畫才華出入岐王、玉真公主府邸,設法讓權貴注意到自己,深知才華不被看見便毫無意義。這首詩表面寫洛陽富家女的奢華生活,結尾卻筆鋒一轉,寫向若耶溪邊浣紗的越女——那正是傳說中西施被發現前的樣子。王維真正認同的不是那個嫁入豪門的女孩,而是這個尚未被人看見、卻同樣值得珍視的浣紗女子,因為那正是還沒被發現前的自己。",
