    "title": "老將行",
    "poem_notes": "【字詞與白話】\n 步行奪得胡馬騎：徒步就搶下敵人的戰馬騎走，形容膽識過人。一劍曾當百萬師：一柄劍曾經抵擋過百萬大軍，是誇飾手法。衛青不敗由天幸，李廣無功緣數奇：衛青一生不敗被說成是運氣好，李廣終身未能封侯被說成是命數不濟，暗諷賞罰不公。疏勒出飛泉：東漢耿恭在疏勒城被圍缺水，向井禱告而得泉水的典故。潁川空使酒：西漢灌夫在潁川閒居時借酒罵座，徒然使性子，卻無濟於事。\n 白話：年少十五二十歲時，徒步就搶下敵人的戰馬騎走，曾經射殺山裡額頭有白毛的猛虎，這樣的膽氣不輸鄴下曹彰那樣的少年英雄。他一個人轉戰過三千里疆場，一柄劍曾抵擋過百萬敵軍。漢軍衝鋒如雷霆迅猛，敵人的騎兵見了插滿蒺藜的陣勢，遠遠就崩潰逃散。衛青一生不敗，人們說是他運氣好；李廣終身未立大功封侯，人們說是他命數不濟。自從被朝廷擱置不用，他便一天天衰老下去，世事蹉跎，如今已是滿頭白髮。當年百發百中的箭術，如今左手肘上都長了贅瘤，連拉弓都困難。他只能在路邊學古人賣瓜，又在門前學前人種柳打發日子。荒涼的古樹連著冷清的小巷，他獨自面對著寂寥的空窗。他發誓要像耿恭那樣，在疏勒城絕境中求得甘泉，也不願像灌夫那樣潦倒到只能借酒罵座。這時賀蘭山下戰雲密布如陣，調兵文書日夜傳送不停，朝廷派使者到三河一帶招募壯丁，五路詔書同時徵召將軍。他擦拭鐵甲，亮得像雪一樣，握起寶劍，劍上的星紋隨光轉動。他只求能拉開燕地強弓，親手射下敵軍大將，絕不讓外族軍隊在自己君王面前耀武揚威。不要嫌棄我這個當年雲中太守是明日黃花，我還能再打一場勝仗，立一次功勳。\n \n 【背後的小故事】\n 詩中的老將並非確有其人，是王維綜合漢代名將衛青、李廣的遭遇，以及當代邊將的處境所塑造出來的典型人物。詩中衛青不敗由天幸、李廣無功緣數奇一句，歷來被認為是借古諷今，暗指唐代賞罰不公、有功者未必得賞的現實。",
