    "dynasty": "盛唐",
    "type": "七言古詩",
    "author": "王維",
    "title": "桃源行",
    "poem_notes": "【字詞與白話】\n 隈隩：山勢彎曲隱蔽的角落。攢雲樹：雲霧籠罩、聚集在一起的樹林。居人未改秦衣服：村裡的人還穿著秦朝式樣的衣服，表示他們幾百年沒有跟外界往來。游衍：遊玩、四處走動，這裡指出洞之後繼續在外遊歷。仙源：指桃花源這個世外之地。\n 白話：漁夫划船順著溪水前行，愛看兩岸桃花映著春光，兩岸古老的渡口夾著滿滿桃花。他看著紅豔的樹林，不覺得走遠了，走到溪水盡頭，還看不見人。山口隱蔽曲折，他鑽了進去，眼前忽然開闊平坦。遠遠望去，雲霧籠罩著一片聚集的樹林，走近才見千家萬戶散布在花竹之間。出洞之後即使隔著山水，他還是決心要繼續在外遊歷。他以為記得原來走過的路不會迷失，怎知山谷峰壑竟然變了樣。當時只記得走進山很深，青溪繞過幾道彎才到雲林深處。等到春天桃花水漫流的時候，再也分辨不出這個仙境入口在哪裡了。\n \n 【背後的小故事】\n 桃源行改寫自陶淵明的桃花源記，原作寫於東晉末年天下大亂之際，寄託了亂世中人們對一個不受戰禍侵擾的理想之地的嚮往。王維十九歲寫下這首長詩時，正值開元盛世，國力強盛，距離陶淵明所處的亂世已隔了數百年，但他幾乎原樣保留了故事裡最核心的恐懼，一旦離開這個與世隔絕的地方，便再也找不到回去的路。這份對失落之地的追尋與惘然，跨越了幾百年的太平與戰亂，依然打動著每一個讀到它的人。",
