    "title": "送陳章甫",
    "poem_notes": "【字詞與白話】\n 虯鬚虎眉仍大顙：捲曲的鬍鬚、如虎般濃密的眉毛，額頭又寬又大，形容相貌威武。腹中貯書一萬卷：肚子裡藏著讀過的萬卷書，形容學問淵博。不肯低頭在草莽：不肯向那些出身草莽、只靠鑽營往上爬的人低頭。東門酤酒飲我曹：在東門買酒，請我們這些朋友一起喝。心輕萬事皆鴻毛：把世間萬事都看得比鴻毛還輕。\n 白話：四月的南風把大麥吹黃了，棗花還沒落盡，梧桐葉子已經長得很長。青山早上剛道別，傍晚又能望見，他騎馬出門，聽著馬嘶聲，想起了故鄉。陳章甫這個人立身處世非常坦蕩，生得捲曲的鬍鬚、老虎般的濃眉，額頭寬大；肚子裡藏著讀不完的萬卷書，不肯向那些草莽出身、靠鑽營爬上去的人低頭。他在東門買酒請我們喝，把世間萬事都看得比鴻毛還輕，喝醉了倒頭就睡，不知道天色已經晚了，醒來又望著天邊一朵孤雲發呆。長河的浪頭洶湧，連著天色一片昏黑，渡口的船一時過不去。我這個鄭州人如今客居洛陽還沒能回家，聽說你家鄉那邊還有不少舊識，只是不知道，你昨天剛剛罷官，如今回去，大家會怎麼看你這一場。\n \n 【背後的小故事】\n 陳章甫確有其人，是李頎的好友，曾經入仕又因故被罷官，詩題與內容都透露出這層背景。李頎在東門為即將返鄉的陳章甫餞行，全詩沒有寫陳章甫如何回應罷官的處境，只留下罷官昨日今如何這句無人能答的疑問，反而更顯出他那份不拘小節的灑脫。",
