    "poem_notes": "【字詞與白話】\n 廣陵客:此處指精通琴藝、氣度不凡的琴師,其稱號讓人聯想到嵇康臨刑彈奏的名曲〈廣陵散〉。奉使:奉命出使、出公差。\n 白話:主人今晚設酒歡聚,請來一位廣陵客彈琴助興。月光照著城頭,烏鴉一半還沒歸巢,寒霜淒清,萬樹落葉,風吹入衣襟。銅爐華燭增添了光亮,他先彈一曲淥水,再彈楚妃。一聲琴音落下,滿座萬物皆靜,無人說話,星光也彷彿稀疏下來。我奉命出使清淮,路程超過千里,如今卻要說,歸隱雲山的念頭,就從這一夜開始了。\n \n 【背後的小故事】\n 李頎奉命出使清淮,途中借宿一戶人家,聽一位自稱廣陵客的琴師彈奏。這個稱號讓在座懂行的人都想起嵇康臨刑彈完〈廣陵散〉後那句絕響的慨嘆,平添幾分蒼涼。深秋寒夜,銅爐燭光下,琴聲一落,滿座忽然鴉雀無聲,連星光都彷彿跟著稀疏。李頎在那個瞬間忽然覺得千里公差毫無意義,寫下想歸隱雲山的念頭——雖然他沒有立刻辭官,但那一夜的琴聲,確實在他心裡種下了想要放下一切的種子。",
