    "type": "七言古詩",
    "author": "李頎",
    "title": "聽安萬善吹觱篥歌",
    "poem_notes": "【字詞與白話】\n 觱篥：一種以竹管製成的吹奏樂器，原是西域龜茲的樂器，經絲路傳入中原。龜茲：古代西域國名，約在今新疆庫車一帶。世人解聽不解賞：世人聽得懂曲調，卻未必真能欣賞它的門道。長飆風中自來往：像長風一樣，在天地間自在來去，不受拘束。漁陽摻：一種節奏急促的軍樂曲調，漁陽是唐代邊防重地。\n 白話：南邊山裡砍下的竹子做成觱篥，這種樂器本來是龜茲那邊傳出來的。流傳到漢地之後，曲調變得更加新奇，今晚是涼州來的胡人樂師安萬善吹給我聽。左右鄰座聽了都忍不住連聲讚嘆，遠離家鄉客居異地的人更是聽得淚流滿面。世人大多只聽得懂曲調，卻未必真能欣賞它的深意，因為它的聲音本來就像長風一樣，在天地間自在來去。一段旋律吹得像枯桑老柏在寒風裡颼颼作響，轉眼又像九隻剛孵化的鳳雛亂糟糟啼叫，接著龍吟虎嘯一齊迸發，像萬千泉水匯聚成一整片秋聲。忽然又變調吹成漁陽那帶節奏急促的軍樂，黃雲低垂，連白晝都顯得陰暗。曲調再一轉，又吹出楊柳依依的春景，滿園繁花在眼前開得鮮亮如新。除夕夜裡高堂上點著明燭，一杯美酒配著一支曲子，誰也捨不得先散席。\n \n 【背後的小故事】\n 安萬善從姓氏推測應是西域安國一帶遷居中原的胡人樂師，他手中的觱篥原是龜茲樂器，沿絲路輾轉經涼州傳入中原，成為唐代宮廷燕樂的重要樂器。李頎這首詩以極富畫面感的比喻描寫音樂，與後來韓愈的聽穎師彈琴、白居易的琵琶行並列為唐代描寫音樂的名篇。",
    "zhuyin": "觱(ㄅㄧˋ)(bì)發音同\"必\"，\n 篥(ㄌㄧˋ)(lì)發音同\"力\"，\n 龜(ㄑㄧㄡ)(guī)發音同\"秋\"，\n 茲(ㄘˊ)(zī)發音同\"詞\"，\n 颷(ㄅㄧㄠ)(biāo)發音同\"標\"，\n 颼(ㄙㄡ)(sōu)發音同\"搜\"，\n 飀(ㄌㄧㄡˊ)(liú)發音同\"留\"，\n 摻(ㄕㄢ)(chān)發音同\"山\"，",
