    "type": "七言古詩",
    "author": "岑參",
    "title": "白雪歌送武判官歸京",
    "poem_notes": "【字詞與白話】\n 瀚海：指大沙漠。轅門：軍營的大門。這首詩寫於岑參在西域北庭任判官期間，送同事歸京之作。\n 白話：北風席捲大地，白草被吹斷，塞外八月就下起了大雪。忽然像一夜春風吹來，千樹萬樹彷彿開滿了梨花。雪花飄入珠簾，沾濕了羅帳，穿著狐裘也不覺得暖，錦被也顯得單薄。將軍凍得拉不開角弓，都護的鐵甲冷得難以穿上。大漠縱橫結著百丈堅冰，愁雲慘澹凝聚在萬里長空。中軍帳裡擺酒為歸客送行，胡琴、琵琶、羌笛齊奏。傍晚雪花紛紛落在轅門，風吹著紅旗，卻被凍得不再翻動。在輪臺東門送你離去，此去滿天山都是白雪覆蓋的路。山勢迴轉，路途曲折，已看不見你的身影，雪地上只留下馬蹄踏過的痕跡。\n \n 【背後的小故事】\n 岑參在西域邊塞待了六年，同事武判官任期屆滿要回長安，他在塞外八月的大雪中為他送行。滿眼飛雪，他把它想像成千樹梨花盛開——與其說是浪漫的聯想，不如說是他說服自己撐過這個苦寒冬天的方式。送到輪臺東門，看著友人的馬隊消失在山路轉彎處，雪地上只留下漸漸被新雪覆蓋的蹄印——朋友要回去溫暖的長安，他自己還要繼續留在冰天雪地裡。這是每一個在異地送同事回家、自己卻仍要留下的人，都能懂的心情。",
    "zhuyin": "白(ㄅㄛˊ)(bái)發音同\"伯\"，白色的。\n 煖(ㄋㄨㄢˇ)(xuān)發音同\"暖\"，溫和、溫暖。「暖」的異體字。\n 衾(ㄑㄧㄣ)(qīn)，大被子。\n 黲淡(ㄘㄢˇ ㄉㄢˋ)(cǎn dàn)發音同\"慘但\"，形容昏暗不明。\n 羌(ㄑㄧㄤ)(qiāng)發音同\"槍\"，中國西北少數民族之一。舊稱為西戎，分布在今大陸地區青海、甘肅、四川一帶。\n 轅門(ㄩㄢˊ ㄇㄣˊ)(yuán mén)發音同\"元門\"，將帥的營帳或軍營的大門。\n 掣(ㄔㄜˋ)(chè)，疾速飛行。",
