    "author": "高適",
    "title": "燕歌行並序",
    "poem_notes": "【字詞與白話】\n 燕歌行:樂府舊題,多寫邊塞征戰之苦。序中\"開元二十六年,客有從御史大夫張公出塞而還者\"說明此詩緣起。玉筯:玉製筷子,此處比喻思婦淚水凝結如玉筯般晶瑩,形容悲泣之深。\n 白話:漢家邊疆烽煙又起,將士辭家出征討伐叛賊,男兒本就重視縱橫沙場的功業,天子也格外恩寵有加。大軍出榆關、過碣石,軍書飛越瀚海,敵軍狼煙照亮狼山。戰士在陣前拚死拚活,將軍帳中卻仍有美人歌舞。大漠深秋草木枯衰,孤城落日下士兵越打越少,鐵衣征人久戍不歸,家中妻子淚如玉筯。你難道沒看見沙場征戰之苦,至今仍讓人懷念愛惜士卒的李廣將軍。\n \n 【背後的小故事】\n 開元二十六年,高適的一位朋友隨御史大夫張守珪出塞歸來,講述了軍中見聞——那年張守珪其實吃了敗仗,卻隱瞞真相,向朝廷謊報大捷。高適聽完深受觸動,想起自己年輕時也曾在邊塞一帶謀求出路,深知前線之苦。他把士兵浴血奮戰、將軍帳中美人歌舞的荒謬落差寫進詩裡,結尾懷念真正與士卒同甘共苦的李廣將軍,既是懷古,也是對眼前這種看不見前線苦難的軍中風氣,最沉重的一句質問。",
    "zhuyin": "摐榆旆逶迤碣\n 戍(ㄕㄨˋ)(shù)發音同\"樹\"，以兵卒防守邊疆。\n 薊颻",
