    "title": "古從軍行",
    "poem_notes": "【字詞與白話】\n 交河：西域地名，唐代軍事重鎮，在今新疆吐魯番附近。刁斗：軍中夜間巡邏、白天煮飯兩用的銅器，敲擊可作警戒信號。公主琵琶：漢代遠嫁烏孫和親的公主所彈奏、流傳下來的琵琶曲調。玉門猶被遮：據史書記載，漢武帝曾下令玉門關禁止出征在外的士兵返鄉，違者處死。空見葡萄入漢家：暗指漢武帝派李廣利遠征大宛求汗血馬，士兵死傷慘重，最後只換回葡萄種子傳入中原。\n 白話：白天登上山頭遙望烽火台，黃昏在交河邊飲馬。行軍途中刁斗聲響，風沙遮天蔽日，遠遠聽見幽怨的琵琶聲，那是當年和親公主留下的曲調。四野荒涼，萬里看不見一座城郭，大雪紛飛連接著茫茫大漠。胡雁夜夜哀鳴著飛過，連胡人士兵聽了都忍不住落淚。聽說玉門關那邊仍然攔著不許歸鄉的士兵通行，只能把性命交給眼前這輛輕車，繼續往前衝。年年戰死的士兵屍骨，就這樣一具接一具埋葬在荒野之外，朝廷換回來的，不過是幾串葡萄種子，被帶進了長安的宮廷園林。\n \n 【背後的小故事】\n 這首詩表面寫漢代軍旅之事，實際上借古諷今，暗指唐代屢次對吐蕃、西域用兵的現實。詩末空見葡萄入漢家化用漢武帝為求大宛汗血寶馬與葡萄種，派李廣利勞師遠征、死傷慘重的典故，以士兵的犧牲換來的僅是一顆葡萄，道盡窮兵黷武的荒謬與殘酷。",
