    "title": "八月十五夜贈張功曹",
    "poem_notes": "【字詞與白話】\n 判司：唐代州府裡職位卑微的佐官。荊蠻：泛指荊州一帶偏遠地區。\n 白話（摘要）：中秋夜月色清朗，江邊沙平水靜。張署唱起這幾年遭貶謫的苦楚，九死一生才到貶所，終日提心吊膽；好不容易盼到大赦，卻被地方官員壓下名單，只調任到更卑微的職位，同輩人多半已踏上回京的路。韓愈聽得落淚，接著唱道，一年裡今晚月色最好，人生由命不由人，有酒何不痛快一飲，何必對著明月空自嘆息。\n \n 【背後的小故事】\n 韓愈因上書為饑民請命得罪權貴，被貶陽山；好友張署同時遭貶臨武。永貞元年天下大赦，兩人滿心以為能回京，途中卻得知地方官壓下了他們的名單，只調去荊蠻之地當卑微判司。中秋夜，兩人在江邊對坐，張署唱盡這幾年的委屈與希望落空，韓愈聽得落淚，反過來勸他不如就著這輪好月色，痛快喝一杯，人生由命，不是這一夜爭得來的。",
    "zhuyin": "鼯(ㄨˊ)(wú)發音同\"無\"，\n 蟄(ㄓˊ)(zhé)發音同\"直\"，動物入冬藏伏土中，不飲不食。\n 腥臊( ㄒㄧㄥ ㄙㄠ)(xīng sào)發音同\"星騷\"，魚肉的腥臭味。\n 夔(ㄎㄨㄟˊ)(kuí)發音同\"葵\"，此指古人伯夔。一種傳說中的怪獸。外形像龍，僅有一足。\n 皋(ㄍㄠ)(gāo)發音同\"高\"，此指古人皋陶。",
