    "title": "石鼓歌",
    "poem_notes": "【字詞與白話】\n 石鼓：先秦時期刻有文字的鼓形石刻，內容記述田獵、頌功。少陵、謫仙：分別指杜甫與李白，兩人皆已過世。\n 白話（摘要）：友人張籍帶著石鼓拓本來訪，勸韓愈作歌記述。相傳石鼓是周宣王平定四方後刻石紀功，歷經近兩千年風雨野火仍完好如初，字體筆勢或如快劍斷龍、或如鸞鳳飛翔、珊瑚交枝。韓愈感嘆生得太晚，未能及早見到此寶，於是上書建議將石鼓遷入太學保存供人研習，卻始終無人重視，六年間眼看石鼓日漸磨損，只能徒然嘆息，感嘆自己心意終究落空。\n \n 【背後的小故事】\n 元和初年，友人張籍帶著鳳翔石鼓的拓本來找韓愈，他一見拓本上的古老筆畫便深受震動，相傳那是周宣王刻石紀功之物，兩千年來竟毫髮無損。他多方奔走，建議朝廷將石鼓遷入太廟或太學妥善保存，卻始終無人肯為此出力，任由牧童拿石鼓敲火、牛隻在上頭磨角。韓愈終究沒能在生前促成此事，但千年後，這十面石鼓真的被好好收藏，如今就安放在故宮博物院裡。",
