    "id": 99,
    "dynasty": "中唐",
    "type": "七言古詩",
    "author": "李賀",
    "title": "金銅仙人辭漢歌",
    "poem_notes": "【字詞與白話】\n 茂陵劉郎：指漢武帝。這首詩借三國時期魏明帝下令拆遷長安漢武帝銅像一事，抒發李賀自身被迫離開長安的心情。\n 白話：長眠茂陵的漢武帝，如今只是秋風中的過客，夜裡彷彿聽見他的馬嘶鳴，天亮卻已無蹤跡。畫欄邊的桂樹依然懸著秋天的香氣，三十六座宮殿早已長滿青碧的苔蘚。魏國官員牽引銅車指向千里之外，東門的寒風刺痛了銅人的眼睛。銅人徒然帶著漢代的月光走出宮門，想起故主，清淚如鉛水般沉重地滾落。枯萎的蘭草在咸陽道上為他送行，若是上天有感情，也會為此衰老。他獨自捧著承露盤走在荒涼的月色下，渭城已經遠去，江水的聲音也漸漸微弱。\n \n 【背後的小故事】\n 李賀因父親名字犯諱，終生被剝奪考進士的資格，即使韓愈親自為他辯護也無濟於事，只能擔任九品小官，最終棄官離開長安。這首詩寫於他離京途經咸陽道時，讀到三國時魏明帝下令拆走漢武帝銅像、遠遷洛陽的史事，忽然覺得那尊被迫離開故土、一路流淚的銅人，就是他自己的寫照。他把這份被時代與規則排除在外的悲憤，全部寄託在這尊虛構的銅人身上，寫下「天若有情天亦老」這句千古名句。十年後，李賀二十七歲便英年早逝，沒能等到平反的那一天。",
