    "title": "簡簡吟",
    "poem_notes": "【字詞與白話】\n 簡簡:蘇家女兒的乳名。謫人世:被貶謫到人間,古人常用此說法安慰早夭者的家人,意指此人本非凡人。彩雲易散琉璃脆:比喻美好的事物往往容易破碎消散。\n 白話:蘇家有個小女兒名叫簡簡,容貌如芙蓉花般嬌美,眼如柳葉。十一歲學拿鏡子梳妝,十二歲能穿針繡衣,十三歲坐立行止都得體周到,雲髻梳出各種花樣,衣袖飄動帶著薔薇香氣,姿態美得難以形容。二月忽然降下反常繁霜,凍死了滿院桃李,她眼看明年就要出嫁,今年卻病死了。父母不要太傷心,這孩子本不是凡間之人,大概是天上仙女被貶謫到人間走一遭,原本就只准活十三歲。世間好東西大多不牢固,就像彩雲容易消散、琉璃容易破碎一樣。\n \n 【背後的小故事】\n 蘇家女兒簡簡從小容貌才藝出眾,親事已定,眼看明年就要出嫁,卻在一場反常的春霜後忽然病死。白居易到蘇家探望,想不出什麼話能安慰,只能說這孩子本是天上謫仙,只被允許活十三年。他說這話時,心裡想起自己三歲夭折的女兒金鑾子——那種喪女之痛他早已嚐過,始終沒有真正癒合。他其實比誰都清楚這種安慰騙不了人,詩末那句好物不堅牢、彩雲易散琉璃脆,與其說是說給蘇家聽的,不如說是他寫給自己的。",
    "zhuyin": "腮(ㄙㄞ)(sāi)發音同\"塞\"，面頰。\n 髻(ㄐㄧˋ)(jì)發音同\"記\"，盤結於頭頂或腦後的頭髮。\n 飄颻(ㄧㄠˊ)(piāo yáo)發音同\"搖\"，隨風飄動。\n 謫(ㄓㄜˊ)(zhé)，古代官吏降職調任。",
