    "poem_notes": "【字詞與白話】\n 全詩長達120句，節錄關鍵句意。這首詩寫於白居易三十五歲，源自友人聚會時的即興提議。\n 白話：（節錄）唐明皇重視美色，一心思慕傾國佳人……楊家有位女兒剛剛長成，養在深閨無人認識……天生麗質難以被埋沒，一朝被選入君王身邊……（中略：安史之亂爆發，貴妃死於馬嵬坡）君王掩面卻無法相救，回頭一看，血淚交流……（中略：玄宗派道士尋訪貴妃魂魄，終於在仙山尋得）在天願化作比翼鳥，在地願化作連理枝。天地雖長久終有窮盡之時，這份遺憾卻綿延無盡、永無止境。\n \n 【背後的小故事】\n 白居易三十五歲時與友人陳鴻、王質夫同遊仙遊寺，酒後聊起五十年前唐玄宗與楊貴妃的往事——安史之亂中，楊貴妃被迫死於馬嵬坡，玄宗晚年孤獨終老。王質夫提議：這樣的故事若無人寫下，終將被遺忘，白居易，你來寫。白居易當場答應，花幾天寫成這首一百二十句的長詩。詩一問世長安轟動，人人爭相傳誦。有趣的是，當時的白居易尚未經歷真正的生離死別，卻寫出「此恨綿綿無絕期」——多年後，他被迫與初戀湘靈永遠分離，又痛失愛女，彷彿早已替自己的人生寫下了伏筆。",
    "zhuyin": "驪宮(ㄌㄧˊ ㄍㄨㄥ)(lí gōng)發音同\"離?\"，指 華清宮 。因其建在驪山之上，故稱驪宮。\n 鼙鼓(ㄆㄧˊ ㄍㄨˇ)(pí gǔ)發音同\"皮股\"，古代軍中使用的戰鼓。\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。\n 千乘萬騎(ㄑㄧㄢ ㄕㄥˋ ㄨㄢˋ ㄐㄧˋ)(qiān chéng wàn qí)發音同\"千聖萬記\"，形容車馬眾多。\n 鈿(ㄉㄧㄢˋ)(diàn)發音同\"電\"，用金銀珠寶鑲製成的花形飾物。\n 縈紆(ㄧㄥˊ ㄩ)(yíng yū)發音同\"迎於\"，曲折旋繞。\n 旌(ㄐㄧㄥ)(jīng)發音同\"經\"，一種旗杆上裝飾著五彩羽毛的旗子。\n 躊躇(ㄔㄡˊ ㄔㄨˊ)(chóu chú)發音同\"仇廚\"，猶豫不決。\n 馬嵬(ㄇㄚˇ ㄨㄟˊ)(mǎ wéi)發音同\"馬圍\"，地名。在陝西省興平縣西二十五里。相傳唐時安祿山作亂，玄宗奔蜀，次馬嵬驛，命高力士賜楊貴妃死。\n 衾(ㄑㄧㄣ)(qīn)，大被子。\n 臨邛(ㄌㄧㄣˊ ㄑㄩㄥˊ)(lín qióng)發音同\"?窮\"，縣名。位於四川省西境，濱邛水北岸。禹貢梁州地，秦置臨邛縣，漢屬蜀郡，北周兼置邛州郡，唐改為邛州。\n 馭(ㄩˋ)(yù)發音同\"育\"，乘御、乘駕。\n 縹緲(ㄆㄧㄠˇ ㄇㄧㄠˇ)(piǎo miǎo)發音同\"縹秒\"，高遠隱忽而不明。\n 綽約(ㄔㄨㄛˋ ㄩㄝ)(chuò yuē)發音同\"啜約\"，柔媚婉約。\n 參差(ㄘㄣ ㄘ)(cān chà)發音同\"參疵\"，大約、幾乎。\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。\n 扃(ㄐㄩㄥ)(jiōng)發音同\"冋\"，安裝在門外的門閂或環鈕。\n 迤邐(ㄧˇ ㄌㄧˇ)(yǐ lǐ)發音同\"以理\"，連續不斷的樣子。\n 袂(ㄇㄟˋ)(mèi)發音同\"妹\"，衣袖。\n 睇(ㄉㄧˋ)(dì)發音同\"地\"，看、注視。\n 人寰(ㄖㄣˊ ㄏㄨㄢˊ)(rén huán)發音同\"人環\"，人世、人間。\n 釵(ㄔㄞ)(chāi)發音同\"拆\"，舊時婦女頭上所戴的首飾。形似叉，以金玉製成。\n 擘(ㄅㄛˋ)(bò)發音同\"播\"，分開、分裂。",
