    "type": "七言古詩",
    "author": "白居易",
    "title": "賣炭翁",
    "poem_notes": "【字詞與白話】\n 宮市：唐代中後期宮中派人到民間市集強行低價採購物資的制度，實為變相掠奪。輾冰轍：牛車輾過結冰的車轍。\n 白話：老人滿臉塵灰煙火的顏色，兩鬢斑白，十根手指頭都是黑的。賣炭換來的錢，不過用來買身上的衣裳和嘴裡的飯食。可憐他身上衣裳單薄，心裡卻盼著天氣更冷，好讓炭賣個好價錢。昨夜城外下了一尺深的雪，清晨他駕著炭車輾過結冰的車轍進城，牛累人餓，日頭已高，只能在市集南門外的泥地裡歇腳。這時兩個騎馬的人趕來，是宮裡的太監和隨從，手持文書口稱奉旨，硬是把一車一千多斤的炭拖走，只用半匹紅紗和一丈綾打發了事。\n \n 【背後的小故事】\n 白居易任左拾遺時，職責是替皇帝聽取民間疾苦。當時衙門裡流傳一樁真事：有農夫進城賣柴，被宮市的人攔下強行搬走，只給幾尺絹布，開口爭辯還挨了打。他想起街市上見過類似的賣炭老人，天冷得直哆嗦，心裡卻盼著更冷一點，好讓炭好賣。這樣一份卑微又心酸的指望，最後還是被宮市的人奪走。白居易把這件事寫成詩，注明苦宮市也，盼著這首詩能讓皇帝聽見百姓的苦處。",
    "zhuyin": "轍(ㄔㄜˋ)(zhé)，車輪碾過所留下的痕跡。\n 敕(ㄔˋ)(chì)發音同\"赤\"，告誡、命令。\n 叱(ㄔˋ)(chì)發音同\"赤\"，吆喝。\n 綃(ㄒㄧㄠ)(xiāo)發音同\"消\"，用生絲織成的絲織品。\n 綾(ㄌㄧㄥˊ)(líng)發音同\"靈\"，比緞細薄，有花紋的絲織品。",
