    "title": "送杜少府之任蜀州",
    "poem_notes": "【字詞與白話】\n 宦遊人：離鄉在外做官的人。「海內存知己，天涯若比鄰」被稱為送別詩的一次革命，打破了傳統依依不捨的寫法。\n 白話：長安城由三秦大地拱衛，遙望蜀地，只見一片風煙迷茫。我和你此刻的離別心情，都是同樣在外做官漂泊的人。只要四海之內還有你這位知己，即使遠在天涯也像近鄰一樣。不要在岔路口分別時，像小兒女那樣淚濕衣巾。\n \n 【背後的小故事】\n 王勃是初唐四傑之首，六歲能寫文章，十七歲便中進士，天才早熟。這首詩寫於他二十出頭、在長安任官時，送一位姓杜的朋友遠赴蜀州任職。他一反送別詩慣常的哭哭啼啼，反而說：我們本來就都是離鄉在外的人，這次分離不過是漂泊中的一段插曲；只要彼此心裡有對方，天涯也像近鄰。他寫下這句話時，還不知道自己二十多歲就會因渡海探望父親而溺水身亡——「天涯若比鄰」竟成了他與朋友之間，一句再也沒能兌現的約定。",
    "zhuyin": "闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。",
