    "title": "雜詩",
    "poem_notes": "【字詞與白話】\n 黃龍戍：唐代東北邊境的軍事據點，泛指遙遠的邊疆前線。解兵：撤兵、停戰。良人：古時妻子對丈夫的稱呼。旗鼓：軍隊的旗幟與戰鼓，代指統兵作戰。龍城：古代北方邊塞的重鎮，這裡泛指敵方據點，取勝即代表戰事結束。\n 白話：聽說黃龍戍那邊連年都沒能停戰。可憐閨房裡的月光，同時也照在丈夫駐守的軍營上。少婦今天春日裡滿懷的心意，對應著丈夫昨夜在營中的思念。誰能率領軍隊打下龍城，結束這場戰事，讓大家都能回家團圓。\n \n 【背後的小故事】\n 沈佺期是武后、中宗兩朝著名的宮廷詩人，文采出眾，曾官運亨通。這首雜詩借閨中少婦的口吻，寫邊疆戰事久久未歇造成的長期分離，是當時宮廷詩人常見的邊塞閨怨題材。相傳他後來因牽連張易之一案，被貶謫到嶺南極南的驩州，與家人天各一方多年，親身嚐到了詩裡那份等待與分離的滋味。這首寫在他被貶之前的作品，像是提前為自己後來的人生寫下了一則預告。",
    "zhuyin": "戍(ㄕㄨˋ)(shù)發音同\"樹\"，以兵卒防守邊疆。\n 閨",
