    "title": "贈孟浩然",
    "poem_notes": "【字詞與白話】\n 軒冕：古代官員乘坐的車子與戴的官帽，代指官位與功名。中聖：喝清酒喝到微醺，古人戲稱清酒為聖人、濁酒為賢人，中聖即喝醉了清酒。\n 白話：我深深敬愛孟先生，他瀟灑的風度天下皆知。年輕時就放下官位功名，到老年仍隱居在松林雲霧之間。常常醉臥在月下，也不願委身侍奉君王，一心沉醉於賞花。他的品格像高山一樣讓人仰望不盡，我只能在此拱手，承接他清高的芬芳。\n \n 【背後的小故事】\n 太白剛出蜀在安陸落腳，聽襄陽人一直提起孟浩然，說這人年輕時放下官帽官服，一頭栽進鹿門山隱居。太白還沒見過本人就已經把他當偶像，這在向來自視甚高的太白身上很少見。兩人相識後，一起喝酒賞花，太白發現孟浩然是真心放下了仕途，不是裝出來的灑脫。這份仰慕維持了很多年，幾年後太白在黃鶴樓上送孟浩然坐船遠行，望著船影消失都捨不得移開視線。",
