    "title": "渡荊門送別",
    "poem_notes": "【字詞與白話】\n 荊門：地名，在今湖北宜昌一帶，是蜀地與中原的分界。海樓：海市蜃樓，形容雲氣蒸騰結成的樓閣幻影。憐：此處作愛惜、捨不得解，不是憐憫。\n 白話：渡過遠方的荊門，來到楚地遊歷。山巒隨著平原展開漸漸消失，江水流入無邊的原野。月亮倒映水中像飛下來的天鏡，雲氣蒸騰結成海市蜃樓般的景象。我仍然愛戀著故鄉流出的江水，它伴著我的行舟送出萬里之遠。\n \n 【背後的小故事】\n 二十五歲那年，李白第一次離開四川出外闖蕩，船行到荊門，兩岸的山忽然往後退開，江水鋪展成一片大荒野。這種開闊是他在蜀地山谷裡從沒見過的。夜裡他看見月亮倒映江面像飛下的鏡子，白天雲氣結成海市蜃樓。可是船到夜深，他還是忍不住想家，那條江水正是從蜀地一路流出來的，等於故鄉的水陪他走完這一程。這一走，李白此後三十幾年再也沒回過蜀地。",
    "zhuyin": "荊門(ㄐㄧㄥ ㄇㄣˊ)(jīng mén)發音同\"經門\"，山名。（1）位於湖北省宜都縣西北五十里，與虎牙山相對。形勢險要，自古為重要關塞。（2）位於湖北省荊門縣南。",
