    "poem_notes": "【字詞與白話】\n 孤蓬：隨風飄轉的蓬草，比喻漂泊無依的遊子。這位「友人」的姓名史料未載，後人無從考證。\n 白話：青翠的山巒橫臥在城的北郭，清澈的流水環繞著城的東邊。這裡一旦分別，你就要像孤獨的蓬草一樣，隨風飄向萬里之外。天上的浮雲，正如遊子漂泊不定的心意；西沉的落日，也似老朋友依依不捨的情誼。揮一揮手，從此各自離去，連馬兒也蕭蕭嘶鳴，彷彿替我們不捨分離。\n \n 【背後的小故事】\n 李白一生輾轉漂泊，二十五歲離開四川後便再也沒有回去過，此後在長安、山東、洛陽等地輾轉，始終沒有一個真正意義上的家。這首詩寫他騎馬送一位友人出城，兩人並肩走過青山白水，話越來越少。送別途中，李白望著天邊隨風飄移的浮雲，聯想到友人漂泊不定的心情，也想到自己何嘗不是那株被風吹到各處的孤蓬。分別時兩匹馬仰頸長嘶，彷彿替兩個不好意思落淚的男人，先哭了出來。這位友人是誰，史料已無從考證，但那個黃昏兩匹馬不肯分開的嘶鳴聲，卻流傳了一千三百年。",
    "zhuyin": "郭(ㄍㄨㄛ)(guō)，城牆外再築的一道城牆。即外城。\n 遶(ㄖㄠˋ)(rào)發音同\"繞\"，圍繞。",
