    "poem_notes": "【字詞與白話】\n 綠綺：相傳是漢代蜀人司馬相如所彈名琴之名，此處借指蜀僧懷抱的古琴。霜鐘：傳說中山中會隨霜降而鳴的鐘，此處指山寺的鐘聲。\n 白話：蜀地僧人懷抱著綠綺琴，從峨眉山西邊下山而來。他為我揮手一彈，琴聲如同聽見千山萬壑的松濤。我的心像被流水洗淨，餘音融入山寺隨霜而鳴的鐘聲裡。不知不覺青翠山色已入暮色，秋雲一層一層暗了下來。\n \n 【背後的小故事】\n 李白中年以後在異鄉聽到一個從峨眉山下來的和尚彈琴，那張琴名叫綠綺，這個名字他從小在蜀地就聽過，相傳是漢代同鄉司馬相如彈過的名琴。一曲彈完，他覺得整顆心像被流水洗過，連日趕路的疲憊全沖乾淨了。他坐在那裡直到暮色染暗山色都沒察覺。離家幾十年、再沒回過蜀地的李白，那個下午，一個陌生和尚用一張借了老鄉名字的琴，替他把峨眉山的風送到了眼前。",
    "zhuyin": "綺(ㄑㄧˇ)(qǐ)發音同\"起\"，華麗、美麗。\n 壑(ㄏㄨㄛˋ)(hè)發音同\"或\"，谷、溝。",
