    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "杜甫",
    "title": "春望",
    "poem_notes": "【字詞與白話】\n 渾欲不勝簪：形容頭髮稀疏得幾乎插不住髮簪。這首詩寫於安史之亂期間，杜甫被困長安、與家人失聯之時。\n 白話：國都淪陷了，但山河依舊存在；長安城裡春天到來，草木卻長得雜亂深密。感傷時局，看見花開也忍不住落淚；痛恨離別，聽見鳥鳴也讓人心驚。戰火已經連續延燒三個月，一封家書抵得上萬兩黃金那樣珍貴。愁得搔頭，白髮越搔越少，簡直連髮簪都插不住了。\n \n 【背後的小故事】\n 安史之亂爆發後，杜甫將妻兒安置在鄜州老家，自己隻身北上投奔新即位的唐肅宗，途中卻被叛軍俘虜押回長安，軟禁近一年。這首詩寫於被困期間的一個春天，他登高望向妻兒所在的方向，音訊全無，戰火已燒了三個月，家書一封也送不到。長安城殘破，宮殿荒蕪，草木叢生，他看花流淚、聞鳥心驚，天天摸著日漸稀疏的頭髮發愁。「家書抵萬金」放到今天，就是等一則家人平安訊息等到心慌意亂的心情——這首詩沒有寫戰爭的殘酷畫面，寫的只是一個父親對家人安危的牽掛。",
    "zhuyin": "簪(ㄗㄢ)(zān)，插、戴。古人用來綰髮或固定頭冠的頭飾。",
