    "title": "春宿左省花隱掖垣暮",
    "poem_notes": "【字詞與白話】\n 掖垣：宮中側門的矮牆，這裡指門下省（左省）所在的宮牆一帶。啾啾：鳥鳴聲。金鑰：宮門開鎖的鑰匙聲，這裡指清晨開啟宮門的動靜。玉珂：馬勒上的玉飾，這裡借代官員上朝時的馬鈴聲。封事：密封起來、只呈皇帝親自拆閱的奏章。\n 白話：暮色中，花叢隱沒在宮牆邊，幾隻歸巢的鳥啾啾叫著飛過。星光彷彿隨著千家萬戶的燈火晃動，月色貼著宮闕那頭的天空，顯得格外皎潔明亮。他睡不著，聽著風聲，恍惚間想像清晨開宮門的鑰匙聲、百官上朝的馬鈴聲。明天早上有一份密封的奏事要呈上，他一次次問值夜的人，現在到什麼時辰了。\n \n 【背後的小故事】\n 這首詩寫於至德二年，杜甫剛從叛軍占領的長安逃出來，投奔在鳳翔的唐肅宗。他當時衣衫破爛、腳穿草鞋，史書記載他「麻鞋見天子，衣袖露兩肘」，皇帝感其忠心，封他為左拾遺——一個能在皇帝身邊直言進諫的小官。這是杜甫這輩子少數真正貼近權力核心的時刻，可惜好景不長，幾個月後他就因替房琯辯護觸怒肅宗，被貶到華州，從此再也沒能回到朝廷中樞。",
