    "poem_notes": "【字詞與白話】\n 金光門:唐長安城西面城門之一。至德二載:公元757年,唐肅宗年號。西郊胡正繁:指當時長安西郊叛軍勢力猖獗。未招魂:形容驚魂未定,靈魂彷彿還沒完全招回身體。\n 白話:這條路過去曾是我歸順朝廷的路,那時西郊到處都是叛軍。至今想起仍嚇得肝膽俱裂,魂魄彷彿還沒招回。如今好不容易回到京城,這次調任,難道真是皇上的本意嗎?我沒有才能,一天天衰老下去,勒住馬回望長安城數不清的宮門。\n \n 【背後的小故事】\n 至德二年,長安淪陷於叛軍之手,杜甫冒死從金光門逃出城,穿越叛軍哨卡投奔在鳳翔的肅宗,因此獲授左拾遺一職,滿以為抱負終於有了著落。第二年他因替被貶的宰相房琯辯護觸怒肅宗,被以移官之名貶為華州司功參軍,離京時又一次經過同一道金光門。兩年前拚死想進城見皇帝,兩年後卻被禮貌地送出城——同一道門,見證了他人生中兩種截然相反的命運轉折,這段際遇有明確史書記載,並非杜撰。",
