    "title": "月夜憶舍弟",
    "poem_notes": "【字詞與白話】\n 露從今夜白：指白露節氣，從這一夜起露水開始凝結變白。「月是故鄉明」道出離家之人共同的錯覺——月亮明明一樣，故鄉的卻總覺得比較亮。\n 白話：戍樓的鼓聲響起，宵禁開始，路上斷絕了行人；秋夜邊塞傳來一聲孤雁的鳴叫。從今夜起就是白露節氣了，可我總覺得故鄉的月亮比較明亮。弟弟們都因戰亂四散各地，連個可以打聽他們生死的家都沒有了。寄出去的家書常常送不到，何況這場戰爭至今還沒有停歇。\n \n 【背後的小故事】\n 杜甫有四個弟弟，安史之亂把他們打散到四個方向，生死不明。這年秋天他剛丟了官職，帶著家人狼狽逃到秦州，某個失眠的夜晚走出屋子看月亮，聽見邊塞戍樓的鼓聲和一聲孤雁鳴叫，忽然想起今夜正是白露節氣。他抬頭望著同一輪月亮，卻覺得故鄉的月光比較亮——那是記憶替故鄉加上的濾鏡。他最掛心的是四散的弟弟們，連個可以打聽他們死活的地方都沒有，寄出的信也常常石沉大海。這首詩沒有寫誇張的悲劇想像，寫的只是一種持續發作的、日常的牽掛與無助。",
    "zhuyin": "戍鼓(ㄕㄨˋ ㄍㄨˇ)(shù gǔ)發音同\"樹股\"，古時守邊軍士所擊的鼓聲。",
