    "poem_notes": "【字詞與白話】\n 天末：天邊，指極遠的地方，這裡指秦州。魑魅：山林裡的鬼怪，比喻害人的小人。汨羅：汨羅江，屈原投江自盡之處。\n 白話：涼風從天邊吹起，不知道你近來心緒如何。大雁幾時才能捎來你的消息，江湖上秋水正深，路途想必艱難。才華越高的人，命運偏偏越坎坷；小人卻總愛看人倒楣受苦。你此刻大概正經過屈原投江的地方吧，若真能與他的冤魂對話，不妨把這首詩也投給汨羅江，讓他知道你的委屈。\n \n 【背後的小故事】\n 七五九年秋，杜甫在秦州聽聞李白因永王璘案被判流放夜郎，寫下這首詩替好友抱不平。兩人十五年前曾同遊梁宋，交情深厚。杜甫想像李白途經湘江一帶，或許能與屈原的冤魂對話。他不知道的是，李白其實已在此前於白帝城遇赦，正順流而下高唱著「朝辭白帝彩雲間」，他為一個早已無事的朋友，白白揪心了很久。",
