    "id": 121,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "杜甫",
    "title": "奉濟驛重送嚴公四韻",
    "poem_notes": "【字詞與白話】\n 遠送：一路送到很遠的地方，暗示捨不得，送了不只一次。青山空復情：青山依舊含情，卻什麼都留不住人，是徒然的深情。杯重把：重新舉杯共飲，這裡是隨口一問，卻成了日後無法兌現的約定。列郡謳歌惜：嚴武治理過的郡縣百姓，聽聞他要離開都唱歌相送，捨不得他。三朝出入榮：嚴武歷經三位皇帝重用，出入朝廷都是榮耀。江村獨歸處：杜甫要獨自回到江邊那個叫草堂的小村子。寂寞養殘生：自嘲往後大概只能一個人在寂寞裡度過剩下的歲月。\n 白話：這一路送你送到這麼遠，才要真正道別，眼前青山彷彿也懂得離情，卻只能徒然地佇立著，什麼都留不住。不知道什麼時候才能再舉杯同飲，昨夜我們還一起在同一片月光下走著。你治理過的郡縣百姓都捨不得你，唱著歌相送；你歷經三朝天子的器重，這一去是真正的榮耀。而我只能獨自回到江邊那個村子，在寂寞裡度過剩下的日子。\n \n 【背後的小故事】\n 杜甫寓居成都草堂那幾年，全靠嚴武照應才安穩下來。嚴武被召回京城升任京兆尹，杜甫捨不得，一路從成都送到綿州奉濟驛，這已經是第二次相送了。臨別隨口問一句幾時能再舉杯，兩人誰也沒把這句話當真的離愁，只當是尋常的客套。沒想到幾年後嚴武真的又回到成都接濟杜甫，讓他過了一段安穩日子，卻在不久之後暴病去世，年僅四十歲。杜甫從此離開成都，一路漂泊，再也沒能等到那杯重新舉起的酒，最終死在湘江一條小船上。",
