    "poem_notes": "【字詞與白話】\n 房太尉：房琯，曾任宰相，兵敗後屢遭貶謫，卒於閬州。謝傅：東晉謝安，曾在強敵壓境時鎮定下棋。徐君：春秋時徐國國君，季札許諾贈劍卻未及開口，徐君死後季札仍解劍掛其墓前樹上。\n 白話：漂泊他鄉又要繼續奔波，勒馬暫停向這座孤墳道別。眼淚沾濕了墳前所有的泥土，天邊低垂的雲也斷斷續續飄著。想起你曾像謝安那樣鎮定地與人對弈，我也要像季札一樣，把心裡的承諾兌現在你墓前。只聽見林間花落，黃鶯的啼聲一路送我離開。\n \n 【背後的小故事】\n 房琯是杜甫的恩主與摯友。安史之亂中房琯兵敗被貶，杜甫不顧自身安危上疏營救，因此觸怒肅宗，被貶為華州司功參軍，仕途從此一蹶不振。房琯762年病逝於閬州僧舍，杜甫特意繞道前去祭拜。他自比古代重信守諾、為亡友掛劍的季札，即使房琯已聽不見，這份心意還是要送到——這是一次用整個官運換來的、不後悔的仗義執言。",
