    "title": "旅夜書懷",
    "poem_notes": "【字詞與白話】\n 危檣：高聳的桅杆。天地一沙鷗：杜甫用來自況的意象，形容自己漂泊無依。\n 白話：岸邊細草在微風中輕搖，一艘孤舟在夜裡停靠，桅杆高聳。星光低垂，平野顯得格外遼闊；月光湧動，映照著大江奔流。難道名聲是靠文章顯揚的嗎？做官本該因年老多病而退休。四處漂泊的我像什麼呢？就像天地間一隻孤獨的沙鷗。\n \n 【背後的小故事】\n 杜甫在成都靠好友嚴武照顧過了幾年安穩日子，嚴武驟逝後失去依靠，只能帶著家人乘船東下，另尋出路。那夜船停江上，一家人都睡了，唯獨他醒著，望著低垂的星空與湧動的月光，忽然覺得天地浩大、自己渺小。他一生想以政績留名，卻屢遭挫折，反倒因詩留名——這並非他所願，於是把自己比作找不到棲身之處的沙鷗。他不知道自己五年後就會客死湘江舟中，更不知道這首自嘲失敗的詩，會流傳千年，成為所有中年失意者的心情寫照。",
    "zhuyin": "危檣(ㄨㄟˊ ㄑㄧㄤˊ)(wēi qiáng)發音同\"圍強\"，船上高聳的桅竿。",
