    "title": "登岳陽樓",
    "poem_notes": "【字詞與白話】\n 坼：裂開，這裡形容吳楚兩地的地界像被這片大水硬生生撕裂開一道縫。乾坤日夜浮：天地彷彿日夜都漂浮在水面上晃動，形容洞庭湖浩大到讓人分不清天地的界線。老病有孤舟：年老又生病，只剩一條孤零零的小船當作全部的家。憑軒涕泗流：靠著窗欄，眼淚鼻涕一起流下來。\n 白話：早就聽過洞庭湖水的名氣，今天終於親自登上岳陽樓。吳地和楚地在東南方彷彿被這片大水硬生生撕開一道裂縫，天地日夜都漂浮在水面上晃動。親戚朋友連一個字的音信都沒有，自己又老又病，身邊只有一條孤零零的小船。北方還在打仗動亂，我靠著窗欄，忍不住眼淚直流。\n \n 【背後的小故事】\n 這是杜甫晚年最後幾年的作品。嚴武死後他離開成都，沿長江一路往下漂，經過夔州、江陵，終於在冬天抵達岳陽，站上這座他年輕時就聽過名氣卻從沒機會親眼看過的樓。眼前的洞庭湖浩大得驚人，可他一低頭，只剩自己又老又病，親友音信全無，一條小船就是全部的家當。北方戰事未平，他趴在窗欄邊哭了出來。兩年後他真的死在離岳陽不遠的湘江一條小船上，跟詩裡寫的境況幾乎一模一樣。",
