    "title": "春夜喜雨",
    "poem_notes": "【字詞與白話】\n 乃：於是、就。潛：悄悄地、不張揚地。錦官城：成都的別稱，因古代錦緞織造業發達而得名。\n 白話：好雨懂得應時而降，正是春天萬物萌發的時節。它隨著夜風悄悄滲入，滋潤萬物卻毫無聲息。田間小路一片漆黑，只有江上的船燈獨自亮著。清晨看那被雨水打溼的花朵，整座錦官城的花都顯得更加沉重。\n \n 【背後的小故事】\n 杜甫在成都浣花溪邊蓋了草堂，總算有處安穩住下的地方。一夜他被雨聲吵醒，聽出這雨隨風悄悄滲入泥土，一點都不張揚。他這輩子見過太多場大雨，戰亂裡的雨、逃難路上的雨、兒子餓死那年的雨，這一場卻不一樣，草堂周圍那幾畦菜地是他跟家人的口糧，這場雨等於替全家把明天的飯補上了。隔天清晨他出門看，花瓣被打溼，沉甸甸地垂著。這是杜甫存世詩裡少數題目就帶著喜字的一首。",
