    "title": "輞川閑居贈裴秀才迪",
    "poem_notes": "【字詞與白話】\n 接輿醉：接輿是楚國裝瘋拒官的隱士，這裡借指裴迪醉後狂放的樣子。狂歌五柳前：在自己家門前放聲高歌，五柳借用陶淵明自號五柳先生的典故，暗示這扇柴門也有隱士風骨。\n 白話：寒山一天天轉成蒼翠色，秋天的溪水日日潺潺流著。我拄著拐杖站在柴門外，迎著晚風聽暮蟬鳴叫。渡口那邊剩下一點落日餘光，遠處村落升起一縷孤零零的炊煙。又碰上你像接輿一樣喝醉了，在我這五柳先生的門前放聲高歌。\n \n 【背後的小故事】\n 王維晚年身居高位，卻在長安附近的輞川買了一處別業，一邊做官一邊過著半隱居的日子。裴迪是他晚年最要好的忘年交，兩人常常同遊唱和，後來留下整整一組輞川集。這天秋天傍晚，王維倚杖站在柴門外聽蟬看落日，裴迪不知在哪兒喝醉了，一路狂歌著走來。王維看著這個放浪的年輕朋友，忽然想起楚國那個裝瘋拒官的接輿，也想起自己這扇柴門，竟像陶淵明門前種的那五棵柳樹。他知道自己不是真正的隱士，還要回朝廷做官，可只要輞川還有這扇門，他這顆心就有地方可以安放。",
    "zhuyin": "潺湲墟輿",
