    "title": "山居秋暝",
    "poem_notes": "【字詞與白話】\n 王孫：這裡反用《楚辭·招隱士》「王孫兮歸來，山中兮不可久留」之意，表達自己甘願留在山中、不再留戀官場的心境。\n 白話：空寂的山中剛下過一場新雨，傍晚時分天氣已透出秋意。皎潔的明月透過松林灑下光輝，清澈的泉水在山石上淙淙流淌。竹林裡傳來喧鬧聲，是洗衣的女子結伴歸來；蓮葉輕輕搖動，是漁船順流而下。任憑春天的花草凋謝吧，我這王孫自願留在山中。\n \n 【背後的小故事】\n 王維早年仕途順遂，卻在安史之亂中被叛軍強迫任偽職，戰後幾乎被治罪，靠弟弟王縉求情才撿回一命。經歷這場劫難後，他雖仍在朝為官，卻把心思漸漸移往終南山下的輞川別業。這首詩寫於一個雨後的秋日傍晚，他望著松間明月、石上清泉、浣衣歸來的女子與順流而下的漁舟，忽然想起古人勸隱士歸城做事的詩句，卻覺得反過來說才對——不管外頭春光是否消逝、朝廷有什麼變動，他就是想留在這裡。全詩沒有一個「我」字，卻用眼前所見的一切，寫下了他對官場心灰意冷、甘願歸隱山林的真心話。",
    "zhuyin": "浣(ㄏㄨㄢˇ)(huàn)發音同\"緩\"，洗滌、洗濯。",
