    "title": "歸嵩山作",
    "poem_notes": "【字詞與白話】\n 清川：清澈的河流。帶：像帶子一樣環繞。閒閒：從容不迫的樣子。迢遞：遙遠的樣子。閉關：關上大門，這裡指歸隱、不再過問世事。\n 白話：清澈的溪流環繞著長滿雜草的岸邊，車馬緩緩前行，一點也不慌張。流水好像懂得他的心意，傍晚的歸鳥也與他一同返回。經過一座荒涼的城池，緊臨著古老的渡口，夕陽灑滿了秋天的山巒。到了遙遠的嵩山腳下，他終於到家，把門關上，不再過問世事。\n \n 【背後的小故事】\n 這首詩一般認為寫於張九齡罷相前後那段時間。張九齡是王維仕途上少有的真心提攜者，曾將他拔擢為右拾遺；張九齡被李林甫排擠出朝、貶往荊州後，王維在政治上失去了唯一的靠山。與其說他是被貶謫或排擠而走，不如說他是在情勢還沒惡化之前，主動選擇暫時抽身，前往嵩山歸隱。這種「先一步關門」的姿態，後來也成為他中晚年半官半隱生活的預告。",
