    "id": 129,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "王維",
    "title": "終南山",
    "poem_notes": "【字詞與白話】\n 太乙近天都：終南山古名太乙，離長安皇城很近。白雲迴望合：走進山裡回頭望，白雲已經在身後層層合攏，把來時的路都遮住了。青靄入看無：遠遠看是一片青色霧氣，走近了卻什麼都看不見。分野中峰變：同一座山，主峰兩側分屬不同地界。隔水問樵夫：隔著溪水，向對岸的樵夫問路投宿。\n 白話：終南山古名太乙，離長安皇城很近，山勢連綿彷彿一路接到海邊。走進山裡回頭望，白雲已經層層合攏擋住來路；遠處那片青色霧氣，走近了卻什麼都看不見。同一座山，主峰兩邊分屬不同地界，山谷裡陰晴天氣也各不相同。天色漸暗想找個地方投宿，只能隔著溪水，向對岸砍柴的人問路。\n \n 【背後的小故事】\n 那時候長安城裡流行一種怪風氣，一些人跑進終南山搭個草棚假裝隱居，其實是等著朝廷派人來徵召做官，人稱終南捷徑。王維自己也在朝中做官，他這天進山，卻不是去演給誰看的，只是想找個下午讓自己真的渺小一次。他一路走進雲霧裡，回頭已經看不清來路，同一座山兩側竟是不同的天氣。天色漸暗，他這才發現自己走遠了，認不出方向，只能隔著溪水，向一個素不相識的樵夫喊話問路。一個習慣被人求教的朝廷官員，難得能這樣低下頭問一句簡單的路，終南山的浩大，也讓他重新記起自己有多小。",
    "zhuyin": "隅\n 靄(ㄞˇ)(ǎi)發音同\"矮\"，煙霧、雲氣。\n 壑(ㄏㄨㄛˋ)(hè)發音同\"或\"，谷、溝。",
