    "poem_notes": "【字詞與白話】\n 窮通理：指窮困與顯達的道理，即人生際遇的哲理。「君問窮通理，漁歌入浦深」以漁歌漸行漸遠作結，避而不答，留下無盡餘韻。\n 白話：晚年只喜好清靜，世間萬事都不再關心。自問沒有什麼安邦定國的長遠計策，只知道要返回山林舊居。松林間的清風吹開了我腰間的衣帶，山中的明月照著我彈琴。你問我窮困與顯達的道理是什麼，我卻只聽見漁夫的歌聲，漸漸消失在水灣深處。\n \n 【背後的小故事】\n 經歷安史之亂被迫任偽職、戰後幾乎被治罪的劫難後，王維雖仍掛著官職，心思早已移往輞川山居。這首詩是他回覆一位張姓縣尉來信詢問人生哲理時所寫——他收到信後，望著夕陽西下、明月東升，解開衣帶讓山風吹拂，彈起琴來，卻始終無法用言語回答對方的問題。最終他只寫下自己晚年只求清靜、萬事不再關心的心境，把「窮通之理」這個大哉問，交給遠處漸行漸遠的漁歌作答——有些道理，是要等對方自己走到這一步，才會真正明白的。",
