    "author": "王維",
    "title": "過香積寺",
    "poem_notes": "【字詞與白話】\n 古木無人徑：古老的樹林裡連一條有人走過的小路都沒有。泉聲咽危石：泉水在陡峭的石頭縫裡擠著流，發出像哽咽一樣的聲音。日色冷青松：陽光被一片青翠的松林擋住，照在地上都帶著涼意。安禪制毒龍：毒龍是佛教典故裡指內心的欲念與煩惱，這裡指靠打坐禪定壓下心中的躁動。\n 白話：不知道香積寺到底在哪，只顧著往雲霧繚繞的山峰裡走了好幾里路。古老的樹林裡連一條有人走過的小路都沒有，深山裡傳來鐘聲，卻聽不出是從哪個方向敲來的。泉水在陡峭的石頭縫裡擠著流，發出哽咽般的聲音；陽光被青翠的松林擋住，落在地上帶著涼意。傍晚時分面對一片空蕩蕩的潭水，就靠打坐禪定，把心裡那條躁動的毒龍壓下去。\n \n 【背後的小故事】\n 王維這個名字本來就是從佛經維摩詰經裡取來的，他自小與佛教有緣，晚年更是常常獨自焚香打坐。這天他特意找一處從沒去過的寺，想給自己找一塊真正安靜的地方，卻連路都認不清，一路穿林深入，連鐘聲從哪個方向傳來都聽不出。泉水在石縫裡哽咽，陽光被松林擋成一片涼意，他走到日頭快落下時，眼前忽然開闊出一片空潭。他知道自己心裡那條毒龍這些年從沒真正安靜過，官場的進退、身邊人事的變化，總會時不時把它惹醒。他在潭邊坐下，把呼吸放慢，一點一點把那條龍重新壓回去，直到天黑透都沒有起身。",
    "zhuyin": "咽",
