    "title": "漢江臨眺",
    "poem_notes": "【字詞與白話】\n 楚塞三湘接：楚地邊塞與三湘之地在遠方相接。荊門九派通：荊門一帶九條支流全匯進這條江裡。江流天地外：江水浩浩蕩蕩，彷彿流出天地的界線之外。郡邑浮前浦：遠處的城邑彷彿漂浮在江面前方。留醉與山翁：山翁是晉朝愛喝酒的襄陽太守山簡，這裡指願意找這樣的酒友一起痛飲。\n 白話：楚地邊塞與三湘之地在遠方相接，荊門一帶九條支流全匯進這條江裡。江水浩浩蕩蕩，彷彿流出天地之外；遠山忽隱忽現，若有若無。遠處城邑彷彿漂浮在江面前方，波瀾起伏，連天空都好像被震得晃動。襄陽這裡風光這麼好，真想留下來，找個像山簡那樣的酒友痛痛快快醉一場。\n \n 【背後的小故事】\n 王維這回因公務經過襄陽一帶，順路登高眺望漢江，眼前的景象大到讓他一時說不出話，江水彷彿流出天地之外，城邑像漂浮在水面前方的小點。可就在這麼壯闊的時候，他腦子裡冒出來的，卻是幾百年前一個愛喝酒的老太守。晉朝的山簡當年鎮守襄陽，常常在習家池邊喝到爛醉，被下屬用車拉著顛顛倒倒送回府裡，清醒的時候沒幾回，卻沒人覺得他失職。王維望著眼前的襄陽城，忽然很想效仿他，找個懂得縱情山水的老朋友，把這片壯闊江山配著酒一起喝下去。",
    "zhuyin": "荊(ㄐㄧㄥ)(jīng)發音同\"經\"，邑",
