    "id": 134,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "王維",
    "title": "終南別業",
    "poem_notes": "【字詞與白話】\n 空自知：獨自知曉，不與人分享、不刻意記錄。「行到水窮處，坐看雲起時」被視為中國人「絕處不慌」的人生哲學代表句。\n 白話：中年以後頗喜愛修道，晚年就在終南山邊安家。興致來時常常獨自前往，遇到美好的事，只有自己心裡知道。走到溪水的盡頭，就坐下來看雲霧升起。偶然遇見山林裡的老翁，談笑起來，竟忘了回家的時間。\n \n 【背後的小故事】\n 王維早年仕途順遂，卻在安史之亂中被叛軍強迫任偽職，戰後幾乎被治罪，經歷這場劫難後看透官場，選擇半官半隱的生活，在藍田輞川置業。這首詩寫於他晚年某次獨自上山：沿著溪流走，走到水源盡頭，路斷了，他索性坐下看雲升起，途中偶遇一位打柴老翁，兩人聊到忘了時間。「行到水窮處，坐看雲起時」不是說絕境會逆轉，而是告訴人：走不通的時候，不必慌，坐下來就是了。",
    "zhuyin": "陲(ㄔㄨㄟˊ)(chuí)發音同\"錘\"，邊界、邊疆。\n 叟(ㄙㄡˇ)(sǒu)，稱謂。對老年男子的尊稱。",
