    "id": 135,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "王維",
    "title": "使至塞上",
    "poem_notes": "【字詞與白話】\n 都護：唐代邊疆軍政長官。「大漠孤煙直，長河落日圓」是全詩最著名的兩句，被譽為描寫塞外風光的千古絕唱。\n 白話：獨自駕著一輛車前往邊塞慰問，途經的屬國早已過了居延。像隨風而飛的蓬草一樣飄出漢地關塞，又像北歸的大雁一樣飛入異族的天空。浩瀚沙漠中一縷孤煙筆直升起，蜿蜒長河上一輪落日渾圓低垂。到了蕭關遇見偵察的騎兵，得知都護此刻正在燕然山前線。\n \n 【背後的小故事】\n 王維一向以描寫江南山水、松林細泉聞名，這是他這輩子唯一一次深入大漠。當時朝中張九齡一派被李林甫排擠，王維作為張九齡提拔的人，被派往西北邊塞慰問剛打贏吐蕃的河西節度使，名義上是榮譽差事，實則是變相的邊緣化。一路上他望著北飛的大雁，覺得自己就像被連根拔起、隨風飄零的蓬草。行至大漠深處，他被眼前浩瀚無垠、毫無遮蔽的孤煙與落日震撼，第一次見識到與江南水鄉截然不同的壯闊景象，寫下這兩句千古絕唱。此後他再未寫過大漠，晚年詩作仍回歸松風山月的輞川風光。",
