    "id": 137,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "孟浩然",
    "title": "與諸子登峴山",
    "poem_notes": "【字詞與白話】\n 人事有代謝：人和事情總是一代換一代，不斷更替。水落魚梁淺：江邊那片叫魚梁的沙洲，水位低的時候露出淺淺一片。天寒夢澤深：天冷的時候，遠處雲夢澤那一帶看起來水深得很。羊公碑：晉朝荊州都督羊祜生前深得民心，死後百姓在他常登臨的峴山立碑紀念，相傳後人讀碑無不落淚，稱墮淚碑。\n 白話：人和事情總是一代換一代不斷更替，來來去去就成了古今。江山還留著前人的遺跡，我們這一代人又登臨到這裡。水位低的時候，魚梁沙洲露出淺淺一片；天冷的時候，遠處雲夢澤看起來水深得很。羊公碑上的字還在，讀完之後，眼淚已經沾濕了衣襟。\n \n 【背後的小故事】\n 孟浩然是襄陽本地人，峴山他從小爬到大。這天跟幾個朋友又一起登山，爬到半山看江景，忽然想起自己站的這塊地，幾百年前也曾經站過一個人，晉朝的荊州都督羊祜。羊祜鎮守襄陽時待百姓寬厚，深得民心，死後百姓感念他，在他生前常登臨的地方立了一塊碑，相傳後人讀碑時想起這樣一個好官已經不在了，沒有一個不掉眼淚，所以被稱為墮淚碑。孟浩然想到自己考了那麼多次科舉都沒考上，好像什麼都沒留下，眼淚跟著落下來。他懂了，什麼樣的活法才配得上被後人記住，不是官做得多大，是活著的時候做了讓人記得的事。",
    "zhuyin": "襟(ㄐㄧㄣ)(jīn)發音同\"金\"，衣服胸前釘紐扣的地方。如：「對襟」、「開襟」。《楚辭．屈原．離騷》：「攬茹蕙以掩涕兮，霑余襟之浪浪。」也作「衿」。",
