    "id": 138,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "孟浩然",
    "title": "清明日宴梅道士房",
    "poem_notes": "【字詞與白話】\n 林臥愁春盡：躺在山林裡，發愁春天要過去了。忽逢青鳥使：青鳥使是傳說裡西王母派來傳信的使者，這裡形容忽然收到朋友邀約的消息。邀入赤松家：赤松子是傳說裡的仙人，這裡借指梅道士的居所像仙家一樣。丹灶初開火：煉丹的爐子剛點上火。何惜醉流霞：流霞是傳說裡的仙酒，這裡指既然留不住青春，那就痛快喝一場。\n 白話：躺在山林裡發愁春天要過去了，推開窗看外頭的景色。忽然收到朋友傳來邀約的消息，像被邀請進了仙人的居所。煉丹的爐子剛點上火，院子裡的仙桃花正開得盛。如果年輕的容顏真能靠這爐丹藥留住，那又何必吝惜，乾脆痛快醉一場。\n \n 【背後的小故事】\n 那年清明，孟浩然身體又不太好，窩在家裡看著春天一天天要過去，心裡堵得很。他這些年身子一直弱，眼看著春光溜走，自己卻只能躺著看它溜走。正悶著的時候，朋友梅道士派人來請他過去聚聚，他形容得像被仙使邀進了神仙的家。到了地方一看，梅道士剛把煉丹的爐子點上火，院子裡的仙桃花開得正盛。孟浩然坐下喝了幾杯酒，忽然生出一個念頭，如果真能靠這爐丹藥留住年輕的容顏，那該多好。可他也清楚，誰也說不準，既然說不準，那就別糾結了，索性把流霞美酒當仙丹喝下去，痛痛快快活成了一次神仙。",
