    "id": 139,
    "dynasty": "盛唐",
    "type": "五言律詩",
    "author": "孟浩然",
    "title": "歲暮歸南山",
    "poem_notes": "【字詞與白話】\n 北闕：宮殿北面的門樓，古代臣子上書言事之處，代指朝廷。不才：自謙沒有才能。青陽：指春天。\n 白話：不再向朝廷上書了，回到南山我那簡陋的屋子。不是明君嫌棄我沒有才能，是我自己疾病纏身，連老友都漸漸疏遠。白髮催著我老去，春天的腳步又逼近了歲末。我滿懷憂愁徹夜難眠，只有窗外松間的月色伴著我。\n \n 【背後的小故事】\n 相傳孟浩然有次在王維官署裡閒坐，唐玄宗忽然駕到，他來不及走，慌忙躲進床底。玄宗聽王維說起床下藏人，又聽過孟浩然的詩名，便叫他出來當面念一首詩。這本是孟浩然一輩子難得的機會，他卻脫口念出這首歲暮歸南山，念到抱怨自己不受重用的那句，玄宗臉色一變，說他自己從沒認真求官，何曾被棄，說完轉身就走。孟浩然這輩子再沒能做官，離朝廷最近的一次，卻被自己一句沒忍住的牢騷，關上了唯一的門。",
    "zhuyin": "闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。\n 寐",
