    "poem_notes": "【字詞與白話】\n 滄江：江水，多指青蒼色的大江，這裡指桐廬江一帶的水域。建德：地名，今浙江建德，即桐廬江所在的地方。維揚：揚州的別稱，語出《尚書》「淮海惟揚州」。海西頭：指揚州一帶，因臨近東海西側而得名。\n 白話：山色昏暗，聽見猿猴哀鳴；江水在夜裡湍急地流著。風吹得兩岸樹葉沙沙作響，月光照著江上一艘孤零零的船。建德不是我的家鄉啊，讓我想起在揚州和老朋友相聚的日子。姑且把這兩行眼淚，遙遙寄給遠在海西頭的你們。\n \n 【背後的小故事】\n 孟浩然一生未曾出仕，四十歲才首次赴長安求官，卻始終未能如願。相傳他曾由王維引薦、私下被帶入宮中，恰逢唐玄宗駕臨，倉促間躲於床下，經王維據實稟報後，玄宗命他當面誦詩，他念出「不才明主棄，多病故人疏」一句，惹得玄宗不悅，此後便絕了仕進之心，轉而終身漫遊於江湖山水之間。這首詩正寫於他南遊途中夜宿桐廬江時，思念揚州舊友的心情。",
