    "poem_notes": "【字詞與白話】\n 賦得：命題作文的規格用語，表示題目由他人所出。「野火燒不盡，春風吹又生」是全詩靈魂，寫的是毀滅不了的生命力。\n 白話：原野上茂盛的雜草，每年都要枯萎一次、繁茂一次。野火怎麼燒也燒不盡它，春風一吹又重新長出。遠處的芳草蔓延到古老的道路，晴日的翠色連接著荒廢的城牆。此刻又要送別友人遠行，滿眼茂盛的青草也裝滿了離別的情意。\n \n 【背後的小故事】\n 這首詩是白居易十五、六歲時的命題作文練習。他帶著詩稿拜訪長安文壇前輩顧況，顧況起初拿他的名字開玩笑「長安米貴，居大不易」，讀到「野火燒不盡，春風吹又生」時卻大為讚嘆，改口說「有句如此，居天下亦不難」。一個少年就此一夕成名。這句話後來被無數失意的人借用——革命者、失戀者、病人、創業失敗者，都拿它鼓勵自己：只要根還在，就會再長出來。",
