    "poem_notes": "【字詞與白話】\n 須白麵微紅：鬍鬚已白，臉頰卻因飲酒泛紅。臥疾瘦居士：臥病消瘦，自比佛家居士。好事者：喜歡湊熱鬧、附庸風雅的人。\n 白話：鬍鬚已經全白，臉上卻帶著幾分酒後的紅暈，整日醺醺然半醉半醒。百年的光陰不過是隨手翻過的一頁，世間萬事到頭來一場空。臥病在床，瘦得像個修行的居士；興致一來又唱歌跳舞，活脫脫一個放蕩的老頭。聽說還有好事的人，特地要把我這副模樣畫進屏風裡去。\n \n 【背後的小故事】\n 這是白居易晚年退居洛陽履道里時所寫。他早年因〈長恨歌〉〈琵琶行〉名滿天下，晚年卻自嘲活得又病又醉、狼狽不堪，還自號醉吟先生、香山居士，不再汲汲於功名。他聽說有人特意要把自己醉醺醺的模樣畫進屏風裡當作雅事，自己都覺得哭笑不得。沒想到後世竟真把這副他自嘲的醉態，當成了他晚年最風流的寫照。",
