    "title": "望月懷遠",
    "poem_notes": "【字詞與白話】\n 這首詩寫於張九齡晚年被貶荊州長史期間，望月思念遠方親友之作。「滅燭憐光滿，披衣覺露滋」寫的是他熄燭賞月、渾然忘我的深夜情景。\n 白話：一輪明月從海上升起，此刻天涯兩地的人，正共享著同一片月光。有情之人埋怨這漫漫長夜，整夜都被相思所牽動。熄滅蠟燭，更憐愛這滿室的月光；披上外衣走到庭院，才驚覺夜露已經沾濕了衣裳。這滿手的月光無法捧起相贈，不如回去睡覺，或許能在夢中與你相會。\n \n 【背後的小故事】\n 張九齡曾任玄宗朝的中書令，力主賢能治國，甚至提醒玄宗安祿山「狼子野心，面有逆相」，應當依法處死，玄宗卻不以為意，將安祿山放回范陽。後來張九齡被李林甫排擠出朝，貶至荊州，深知此生再難回到長安。這首詩寫於一個夏夜，他望著從海上升起的明月，想起遠方的親人，熄滅燭火只為多留一室月光，捧起滿手清輝卻無法寄贈遠方。十九年後，安祿山果然叛變，玄宗倉皇逃往蜀地途中，想起張九齡當年的忠告，含淚派人到他墳前致祭——只是那時，早已太遲。",
