    "poem_notes": "【字詞與白話】\n 客路：旅途、在外奔波的路程。殘夜：天將亮未亮、夜色未完全褪去的時分。鄉書：寄往家鄉的書信。\n 白話：旅途行進在青山之外，船行在綠水之前。潮水平穩，兩岸顯得格外開闊，風向正順，一片船帆高高懸掛。海上的太陽已在殘夜中升起，江上的春意闖入了舊年未盡的日子。家書該寄到哪裡才能送達呢，只盼北歸的大雁飛過洛陽時捎個平安。\n \n 【背後的小故事】\n 王灣常年在江南一帶跑船辦事，很少回洛陽老家。有一年行船到鎮江北固山下過夜，清晨他看見一件奇怪的事，夜色還沒褪盡，海上的太陽已經先升起來了，江上明明還是舊年的日子，春天的暖意卻先鑽了進來。他站在船頭忽然意識到，自己已經在外漂泊太久，連過年都趕不回家。這首詩後來傳到宰相張說手上，他大為讚賞，親手題在政事堂牆上，讓滿朝官員都拿來當範本學習。",
