    "poem_notes": "【字詞與白話】\n 聯步趨丹陛：兩人並肩走上宮殿的紅色台階。分曹限紫微：分別隸屬不同的官署，各自進入自己當值的省署。曉隨天仗入：清早跟著皇帝的儀仗隊伍進宮。暮惹御香歸：傍晚身上沾滿了宮裡的香氣才回家。白髮悲花落：看到自己頭髮變白，像看到花落一樣感慨。青雲羨鳥飛：羨慕別人升遷得快，像鳥一樣飛得又高又遠。聖朝無闕事，自覺諫書稀：表面說朝廷清明沒有過失可以進諫，實際暗指敢說真話的空間越來越小。\n 白話：兩人並肩走上宮殿的紅色台階，分別進入不同的官署當值。清早跟著皇帝的儀仗隊伍進宮，傍晚身上沾滿了宮裡的香氣才回家。看著自己頭髮變白，像看花落一樣感慨，又羨慕別人升遷得像鳥一樣飛得又高又遠。當今朝廷清明，沒什麼過失可以進諫，我也覺得自己上的諫書一天比一天少了。\n \n 【背後的小故事】\n 那幾年岑參在長安做右補闕，官職不大卻是諫官，隔著宮牆能看到門下省那頭坐著另一個諫官，左拾遺杜甫，兩人職位相近，常常一起進宮聊幾句。每天清早跟著儀仗隊踏上台階，傍晚沾著滿身御香拖著步子回家，日子久了頭髮漸漸變白，看著別人青雲直上，心裡難免有點酸。但真正讓岑參憋著一股氣的，是諫官這個身分越來越沒意思，能上的諫書越來越少，不是朝廷真的完美無缺，是敢說真話的空間越來越窄。他把這份心情寫進寄給杜甫的詩裡，表面稱頌朝廷清明，底下藏著的是苦笑。不久之後杜甫就因為替房琯說話惹惱皇帝，被貶去做了華州司功參軍，離開長安，這句諫書稀的苦笑，早就替兩人的處境寫好了注腳。",
