    "title": "題破山寺後禪院",
    "poem_notes": "【字詞與白話】\n 「曲徑通幽處，禪房花木深」後來成為中文裡形容蜿蜒小徑通往幽靜之地的固定用語。萬籟：指自然界的各種聲音。\n 白話：清晨走進這座古老的寺廟，初升的陽光照耀著高聳的樹林。一條曲折的小徑通向幽深之處，禪房掩映在花木深處。山中的光影使鳥兒歡悅鳴叫，潭水的倒影讓人心中的雜念頓時清空。此刻萬籟俱寂，只剩下鐘磬的聲音悠悠傳來。\n \n 【背後的小故事】\n 常建與王昌齡同榜進士及第，兩人年少時意氣風發，多年後卻都只在小地方任職，抱負始終無從施展。這首詩寫於他請假散心、清晨獨自走進常熟破山寺的經歷——沿著彎曲小徑一路深入，直到眼前豁然開朗，見到一間隱於花木深處的禪房與一方倒映天光的水潭。他在潭邊靜坐良久，聽著山鳥自在鳴叫，望著水中自己的倒影，多年堆積的心事彷彿被一點點洗去，直到寺裡的鐘磬聲響起才驚覺，整座山原來如此寂靜。",
