    "poem_notes": "【字詞與白話】\n 中丞：御史中丞，這裡是對這位曾任高階武職將領的尊稱。三邊：泛指邊境三處要地。輕生一劍知：形容視死如歸的決心，只有隨身佩劍才知曉那些出生入死的瞬間。\n 白話：這位曾經南征的將軍，如今流落至此，當年統率過十萬大軍。如今罷官歸來，連舊日的家業都沒留下，年紀老了，還眷戀著那個曾經清明安定的時代。他曾獨自一人鎮守邊境，使三方安靜無事；他那不惜性命的決心，只有腰間的劍知道。在茫茫的長江漢水之上，日暮時分，他又該往哪裡去呢。\n \n 【背後的小故事】\n 劉長卿一生仕途坎坷，曾兩度遭誣陷貶謫，一次遠貶嶺南潘州，罪名含糊不清。或許正因為他自己也嘗過被朝廷無端拋棄的滋味，送別這位罷官歸鄉的老將軍時，字裡行間格外能體會對方的處境——一個曾經替國家鎮守邊疆、視死如歸的人，到頭來連該往哪個方向走都茫然無措。這首詩表面寫的是送別老將，內裡藏著的，其實也是劉長卿自己的身世之嘆。",
