    "poem_notes": "【字詞與白話】\n 望君煙水闊：望著友人乘船離去，眼前江面煙霧茫茫一片開闊。飛鳥沒何處：飛鳥飛向遠處，不知道落在哪裡。青山空向人：青山依舊立在那兒，卻對著送別的人什麼都做不了。誰見汀洲上，相思愁白蘋：想像友人到了南方的汀洲，面對滿地白蘋草，被相思愁緒纏住。\n 白話：望著你乘船離去，眼前江面煙霧茫茫一片開闊，揮手告別的時候，眼淚已經濕了整條手巾。抬頭看飛鳥往遠處飛去，不知道落在哪裡；青山依舊立在那兒，卻對著我什麼都做不了。長江上那片帆影漸漸遠去，你這一路南下，到了那邊該是落日灑在五湖的春色上。不知道有誰看見，你站在汀洲上，對著滿地白蘋，被相思愁緒纏住。\n \n 【背後的小故事】\n 劉長卿送一個叫王十一的朋友南遊，兩人交情不算頂深，但足夠讓他站到看不見船影才肯走。船開的時候他望著江面煙水茫茫，船越走越小，他還站在那裡。他自己也說不清為什麼這次特別捨不得，也許是這些年他自己被貶來貶去，吃過太多次看著別人的船走遠、或自己被人送走的滋味，格外懂這一刻的重量。他抬頭看飛鳥飛向遠方，再看看兩岸青山，忽然覺得自己跟那青山有點像，想留人留不住，只能陪著看這一程。他把這些畫面收進四十個字裡，寫完轉身往回走，江面上早已看不見帆影，只剩水波一圈一圈散開，他知道這次送別要好一陣子才能想起來不難受，但不後悔站到了眼睛能看見的最遠處。",
