    "title": "尋南溪常山道人隱居",
    "poem_notes": "【字詞與白話】\n 這首詩題目中的「常山道人」生平不詳。「溪花與禪意，相對亦忘言」寫的是造訪友人不遇，卻在山水間獲得心靈慰藉的體悟。\n 白話：一路走來所經之處，青苔上還留著鞋印的痕跡。白雲依偎在寧靜的水中小洲，芳草已經長得遮住了那扇悠閒的柴門。雨後望著松樹的顏色更顯青翠，順著山勢一路走到水源之處。溪邊的野花與心中的禪意相對而視，竟連話都忘了該怎麼說。\n \n 【背後的小故事】\n 劉長卿一生兩度被貶，這首詩寫於他被貶睦州司馬期間，前往拜訪一位隱居山中的道人朋友。他帶著寫好的拜帖上山，卻在半途發現青苔上的鞋印顯示友人已經外出，到了門前也只見芳草掩門、無人應答。他沒有敲門，轉而沿著山路繼續往上走，雨後松色青翠、溪水潺潺，最終在溪邊坐下，看著漂浮的野花，忽然覺得心裡想對朋友說的話，此刻對著這朵花也已經說得明白——有些拜訪，不遇也是一種圓滿。",
    "zhuyin": "渚(ㄓㄨˇ)(zhǔ)發音同\"主\"，小洲，水中的小陸地。",
