    "type": "五言律詩",
    "author": "錢起",
    "title": "送僧歸日本",
    "poem_notes": "【字詞與白話】\n 上國：指大唐，僧人因緣份來到中土居住。隨緣：不強求，順著因緣。法舟：載著佛法歸去的船，喻僧人此行的使命。水月：水中月影，佛教常用來比喻虛幻與禪定的清明。梵聲：誦經的聲音。\n 白話：他因緣份來大唐住了許多年，來的路途遙遠得像一場夢。天空浮在滄茫大海之上，他乘的法舟載著佛法，行囊卻很輕。水中映月，通向禪定的寂靜，魚和蛟龍彷彿都聽得懂他誦經的聲音。最讓人牽掛的是那一盞燈影，在萬里之外的眼中依然明亮。\n \n 【背後的小故事】\n 錢起是大曆十才子之一，這首詩送別一位在中土學法多年、即將搭遣唐使船隊回日本的僧人。他的法名沒有留下記載——那個年代太多這樣的名字，隨遣唐使的船隊往返，留下的只有一首詩。詩裡沒有描述海上的風浪多可怕，反而寫得很安靜：水月、梵聲、一盞燈。這盞燈影很可能讓人聯想到幾十年前六次東渡日本、最後雙目失明才成功抵達的鑑真和尚——一僧西來求法，一僧東渡歸鄉，方向相反，卻都是那盞燈在黑暗大海裡沒有熄滅。",
