    "title": "谷口書齋寄楊補闕",
    "poem_notes": "【字詞與白話】\n 茅茨：茅草屋頂，借指簡陋屋舍。薜帷：薜荔藤蔓織成如帷幕般的門簾。楊補闕：楊姓友人，補闕是唐代諫官官名。故人期：與老朋友的約定。\n 白話：泉水山壑環繞著茅屋，雲霞低生在薜荔織成的門簾外。竹子剛淋過新雨，格外討人喜愛；山在夕陽時分，也格外可愛。悠閒的白鷺總是早早歸巢，秋天的花卻比別處落得更遲。家裡的僮僕正在打掃長滿藤蘿的小路——因為昨天已經跟老朋友約好了，他要來。\n \n 【背後的小故事】\n 谷口這個地名在漢代就有典故：隱士鄭子真隱居在谷口的巖石下耕田，朝廷幾次徵召都不出，名氣反而傳遍長安城。錢起是大曆十才子之一，官做得不算差，卻特意在谷口蓋了間書齋，擺明是想沾一點這位拒官前輩的骨氣。全詩前六句寫得很悠閒，泉水、雲霞、新竹、夕陽、歸鷺、遲花，像是一個人自顧自過日子的風景，直到最後兩句才揭曉真相——他一早就叫僮僕把藤蘿小路掃乾淨，因為昨天已經跟諫官楊補闕約好對方要來。前面的閒適原來都是等待，他把最好的風景留著，只等一個懂的人。",
