    "poem_notes": "【字詞與白話】\n 江漢：泛指梁州一帶（今陝西漢中附近）。浮雲、流水：比喻聚散無常與光陰流逝。蕭疏鬢已斑：鬢髮稀疏斑白。\n 白話：當年我們都在梁州客居異鄉，每次相聚總要喝到盡興才回去。一別之後像浮雲一樣各自飄散，十年光陰像流水一樣悄悄流過。今日重逢，笑聲跟從前一樣，可是彼此的鬢髮都已花白稀疏。你問我為什麼還不回北方老家去，我望著淮水對岸的秋山，一時竟答不上來。\n \n 【背後的小故事】\n 韋應物與這位梁州故人年輕時同遊同醉，交情深厚，一別十年，書信漸稀。這年他在淮上任職，兩人竟意外重逢，把酒言歡，笑聲彷彿還停留在十年前。可是笑著笑著，才驚覺彼此鬢角都已斑白——十年不是輕飄飄的一句一別，它像浮雲一樣悄悄飄過，飄過的地方，人已經整個變了樣。老友問他為何不歸鄉，他望著秋山，答不上來，連自己也說不清是什麼把他一直留在外面。",
