    "title": "闕題",
    "poem_notes": "【字詞與白話】\n 闕題：題目缺失，後人代擬的篇名。道：道路。青溪：清澈的溪水。幽映：幽靜的光影。清輝：清亮的日光。\n 白話：小路順著白雲一路延伸到看不見盡頭，春意跟青溪一樣悠長。不時有落花飄來，伴著流水的香氣一路遠遠飄送。柴門常對著山路敞開，深深的柳蔭裡藏著一間讀書堂。那裡幽靜的光影天天都在，清亮的日光正照在衣裳上。\n \n 【背後的小故事】\n 劉脊虛是盛唐詩人，二十出頭就中進士，跟孟浩然、王昌齡、常建都是朋友，可惜相傳他中年早逝，全唐詩裡留下的詩不到二十首。這首最有名的作品，收錄進殷璠河嶽英靈集時，題目那一欄已經是空的——後人只能用闕題兩個字代替，意思是原本的題目找不到了。詩裡寫的是去拜訪一位隱居讀書的朋友，路上白雲、青溪、落花、柴門、柳蔭、讀書堂，一路寫得清清楚楚，唯獨沒說他到底去見了誰。那個人的名字，跟這首詩的題目一樣，都隨著時間散佚了，留下來的只有路怎麼走、光怎麼照。",
