    "title": "喜見外弟又言別",
    "poem_notes": "【字詞與白話】\n 外弟：表弟。「問姓驚初見，稱名憶舊容」精準捕捉了久別重逢時，先認出姓氏、後想起容貌的真實心理過程。\n 白話：經歷十年離亂之後，直到長大成人才又相逢。詢問姓氏時驚覺竟是初次相見的陌生人，聽到名字後才想起舊時的容貌。訴說著分別以來滄海桑田般的種種往事，聊完時已聽見黃昏寺廟的鐘聲。明天我就要踏上前往巴陵的路，不知道秋山又要翻越幾重。\n \n 【背後的小故事】\n 安史之亂讓李益年幼時與家族親人四散離失，其中包括一位年幼的表弟，此後音訊全無。多年後的一個秋日，他在路上被一位陌生男子叫住問姓，對答之下才驚覺對方竟是失散多年的表弟。兩人相擁而泣，找了間酒館從中午一路聊到黃昏鐘響，訴說彼此這十年來的顛沛流離。然而重逢的喜悅還沒散去，隔天他就要啟程前往巴陵，兩人又要各自翻越秋山、分道揚鑣。李益一生寫過無數離別詩，但這首「喜見」之所以格外動人，正是因為那個下午，他難得沒有寫分離，而是寫下了那份意外抓住的、僅有一夜的重逢。",
