    "title": "沒蕃故人",
    "poem_notes": "【字詞與白話】\n 月支：古代西域民族名，此處泛指與吐蕃相關的邊境部族。沒全師：全軍覆沒。蕃漢：吐蕃與唐朝。廢帳：戰後遺棄的軍帳。殘旗：殘破的軍旗。\n 白話：前年出兵征討邊境部族，城下一戰全軍覆沒。吐蕃與唐朝之間消息斷絕，生是死是，從此長久分離。沒有人去收拾戰場上遺棄的軍帳，只有一匹自己走回來的馬，馬鞍上還認得出殘破的軍旗。想替你辦祭奠，卻又懷疑你可能還活著，只能在天涯的這一頭，獨自哭這一場。\n \n 【背後的小故事】\n 中唐時期，唐軍與吐蕃在西北邊境屢有惡戰，史書上不只一次記載整支軍隊全軍覆沒的慘況。張籍這首詩應是為一位真實從軍、下落不明的朋友所寫，對方的姓名如今已不可考，詩題只留下故人二字。全詩最揪心的一句是歸馬識殘旗——人沒有回來，馬卻自己走回了營地，鞍上還掛著那面破旗，彷彿在替主人交代些什麼。最後兩句欲祭疑君在，寫的是一種比確定死亡更折磨人的懸念：張籍想辦喪事悼念朋友，卻又不敢肯定他真的死了，只能對著天涯的方向，哭這一次。",
