    "poem_notes": "【字詞與白話】\n 「推敲」一詞即出自這首詩的創作過程——賈島反覆斟酌「僧推月下門」與「僧敲月下門」，後來成為中文裡「反覆斟酌字句」的代稱。\n 白話：隱居之處少有鄰居相伴，一條雜草小徑通向荒蕪的園子。鳥兒棲息在池邊的樹上，僧人在月下輕輕敲門。走過橋去，眼前的原野景色分外清晰，山石移動，彷彿連雲的根基都被牽動了。暫時離去，還會再回到這裡，不會辜負這個幽靜的約定。\n \n 【背後的小故事】\n 賈島深夜拜訪隱居友人李凝，敲門前反覆猶豫該用「推」還是「敲」，兩人暢談到天亮才依依道別。回長安路上他仍在反覆斟酌這個字，比劃到入神，竟一頭撞進京兆尹韓愈的儀仗隊。韓愈聽完緣由，不但沒有怪罪，反而認真思考後建議用「敲」——因為深夜一聲敲門，才能襯出那份寂靜。兩人從此成為摯友，韓愈此後多次在賈島窮困潦倒時出手相助。這個猶豫不決的推敲過程，後來成了中文裡「反覆斟酌字句」的代名詞。",
