    "poem_notes": "【字詞與白話】\n 五銖錢：漢代通行的貨幣，劉備稱帝後恢復鑄造，象徵延續漢室正統。得相：指諸葛亮輔佐。象賢：像先人一樣賢能，這裡指劉禪不肖。蜀故妓：蜀漢滅亡後被擄入魏宮的宮廷歌妓。\n 白話：一代英雄的氣概，千年後依然凜然逼人。天下三分之勢已定，他仍恢復漢室五銖錢以示正統。有諸葛亮這樣的賢相輔佐才得以開國，可惜生的兒子劉禪並不賢能。最淒涼的是那些蜀漢舊時的宮妓，如今卻在魏國的宮殿前，繼續為新的主人跳著同一支舞。\n \n 【背後的小故事】\n 劉禹錫被貶為夔州刺史時，親臨劉備託孤諸葛亮的永安宮舊址，寫下這首詠史詩。他自己也曾參與永貞革新，半年就因順宗早逝而全盤失敗，一貶就是十幾年。站在蜀先主廟前，他看劉備開創基業、諸葛亮鞠躬盡瘁，卻因劉禪不肖二世而亡，格外有共鳴。最讓他唏噓的是亡國舊妓依然在敵國宮廷裡跳著同一支舞，彷彿江山興替與她們毫無關係——人存政舉、人亡政息的滄桑，他比誰都懂。",
