    "poem_notes": "【字詞與白話】\n 闕：京城，這裡指長安。長亭：古代驛路上供人休息餞別的亭子。太華：西嶽華山。中條：中條山，在今山西南部。帝鄉：京城。漁樵：打漁砍柴，借指隱居的生活。\n 白話：紅葉在晚風中蕭蕭作響，在長亭下喝一瓢酒。殘雲慢慢飄回太華山，疏落的雨掠過中條山。樹木的顏色隨著山勢一路延伸到遠方，河水聲一路流向遙遠的大海。明天就要抵達京城了，可他心裡想的，還是打漁砍柴的日子。\n \n 【背後的小故事】\n 許渾是晚唐詩人，後來做過潤州、睦州刺史，一生宦途起伏不算劇烈，卻始終擺脫不掉對山水隱逸生活的眷戀，後人甚至戲稱他「許渾千首濕」，說他寫詩十有八九都帶著雨氣水色。這首詩寫於他赴長安謀官途經潼關驛樓之時，人還沒到京城，心裡卻已經開始嚮往退隱山林的日子，正是他一生在仕途與山水之間反覆搖擺的縮影。",
