    "poem_notes": "【字詞與白話】\n 調角：吹起號角。戍樓：邊防駐軍用的瞭望樓。青塚：王昭君墓，相傳墓上草色常年青翠，故稱青塚。梁州：地名，這裡泛指西北邊地。蕃情：這裡指邊疆外族的心意。\n 白話：號角聲劃破清秋的天空，戍守邊疆的士兵倚靠著瞭望樓。春風吹拂著王昭君的青塚，夕陽落在遙遠的梁州。廣闊的沙漠上沒有兵戈阻隔，連偏遠的邊塞都有旅人往來遊賞。異族的心意就像這條河水，總是願意向南流去。\n \n 【背後的小故事】\n 張喬是晚唐詩人，考中進士後遇上黃巢之亂，索性隱居九華山，終生未再出仕。這首詩相傳寫於他早年遊歷邊塞之時，難得地描繪出一幅沒有戰事的邊疆景象——這與詩中提到的王昭君青塚形成了跨越數百年的呼應：昭君當年遠嫁匈奴，以一生的孤獨換取兩國數十年的和平，而詩人眼前這片安穩的邊塞，正是她當年那份犧牲，遲了幾百年才真正兌現的模樣。",
