    "poem_notes": "【字詞與白話】\n 嬋娟：美貌，此處指宮女因美貌而遭忌。承恩：得到皇帝的寵幸。若為容：該怎麼裝扮打扮。越溪女：越地溪邊的女子，暗指西施浣紗的典故，泛指民間自在的女子。\n 白話：早年就被自己的美貌耽誤了，想梳妝打扮，對著鏡子卻提不起勁。得到寵幸從來不是靠容貌，那我該怎麼裝扮自己才好呢？風暖了，鳥叫聲一句句碎碎地響；日頭高了，花影一層層疊在地上。年年想起那些在溪邊採蓮的女子，懷念她們自在的日子。\n \n 【背後的小故事】\n 杜荀鶴的身世相傳頗為曲折——據說他是杜牧年輕時與一名妾室所生的私生子，杜牧未曾相認，他一輩子頂著模糊的出身，在科舉路上摸爬滾打近三十年，直到四十六歲才終於中進士。這首詩表面寫一個因美貌反而不受寵的宮女，實則是他自身懷才不遇的投射：宮女因為太出眾遭人忌妒排擠，他自己則因為出身與際遇，屢屢落第。詩中風暖鳥聲碎，日高花影重一聯格外工整精巧，相傳杜荀鶴自己也極為得意，曾花費不少心思琢磨。宮女懷念溪邊採蓮的自在日子，杜荀鶴大概也在懷念，那些還沒被科舉困住之前的自己。",
