    "poem_notes": "【字詞與白話】\n 清瑟：清越的瑟聲。楚角：楚地的號角聲，古代軍中報時或警戒用。章臺：本為長安街名，此處借指異鄉夜色所在。云暮：說是已到暮色深重之時，指季節將盡。\n 白話：清越的瑟聲在漫漫長夜裡帶著哀怨，絃音纏繞著像風雨交加一樣淒涼。一盞孤燈下聽見楚地的號角聲，殘月慢慢沉向章臺。芳草已經到了深秋暮色，老朋友卻遲遲沒有來。家鄉的書信沒辦法寄出去，秋天的大雁又要往南飛了。\n \n 【背後的小故事】\n 韋莊年輕時遇上黃巢之亂，長安淪陷那幾年他正困在城中，親眼見證屠城慘況，後來寫成長詩秦婦吟，轟動一時，人稱秦婦吟秀才。這首詩相傳寫於亂後輾轉流落江南的歲月，家人仍在北方，兵荒馬亂裡音訊斷絕。詩裡的章臺，本是長安城裡的街名，如今卻用來稱呼異鄉的夜色，透著物是人非的滋味。最後兩句最見心酸：家書寄不出去，而每年南飛過冬的大雁，方向剛好跟他想送信回家的方向相反——連候鳥都幫不上忙，鄉愁就真的無處可去了。",
