    "poem_notes": "【字詞與白話】\n 帶郭：靠近外城。桑麻：桑樹與麻田，泛指鄉間田野。籬邊菊：籬笆邊種的菊花，暗合陶淵明「採菊東籬下」的意境。\n 白話：他雖然搬了家，卻仍靠近城郭，一條野徑通往種著桑麻的田野。籬笆邊新種了菊花，秋天到了卻還沒開花。敲門沒聽見狗叫，正要離開時去問西邊的鄰居。鄰居說他到山裡去了，通常要等到太陽偏西才會回來。\n \n 【背後的小故事】\n 陸鴻漸就是陸羽，相傳幼年是被遺棄在湖邊的孤兒，由僧人智積收養於寺中長大，後來卻一心鑽研茶事，走遍各地山水尋訪水源與茶樹，寫成流傳後世的《茶經》，被尊為茶聖。皎然是一位僧人詩人，與陸羽是相交數十年的摯友，兩人常有茶詩唱和。這首詩寫的正是皎然去尋訪陸羽卻撲空的一次日常，字裡行間沒有絲毫抱怨，反而是對這位老友隨性性格的熟稔與包容。",
