    "poem_notes": "【字詞與白話】\n 「總為浮雲能蔽日，長安不見使人愁」以浮雲遮日比喻奸臣蒙蔽君主，暗喻自己被排擠、無法回到朝廷的處境。\n 白話：鳳凰台上曾經有鳳凰來遊，如今鳳凰已飛走，樓台空自佇立，只有江水依舊自顧自地流淌。吳國宮殿裡的花草，如今埋沒在幽深的小徑；東晉時代的達官貴人，也都已化為古老的墳丘。三座山峰有一半隱沒在青天之外，秦淮河與長江在白鷺洲中間分流而過。都因為那片浮雲能夠遮蔽太陽，讓人望不見長安，心中充滿了憂愁。\n \n 【背後的小故事】\n 李白年輕時登黃鶴樓，本想題詩卻見崔顥的〈黃鶴樓〉已在牆上，自嘆「眼前有景道不得，崔顥題詩在上頭」，擱筆離去，這口氣他嚥了近三十年。晚年他特地登上金陵鳳凰台，用與崔顥相似的結構寫下這首詩，試圖一雪前恥——但他心裡最沉重的，其實不是與崔顥的較量，而是詩末那句「長安不見使人愁」：浮雲遮蔽了太陽，也遮住了他此生再難回去的朝廷。這首詩寫成隔年，李白便客死當塗，終究沒能等到浮雲散去的那一天。",
