    "id": 191,
    "dynasty": "盛唐",
    "type": "七言律詩",
    "author": "李白",
    "title": "上李邕",
    "poem_notes": "【字詞與白話】\n 宣父：唐代對孔子的尊稱。「宣父猶能畏後生，丈夫未可輕年少」引用孔子「後生可畏」之語，反擊對方輕視年輕人的態度。\n 白話：大鵬鳥一旦乘著風勢而起，便能盤旋直上九萬里高空。就算風停下來、大鵬落下，也還能掀起滄海的波濤。世人見我總是與眾不同，聽到我說大話都在冷笑。連孔子都懂得敬畏後輩年輕人，大丈夫怎麼可以輕視年少之人呢！\n \n 【背後的小故事】\n 李白二十多歲出蜀遊歷，特地拜見當時聲望極高的官員李邕，滿懷期待地陳述自己的抱負，卻只換來對方不鹹不淡的敷衍與一絲冷笑，被禮貌地送客。回到旅店，他越想越不服氣，連夜寫下這首詩，以《莊子》裡扶搖直上九萬里的大鵬自比，並引用孔子「後生可畏」之語反擊李邕輕視年輕人的態度。多年後，李邕因遭李林甫誣陷，七十歲時被朝廷杖打致死，李白得知後反而寫詩替他鳴不平——原來他始終記得並敬重這位曾經看輕自己的長者。這首詩裡那股不服輸的少年意氣，千年來一直鼓舞著每個被冷落、卻仍相信自己能一飛沖天的年輕人。",
    "zhuyin": "簸(ㄅㄛˇ)(bò)發音同\"跛\"，搖動。\n 滄溟(ㄇㄧㄥˊ)(cāng míng)發音同\"名\"， 大海。",
