    "poem_notes": "【字詞與白話】\n 三顧：指劉備三顧茅廬請諸葛亮出山。「出師未捷身先死，長使英雄淚滿襟」寫的是諸葛亮北伐未成先病逝五丈原之事。\n 白話：丞相的祠堂要去哪裡尋找？就在成都城外，那片柏樹森森之處。台階前的碧草自顧自地展現春色，樹葉間的黃鸝白白地唱著好聽的歌。當年劉備三顧茅廬向他請教天下大計，他輔佐兩代君主，盡了老臣的忠心。可惜出兵北伐還未成功，人就先病逝了，長久以來讓後世的英雄們為此淚濕衣襟。\n \n 【背後的小故事】\n 杜甫在成都草堂安頓下來後，前往武侯祠拜謁諸葛亮。祠堂裡春色正好，鳥鳴悅耳，卻已無人聆賞——這片沒有主人的春天，讓杜甫想起自己：一生渴望被明主賞識、大展抱負，卻始終未能如願。他寫下諸葛亮出師未捷、齎志而歿的結局，忍不住落淚——不只是為諸葛亮，也是為所有「盡了力卻沒能成功」的人。十年後，杜甫也在漂泊途中病逝於湘江船上，寫詩寫到一半就離世了。這首詩其實是他對自己一生的預言。",
    "zhuyin": "襟(ㄐㄧㄣ)(jīn)發音同\"金\"，衣服胸前釘紐扣的地方。如：「對襟」、「開襟」。《楚辭．屈原．離騷》：「攬茹蕙以掩涕兮，霑余襟之浪浪。」也作「衿」。",
