    "poem_notes": "【字詞與白話】\n 明府：對縣令一類地方官員的敬稱。盤飧：盤中的飯菜，飧指熟食。舊醅：未經過濾的陳釀濁酒，家貧買不起好酒的意思。\n 白話：草堂南北都漲滿了春水，平常只見一群群鷗鳥天天飛來。長滿花的小路從沒為客人清掃過，今天才第一次為你把柴門打開。因為離市集太遠，盤中的菜色沒有兩樣以上；家裡貧窮，只有自家釀的陳年濁酒。如果你願意跟鄰家老翁一起對飲，我就隔著籬笆喊他過來，把剩下的酒喝完。\n \n 【背後的小故事】\n 崔明府相傳是杜甫母親崔氏那邊的親戚，具體身分後人已考據不清。杜甫聽說他要來，高興得把柴門推開特別大，他家南北都是春水，平常只有鷗鳥天天報到，幾乎沒有正經客人上門。他心裡過意不去，菜色湊不齊、酒也只是自家陳釀，一邊張羅一邊解釋。可是高興的心情壓不住，兩人喝到興頭上，他忽然隔著籬笆喊來鄰居老翁一起喝，捨不得這場難得的熱鬧只有兩個人。那條從沒為客人掃過的花徑，那天終於派上用場。",
    "zhuyin": "飧(ㄙㄨㄣ)(sūn)發音同\"孫\"，煮熟的飯菜。\n 樽(ㄗㄨㄣ)(zūn)發音同\"尊\"，酒器。\n 醅(ㄆㄟ)(pēi)發音同\"胚\"， 沒過濾的酒。",
