    "poem_notes": "【字詞與白話】\n 三城戍：指松州、維州、保州三處防禦吐蕃的軍事據點。涓埃：涓滴與塵埃，比喻極微小的貢獻。聖朝：對當朝的敬稱。\n 白話：西山白雪皚皚，三座城池仍有軍隊駐守防備；南邊江水清澈，橫跨著萬里橋。四海之內兵荒馬亂，兄弟們各自分散；獨自一人在天涯，忍不住流下眼淚。如今年老多病，什麼都做不了，對朝廷連一點微薄的貢獻都拿不出來。騎馬出城，遠望四方，實在受不了人世一天比一天蕭條。\n \n 【背後的小故事】\n 這首詩寫於廣德二年，杜甫當時在成都嚴武幕府中掛職，勉強有俸祿糊口，但心境並不安穩。前一年成都才發生徐知道叛亂，他帶著家人倉皇逃難，好不容易又回到草堂；他的幾個弟弟因戰亂各自流落他方，音訊斷絕，生死未卜。詩中西山三城戍守吐蕃的緊張局勢，與他自身老病無力、無法報效朝廷的處境相互映照，寫盡了一個亂世裡想做事卻無能為力的悲涼。",
