    "poem_notes": "【字詞與白話】\n 漫卷詩書：隨手胡亂捲起書卷，形容喜悅到失去平日的整齊有序。這是杜甫詩中少見的、毫不掩飾的狂喜之作。\n 白話：劍門關外忽然傳來收復薊北的消息，剛聽到時眼淚就沾滿了衣裳。回頭看看妻兒，先前的愁容已經不見了，隨手胡亂捲起詩書，高興得幾乎要發狂。大白天就該放聲高歌、盡情飲酒，趁著春光正好結伴回鄉。立刻從巴峽穿過巫峽，再由襄陽直奔洛陽。\n \n 【背後的小故事】\n 安史之亂持續八年，杜甫被戰亂折磨得幾乎家破人亡。這天他在四川梓州忽然聽聞官軍收復河南河北的消息，喜極而泣，看妻兒臉上的愁容也一掃而空，興奮得胡亂捲起書卷就想動身回家，甚至在腦中把回鄉路線一口氣規劃到底。這是杜甫一生詩作中唯一一次毫不掩飾的快樂。可惜他終究沒能真正回到洛陽——晚年仍在漂泊，五十九歲客死於前往洛陽途中的湘江船上。那份規劃好的歸鄉喜悅，成了他一生最珍貴、卻也最終未能實現的希望。",
