    "poem_notes": "【字詞與白話】\n 全詩被明代胡應麟譽為「古今七律第一」。「無邊落木蕭蕭下，不盡長江滾滾來」是全詩最壯闊、也最沉重的一句。\n 白話：風勢猛烈，天空高遠，猿猴的叫聲淒厲哀傷，水中沙洲清澈，白沙映襯，鳥兒盤旋飛回。無邊無際的樹葉蕭蕭飄落，望不盡的長江水滾滾奔流而來。萬里漂泊，在這悲涼的秋天裡常年作客異鄉，一生多病，如今獨自登上高台。艱難困苦與深深的憾恨，讓鬢髮更加斑白，如今窮困潦倒，連一杯濁酒也剛剛戒掉。\n \n 【背後的小故事】\n 杜甫五十六歲那年重陽節，獨自一人在夔州登高——牙齒掉落大半，右耳失聰，風濕纏身，醫生剛叮囑他戒酒，這是他人生第一個沒有酒的重陽節。站在高台上，他望著落葉紛飛、長江奔流，想起三十二年前自己在泰山寫下「會當凌絕頂，一覽眾山小」的豪情壯志，如今卻連夔州這座小小的高台都爬得吃力。他把自己萬里漂泊、百病纏身、孤獨登台的一生濃縮進這八句詩裡。兩年後他病逝於湘江舟中，再也沒能回到長安。這首詩後來被譽為「古今七律第一」，但他寫下這些字時，只是一個沒有酒喝的重陽節，一個人拄著拐杖慢慢下山。",
