    "poem_notes": "【字詞與白話】\n 陰陽：指日月，這裡代指時間。短景：冬天日短。五更：天快亮前的更次。夷歌：當地少數民族的歌謠。臥龍：諸葛亮的別稱。躍馬：公孫述，西漢末年自立為蜀帝，相傳因乘馬奔逃而得名。\n 白話：歲末天色一天比一天短，天涯之地霜雪剛停，寒夜清朗。五更時分傳來悲壯的鼓角聲，三峽上空的星河倒映水中，隨波搖晃。千家萬戶因為戰亂傳出哭聲，幾處漁夫樵夫唱著異鄉的歌謠。諸葛亮和公孫述這樣的人物，最終也不過化成黃土一坏，人世的消息和書信，也只剩滿滿的寂寞。\n \n 【背後的小故事】\n 這首詩寫於杜甫晚年寓居夔州時，當時他已五十五歲，身體多病，牙齒脫落、耳朵重聽、右臂不便，生活十分困頓。更讓他難受的，是身邊至交好友一個接一個離世——李白病逝於當塗，鄭虔、蘇源明也先後過世，剩下的朋友音信難通。詩中借諸葛亮與公孫述這兩位截然不同的歷史人物同歸黃土，映照出人世的無常，也道出了一個病老詩人在異鄉聽著鼓角聲時，那份無處可訴的孤寂。",
