    "poem_notes": "【字詞與白話】\n 支離：流離失所的樣子。羯胡：對安祿山的貶稱，因其出身羯族後裔。詞客：泛指文人，這裡兼指庾信與杜甫自己。江關：長江與三峽一帶的關隘，泛指這片土地。\n 白話：在東北的戰亂裡流離失所，又在西南的天地間四處漂泊。三峽的樓閣高聳，彷彿把日月都淹沒在其中；這裡的居民穿著五溪一帶少數民族的服飾，與雲山為伴。安祿山身為臣子卻終究背叛了君主，寫詩的人為時局悲傷，至今還無法歸去。庾信一生最是淒涼落魄，晚年寫下的詩賦，卻震動了整個長江關塞一帶。\n \n 【背後的小故事】\n 庾信原是南朝梁的宮廷文人，奉命出使西魏期間，梁朝因侯景之亂、江陵陷落而滅亡，他從此被迫滯留北方，終生未能回到故鄉江南，晚年寫下哀江南賦，抒發亡國思鄉之痛。杜甫寫這首詩時同樣困居夔州，因安史之亂而輾轉流離、有家難歸，境遇與庾信驚人地相似。他借憑弔庾信，寫的其實也是自己這幾年漂泊西南、有志難伸的心境。",
