    "title": "詠懷古跡五首之二",
    "poem_notes": "【字詞與白話】\n 搖落：草木凋零飄落，語出宋玉〈九辯〉「蕭瑟兮草木搖落而變衰」。風流儒雅：指宋玉文章的才情與氣度。異代：不同的時代，這裡指杜甫與宋玉相隔約九百多年。雲雨荒臺：指宋玉〈高唐賦〉裡楚王夢見巫山神女、神女自稱「旦為朝雲，暮為行雨」的那座高臺，如今已荒廢。\n 白話：看到草木凋零飄落，才真正明白宋玉當年心裡的悲傷；他文章裡的才情風度，也值得我當老師學習。遙想千年前的心情，忍不住灑下眼淚，可惜我們生在不同的時代，終究無緣同時相見。江山還在，宋玉的舊宅卻只剩下空留的文字，當年雲雨高臺的故事，難道不也只是一場夢？最讓人感傷的是，整個楚國的宮殿都已經灰飛煙滅，如今只有搖船的船夫，偶爾指著江邊一處遺跡，猜測那裡是不是當年的舊址，到現在還說不準。\n \n 【背後的小故事】\n 杜甫寫這首詩時五十五歲，人在夔州，是他人生最後幾年最顛沛的一段。靠山嚴武剛病逝，他失去成都草堂的依靠，只能舉家東遷，暫居夔州，四年後就病死在湘江的船上，沒能回到故鄉。這首詩是〈詠懷古跡五首〉的第二首，整組詩他寫了庾信、宋玉、王昭君、劉備諸葛亮等好幾位古人，每一位都跟他自己的處境隱隱呼應。宋玉這位戰國辭賦家，才氣沒有被真正用上，連舊居的確切位置都眾說紛紜，杜甫在這裡寫的與其說是宋玉，不如說是借宋玉的酒杯，澆自己懷才不遇的塊壘。",
