    "title": "黃鶴樓",
    "poem_notes": "【字詞與白話】\n 悠悠：形容長久、渺茫的樣子。這首詩讓連李白都甘拜下風——留下「眼前有景道不得，崔顥題詩在上頭」的傳世感嘆。\n 白話：昔日仙人已乘黃鶴離去，此地只留下一座空盪盪的黃鶴樓。黃鶴一去再也沒有回來，千年來只剩白雲悠悠飄蕩。晴朗天空下漢陽的樹木清晰可見，鸚鵡洲上芳草長得茂盛。日暮時分，我的家鄉在哪裡呢？江面上煙波浩渺，讓人滿懷愁緒。\n \n 【背後的小故事】\n 崔顥登上武昌黃鶴樓，望著仙人乘鶴而去的傳說之地，只剩空樓與千年白雲，忽然想起自己的故鄉，卻怎麼也望不清方向，滿江煙波化作愁緒，寫下這首詩。多年後，李白也登樓準備題詩，抬頭卻看見崔顥的詩已寫在牆上，讀完便擱筆感嘆：「眼前有景道不得，崔顥題詩在上頭」——這是李白一生唯一一次公開承認技不如人。後來他寫〈登金陵鳳凰台〉，明顯是想跟崔顥較量，但後世公認，這一次李白還是輸了。",
    "zhuyin": "萋(ㄑㄧ)(qī)發音同\"七\"，草木繁盛的樣子。",
