    "type": "七言律詩",
    "author": "崔顥",
    "title": "行經華陰",
    "poem_notes": "【字詞與白話】\n 岧嶢：山勢高峻的樣子。太華：華山。咸京：長安。武帝祠：漢武帝求仙祭祀所建的祠廟。仙人掌：華山一峰名，傳說是巨靈神劈山留下的掌印。畤：古代祭天地五帝的祭壇。\n 白話：高聳的華山俯瞰著長安，天外那三座主峰陡峭得像刀削一樣。漢武帝祠前雲霧正要散去，仙人掌峰上雨才剛剛放晴。山河北邊枕著險要的秦地關隘，驛道旁的樹木向西一路連到平坦的漢代祭壇。請問路旁那些追逐名利的旅人：沒有比在這裡學道求仙更好的事了。\n \n 【背後的小故事】\n 崔顥年少才氣過人，卻在舊唐書裡留下不太好看的紀錄：好賭博、嗜酒，娶妻專挑美貌的，稍不順心就休掉，前前後後換了好幾任。這首詩寫他路過華陰，望見華山三峰陡峭如削，山腰上漢武帝當年求仙的祠廟雲霧繚繞。他想起漢武帝擁有天下卻仍求長生不得，忽然想到自己年輕時追逐的那些東西，本質上也是一場抓不住的空。詩末他問路上趕考求利的旅人是否值得，也像是在問曾經的自己。相傳崔顥晚年詩風確實比早年沉厚許多，後來寫出千古傳誦的黃鶴樓——那份轉變，或許就從華山腳下這個念頭開始。",
    "zhuyin": "岧嶢\n 咸(ㄒㄧㄢˊ)(xián)發音同\"賢\"，陽 秦朝的首都，位於今陝西省長安市東北。\n 畤",
