    "title": "送魏萬之京",
    "poem_notes": "【字詞與白話】\n 驪歌：送別時唱的歌，相傳出自逸詩〈驪駒〉，後世泛指送別曲。度河：渡過黃河。關城：指潼關一帶的城池，是由中原進入長安的必經關口。御苑：皇家園林，這裡代指長安城。蹉跎：光陰虛度、耽誤。\n 白話：今天早上聽見遠行的人唱起送別的歌，昨夜一層薄霜剛剛渡過黃河而來。大雁的叫聲在愁緒裡聽了讓人難受，何況你還要獨自穿過雲霧繚繞的山路，在外地作客。過了潼關，樹色一天天催著寒意靠近；長安的宮苑附近，入夜以後搗衣的砧聲也漸漸多了起來。不要把長安只看成一個行樂的地方，免得大好時光就這樣被白白耽誤過去。\n \n 【背後的小故事】\n 魏萬是個真實存在的年輕人，後來改名魏顥。他從李頎這裡出發前往長安之後，一路輾轉打聽，竟然追著當時已經聲名遠播的李白，走了三千多里路才見到本人。李白對這份執著非常感動，兩人結為忘年之交，臨別前李白把自己散落各地的詩稿都託付給他整理成集。魏萬果然沒有辜負，後來編成《李翰林集》並親自作序，成為今天研究李白生平最重要的第一手資料之一。李頎送行時寫下的「莫見長安行樂處，空令歲月易蹉跎」，像是一句提前寫好的祝福，魏萬確實沒有蹉跎歲月。",
