    "title": "望月有感",
    "poem_notes": "【字詞與白話】\n 這首詩寫於白居易二十八歲時，因戰亂與饑荒被迫與五位兄弟姊妹分散五地，同一夜寫下五份幾乎相同的家書寄往各地。\n 白話：時局艱難、年歲荒亂，祖傳的家業已經空盡，兄弟們各自漂泊，東奔西散。戰亂過後，田園變得荒蕪冷落，骨肉親人流離失所，散落在各處路途之中。形單影隻，像是被拆散成千里之外的孤雁；離開了根的土地，像秋天裡四散飄零的蓬草。今夜我們共同望著這輪明月，想必都會落淚，因為同一個思鄉的心情，此刻正同時牽動著五個地方的親人。\n \n 【背後的小故事】\n 白居易年輕時遭逢藩鎮戰亂與關中大旱，家中僅有的田產難以維持，兄弟姊妹被迫各自逃難，分散在浮梁、於潛、烏江、符離、下邽五個地方，音訊往來要花上數月。這年秋夜，他在符離獨坐燈下，望著窗外明月，想到此刻同一輪月光，正同時照耀著五位散居各地的親人，忍不住提筆寫下這首詩，一連抄寫五份，分別寄往五個地址——讓五位親人在同一夜，收到同一份月光下的思念。",
    "zhuyin": "羈旅(ㄐㄧ ㄌㄩˇ)(jī lǚ)發音同\"機旅\"，寄居他鄉。\n 寥落(ㄌㄧㄠˊ ㄌㄨㄛˋ)(liáo luò)發音同\"聊洛\"，衰敗、破落。\n 弔影(ㄉㄧㄠˋ ㄧㄥˇ)(diào yǐng)發音同\"釣影\"，獨居無伴，對影自憐。形容孤獨之極。",
