    "poem_notes": "【字詞與白話】\n 孤山寺、賈亭：均為西湖邊的地標建築。沒馬蹄：淺草剛冒頭，剛好能沒過馬蹄。白沙堤：西湖邊的堤岸，即今日的白堤。\n 白話：從孤山寺北邊到賈公亭西側，湖面剛剛漲平，天上的雲低低垂著。幾隻早來的黃鶯爭搶向陽的樹枝，不知誰家的新燕正銜泥築巢。繁盛的野花漸漸開得讓人眼花繚亂，淺淺的春草剛好能沒過馬蹄。我最愛湖東這一帶，怎麼走都走不夠，尤其是那綠楊成蔭的白沙堤。\n \n 【背後的小故事】\n 白居易任杭州刺史期間，帶人疏浚西湖、修築堤壩蓄水灌溉農田，是他仕途中少見能真正落地見效的政績。這首詩寫的是他春天騎馬繞湖巡視時單純的喜悅，沒有貶謫的苦悶，只有對一片山水由衷的眷戀。離任時他把剩餘的官俸都留在州庫作為水利基金，沒留下多少財產，倒是這條堤、這片湖，和這首詩裡走不完的春天，留到了今天，成了西湖最好的名片。",
