    "id": 217,
    "dynasty": "中唐",
    "type": "七言律詩",
    "author": "韋應物",
    "title": "寄李儋元錫",
    "poem_notes": "【字詞與白話】\n 邑：此處指韋應物所管轄的地方。流亡：因賦稅、災荒而逃離家鄉、無以為生的百姓。愧：慚愧，自覺對不起。\n 白話：去年在花叢中與你們分別，今天花又開了，已經過了一年。世事茫茫難以預料，春愁滿懷，我常常一個人難以入眠。身體多病，常想著乾脆歸隱田園，可轄區裡還有流離失所的百姓，我拿著俸祿覺得慚愧。聽說你們原本要來探望我，我在西樓望著月亮，已經數不清圓缺了幾回。\n \n 【背後的小故事】\n 韋應物年輕時當唐玄宗的貼身侍衛，仗著皇帝寵信在長安街頭橫行，是出了名的紈絝子弟。安史之亂打碎了他的靠山，他這才關起門苦讀，從街頭混混一路讀成正經的地方官。當上刺史後，他常年生病，一心想歸隱田園，可轄區裡連年有百姓因交不起賦稅而流亡在外，他一想到這些人，就覺得自己這份俸祿領得心虛。相傳南宋朱熹讀到邑有流亡愧俸錢一句，感嘆當世官員裡還有幾個能有這種心思。",
    "zhuyin": "黯(ㄢˋ)(àn)發音同\"案\"，心神暗淡的樣子。\n 邑(ㄧˋ)(yì)發音同\"意\"，城市。如：「城邑」。此指韋應物所管轄的地區。\n 愧(ㄎㄨㄟˋ)(kuì)發音同\"潰\"，辜負、對不起。\n 俸(ㄈㄥˋ)(fèng)發音同\"鳳\"，薪資。以前單指官員所得的薪資、酬勞。",
