    "poem_notes": "【字詞與白話】\n 謫宦：被貶官。棲遲：停留、羈留。楚客：本指屈原、賈誼這類流放到楚地（長沙一帶）的人，這裡也暗指劉長卿自己。漢文有道：指漢文帝是史書公認的仁厚明君。搖落：草木凋零。\n 白話：賈誼被貶到這裡當了三年的官，千百年後，只留下這位楚地旅人的悲傷被人記得。秋草蕭瑟，我獨自尋訪，那人早已不在；寒林寂靜，只看見夕陽斜照。漢文帝雖然稱得上有道明君，對賈誼的恩澤卻還是太薄了；湘江水無情地流著，哪裡會知道我此刻在為誰憑弔。這一片草木凋零、寂靜蕭條的江山裡，實在讓人心疼，你當年究竟是為了什麼，才會被貶到這麼遙遠的天涯。\n \n 【背後的小故事】\n 賈誼是西漢初年的天才，二十出頭就被漢文帝破格提拔，議論政事一針見血，卻因此引來滿朝老臣忌憚排擠，被外放到長沙當太傅，三年後雖獲召回，又因梁懷王墜馬而死而自責，隔年抑鬱早逝，死時才三十三歲。劉長卿寫這首詩時，正是在被誣陷後第二次遭貶的南下途中，經過長沙，特地尋訪賈誼舊宅。他自己的仕途也是屢遭誣陷、幾度貶謫，跟賈誼隔了近九百年，處境卻驚人地相似。這首詩表面上問賈誼，其實問的是自己，是典型的借古人酒杯，澆自己心中塊壘的寫法。",
