    "poem_notes": "【字詞與白話】\n 汀洲：水中的沙洲，這裡指鸚鵡洲。楚客：流落楚地的旅人，這裡指劉長卿自己。漢口：長江與漢水交會處。戍：駐守的城樓。中丞：官名，指御史中丞，源姓友人當時擔任此職。\n 白話：沙洲上沒有波浪，也沒有霧氣，我這個流落他鄉的旅人，心裡的思念反而更加渺遠。漢口的夕陽下，鳥兒斜斜飛過江面；洞庭湖的秋水浩蕩，遠遠地與天相連。孤城背靠著山嶺，寒風裡傳來號角聲；江上戍樓孤零零的，我的船就在這裡夜泊。當年賈誼上書為漢室操心，卻被貶到長沙，這樣的事，從古到今都讓人心疼。\n \n 【背後的小故事】\n 這首詩是劉長卿第二次被貶南下途中所寫，船行經夏口附近的鸚鵡洲，遙望岳陽方向，寄給友人源中丞。鸚鵡洲因東漢才子禰衡在此被殺、又因他生前寫過〈鸚鵡賦〉而得名，是懷才不遇的著名典故之地。這首詩的結尾提到賈誼被貶長沙的往事，而長沙正是劉長卿這趟南下途中接下來會抵達的地方，他後來果然寫下另一首名作〈長沙過賈誼宅〉，兩首詩可以算是同一趟貶謫旅程前後相連的兩段心情記錄，一首在路上先想著，一首到了以後真的去看。",
