    "poem_notes": "【字詞與白話】\n 王濬：西晉將軍，奉命伐吳。樓船：高大的戰船。金陵王氣：指東吳建都金陵所仗恃的王者氣運。千尋鐵鎖：東吳在長江設下的千尋長鐵鎖，企圖阻擋晉軍。石頭：石頭城，金陵的別稱。\n 白話：王濬的戰船從益州順江東下，金陵城上空的王者氣運黯然收場。千尋長的鐵鎖沉進江底，一片降旗從石頭城裡舉了出來。人世間一次又一次為這些往事感傷，山的形狀卻依舊枕著寒冷的江水，什麼都沒變。從今以後天下統一，四海如同一家，昔日的舊營壘只剩秋天裡蕭蕭作響的蘆葦荻花。\n \n 【背後的小故事】\n 相傳劉禹錫路過西塞山時，正逢一場以六朝興亡為題的詩人聚會，座上賓客中據說也有白居易。眾人各自寫詩競技，劉禹錫寫下這首，把西晉滅吳、鐵鎖沉江、金陵降旗的往事，與眼前四海統一的現實對照，寫盡了六朝更迭的滄桑感——尤其山形依舊枕寒流一句，把一座山看盡王朝興衰卻始終不變的姿態寫得極沉靜。相傳在座賓客讀完這首詩後，紛紛擱筆不再寫，自認寫不出更好的了，這成了唐代詩壇流傳的一則佳話。劉禹錫自己也因永貞革新失敗被貶二十多年，寫這首詩時，他比誰都清楚興亡二字的重量。",
