    "title": "遣悲懷三首之一",
    "poem_notes": "【字詞與白話】\n 謝公最小偏憐女：借東晉謝安最疼愛小女兒謝道韞的典故，形容韋叢是父親韋夏卿最疼愛的女兒。黔婁：戰國時代齊國的貧士，這裡元稹用來自比當年的貧窮。藎篋：草編的箱篋，指簡陋的衣箱。泥他：糾纏、央求。\n 白話：你是父親最疼愛的小女兒，自從嫁給我這個像黔婁一樣貧窮的人之後，什麼事都不順遂。見我沒有衣服穿，你翻遍箱子找舊布料；我想喝酒，你二話不說拔下金釵去換錢。家裡窮，就用野菜和豆葉將就著吃，你也吃得心甘情願；沒有柴火，就靠院子裡老槐樹落下的枯葉添進灶裡。如今我的俸祿已經超過十萬錢了，能為你做的，卻只剩下設奠祭拜、辦法事超度。\n \n 【背後的小故事】\n 元稹二十五歲時娶韋叢，她出身名門，父親韋夏卿官居太子少保，卻不嫌棄元稹當時的貧窮，兩人共同捱過最窮困的幾年。韋叢二十七歲病逝，那時元稹的仕途正好開始好轉，俸祿大幅增加，卻已經沒有人能陪他享用。他一連寫了〈遣悲懷三首〉，這是第一首，字字句句都是兩人共患難的生活細節，被後世公認是最沉痛的悼亡詩之一，和他另一組作品〈離思〉裡「曾經滄海難為水」同樣出自對韋叢的思念。",
