    "poem_notes": "【字詞與白話】\n 這首詩寫於元稹悼念亡妻韋叢期間，整理妻子遺物時的真實心境。「貧賤夫妻百事哀」道出患難夫妻情深，卻連基本溫飽都無法保障的辛酸。\n 白話：從前開玩笑談論身後事，如今卻都真實地擺在眼前。你的衣裳大多已經施捨送盡，唯獨那個針線盒還留著，我始終不忍心打開。想起舊日情分，格外憐惜家中的婢女僕人，也曾因為夢見你在陰間缺錢，燒紙錢送去給你。我明白這樣的遺憾人人都會遇到，但貧賤夫妻共同經歷的種種，格外令人哀傷。\n \n 【背後的小故事】\n 元稹的妻子韋叢出身名門，卻甘願嫁給當時窮困的他，粗茶淡飯、賣釵沽酒也毫無怨言，兩人相守七年後她病逝，年僅二十七歲。這首詩寫於他將亡妻衣物一件件分送給窮親戚與婢僕的午後，唯獨面對她生前的針線盒，他捧在手裡卻始終不敢打開——裡頭或許還留著她未縫完的針線。他想起妻子生前曾半開玩笑問過「我若先走了，你怎麼辦」，如今這句玩笑話竟成了眼前的現實。兩年後元稹續娶他人，但那個午後他捧著針線盒不忍揭蓋的模樣，仍是他對這段患難情深最真實的悼念。",
