    "title": "遣悲懷三首之三",
    "poem_notes": "【字詞與白話】\n 鄧攸：晉代官員，戰亂中捨親子保姪子，後終身無子，典出典故指命運無常只能認命。潘岳：西晉文人，妻死後作悼亡詩傳世，此處指文字辭藻再多也難補遺憾。同穴：死後合葬。窅冥：幽暗渺茫。\n 白話：閒坐著悲傷你，也悲傷我自己，人活一輩子，滿打滿算能有多少時光？鄧攸戰亂中捨棄親子，後來無子，只能認命；潘岳妻死後寫盡悼亡詩，辭藻再多也終究不夠。就算死後同穴而葬，黃泉幽暗渺茫，又能有什麼指望；若寄望來生再續前緣，那就更難期待了。只能整夜睜著眼睛不睡，用這個方式，報答你這一生很少舒展過的眉頭。\n \n 【背後的小故事】\n 元稹的妻子韋叢出身名門，父親韋夏卿官位不低，她卻嫁給當時還清貧的元稹，跟著吃了七年苦——翻舊衣給他穿、當金釵換酒錢，這些細節元稹全記得清清楚楚。好不容易元稹官運轉好，韋叢卻在二十七歲病逝，一天好日子都沒趕上。這是遣悲懷組詩的第三首，元稹寫到鄧攸命中無子、潘岳悼亡費詞，兩個典故都在說：認命也好，寫再多也好，終究換不回一個人。最後他想到，同穴合葬渺茫難期，來生再續更難指望，能做的只剩下整夜不睡——用清醒著的痛，去償還妻子活著時很少能舒展的眉頭。",
    "zhuyin": "窅冥(ㄧㄠˇ ㄇㄧㄥˊ)(yǎo míng)發音同\"咬名\"，深邃的樣子。",
