    "poem_notes": "【字詞與白話】\n 黑雲壓城：形容敵軍壓境、局勢危急。燕脂：胭脂色，這裡形容戰場上暮色與血色交融。黃金臺：燕昭王築台招賢納士之處，這裡代指知遇之恩。玉龍：寶劍的美稱。\n 白話：敵軍壓境，黑雲厚重得像要把城牆壓垮，我軍鎧甲在陽光下閃著金鱗般的光。號角聲響徹瀰漫秋色的天空，塞上暮色與血色凝成一片深紫。半卷著紅旗，連夜急行軍趕到易水邊，寒霜濃重，連戰鼓都敲不響了。若能得到如燕昭王築台招賢那樣的知遇之恩，我願提著寶劍，為你血戰到死。\n \n 【背後的小故事】\n 李賀因父親名叫李晉肅，晉與進士的進同音犯諱，被迫放棄科舉，終生只能做個從九品小官，韓愈曾為他寫〈諱辯〉抱不平也無濟於事。他一輩子沒真正上過戰場，卻用想像力寫出了唐詩裡最壯烈的一場戰爭，把自己沒能施展的豪情，全部寄託在詩中將士為君而死的誓言裡。他二十七歲便英年早逝，沒等到那個賞識他的黃金臺，但這份想像中的豪情，燒了一千多年，至今仍亮著。",
