    "poem_notes": "【字詞與白話】\n 水部張十八員外：張籍，時任水部員外郎，家中排行十八。潤如酥：形容雨後地面濕潤光滑如酥油。逐春心：追逐春天景色的興致。\n 白話：長安街上的小雨把地面潤得像酥油一樣，草色遠看隱約有綠意，近看卻幾乎看不見。這是一年裡春天最好的時候，遠勝過滿城柳絮紛飛的暮春景致。別說自己公務繁忙、年紀已老，就沒了年輕時追逐春光的興致。拜託你先去江邊看看，回報我一聲那柳色如今染綠了幾分。\n \n 【背後的小故事】\n 張籍是韓愈多年提攜的晚輩兼摯友，兩人交情深到能互相調侃。這首詩寫於一場春雨初停的早晨，韓愈看見早春草色若有若無的曖昧美感，怕錯過就寫信催張籍趕緊出門去看，還先堵住對方可能拿公務忙、人老了當藉口推辭的話。這封帶著損友式叮嚀的邀約信，後來成了千古傳誦的早春名作，可他寫的時候想的沒那麼多，就是捨不得一個老朋友錯過這年最好的幾天。",
