    "title": "奉和中書舍人賈至早朝大明宮",
    "poem_notes": "【字詞與白話】\n 紫陌：京城的道路，因宮中常植紫色植物而得名。金闕：金碧輝煌的宮門。玉階：玉石鋪的臺階，指宮廷。仙仗：儀仗隊，形容其威嚴如仙人。鳳凰池：中書省的別稱，代指賈至的官職。陽春：古代高雅難唱和的樂曲。\n 白話：雄雞在紫色宮道上啼叫，曙光帶著寒意；黃鶯在京城裡鳴叫，春色已經漸漸消退。金色的宮門隨曉鐘打開，通向千家萬戶；玉階上儀仗如仙人般威嚴，簇擁著上千位官員。花叢間，佩劍玉飾的官員們迎著剛落的星光走來；柳條輕拂旗幟，露水還沒乾透。只有中書省裡賈至這位貴客，他這首〈陽春〉般的佳作，實在讓人難以唱和。\n \n 【背後的小故事】\n 這首詩寫於安史之亂後，唐肅宗收復長安、朝廷遷回大明宮恢復早朝舊制的時期，大約在西元七五八年前後。中書舍人賈至率先寫了一首記錄早朝盛況的詩，岑參、王維、杜甫都各自寫了唱和之作，四位大唐第一流的詩人，罕見地同時留下同一場景的紀錄，是中國文學史上少見的同框時刻。表面上是歌頌宮廷禮儀的應制詩，底下其實藏著劫後餘生、帝國終於恢復秩序的慶幸。",
    "zhuyin": "陌(ㄇㄛˋ)(mò)發音同\"末\"， 田間東西向的小路。司馬貞索隱引《風俗通》：「南北曰阡，東西曰陌。\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。",
