    "title": "同題仙游觀",
    "poem_notes": "【字詞與白話】\n 仙臺：指仙遊觀的樓臺。五城樓：傳說中天帝或神仙居住的城樓，這裡形容道觀建築的壯麗。秦樹、漢宮：借用秦漢古稱，泛指長安一帶。方外：世俗之外，指仙境或出家人的世界。丹丘：傳說中神仙居住、晝夜長明的地方。\n 白話：初次看到仙遊觀的樓閣，像傳說中神仙的五重城樓，周圍景物帶著雨後的清冷，昨夜的雨才剛剛收住。山色遙遙連接著長安城外的樹影，漸漸沒入暮色；附近村落的搗衣聲，近處聽來，彷彿在宣告長安城已經入秋。稀疏的松影落在空蕩的祭壇上，一片寂靜；細草散發淡淡香氣，小小的洞穴顯得格外幽深。何必捨近求遠去別處尋找仙境呢，人間本來就自有這樣的丹丘仙境。\n \n 【背後的小故事】\n 韓翃是「大歷十才子」之一，寫這首詩時仕途還很不得意，考中進士後多年沒有正式官職，常常一個人到長安城外的道觀散心排遣。仙遊觀是唐高宗時為道士潘師正興建，以清幽著稱。多年後，韓翃因為一首寫寒食節的詩「春城無處不飛花，寒食東風御柳斜」深得皇帝欣賞，朝廷正好要補一個官缺，又剛好有同名之人，官員請示，皇帝親筆批示指名要用寫這首詩的韓翃，他才一夕之間從默默無聞躍升為人人稱羨的對象。這首寫仙遊觀的詩，正好是他那段沉潛歲月裡留下的心境紀錄。",
