    "id": 233,
    "dynasty": "晚唐",
    "type": "七言律詩",
    "author": "李商隱",
    "title": "流鶯",
    "poem_notes": "【字詞與白話】\n 流鶯：漂泊不定的黃鶯，此處以鳥喻人。本意：真正的心意、用意。鳳城：京城長安的別稱。\n 白話：黃鶯四處漂泊，飛得參差不齊，穿越小路、臨近溪流也身不由己。牠婉轉的鳴叫難道沒有本意嗎，可是好時節未必等得到好機會。無論風朝露夜、陰晴變化，牠都在千家萬戶的門開了又關之間度過。早已為傷春的曲調苦惱得不忍再聽，長安城裡，到底哪裡才有屬於牠的一枝花木。\n \n 【背後的小故事】\n 李商隱早年受知於令狐楚，如同己出，後來還透過其子令狐綯的關係考中進士。偏偏他娶了王茂元的女兒，王家與令狐家分屬朝廷對立兩派，這樁婚事被視為背叛恩師，令狐綯從此對他冷了臉。李商隱看著園子裡一隻漂盪的黃鶯，覺得那就是自己，歌聲婉轉分明有心意，聽的人卻未必懂、未必肯幫。他一次次寫詩寄給這位昔日至交，想解釋、想求助，得到的多半是沉默，始終沒能在長安找到真正屬於自己的枝頭。",
    "zhuyin": "囀(ㄓㄨㄢˇ)(zhuàn)發音同\"轉\"，鳥鳴。",
