    "id": 234,
    "dynasty": "晚唐",
    "type": "七言律詩",
    "author": "李商隱",
    "title": "錦瑟",
    "poem_notes": "【字詞與白話】\n 全詩沒有明確對象，一千兩百年來眾說紛紜，有悼亡、自傷、懷才不遇等多種解讀。「此情可待成追憶，只是當時已惘然」是李商隱晚年詩集開篇之作。\n 白話：這把錦瑟為何無端有五十根弦？每一弦每一柱都讓人想起似水年華。莊周夢見自己化為蝴蝶，分不清夢與現實；望帝死後化為杜鵑，寄託滿腔春心。滄海月明時，鮫人的淚化作珍珠；藍田日暖時，美玉彷彿蒸騰出煙氣。這份感情何必等到將來才追憶，其實在當時就已經令人惘然若失了。\n \n 【背後的小故事】\n 李商隱一生夾在政治派系鬥爭之間，妻子王氏在他三十九歲那年病逝，此後他一個人輾轉幕府、養育兒子。這首詩大約寫於他晚年四十六歲時，看著一把積灰七年的錦瑟，想起年少求道、與妻子相守的種種往事，才驚覺那些美好在發生的當下，自己就已經隱隱預感留不住。詩題只是取開頭二字，他從未解釋寫給誰——一千兩百年來注家爭論不休，但答案或許早已在他自己寫下的五個字裡：「當時已惘然」。幾個月後，他就病逝了。",
    "zhuyin": "絃(ㄒㄧㄢˊ)(xián)發音同\"賢\"，裝於樂器以彈奏發聲的絲、線。同「弦」。\n 惘然(ㄨㄤˇ ㄖㄢˊ)(wǎng rán)發音同\"網然\"，模糊不清的樣子。",
