    "id": 235,
    "dynasty": "晚唐",
    "type": "七言律詩",
    "author": "李商隱",
    "title": "無題",
    "poem_notes": "【字詞與白話】\n 靈犀：犀牛角上有一條白線貫通兩端，古人相信能感應，比喻心意相通。「身無彩鳳雙飛翼，心有靈犀一點通」是全詩最著名的一句。\n 白話：昨夜的星辰、昨夜的風，就在那畫樓西邊、桂堂東邊。身上雖沒有彩鳳般的雙翅可以飛去找你，心裡卻像靈犀一樣與你一點相通。隔著座位玩送鉤遊戲時春酒正暖，分組玩射覆遊戲時蠟燈正紅。可嘆我聽到上朝的鼓聲就得離去，騎馬奔向蘭台，像隨風飄轉的蓬草。\n \n 【背後的小故事】\n 李商隱寫了將近二十首〈無題〉詩，多半寫的是不能公開的感情。這首寫的是一場宴席：他與一位女子隔座相望，眼神交會卻無法靠近，兩人分屬不同遊戲小組，被物理和身份同時隔開。天亮後他必須赴官上朝，只能騎馬離去，把自己比作身不由己的飄蓬。這首詩精準捕捉了一種現代人也熟悉的心情——在聚會或職場中與某人心意相通，卻因為責任在身，連告白的機會都沒有就必須轉身離開。",
    "zhuyin": "鉤(ㄍㄡ)(gōu)發音同\"勾\"，形狀彎曲，具有探取、懸掛、連接等功能的器具。此指酒鉤，當飲者以鉤引杯。\n 嗟(ㄐㄧㄝ)(jiē)發音同\"接\"，表示感傷、哀痛的語氣。",
    "rating": 6,
