    "title": "隋宮",
    "poem_notes": "【字詞與白話】\n 紫泉：即紫淵，因避唐高祖李淵名諱而改稱，此處指隋代宮殿所在。日角：古代相術用語，指額頭方正突起、有帝王之相，此處代指唐高祖李淵。腐草無螢火：古人相傳螢火蟲由腐草所化。\n 白話：隋代的宮殿如今鎖在煙霞之中，煬帝當年一心想把蕪城改建成自己的帝都。若不是天命歸於相貌堂堂的李淵，他那錦緞為帆的龍舟大概會一路開到天涯海角。如今腐草叢生卻連螢火蟲都沒有，古來種下的垂楊柳只剩黃昏歸巢的烏鴉棲息。若在地下遇見同樣亡國的陳後主，又何必再問起後庭花那樣的往事。\n \n 【背後的小故事】\n 相傳李商隱行經隋代運河舊道，聽當地人講起隋煬帝的往事，那條河、河邊的垂楊柳，都是煬帝為了南巡揚州所開鑿、栽種，他甚至下令捕捉螢火蟲夜裡放出，只為出遊時看著好玩。李商隱想到，若不是天命轉到唐高祖李淵身上，煬帝那艘龍舟恐怕還會一路開下去。如今河堤只剩腐草，連螢火蟲都沒有，垂柳上只落著烏鴉。他想起同樣因享樂而亡國的陳後主，寫下兩位亡國之君地下相見也無話可說。這首詩表面說前朝，心裡想的其實是當朝。",
