    "poem_notes": "【字詞與白話】\n 這首詩以女子口吻書寫夜深等候的心境，末句「何處西南待好風」化用曹植「願為西南風，長逝入君懷」的典故。\n 白話：說要來卻是句空話，一去就杳無蹤跡，月光斜照樓頭時，已是五更鐘響時分。夢裡因遠別而哭泣，怎麼呼喚也喚不醒；醒來急著寫信，墨還沒磨濃就催著寫完。燭光半籠罩著金翡翠的帷帳，麝香的氣息淡淡飄過繡著芙蓉的被褥。當年劉郎已經怨恨蓬萊仙山太過遙遠，如今我與你之間，卻更隔著萬重蓬山。\n \n 【背後的小故事】\n 李商隱寫下將近二十首〈無題〉詩，多半藏著他不能公開言說的心事。這首詩他借一位女子的口吻與視角，描寫她深夜獨自縫製帷帳、搖著團扇卻與心上人擦身而過、徹夜點燈等待消息、望著石榴花開花謝仍音訊全無的漫長等待。詩末化用曹植「願為西南風，長逝入君懷」的典故，讓這位女子問出「何處西南待好風」——這既是她的疑問，也是李商隱借她之口，說出自己一輩子不敢言說的期盼與遺憾。",
    "zhuyin": "更(ㄍㄥ)(gèng)發音同\"耕\"，古代表示夜間計時的用語。一夜分為五更，每更約兩小時。\n 麝(ㄕㄜˋ)(shè)，麝香的香氣。",
