    "id": 240,
    "dynasty": "晚唐",
    "type": "七言律詩",
    "author": "李商隱",
    "title": "無題",
    "poem_notes": "【字詞與白話】\n 蓬山：傳說中的蓬萊仙山，此處比喻對方遙不可及。「春蠶到死絲方盡，蠟炬成灰淚始乾」是全詩最著名的一句，寫的是無法停止的感情。\n 白話：見面已經很難，離別更是難捨難分，東風無力，百花漸漸凋殘。春蠶要吐絲到死才會停止，蠟燭要燃燒成灰燭淚才會流乾。她清晨照鏡子，該是擔心鬢髮漸漸改變了吧；夜裡吟詩，也該覺得月光寒冷了吧。蓬萊仙山離這裡並不算遠，希望青鳥能殷勤地替我去探望她。\n \n 【背後的小故事】\n 這首詩的對象千年來眾說紛紜——有人說是他年少時愛慕的女道士，有人說是身分懸殊的貴族女子。李商隱始終沒有說明，只以「無題」為名。詩中寫的是一段明知不會有結果、卻無法停止的感情：像春蠶吐絲到死方休，像蠟燭燃燒到成灰淚才乾涸。他想像對方清晨照鏡時是否也在為容顏老去發愁，卻連一封信都送不到對方手中，只能寄望傳說中的青鳥代為探看。這首詩寫的不是某個具體的人，而是每個人心中那份明知希望渺茫、卻無法放手的執著。",
    "zhuyin": "鬢(ㄅㄧㄣˋ)(bìn)發音同\"殯\"，靠近耳朵兩側的頭髮。",
