    "title": "無題二首之一",
    "poem_notes": "【字詞與白話】\n 鳳尾香羅：繡有鳳尾紋樣的香羅綢緞。月魄：月亮，這裡形容團扇裁成月亮般的圓形。斑騅：毛色青白相間的馬，這裡代指心上人的坐騎。\n 白話：鳳尾紋的香羅帳子薄薄疊了幾層，深夜裡還在縫製繡著碧紋圖案的圓頂帳。她用裁成月形的團扇遮住羞怯的臉龐，車聲如雷般駛過，兩人卻沒能說上一句話。曾經在燈燼將盡的寂寥夜裡苦守，如今石榴花都開了，消息依然斷絕。那匹青白花馬只拴在垂楊岸邊，不知何處才能借得西南風把心意捎過去。\n \n 【背後的小故事】\n 這是李商隱最著名的無題詩之一，連他同時代的人都猜不透詩中人是誰——有人說是他早年愛慕的女道士，有人說是與他婚姻牽連的政治處境的隱喻。真相已不可考，只能誠實地說相傳如此。詩裡寫的，其實是一種所有人都懂的心情：一輛擦身而過的香車，車簾裡似乎坐著自己認得的人，可是車聲太響、時間太短，一句話都沒能問出口。這份說不出口的悵然，比坐實某段戀情，更接近他當時真正的心事。",
    "zhuyin": "寂寥(ㄐㄧˊ ㄌㄧㄠˊ)(jì liáo)發音同\"及聊\"，寂靜冷清。\n 燼(ㄐㄧㄣˋ)(jìn)發音同\"進\"，物體燃燒後剩餘的東西。如：「餘燼」。\n 騅(ㄓㄨㄟ)(zhuī)發音同\"追\"，毛色蒼白相雜的馬。",
