    "poem_notes": "【字詞與白話】\n 重帷：層層垂下的帷幕，指臥房深處。神女：巫山神女，傳說與楚王夢中相會而後消失，比喻美好卻虛幻的情緣。小姑：青溪小姑，傳說中獨居無夫的女神，也暗指獨居的少女。\n 白話：層層帷幕深深垂下遮住莫愁堂，躺下之後才發覺這清冷的長夜特別漫長。神女那段情緣終究只是一場夢，小姑獨居本來就沒有丈夫。風波不相信菱角的莖有多柔弱，偏要去折騰它；月光和露水誰又給了桂葉飄香的機會。明知道一直這樣思念沒有任何用處，也不妨就任由自己惆悵、任性糊塗一次。\n \n 【背後的小故事】\n 義山十六歲被恩師令狐楚看中，與其子令狐綯情同手足。令狐楚死後，義山娶了政敵陣營王茂元之女，從此被令狐綯冷落，終身仕途坎坷。他多年寫信懇求舊日情分，明知無用仍執意而為。這首借深閨女子之口寫成的詩，後人讀了千年，分不清他寫的到底是思婦，還是那段回不去的少年情誼。",
    "zhuyin": "帷(ㄨㄟˊ)(wéi)發音同\"圍\"，帳幕。\n 惆悵(ㄔㄡˊ ㄔㄤˋ)(chóu chàng)發音同\"仇唱\"，悲愁、失意。",
