    "type": "七言律詩",
    "author": "溫庭筠",
    "title": "利洲南渡",
    "poem_notes": "【字詞與白話】\n 澹然：水面平靜的樣子。曲島：彎曲的江中小島。翠微：青翠的山色。棹：船槳，這裡代指船。五湖：春秋時范蠡功成身退後泛舟隱居的地方，後世用來指歸隱山水。忘機：忘掉世俗的心機算計。\n 白話：江水平靜地映著斜陽，彎曲的小島蒼茫地連著青翠的遠山。波浪上馬兒嘶鳴，看著船隻搖槳離去；柳樹旁有人歇腳，等著船再划回來。幾叢沙洲水草邊，一群鷗鳥被驚散飛開；萬頃江邊田野上，一隻白鷺獨自飛過。有誰能懂得像范蠡那樣駕船歸隱，獨自在五湖的煙水裡忘卻塵世的算計呢。\n \n 【背後的小故事】\n 溫庭筠才思敏捷到考試只要拱手八次就能寫出一篇八韻賦，人稱溫八叉，照理該是科場常勝軍，卻因為言語尖利得罪考官、又習慣在考場裡幫鄰座作答，一輩子屢試不第，仕途也因此坎坷潦倒。這首詩寫他在利州渡口等船，眼前眾人各自忙著渡河、等船、歸家，他卻想起范蠡功成之後棄官泛舟五湖的往事。范蠡那種說放手就放手的灑脫，正好照見溫庭筠自己怎麼樣都甩不脫的糾纏與委屈——這份羨慕，是他寫給自己聽的。",
    "zhuyin": "澹(ㄉㄢˋ)(dàn)發音同\"但\"，恬靜而寡欲。\n 棹(ㄓㄠˋ)(zhào)發音同\"照\"， 借以指船。同「櫂」。\n 頃(ㄑㄧㄥˇ)(qǐng)發音同\"請\"，量詞。表示面積的單位。在公制中一頃等於一百畝。也稱為「公頃」。\n 范蠡(ㄈㄢˋ ㄌㄧˇ)(fàn lí)發音同\"飯理\"，人名。字少伯，生卒年不詳，春秋楚人。與文種同事越王句踐二十餘年，苦身戮力，卒以滅吳，尊為上將軍。蠡以大名之下，難以久居，且句踐為人，可與共患難，難與同安樂，遂浮海適齊，變姓名為鴟夷子皮。至陶，操計然之術以治產，因成巨富，自號陶朱公。",
    "rating": 2,
