    "dynasty": "晚唐",
    "type": "七言律詩",
    "author": "秦韜玉",
    "title": "貧女",
    "poem_notes": "【字詞與白話】\n 秦韜玉靠依附權宦田令孜獲得進士出身，一生為此備受議論。「苦恨年年壓金線，為他人作嫁衣裳」是全詩最廣為流傳的名句。\n 白話：住在蓬草編門的人家，從未見識過綾羅綢緞的香氣，想託人做媒說親，反而更添自己的傷感。有誰真正欣賞風雅高尚的格調呢？大家只憐惜當下流行的儉樸梳妝。她敢誇口自己的十根手指靈巧善於針線，卻不願跟人爭著把雙眉畫得又細又長。年復一年辛苦地為別人縫製嫁衣，壓著那金線，心裡總是充滿怨恨。\n \n 【背後的小故事】\n 秦韜玉屢試不第，後來投靠權宦田令孜當幕僚，靠著這層關係才被特賜進士出身，此後始終被科舉正途出身的士人另眼相看。這首詩寫他某天路過長安窮巷，看見一位貧家女孩坐在門口，低頭替別人縫製嫁衣——她手藝靈巧、格調高潔，卻無人賞識，也負擔不起自己的婚事。秦韜玉看著看著，忽然覺得那女孩就是自己的寫照：他一輩子替權貴撰寫文書、鋪陳文采，那些成就都像是穿在別人身上的嫁衣，自己卻始終不曾真正擁有。這句「為他人作嫁衣裳」，道盡了古今無數懷才卻無法為自己而活之人的辛酸。",
    "zhuyin": "鍼(ㄓㄣ)(zhēn)發音同\"真\"，縫布帛的工具。同「針」。",
