    "title": "咸陽城東樓/咸陽城西樓晚眺/西門",
    "poem_notes": "【字詞與白話】\n 蒹葭：蘆葦。汀洲：水中沙洲。秦苑、漢宮：分別指秦朝、漢朝的宮苑遺址，此地曾是秦漢故都咸陽一帶。\n 白話：一登上這座高城，就湧起望不到邊的愁緒，眼前的蘆葦楊柳，看起來竟像江南水邊的沙洲。溪上雲氣剛剛聚起，太陽已沉到樓閣後面；山雨就要來了，滿城的風先灌滿了這座樓。鳥兒落進秦朝苑囿的荒草裡歇息，蟬鳴聲響在漢朝宮殿的黃葉間。路過的人啊，別再問當年那些興亡舊事了，只有渭水依舊從東邊流過，日夜不停。\n \n 【背後的小故事】\n 許渾體弱多病，一生奔波於赴任辭官的路上，常繞道憑弔前朝廢墟。這次途經秦漢故都咸陽，登樓遠眺，眼看山雨將至、滿城風動，聯想起晚唐宦官專權、藩鎮割據的亂象，心裡那份說不清的不安，與天象悄然對上。這句詩後來成了形容大禍將至的千古名句，四十多年後，大唐果然在風雨中傾覆。",
