    "type": "七言律詩",
    "author": "薛逢",
    "title": "宮詞",
    "poem_notes": "【字詞與白話】\n 十二樓：泛指後宮眾多的樓閣。望仙樓：唐代宮中樓閣名，這裡取其望向遠方之意。金獸：獸頭形狀的門環或鎖具。銅龍：銅鑄的水漏，古代計時器。雲髻：形容如雲朵般蓬鬆的髮髻。袍褲宮人：穿著粗布衣褲、做粗活的低階宮女。\n 白話：後宮眾多樓閣裡的女子，一早就梳妝打扮完畢，站上望仙樓遠遠望著，盼著能見到皇帝一面。門上的金獸鎖環冰冷，銅鑄水漏滴答不停，白天的時辰顯得格外漫長。梳好雲髻般的髮型，還是忍不住又對鏡端詳；絲綢衣裳換了又換，還要再添點香氣。遠遠望向正殿簾子掀開的地方，看到的卻只是一個穿粗布衣褲的宮女，正在打掃皇帝的床鋪。\n \n 【背後的小故事】\n 薛逢是晚唐詩人，年輕時進士及第，一度意氣風發，但因性格剛直、屢次得罪當朝宰相，仕途始終不順，官職越做越低，終生沒能得到真正的重用。宮怨詩在唐代常被文人拿來寄託自己懷才不遇的心情，表面寫深宮女子等待皇帝臨幸而終究落空，底下往往藏著士人等待朝廷賞識卻一再落空的自況。這首詩結尾以一個打掃床鋪的宮女作結，不寫失落，卻讓那份精心準備後的落空不言而喻，是這類宮怨詩裡少見的含蓄筆法。",
    "zhuyin": "髻(ㄐㄧˋ)(jì)發音同\"記\"，盤結於頭頂或腦後的頭髮，有各種形狀。",
