    "title": "寄黃幾復",
    "poem_notes": "【字詞與白話】\n 黃幾復本名黃介，與黃庭堅同鄉、同姓卻不同族，是他少年時代的摯友。「桃李春風一杯酒，江湖夜雨十年燈」是全詩最著名的一句，寫盡少年歡聚與中年離散的強烈對比。\n 白話：我住在北方的渤海邊，你住在南方的海邊，就算託大雁傳信，牠也飛不過那麼遠的距離。當年桃李盛開的春風裡，我們曾共飲一杯酒；如今各自在江湖夜雨中，孤燈相伴已經十年。你持家清貧，家徒四壁，替人治病卻樣樣精通，不必像古人那樣經歷三次骨折才學會醫術。想像你埋首讀書，如今頭髮應該已經全白了吧，隔著溪水，猿猴在瘴癘之地的藤蔓間哀鳴。\n \n 【背後的小故事】\n 黃庭堅與黃幾復是江西同鄉，年少時一同讀書、一同飲酒，暢談未來的抱負，兩人先後中了進士，卻此後天各一方——黃庭堅輾轉北方任職，黃幾復則遠赴嶺南擔任四會縣令，一南一北相隔十年未見。這年春天，黃庭堅望見一隻北飛的大雁，想起傳說大雁飛不過南嶺，音信難通，忍不住提筆寫下這首詩，想像老友在異鄉家徒四壁、白髮讀書的模樣。「桃李春風一杯酒，江湖夜雨十年燈」短短十四字，濃縮了少年相聚的歡快與中年離散的滄桑，成為千古傳誦的名句。",
    "zhuyin": "蘄(ㄑㄧˊ)(qí)發音同\"其\"，祈求。\n 肱(ㄍㄨㄥ)(gōng)，三折肱語出《左傳》，指多次折斷胳膊，比喻經驗豐富、造詣精深。\n 瘴(ㄓㄤˋ)(zhàng)發音同\"丈\"，指山林間因濕熱蒸鬱而產生的有毒氣體，容易使人致病，常形容我國南方山區。",
