    "poem_notes": "【字詞與白話】\n 決決：水流動的聲音。燒痕：野火燒過的痕跡。女王城：黃州城東的一個地名。斷魂：形容極度悲傷、失魂落魄的樣子。\n 白話：一連十天春寒，窩在家裡沒出門，沒想到江邊的柳樹早已悄悄染綠了整個村子。漸漸聽見山谷裡冰雪融化、溪水潺潺流動的聲音，去年火燒過的荒地上，也已經冒出一片新綠，燒痕都看不見了。幾畝荒地就留我在這裡住下吧，你們替我溫了半瓶濁酒等著。去年的今天，我還走在艱難的關山路上，細雨中看著梅花，心都要碎了。\n \n 【背後的小故事】\n 蘇軾因為烏臺詩案被貶到黃州，剛到任時舉目無親，正是在正月二十日這天，一個人冒著細雨、踩著滿路梅花走過艱險的關山路，心裡淒惶到了極點。一年之後同一天，他和當地新交的朋友潘丙、古耕道、郭遘一起去岐亭探望隱士陳慥，三人又送他到女王城東邊的禪院。這一年裡，他在朋友幫忙下開墾了城東的一塊荒地，種田自給，自號東坡居士。同一個日子，一年前後的心境完全不同——蘇軾把這個對照寫進詩裡，往後幾年他還多次在同一天寫詩回顧這件事，成了他黃州歲月裡一個特別的私人紀念日。",
