    "poem_notes": "【字詞與白話】\n 秋鴻：秋天的大雁，比喻年年如期而至、信守約定的人。招魂：《楚辭》典故，此處反用，意指自己活得好好的，不必勞人招魂安慰。\n 白話：東風還不肯吹進東邊的城門，我騎馬又去尋找去年到過的那個村子。人就像秋天的大雁，年年守信歸來；世事卻像一場春夢，醒來後一點痕跡都留不下。江城的白酒濃烈，喝了三杯正好；鄉野老人蒼老的臉上，帶著溫厚的笑容。我們已經約好年年都要在這一天相會，老朋友，不用特地為我招魂擔心。\n \n 【背後的小故事】\n 烏台詩案後，蘇軾被貶黃州，掛著空銜、形同罪官，昔日京城名士避之唯恐不及。倒是本地的潘丙、郭遘這樣不起眼的小人物，常伴他左右。元豐三年正月二十，三人出城到女王城飲酒；一年後同日故地重遊，他寫下和詩，把功業屈辱都看作留不下痕跡的春夢，唯有朋友年年赴約如秋鴻守信，才是真正牢靠的東西。",
