    "poem_notes": "【字詞與白話】\n 柳暗花明又一村：全詩最著名的一句，後世常用來比喻絕境中忽然出現轉機。臘酒：臘月裡自家釀造、尚未過濾的濁酒。\n 白話：不要笑農家臘月釀的酒渾濁，豐收之年招待客人雞肉豬肉都很豐盛。山巒重疊、溪水縈迴，正懷疑前面已經無路可走，忽然柳蔭深深、花朵明豔之處，又出現一座村莊。將近春社日了，簫鼓聲此起彼落，村民衣著簡樸，古風猶存。從今以後如果還能趁著月色悠閒地來訪，我會隨時拄著拐杖，在夜裡叩開你們的家門。\n \n 【背後的小故事】\n 陸游四十二歲時因主戰言論激烈被罷官，返鄉閒居了一整個冬天，心情鬱悶。隔年春天他外出散步，走進一座山村，受到村民熱情款待，一壺渾濁的臘酒、簡單的雞豬肉，卻是他許久未曾感受過的真誠善意。飯後他繼續在山間閒走，山重水複間一度以為無路可走，轉個彎卻見柳暗花明又是一村。這個瞬間讓他明白：被罷官不是絕路，只是還沒走到下一個村子。此後他果然東山再起，活到八十五歲，寫下近萬首詩，臨終前仍念念不忘收復北方。",
    "zhuyin": "臘(ㄌㄚˋ)(là)發音同\"辣\"，陰曆十二月稱為「臘月」。",
