    "poem_notes": "【字詞與白話】\n 汗青：史書的代稱，古時竹簡書寫前需用火烤去竹汁，稱為汗青。「人生自古誰無死，留取丹心照汗青」是文天祥用生命兌現的誓言。\n 白話：辛苦遭逢世事，靠著讀一部經書出仕，如今干戈零落，已過了四年。山河破碎得像被風吹散的柳絮，自己的身世浮沉得像被雨打的浮萍。在惶恐灘頭訴說當年的惶恐，如今在零丁洋裡感嘆自己的孤苦零丁。人生自古以來誰能不死？只求留下一片赤誠之心，照耀史冊。\n \n 【背後的小故事】\n 文天祥兵敗被俘，元軍押解他經過零丁洋時，統帥張弘範逼他寫信勸降仍在抵抗的宋軍將領，他卻寫下這首詩作為回覆，表明寧死不降的決心。張弘範看完便放棄了勸降。之後文天祥被囚禁三年，忽必烈親自勸降、許以宰相之位，他仍不為所動，最終從容就義，臨刑前朝南方跪拜三次。人們在他衣帶中發現遺言：「讀聖賢書，所學何事？而今而後，庶幾無愧。」他用自己的死，把詩中的誓言變成了事實。",
    "zhuyin": "寥(ㄌㄧㄠˊ)(liáo)發音同\"聊\"，空虛、空曠、寂靜或稀少。",
