    "id": 254,
    "dynasty": "清",
    "type": "七言律詩",
    "author": "納蘭性德",
    "title": "木蘭花-擬古決絕詞柬友",
    "poem_notes": "【字詞與白話】\n 「人生若只如初見」是全詞開篇也是最著名的一句，感嘆人心易變，不如永遠停留在初見時的美好。柬友：寫給朋友的書信體詞作。\n 白話：人生如果永遠都像初次相見那樣美好，何必還要面對秋風吹起、如畫扇般被冷落的悲傷呢？如今你輕易地變了心，卻反過來說是我的心容易改變。想當年唐玄宗與楊貴妃在驪山夜半私語盟誓，即使後來馬嵬坡雨夜聞鈴，他始終沒有怨恨過貴妃。這樣比起來，還不如那位被世人稱作薄倖的錦衣郎，至少當年還許下過比翼雙飛、連理同枝的誓言。\n \n 【背後的小故事】\n 納蘭性德出身顯赫，是康熙身邊的一等侍衛，父親更是當朝宰相，然而他二十二歲喪妻後始終無法釋懷，寫下大量悼亡詞。這首詞相傳寫於他收到一封老友變心背棄的來信之後，深夜獨坐書房，決定以女子的口吻回應——他想起漢代班婕妤被冷落後自比秋扇的典故，又想起唐玄宗與楊貴妃至死不渝的盟誓，反襯朋友背信忘義的可悲。開篇「人生若只如初見」看似寫給朋友，實則也是他對亡妻初見那一刻念念不忘的心聲。三年後他便英年早逝，這句感嘆人心易變的名句，卻流傳了三百多年。",
    "zhuyin": "驪(ㄌㄧˊ)(lí)發音同\"離\"，純黑色的馬。驪山位於陝西省，距離西安市區25公里，是秦嶺山脈的一個支脈，東西長25公里，南北寬14公里，最高海拔1302米。它是「關中八景」之一的「驪山晚照」。",
