    "title": "自嘲",
    "poem_notes": "【字詞與白話】\n 華蓋運：民間說法，指人交了倒楣運，諸事碰壁。孺子牛：典故出自齊景公為兒子扮牛供其玩耍，此處指心甘情願為下一代、為弱者服務。\n 白話：交上倒楣的華蓋運，還能求什麼呢，才剛想翻身，額頭就先碰了一下。戴著破帽子遮住臉，匆匆穿過熱鬧的街市；家裡窮得像條漏船，卻還載著酒在水中央漂盪。對著千夫所指的敵人，我冷眼橫眉、絕不低頭；面對像孩子一樣需要照顧的人，我甘願俯首彎腰，做一頭老實的牛。躲進這棟小樓裡，我就自成一方天地，管他外頭是冬是夏、是春是秋。\n \n 【背後的小故事】\n 一九三一年，魯迅親近的青年學生柔石等人被祕密處決，他悲痛許久。次年秋天，郁達夫、柳亞子請他吃飯，席間有人打趣他諸事不順，他笑稱自己交了華蓋運，即席寫下這首詩。橫眉對敵、俯首為牛的兩句，後來成為他一生最著名的自我寫照，外頭是被通緝追捕的落魄，骨子裡卻是絕不妥協的堅硬。",
