    "poem_notes": "【字詞與白話】\n 玉階：宮殿前的白玉台階，泛指宮廷。侵：浸濕、滲透，形容站太久露水沾透了羅襪。玲瓏：形容水晶簾子精緻剔透，這裡也暗指隔簾望月時眼神的清亮。\n 白話：玉石台階上凝結了白露，站得太久，露水浸濕了她的絲織襪子。她終於轉身放下水晶簾子，隔著剔透的簾幕，抬頭望著那輪秋月。\n \n 【背後的小故事】\n 李白最崇拜的詩人是南朝謝朓，常說一生低首謝宣城。謝朓寫過同題的宮怨詩，李白年輕時讀過就想找機會較量。他在翰林院當差時常半夜候旨，一晚看見一名宮女久候玉階，露水濕透了襪子仍不動。他學謝朓的手法，全詩不用一個怨字，只留下露水、羅襪、水晶簾與秋月，把委屈藏進畫面裡，讓讀的人自己感受那份無言的等待。",
