    "poem_notes": "【字詞與白話】\n床：多數學者認為指的是庭院裡的井欄或可摺疊的胡床，不是現代睡覺用的床——所以李白當時很可能不是躺在房裡，而是坐在窗邊或井邊納涼。疑：不是懷疑，是看錯、誤以為。\n白話：床前灑落一片月光，皎潔得讓人一瞬間以為是地上結了霜。抬頭看見那輪明月，低下頭，思念湧上心頭，想起了遠方的家鄉。\n\n【背後的小故事】\n這四句是李白二十六歲寫的，那時他剛離開四川不到一年。那年秋天他生病，獨自客居在外地的旅店裡，半夜被月光照醒，恍惚間真的以為地上結了霜。抬頭看月，低頭卻只能想家——他當時大概以為，出去闖幾年就會回去。他不知道，這一走就是三十五年，直到六十一歲客死異鄉，再也沒能回過四川老家。這首所有人小時候都會背的詩，其實是他一生漂泊的預告。",
