    "poem_notes": "【字詞與白話】\n 敬亭山位於今安徽宣城，南朝詩人謝朓曾在此為官並築樓。「相看兩不厭，唯有敬亭山」是全詩最著名的一句，寫的是人與山相對無言卻彼此不厭的孤獨心境。\n 白話：成群的鳥兒都已高飛遠去，一朵孤雲也獨自悠閒地飄走了。彼此對看而不感到厭倦的，就只有這座敬亭山了。\n \n 【背後的小故事】\n 李白一生七次造訪宣州，只因心中景仰南朝詩人謝朓曾在此任官、築樓賦詩。這首詩寫於他五十三歲那年，離開長安已九年，朋友死的死、散的散，妻子也不在身邊，他獨自一人登上敬亭山。山頂上，鳥群漸漸飛盡，天邊一朵孤雲也悠悠飄走，天地間彷彿只剩他與眼前這座山彼此相伴。他沒有感到難過，反而覺得踏實——即使被朝廷遺忘、被世界冷落，至少還有一座山，願意與他長久相看、彼此不厭。敬亭山從此成了中國人心中，孤獨時最容易想起的那座山。",
