    "poem_notes": "【字詞與白話】\n 八陣圖：諸葛亮所創的軍事陣法遺跡，以石堆排列而成。江流石不轉：江水沖刷千年，石堆依然不動。失吞吳：指劉備伐吳失敗，打亂諸葛亮聯吳抗曹的戰略。\n 白話：諸葛亮的功業在三國鼎立中已是頂點，八陣圖更讓他成名。任憑江水沖刷千年，這些石堆依然屹立不動，只留下一樁沒能挽回的遺恨——伐吳失敗，聯盟盡毀。\n \n 【背後的小故事】\n 杜甫五十五歲流寓夔州，親眼見到諸葛亮留下的八陣圖遺石，任江水沖刷千年不倒。他想起諸葛亮一生主張聯吳抗曹，卻攔不住劉備執意伐吳為關羽報仇，夷陵慘敗毀了整個戰略布局。杜甫自己一生想匡扶社稷，卻在安史之亂裡輾轉流離，處處身不由己。站在江邊，他忽然懂了，諸葛亮的遺恨不是輸給敵人，而是輸給自己最信任的人一個攔不住的決定。",
