    "poem_notes": "【字詞與白話】\n 返景：夕陽返照的餘光。「空山不見人，但聞人語響」是以聲寫靜的經典手法——遠處模糊的回音，反而襯托出空山的幽深。\n 白話：空寂的山中看不見人影，只聽見遠處傳來隱約的人語回聲。夕陽的餘光穿透幽深的樹林，再次照映在青苔上。\n \n 【背後的小故事】\n 這首詩寫於王維在輞川別業「鹿柴」一帶散步時。整首詩沒有一個「我」字，全由山、聲、光、苔這些被動、間接的元素構成——遠處模糊的人聲不是打破寂靜，反而證明了山有多空；穿透密林的餘光找到一絲縫隙，照亮平時曬不到太陽的青苔。王維把自己完全隱去，讓風景自己說話，是禪宗「無我」境界在詩裡的極致體現：當你不再急著表達自己，反而能看見、聽見更多平常錯過的細節。",
    "zhuyin": "景(ㄧㄥˇ)(jǐng)發音同\"影\"，物體的形影、陰影。同「影」。",
