    "poem_notes": "【字詞與白話】\n 幽篁：幽深的竹林。長嘯：撮口發出悠長的聲音，古人抒發情懷的一種方式。\n 白話：獨自坐在幽深的竹林裡，一邊彈琴一邊放聲長嘯。深林裡沒有人知道我在這裡，只有明月照過來，陪伴著我。\n \n 【背後的小故事】\n 安史之亂中王維被叛軍俘虜，被迫接受偽職，凝碧池宴會上目睹樂工含淚奏樂的一幕，事後偷偷寫詩寄託忠心。亂平後他因這首詩及弟弟王縉求情才逃過清算，僅被降職。此後他常躲進輞川別業的竹林深處，不必表演忠誠、不必向誰交代，只有月亮照著他，這是他劫後餘生，難得能徹底做自己的時刻。",
