    "poem_notes": "【字詞與白話】\n 王孫：原指貴族子弟，此處化用《楚辭·招隱士》「王孫遊兮不歸，春草生兮萋萋」的典故，用來稱呼歸隱山林的友人。\n 白話：在山中送別友人之後，天色將晚，我回來把柴門關上。明年春天，山裡的草會照樣綠起來，可是你，還會不會回來呢？\n \n 【背後的小故事】\n 王維一生在出仕與歸隱之間來回擺盪，輞川別業是他的另一個家。這回他送一位真心打算歸隱山林、不再回頭的朋友，陪走到分手處，看著背影消失在山梁後才轉身回家。關上柴門的那一刻，他心裡懸著的疑問，與其說是問朋友，不如說也是問他自己，明年春天，自己會不會也像今天送走的人一樣，一頭走進山裡就不想出來了。",
