    "poem_notes": "【字詞與白話】\n採擷：採摘。相思：思念。這首詩原題其實是《江上贈李龜年》，是寫給一位男性樂師的。\n白話：紅豆生長在南方，春天一到又抽出新的枝芽。希望你多採摘一些，因為這東西最能寄託思念。\n\n【背後的小故事】\n李龜年是盛唐宮廷第一樂師，王維年輕時精通音律，兩人是詞配樂的老搭檔，一個寫詞一個唱。安史之亂爆發，王維被叛軍抓住強迫任偽職，戰後差點被治罪；李龜年則流落江南，靠賣藝維生。戰後王維聽說老友還活著，寫下這首詩寄去——沒有一句提到過去的繁華，只說「你那邊的紅豆多採一些吧」。因為多說一句，兩人都會哭出來。這不是情詩，是共同活過一個時代的老朋友，隔著千里問一句「你還好嗎」。",
