    "poem_notes": "【字詞與白話】\n 陰嶺：山的北面，背陽，故稱陰嶺。霽色：雨雪初晴後的光亮。林表：樹林的頂端、邊緣。暮寒：傍晚的寒意。\n 白話：終南山背陰的那一面山嶺格外秀麗，積雪彷彿浮在雲端。樹林邊緣透出雨雪初晴的光亮，長安城裡，傍晚的寒意卻因此更重了。\n \n 【背後的小故事】\n 這首詩相傳是祖詠參加科舉省試時所作，依照規定，這類考試詩必須寫成五言六韻十二句的排律，祖詠卻只寫了四句就交卷，理由是「詩意已盡」，不願為了湊字數硬塞多餘的句子。這是唐代科舉史上少見的軼事，展現出他對詩藝的堅持勝過對考試規則的服從。祖詠與王維是至交好友，兩人詩作多有往來唱和。他後來雖然順利考中進士，仕途卻始終不得志，晚年辭官歸隱汝墳一帶，以漁樵自娛，終老鄉野。",
