    "title": "宿建德江",
    "poem_notes": "【字詞與白話】\n 煙渚：籠罩著煙霧的水中小洲。客愁新：旅人心中新生的愁緒，不是延續舊愁。野曠：原野空曠。\n 白話：把船划到煙霧繚繞的小洲邊停泊，天色漸暗，旅途中的愁緒又新添了幾分。原野空曠，遠處的樹木彷彿比天空還低，江水清澈，月亮的倒影靠得離人很近。\n \n 【背後的小故事】\n 孟浩然四十歲赴長安應試落第，滯留長安期間在王維家偶遇唐玄宗，被要求當場朗誦近作，一句不才明主棄，多病故人疏惹得玄宗不悅，從此再無人敢舉薦他，仕途徹底斷絕。心灰意冷的他離開長安，南下漫遊吳越排遣。行至建德江邊停船過夜，眼前江清月近的美景，卻牽出心裡剛剛長出來的新愁——不是舊日的失落在延續，而是每次靠岸入夜，那份有家歸不得的感覺重新冒出頭。",
