    "poem_notes": "【字詞與白話】\n曉：天亮。全詩沒有一個「我」字，卻寫盡放下功名後的自在。\n白話：春天睡得香甜，不知不覺天就亮了，到處都聽得見鳥啼聲。想起昨夜隱約有風雨聲，不知道打落了多少花朵。\n\n【背後的小故事】\n孟浩然四十歲前隱居鹿門山，日子過得自在。四十歲那年進京應試落第，又因一句「不才明主棄」惹惱玄宗，被下令「放歸襄陽」，仕途就此斷絕。這首詩寫在他徹底死心、回到鹿門山之後的一個早晨。他睡到日上三竿才醒，不用趕早朝、不用赴考，只是聽著窗外鳥啼，想起昨夜隱約的風雨，隨口問一句花掉了多少——他不再起身去看。這是一個徹底放下的人才寫得出的詩，看似寫景，其實是一個中年人終於甘心的早晨。",
