    "poem_notes": "【字詞與白話】\n 長干：金陵城外秦淮河畔的里巷，商人聚居之地。妾：古代女子自稱。暫借問：暫且冒昧地問一聲。\n 白話：請問您家住在哪裡呢，我住在橫塘。把船停下冒昧問一聲，說不定我們還是同鄉。\n \n 【背後的小故事】\n 崔顥年輕時素有有文無行之名，好賭嗜酒又輕於擇偶，寫的詩也多是豔情風格，長干行便是代表作。他想像金陵秦淮河畔一名商人婦，聽見鄰船口音相近，忍不住停船搭話，問對方是否同鄉。這一聲大膽搭訕背後，其實是異鄉人渴望確認自己不孤單的心思。這首詩讓崔顥坐實了浪蕩才子的名聲，卻沒人料到十幾年後，他會寫出讓李白擱筆的黃鶴樓，人生從此轉了一個大彎。",
