    "poem_notes": "【字詞與白話】\n欲窮：想要看盡。更上一層樓：再登高一層。王之渙一生僅存六首詩，這首與〈涼州詞〉並列千古絕唱。\n白話：夕陽正沿著山巒緩緩落下，黃河一路奔流入海。想要看盡千里之外的風光，就要再登上更高的一層樓。\n\n【背後的小故事】\n王之渙年輕時當小官，因遭同僚誣告，一氣之下辭官，這一閒就是十五年。晚年他重新出仕，只當了個小小縣尉，這首詩大概就寫在他剛重新出發的階段。他登上黃河邊的鸛雀樓，看夕陽西沉、黃河東流，忽然明白：要看得更遠，就得爬得更高。於是他再上一層樓。「欲窮千里目」這句話，只有還想看更多的人才寫得出來——那年他已經歷過十五年賦閒，卻仍選擇繼續往上爬。",
