    "poem_notes": "【字詞與白話】\n 綠螘：即「綠蟻」，指新釀米酒表面浮起的淡綠色泡沫，古人以此代稱新酒。「能飲一杯無」以尋常口語作結，親切自然。\n 白話：新釀的米酒表面浮著一層淡綠色的酒渣，配上一個剛糊好的紅泥小火爐。傍晚時分，天色像是要下雪了，能不能來喝上一杯呢？\n \n 【背後的小故事】\n 白居易被貶江州司馬期間，結識了一位不慕名利、隱居山中的朋友劉十九。這天傍晚，他剛敲開自家新釀米酒的封泥，望著漸暗的天色與逐漸堆積的雲層，猜想今冬第一場雪即將降臨，便隨手寫下這張像便條一樣的邀約，請小僕送去給劉十九。同一時期，他也寫過〈琵琶行〉、〈長恨歌〉這樣情感深沉、篇幅浩大的長詩，但這個冬夜，他只是想找個朋友喝杯酒、聊聊天。這首只有二十個字的小詩，沒有華麗辭藻，卻成了千年來每個冬夜想找人小酌時，心裡最先浮現的那句話。",
