    "poem_notes": "【字詞與白話】\n 豔質：美麗的容顏，這裡指所思念的女子。寒衾：冰冷的被褥。獨眠人：獨自一人睡覺的人。\n 白話：她那美麗的容顏，如今沒有辦法再見到；冰冷的被褥，也沒有人可以親近取暖。這一年最長的冬至夜，要怎麼熬得過去呢——想必此刻，我們兩人都是各自一個人躺著，誰也陪不了誰。\n \n 【背後的小故事】\n 白居易少年時在符離與鄰家女孩湘靈青梅竹馬，情投意合，可是母親嫌棄湘靈家世普通，說什麼都不答應這門親事。白居易拖到將近三十歲仍不死心，還特意選擇離符離不遠的地方任職、應試，可是終究拗不過母命，沒能娶到湘靈，自己也不敢公然忤逆。這首詩寫在一年裡黑夜最長的冬至夜，他一個人在外地，想著湘靈大概也在遠方同樣孤枕難眠。後來他依母命娶了楊氏，可是湘靈這個名字，他直到四十多歲還在詩裡偷偷提起，始終沒有真正放下。",
