    "poem_notes": "【字詞與白話】\n 小艇：小船。不解：不懂得。浮萍一道開：浮萍被船划開，留下一條明顯的水痕。\n 白話：小孩子划著一艘小船，偷偷摘了白蓮往回划。他不懂得掩藏行蹤，水面上的浮萍被划開一道痕跡，一路洩了底。\n \n 【背後的小故事】\n 白居易晚年退居洛陽履道里，院中鑿池種蓮。他一生見識過官場最深的算計，早年直言被貶江州，後又夾在牛李黨爭之間自請外放，膝下一雙兒女又早早夭折，只能過繼侄子為嗣。那個下午，他看見鄰家孩子偷偷划船摘蓮，划過的浮萍卻留下一條藏不住的水痕。見慣了城府深沉的人心，這個笨拙到連秘密都藏不住的孩子，反而讓他覺得說不出的輕鬆與療癒。",
