    "poem_notes": "【字詞與白話】\n 蓑笠翁：披著蓑衣、戴著斗笠的老翁，指柳宗元自己。這首詩寫於他被貶永州期間，「獨釣」象徵他在困境中仍未放棄的姿態。\n 白話：千山之中飛鳥的蹤跡都已絕滅，萬千小路上也不見人的足跡。只有一艘孤舟上，一位披蓑戴笠的老翁，獨自在寒冷的江雪中垂釣。\n \n 【背後的小故事】\n 柳宗元因參與政治改革失敗，被貶到偏遠的永州，母親在赴任途中病逝，他自己也大病一場，牙齒掉落、頭髮早白。好友劉禹錫被貶到數百里外的朗州，兩人靠書信互相打氣。這首詩寫於他在瀟水江邊獨坐垂釣的一個雪天——四周鳥獸絕跡、人蹤全無，天地間彷彿只剩他一人，但他覺得這樣也好：只要他還在做事、還沒放下釣竿，即使世界把他遺忘，他也還在這裡。十年後他客死柳州，沒能等到平反，但這幅孤獨垂釣的畫面，成了千古以來「身處困境仍不放棄」的象徵。",
    "zhuyin": "簑(ㄙㄨㄛ)(suō)發音同\"縮\"，用草或棕櫚葉做成的雨衣。同「蓑」。",
