    "poem_notes": "【字詞與白話】\n 丘壑：山丘溝壑，泛指山中景致。武陵人：陶淵明《桃花源記》裡誤入桃花源、離開後卻再也找不到回路的漁夫。\n 白話：這次歸隱山林，不論深淺都要去，山裡的丘壑美景一定要看個夠。千萬別學那武陵漁夫，只是把桃花源當作一次短暫的遊覽。\n \n 【背後的小故事】\n 裴迪與王維、崔九（崔興宗）同屬輞川別業的小圈子，常一起遊山飲酒。這回崔九說要正式歸隱，裴迪送到山口，想起那個誤入桃花源、看一眼美景就急著回頭報信、最終再也找不到路的武陵漁夫，鄭重叮囑崔九別學他半途而廢。這句提醒不只說給崔九聽，也是裴迪對自己往後歲月的期許。",
