    "title": "送靈澈",
    "poem_notes": "【字詞與白話】\n 蒼蒼：形容竹林寺周圍樹木蒼翠茂密。杳杳：形容鐘聲悠遠。荷笠：背著斗笠。\n 白話：蒼翠的竹林寺，傍晚傳來悠遠的鐘聲。他背著斗笠，披著夕陽的餘暉，獨自一人往青山深處走去，漸行漸遠。\n \n 【背後的小故事】\n 劉長卿性格剛直敢言，一生兩度被誣下獄、兩度遭貶，史稱剛而犯上。他與僧人靈澈交好，常一同論詩品茶。那天送靈澈返回潤州附近的竹林寺，傍晚鐘聲響起，靈澈背著斗笠獨自往青山走去，一句交代都不必留。長卿自己這輩子去留都身不由己，看著朋友的背影被青山漸漸吞沒，心裡說不出是羨慕還是感慨——那是別人求不到的自由，此刻卻乾脆得像轉身一樣簡單。",
