    "poem_notes": "【字詞與白話】\n 泠泠：形容琴聲清越。七絃：古琴有七根絃，代指古琴。松風寒：琴曲名，也指松風聲與琴聲相和，帶著清冷之意。\n 白話：清越的琴聲在七絃上流轉，靜靜聽著彷彿松風吹來的寒意。這首古老的曲調雖然我自己很喜愛，如今的人卻大多不彈了。\n \n 【背後的小故事】\n 劉長卿自號五言長城，性格耿直不肯迎合，一生兩度入獄兩度遭貶，始終沒有改變過。那個夜晚他獨自在家彈奏一首早已過時的古調，窗外松風與琴聲相和，清冷乾淨。滿長安的人都在聽新鮮的胡樂琵琶，沒人耐煩坐下來聽古琴。他彈到一半忽然明白，這首沒人愛聽的老調子，跟他這個不肯變通的性子，其實是同一件事，只是換了個樣子出現。就算無人欣賞，他還是要彈給自己聽。",
