    "poem_notes": "【字詞與白話】\n 上人：對僧人的尊稱。孤雲將野鶴：孤雲伴著野鶴，比喻自在無拘的隱士生活。沃洲山：浙江新昌名山，東晉高僧支遁曾隱居於此。\n 白話：孤雲伴著野鶴，怎麼會願意住在人間呢。千萬別去買沃洲山那塊地隱居，那裡早就是世人都知道的地方了。\n \n 【背後的小故事】\n 劉長卿的方外之交上人打算歸隱沃洲山，那裡因東晉高僧支遁隱居養鶴而聞名千古。長卿卻覺得，正因為太有名，沃洲山早已成了世人心中的隱士朝聖地，人來人往，哪還算真正的清淨。他半開玩笑地化用支遁愛鶴的典故，勸朋友像孤雲野鶴一樣自在飄蕩，別去一個連地址都人盡皆知的名山湊熱鬧。這首小詩後來常被引用，提醒那些想附庸風雅裝隱士的人：真正的歸隱，是連地方都沒人知道。",
