    "title": "秋夜寄邱員外",
    "poem_notes": "【字詞與白話】\n 屬：正當、正值。幽人：隱居的人，這裡指邱員外。\n 白話：正當這樣一個秋夜想念著你，我一個人在院子裡散步，隨口吟誦幾句應景的詩，天氣涼得剛好。空寂的山裡，大概正有松果一顆顆落地；我猜此刻隱居的你，也還沒有睡著。\n \n 【背後的小故事】\n 韋應物年輕時仗著唐玄宗的寵信橫行鄉里，安史之亂後失去靠山，才發憤讀書從政，晚年喪妻，性情變得清冷淡泊。他的朋友邱丹本來也做官，做到員外郎，後來看透仕途，辭官到臨平山當起了道士。這首詩寫韋應物在秋夜院子裡散步想起遠方的朋友，猜想此刻邱丹在空山裡大概也還醒著，聽著松子落地的聲音。兩人相隔幾百里，沒有見面，卻靠著同一時刻的失眠彼此惦記——這種心照不宣的牽掛，是韋應物晚年詩裡最常出現的溫度。",
