    "title": "聽箏",
    "poem_notes": "【字詞與白話】\n 金粟柱：箏上用來繫弦、調音的短柱，因外形像金粟（粟粒狀的裝飾）而得名，這裡代指箏本身做工精美。周郎：三國時期精通音律的周瑜，樂師彈錯一個音他抬頭就知道，後人用「周郎顧」形容懂音律、值得討好的聽眾。\n 白話：金粟柱上鳴響著箏聲，一雙素手在玉飾的箏台前撥弄。她想讓那個懂音律的人抬頭看她一眼，於是一次又一次故意撥錯了絃。\n \n 【背後的小故事】\n 相傳這是李端在駙馬郭曖宴席上的即席之作。歌女鏡兒彈箏時屢屢彈錯，其實是故意為之，只為引詩人李端多看她一眼。郭曖看穿了鏡兒的心思，當場命李端賦詩解謎，李端一語道破欲得周郎顧、時時誤拂絃，滿座大笑，郭曖索性把鏡兒許給了他。一首解謎詩，順手促成了一段良緣。",
