    "poem_notes": "【字詞與白話】\n 三日入廚下：唐代習俗，新婦於婚後第三天需親自下廚做菜給公婆嘗，稱三朝入廚。未諳姑食性：還不熟悉婆婆的口味喜好。\n 白話：成親第三天，她走進廚房，洗淨了手，開始煮羹湯。還不知道婆婆的口味喜好，先叫小姑來嘗一嘗味道。\n \n 【背後的小故事】\n 王建出身寒微，早年輾轉依附幕府謀生，深知初到一個陌生環境，摸清楚上頭脾氣有多重要。他把這份體會，寫進一個新媳婦的廚房裡：不敢直接問婆婆的口味，先請最了解婆婆的小姑試味探路。短短二十字沒有一句寫害怕，那份小心翼翼全藏在動作裡，道出每個初來乍到之人共同的心情。",
