    "title": "玉臺體",
    "poem_notes": "【字詞與白話】\n 蟢子：一種被視為吉兆的小蜘蛛，蟢諧音喜。鉛華：搽臉的脂粉。藁砧：古代隱語，借砧板配鈇（斧頭）、鈇諧音夫，代指丈夫。\n 白話：昨夜睡覺時，裙帶無故自己鬆開了；今天早上，又看見一隻蟢子飛過。臉上的脂粉不能就這樣放棄不用啊——會不會，是我那出遠門的丈夫，就要回來了呢。\n \n 【背後的小故事】\n 權德輿官至宰相，年輕時卻特別擅長寫這種模仿南朝玉臺新詠筆法的閨怨小詩。這首詩寫一個丈夫長年在外的婦人，抓住民間流傳的兩個吉兆——裙帶自鬆、蟢子入室——都說是親人將歸的預兆，一天之內接連碰上，讓她把原本懶得再用的脂粉重新拿出來仔細補妝。詩裡沒有交代丈夫最後回沒回來，權德輿要寫的正是這個懸而未決的瞬間：一整天的心思，全繫在兩個小小的迷信徵兆上，那份執拗又細小的盼望，比直說想念更打動人。",
    "zhuyin": "蟢子(ㄒㄧˇ ㄗ˙)(xǐ zǐ)發音同\"洗?\"，蠨蛸的別名。動物名。蛛形綱蠨蛸科蠨蛸屬。體細長，暗褐色，螯肢甚長。常棲於水邊草際樹間，或在室內牆壁間，結網成車輪狀。舊時常以為是喜慶的徵兆，故也稱為「蟢子」。\n 藁砧(ㄍㄠˇ ㄓㄣ)(gǎo zhēn)發音同\"搞真\"，古代處死刑，罪人席藁伏於砧上，用鈇斬之。鈇、“夫”諧音，後因以“藁砧”為婦女稱丈夫的隱語。",
