    "title": "行宮",
    "poem_notes": "【字詞與白話】\n 行宮：皇帝出巡時沿途暫住的別院，非正式皇宮。寂寞紅：花照常開，卻無人賞，紅得無人問。閒坐說玄宗：老宮女閒坐聊起當年玄宗在世時的種種舊事。\n 白話：一座荒涼冷落的舊時行宮，宮裡的花開得寂寞又鮮紅，沒人欣賞。幾個白髮蒼蒼的老宮女還留在這裡，閒坐著談論當年玄宗在世的舊事。\n \n 【背後的小故事】\n 元稹奉命出使途經一座早已荒廢的行宮，撞見幾個白髮宮女閒坐聊天。她們天寶年間就被選入宮，青春耗在深宮裡，如今朝代已換了幾輪，卻仍留守原地養老。她們聊的還是玄宗當年的排場，語氣輕鬆得像講家常，沒有一句控訴。元稹的好友白居易同期也寫過類似處境的上陽白髮人，兩人都在意這些被盛世遺忘的女子。二十字寫盡繁華落盡後最先被忘記的人。",
    "zhuyin": "寥(ㄌㄧㄠˊ)(liáo)發音同\"聊\"，冷清、寂靜。",
