    "title": "春閨思",
    "poem_notes": "【字詞與白話】\n 裊裊：柳條輕柔擺動的樣子。陌上桑：田間小路旁的桑樹。漁陽：北方邊塞地名，這裡代指丈夫戍守的遠方。\n 白話：城牆邊的柳條隨風輕輕擺動，田埂小路旁的桑葉綠得正好。她提著籠子去採桑葉，卻採到一半忘了動作，因為昨天夜裡，她夢見自己到了漁陽。\n \n 【背後的小故事】\n 張仲素擅長寫這種代言體的閨怨詩，想像一個丈夫遠戍邊關的婦人的日常。詩裡的她本是尋常出門採桑養蠶的婦人，卻在桑樹下忽然停住手，因為昨夜一個關於漁陽的夢還縈繞在心頭。漁陽是遙遠的邊塞地名，離她的生活有幾千里之遠，卻是她丈夫所在的地方。張仲素沒有寫夢裡發生了什麼，也沒有寫丈夫是否平安，他寫的只是忘采葉這個瞬間——被思念打斷的日常動作，比任何直白的想念都更真實。",
    "zhuyin": "裊(ㄋㄧㄠˇ)(niǎo)發音同\"鳥\"，形容搖曳不定。\n 陌(ㄇㄛˋ)(mò)發音同\"末\"， 田間東西向的小路。司馬貞索隱引《風俗通》：「南北曰阡，東西曰陌。",
