    "poem_notes": "【字詞與白話】\n「推敲」的典故就出自賈島本人。這首詩寫的隱者，其實是他年少為僧時「本來可以成為的自己」。\n白話：在松樹下向一位童子打聽，他說師父採藥去了。只知道就在這座山裡，山上雲霧太深，不知道確切在哪裡。\n\n【背後的小故事】\n賈島年輕時當過和尚，後來還俗應考科舉，卻考了一輩子沒中。這首詩寫他上山尋訪一位隱士：松下的童子告訴他，師父採藥去了，就在這座山中，只是雲霧太深不知去處。賈島沒有繼續追問，站了一會兒就轉身下山。他其實在尋找的，是他自己「本來可以成為的那個人」——那個依然活在山林裡的自己，如今被雲霧擋住，看不見了。",
