    "title": "塞下曲四首之三",
    "poem_notes": "【字詞與白話】\n 單于：匈奴首領的稱號，此處泛指敵方首領。輕騎：輕裝快速的騎兵部隊。\n 白話：沒有月光的夜裡，雁群被驚得高高飛起，敵方首領趁著黑夜偷偷逃走了。將領正要率領輕騎兵去追擊，大雪已經落滿了他們的弓和刀。\n \n 【背後的小故事】\n 盧綸科舉路上屢遭戰亂波折，後經宰相元載推薦入仕，又曾在河中節度使渾瑊幕府任判官，隨軍駐紮邊塞，親歷軍旅生活。相傳這首詩寫的正是一個雪夜急襲的場景：斥候來報敵軍夜遁，主帥立即點兵追擊，將士頂著愈積愈厚的大雪策馬衝入黑暗。盧綸沒有寫一個苦字，那份艱難全藏在大雪滿弓刀五個字裡。",
