    "title": "江南曲",
    "poem_notes": "【字詞與白話】\n 瞿塘賈：在瞿塘峽（長江三峽之一，水勢險急）做生意的商人。潮有信：潮水漲退有固定時間，從不失約，信是守信用的意思。弄潮兒：在江邊觀潮、弄潮為生或為戲的人。\n 白話：我嫁的是在瞿塘峽做生意的商人，他卻天天都誤了跟我約定的歸期。早知道潮水這麼守信用，倒不如嫁給那些天天跟潮水打交道的弄潮兒。\n \n 【背後的小故事】\n 李益走南闖北，在瞿塘峽邊聽到一個商婦的怨言。她的丈夫做生意常年在外，說好的歸期一次次落空，她漸漸看透，商人心裡貨物和利益永遠排在她前面。她苦笑著望向江面，潮水漲退幾點不差，連漁民都能靠它排班，早知如此，還不如嫁給天天跟潮水打交道的人，至少潮水從不騙人。李益把這句怨言原封不動寫成詩，沒有一字寫委屈，卻寫盡了等待落空的失望。",
    "zhuyin": "瞿塘(ㄑㄩ ㄊㄤˊ)(qú táng)發音同\"區唐\"，地名。位於四川省奉節縣東的白帝城，至巫山縣的黛溪鎮，長約八公里，為長江三峽之一。\n 賈(ㄍㄨˇ)(jiǎ)發音同\"股\"，做生意的人、商人。",
