    "title": "憫農詩-其二",
    "poem_notes": "【字詞與白話】\n飧：熟食、飯食。這首詩是李紳二十七歲時所寫，出自他真心的憐憫。\n白話：農夫在正午烈日下彎腰鋤禾，汗水一滴滴落進禾苗下的泥土。有誰知道，我們碗裡的每一口飯，都是這樣粒粒辛苦換來的。\n\n【背後的小故事】\n李紳寫這首詩時只有二十七歲，還沒中進士，他親眼見到農夫頂著烈日鋤禾，汗滴入土，才寫下這二十個字。可是後來他官至宰相，晚年生活奢靡，一頓飯殺三百隻雞只取雞舌，還牽涉冤案迫害下屬。寫「粒粒皆辛苦」的李紳，跟晚年殺雞取舌的李紳，是同一個人。這首詩比寫詩的人活得更久、更真——它記得他最好的一刻，也讓後人看見他如何背叛了自己曾經相信的東西。",
