    "poem_notes": "【字詞與白話】\n 何滿子：相傳是唐代一位歌人臨刑前所唱的曲調，聲音悲切，後成為教坊常用的曲調名。故國三千里：離故鄉遙遠三千里。\n 白話：離開故鄉已經三千里遠，在深宮裡困了整整二十年。一聽到何滿子這支悲涼的曲調，忍不住在皇帝面前落下兩行淚。\n \n 【背後的小故事】\n 張祜寫的是一個被困深宮二十年、遠離故鄉的宮女，一聽到何滿子悲切的曲調就落淚的畫面。沒想到多年後，據記載，唐武宗寵妃孟才人病重時親自唱了一曲何滿子，武宗問她自己死後怎麼辦，她答不出話，又唱了一遍就氣絕當場，死在武宗面前。雙淚落君前竟像是提前替她寫好的結局，成為詩史上最巧合的一場預言。",
