    "poem_notes": "【字詞與白話】\n 向晚：傍晚時分。意不適：心情不好。樂遊原是長安東南的高地，是當時人登高眺望的去處。\n 白話：傍晚時心情不太好，就駕車登上古原散心。夕陽的景色美得無限好，只可惜已經接近黃昏了。\n \n 【背後的小故事】\n 李商隱一生夾在牛黨、李黨兩派政治鬥爭之間，兩邊都不完全信任他，才華洋溢卻始終升不上去，四十六歲就過世了。這首詩大概寫在他晚年某個心情低落的傍晚，登上樂遊原看長安夕陽——滿城被染成金色，美得讓人屏息，他卻清楚知道，再過一會兒這片金色就會全部消失，就像他自己，才華已經燒到頂點，時間卻不多了。夕陽無限好，只是近黃昏——這既是寫景，也是寫他自己。",
