    "poem_notes": "【字詞與白話】\n 嶺外：五嶺以南，指嶺南一帶，唐代人視為極遠的貶謫、羈旅之地。音書絕：家書、音訊全部斷絕。近鄉情更怯：越靠近家鄉，心裡反而越是害怕。\n 白話：我在嶺南與家鄉音信斷絕，一個冬天過去又是一個立春。如今越靠近家鄉，心裡反而越膽怯，遇到從家鄉方向來的人，都不敢開口問一句家裡的近況。\n \n 【背後的小故事】\n 這首詩寫一個離家多年、音訊全斷的旅人渡過漢水回鄉前的心情。照理說快到家了該高興，他卻在渡口遲遲不肯上船問路，因為只要還沒問，就還能抱著一絲希望，一旦開口，好消息壞消息都要當場揭曉。這首詩的作者史料上另有一說認為是宋之問，流放嶺南後秘密逃歸途中所寫，學界至今仍有爭論。但無論作者是誰，那份越靠近答案反而越想拖延的心情，是所有離家太久的人都懂的。",
