    "title": "哥舒歌",
    "poem_notes": "【字詞與白話】\n 北斗七星：天上的星宿，這裡渲染夜色與威嚴的氣氛。窺牧馬：偷偷窺伺、意圖侵擾邊境放牧的牲畜。臨洮：唐代西北邊境的軍事要地，在今甘肅一帶。\n 白話：北斗七星高懸夜空，哥舒翰夜裡總是佩刀不離身。到現在，敵人也只敢遠遠窺探邊境的牧馬，不敢越過臨洮半步。\n \n 【背後的小故事】\n 這首歌謠讚頌的是河西節度使哥舒翰。他率軍攻下吐蕃盤據的天險石堡城後，威震隴右，邊境百姓與駐軍傳唱這首歌，說吐蕃人從此再不敢輕易越境侵擾。可是後來安史之亂爆發，哥舒翰早已中風癱瘓多年，朝廷卻把他從病榻上硬拉出來鎮守潼關；他本想堅守，卻被宰相楊國忠一再逼迫出戰，結果在靈寶大敗，被部下綁縛投降，最終在洛陽被叛軍殺害。這首歌永遠停在他最威風的那個夜晚，唱的人未必知道，那個讓敵人不敢過臨洮的猛將，後來輸掉的，是一場自己人逼他打的仗。",
