    "title": "梅花",
    "poem_notes": "【字詞與白話】\n 凌寒：冒著嚴寒。遙知：從遠處就能知道，不用靠近看。暗香：不張揚、若有似無的香氣，與濃烈張揚的花香相對。\n 白話：牆角有幾枝梅花，冒著嚴寒獨自開放。遠遠看去還以為是殘雪未化，走近才知道不是雪，因為有一陣淡淡的香氣飄了過來。\n \n 【背後的小故事】\n 相傳這首詩寫在王安石晚年罷相、退居江寧鍾山之後。他主持的熙寧變法推行到後來，連舊日同僚都反目，連弟弟都站到對立面，他兩度罷相，徹底離開權力中心。沒了官位、沒了聲量，他只是照常在牆角種花。沒人來看的梅花照樣開了，暗香照樣飄得很遠。這首詩的反轉在於，它看似寫梅，其實是他寫給自己的心境，開得好不好，從來不需要靠別人鼓掌來證明。",
