    "poem_notes": "【字詞與白話】\n 振林樾：歌聲響亮，震動了整片樹林（樾指成排的樹）。意欲：心裡忽然想要。\n 白話：牧童騎在黃牛背上，歌聲響亮得震動了整片樹林。忽然他心裡想抓一隻正在鳴叫的蟬，立刻閉上嘴巴，一動不動地站住了。\n \n 【背後的小故事】\n 袁枚辭官後在南京隨園隱居四十多年，晚年最愛在鄉間閒走，觀察日常小景。這天他遇見一個牧童騎牛放聲高歌，歌聲震得整片樹林都在晃，忽然歌聲說停就停，牧童整個人僵住盯著樹上一隻蟬，連呼吸都放輕了——前一秒的張揚和後一秒的凝止，中間沒有任何過渡。袁枚沒加一句道理，只把這個瞬間原封不動寫下來，這正是他一輩子追求的，眼見心動即成詩。",
