    "poem_notes": "【字詞與白話】\n 「苔花如米小，也學牡丹開」是全詩最動人的一句，把卑微渺小的苔花與富貴嬌豔的牡丹相提並論，讚頌平凡生命同樣認真綻放的尊嚴。\n 白話：陽光照不到的角落，春天依然會如期到來。青苔開出的花朵雖然只有米粒般大小，卻也像牡丹一樣認真地綻放。\n \n 【背後的小故事】\n 袁枚二十四歲中進士，三十三歲便辭官隱居南京隨園，此後專心寫詩、著書、廣收門生。這首詩寫於他晚年某個春日，園中牡丹開得正盛，賓客紛紛前來觀賞，他卻獨自繞到終年照不到陽光的後院牆角，蹲下身仔細端詳那一叢青苔，意外發現苔蘚上竟也開著米粒般大小的花朵——雖然無人注意，卻同樣認真地綻放著。這首詩生前並不出名，沉寂了近兩百年，直到後來被貴州山區的一群孩子唱成歌，才被全國聽見——那些在偏遠山區、如同「白日不到處」成長的孩子，正是袁枚當年蹲下身看見的那朵苔花，微小卻依然努力地綻放。",
