    "poem_notes": "【字詞與白話】\n 群玉山、瑤臺：都是傳說中西王母等神仙居住的仙山仙境，詩人用來比擬貴妃美得不似人間。露華濃：牡丹花瓣上凝著濃重的露水，也暗指貴妃受寵正盛，恩澤正濃。\n 白話：貴妃的衣裳如雲霞般絢麗，容貌似牡丹般嬌豔；春風吹拂欄杆，花上的露水濃得晶瑩。這樣的美貌，若不是在群玉山頭見過的仙子，就該是瑤臺月下才能遇見的仙女。\n \n 【背後的小故事】\n 天寶二年，玄宗與貴妃在沉香亭賞牡丹，嫌舊曲配不上眼前盛景，急召翰林學士李白現寫新詞。李龜年奉旨去找人，發現李白正醉倒在長安酒肆，只好連人帶醉架進宮，潑水才半醒。李白提筆一連寫下三首，把貴妃比作天上仙子，滿殿讚嘆。可這風光沒能持續多久——高力士因替他脫靴記恨，事後向貴妃進讒，說詩裡有一句把她比作下場淒涼的趙飛燕，兩年後李白就被禮貌地攆出長安。那天架他進宮的李龜年，後來也流落江南，四十年後在一個落花時節，巧遇另一位從長安走出來的老朋友。",
