    "poem_notes": "【字詞與白話】\n 雲雨巫山：楚王與巫山神女夢中相會的典故，這裡指傳說中的美事。可憐飛燕倚新妝：可憐，這裡是可愛、值得憐愛之意，非悲憐；飛燕指漢朝美女趙飛燕。\n 白話：牡丹紅豔得像凝著露水的清香，美得讓人想起巫山神女的舊夢，那都白白讓人斷腸。試問漢宮裡誰能與眼前的美人相比？大概只有趙飛燕穿著新妝，才勉強比得上。\n \n 【背後的小故事】\n 天寶年間，玄宗與楊貴妃在沉香亭賞牡丹，急召翰林李白現場賦詩。李白酒未醒，一氣寫下清平調三首，這一首把貴妃的美比作趙飛燕穿新妝。滿座聽了都覺得是絕美讚辭，但高力士心裡卻轉了別的念頭——趙飛燕史書上名聲不乾淨，拿她比貴妃暗藏挑撥空間。高力士後來添油加醋說給貴妃聽，種下貴妃對李白心存芥蒂的種子，也成了李白後來被排擠出長安的原因之一。",
