    "poem_notes": "【字詞與白話】\n 名花傾國：名花指沉香亭的牡丹，傾國指足以傾動一國的美人，即楊貴妃。解釋春風無限恨：解釋，消解、化開；意指這一刻的美好把積存已久的種種怨恨都化開了。\n 白話：名花與絕色美人此刻兩相歡聚，常常博得君王含笑相看。這一刻彷彿把春風裡積存已久的無限怨恨都化開了，兩人並肩倚靠在沉香亭北的闌干邊。\n \n 【背後的小故事】\n 這是李白清平調三首的最後一首，寫沉香亭賞花當日玄宗與貴妃相看甚歡的場面，由樂師李龜年當場配曲演唱，是開元天寶最風光的一刻。可惜好景不長，十幾年後安史之亂爆發，長安淪陷，貴妃身死，李龜年也流落江南，靠賣藝維生。據記載，一次江南宴席上有人請李龜年再唱這首曲子，滿座賓客聽著熟悉的詞句，想起再也回不去的盛世，一個個掩面哭泣，連李龜年自己也唱到哽咽唱不下去。",
