    "poem_notes": "【字詞與白話】\n 鬱金香：此處指一種香草，浸泡入酒可增添香氣、染出琥珀般的色澤，不是現代花卉鬱金香。他鄉：異地、離家鄉很遠的地方。\n 白話：蘭陵出產的美酒帶著鬱金草的香氣，用玉碗盛裝，呈現琥珀般的光澤。只要主人能讓客人盡興一醉，又何必計較這裡是不是他鄉呢。\n \n 【背後的小故事】\n 開元晚期，李白把家安在山東任城，自己卻大半時間在外奔波求仕，四處碰壁。這晚他獨自在蘭陵的小酒肆裡喝悶酒，店主倒出一碗用鬱金草浸過的美酒，色澤透亮如琥珀，他一喝就愣住了。老闆說自己當年也是外地遷來，如今早不覺得蘭陵是異鄉。李白心裡清楚自己不一樣——他是一年換一個地方，連任城的家也難得回去幾次。可這碗酒是真的好，好到那一刻他選擇騙過自己：管他鄉不鄉的，今晚喝痛快，這裡就是他的地方。",
