    "poem_notes": "【字詞與白話】\n 天門：長江邊上東梁山、西梁山隔江相對如門，故稱天門山。楚江：長江流經古楚地的一段，這裡泛指長江。日邊來：船從太陽升起的方向遠遠駛來，形容江面開闊、遠景壯麗。\n 白話：天門山像被長江從中間硬生生劈斷，楚江之水從缺口奔流而出。碧綠的江水向東流去，到這裡打了個回旋。兩岸的青山彷彿迎面一座座立起，一片孤帆遠遠地從太陽升起的方向駛來。\n \n 【背後的小故事】\n 李白二十五歲那年第一次離開四川，順著長江東下，經過天門山時寫下這首詩。他從小看慣了蜀地把人四面圍住的高山，眼前這座被江水硬生生劈開的天門山，讓他第一次真正感受到世界比自己以為的大得多。二十八個字裡全是興奮和被打開的痛快，沒有一句提到害怕或不捨。他當時並不知道，這一走就是一輩子，再沒能回頭看一眼峨眉的月，但那個下午，他只顧著站在船頭迎向敞開的天地。",
