    "poem_notes": "【字詞與白話】\n 九天：指天的最高處。「飛流直下三千尺，疑是銀河落九天」誇張了實際瀑布落差的數倍，卻是李白放大版世界觀的真實寫照。\n 白話：陽光照在香爐峰上，升起一片紫色雲煙，遠遠望見瀑布像一條白練掛在山前的溪流上。水流飛速直落三千尺，讓人懷疑是銀河從九重天上落了下來。\n \n 【背後的小故事】\n 李白二十多歲遊歷廬山，站在山下仰望瀑布從山頂垂直沖下，落差之大讓他脫口而出「三千尺」——實際上廬山瀑布落差遠不及此，但李白不是在誇張，他是真的這樣感受到的。他看瀑布會聯想到銀河，就像他看月亮會舉杯相邀、看白髮會想到三千丈——他的世界永遠是放大版的。這正是李白最獨特的天才：不是文學技巧，而是一種觀看世界的方式，讓平凡的風景在他眼中都成了神蹟。",
