    "poem_notes": "【字詞與白話】\n 左遷：古人以右為尊、左為卑，左遷就是降職、被貶官的委婉說法。五溪、夜郎：五溪是湘西一帶少數民族聚居的偏遠山區；夜郎是漢代西南的古國舊地，詩中借指遙遠荒僻，並非龍標實際所在地。\n 白話：楊花落盡，子規鳥聲聲啼叫，聽說你被貶到龍標，要一路經過偏遠的五溪。我把這份擔憂的心思寄託給天上的明月，讓它隨風一直送到你所在的夜郎以西。\n \n 【背後的小故事】\n 天寶年間，王昌齡因平時行事不夠謹慎、遭人詬病，被貶到荒僻的龍標當縣尉，要翻山越嶺穿過五溪一帶。消息傳到江東，李白正在暮春時節聽見布穀鳥啼，手裡的酒杯停在半空。兩人同是七絕聖手，相傳曾在江南把酒言歡，惺惺相惜，可這一次，再深的情誼也換不來實際的幫助——龍標太遠，人到不了。李白抬頭看見月亮，忽然想到，人去不了的地方，月光去得了，便把這份放不下的牽掛，託付給同時照著兩人的那輪月亮。",
