    "poem_notes": "【字詞與白話】\n 踏歌：一種民間歌舞形式，眾人手拉手，邊唱邊用腳踏地打拍子，常用於送別或聚會場合。桃花潭：安徽涇縣一處水潭的地名，並非真的種滿桃花。\n 白話：李白乘船正要出發離開，忽然聽見岸上傳來踏歌的歌聲。桃花潭水縱然深達千尺，也比不上汪倫送我這份情誼深厚。\n \n 【背後的小故事】\n 相傳汪倫是涇縣本地一位沒有官職背景的豪士，仰慕李白已久，寫信謊稱當地有十里桃花、萬家酒店邀他來作客，李白興沖沖趕到才發現只是地名巧合和姓萬的酒店老闆——他不但沒生氣，反倒覺得這份樸拙的心意有意思，在汪倫家住了好幾天。臨別登舟，岸上忽然傳來整齊的踏歌聲，汪倫帶著鄉人追出來相送。李白望著腳下深不見底的潭水，覺得眼前這個素不相識的普通人給的這份情，比潭水還深，提筆寫下這四句話，讓送別有了另一種樣子。",
