    "poem_notes": "【字詞與白話】\n 岐王：唐玄宗之弟李範，府邸是開元年間文藝名流聚集的沙龍。崔九：即崔滌，深受玄宗寵信的殿中監，排行第九。\n 白話：當年在岐王府裡經常見到你演出，也曾在崔九堂前多次聽你唱曲。如今正是江南風光最好的時候，卻在這落花時節又與你重逢。\n \n 【背後的小故事】\n 李龜年是開元年間宮裡最紅的樂師，曾在沉香亭為玄宗、貴妃演唱過李白的清平調。杜甫年輕時托著長輩的關係，在岐王府、崔九堂前見過他演出，那是他一生見過最好的時代。安史之亂後，盛世崩塌，李龜年淪落江南賣唱維生，杜甫自己也一路輾轉漂泊，窮困潦倒。大曆五年春天，兩人在潭州街頭意外重逢，一個曾經的當紅樂師，一個曾經的旁聽少年，如今都成了被時代拋下的老人。這年冬天，杜甫病逝於湘江舟中，這場落花時節的重逢，成了他寫給那個盛世的最後回眸。",
