    "poem_notes": "【字詞與白話】\n 西嶺：成都西邊的岷山，終年積雪。千秋雪：形容積雪常年不化。東吳：長江下游江南一帶，此處泛指遠方的商船來源地。\n 白話：兩隻黃鸝在翠綠的柳枝間鳴叫，一行白鷺飛向青天。窗子彷彿把西邊岷山終年不化的積雪框進畫裡，門前停泊著從幾千里外東吳來的船。\n \n 【背後的小故事】\n 安史之亂後期，杜甫一路顛沛流離逃到成都，靠著好友嚴武照應才在草堂安頓下來。這首詩表面上只是寫景，其實藏著一個關鍵反轉，門前那幾艘東吳來的商船，代表長江航運重新暢通，天下終於要太平了。戰亂時商路斷絕、消息不通，杜甫看著萬里之外的船能停到自己門前，才真正確定苦日子熬過去了。整首詩沒有一個字提到戰爭，卻是他這些年最鬆一口氣的時刻。",
