    "title": "贈李白",
    "poem_notes": "【字詞與白話】\n 飄蓬：隨風飄轉的蓬草，比喻漂泊無定所的人。丹砂：道士煉丹用的原料，這裡指求仙煉丹之事。葛洪：東晉著名道士，傳說修仙有成，這裡用來對比李白煉丹未成。飛揚跋扈：狂放不羈、不受拘束的樣子。\n 白話：秋天到了，我們相看彼此，還都像斷根的蓬草一樣漂泊無依。煉丹修仙的事始終沒有成就，對得起葛洪那樣的前輩嗎？你整天痛飲高歌，把日子白白耗過去，這樣狂放不羈，到底是想證明給誰看？\n \n 【背後的小故事】\n 天寶三載前後，李白剛被玄宗禮貌地送出長安，心裡不痛快，四處雲遊求仙。杜甫那時還沒考中功名，兩人在齊魯一帶結識，一起去王屋山尋訪道士華蓋君，卻聽聞道士已死，白跑一趟。那段時間兩人天天喝酒論詩，子美看太白又佩服又心疼——名氣雖響，處境卻跟自己一樣飄零，煉丹沒成，倒把日子越過越狂放。這首詩是杜甫少見對李白直白的關切與追問，也是兩人交情最真實的證據。",
    "zhuyin": "跋扈(ㄅㄚˊ ㄏㄨˋ)(bá hù)發音同\"拔護\"，形容人態度傲慢無禮，舉動粗暴強橫。",
