    "poem_notes": "【字詞與白話】\n 花卿：成都府尹崔光遠部將花敬定，因平定叛亂有功但恃功驕縱。錦城：成都的別稱。此曲只應天上有：表面誇讚樂曲美妙得不似人間，實則暗指此曲規格逾越了臣子本分，只該屬於天子。\n 白話：成都城裡絲竹管弦之聲終日不絕，一半飄進江風，一半飄入雲端。這樣的曲子應該只有天上才有，人間能有幾回聽得到呢。\n \n 【背後的小故事】\n 上元二年，花敬定平定梓州叛亂立下大功，卻縱兵搜刮，家宴用的樂曲規格逾越臣子本分，僭用了只有天子才配用的排場。寓居成都草堂的杜甫受邀赴宴，聽著滿堂絲竹飄得滿城都是，心裡清楚這場面不對勁，卻不好當面得罪主人。酒過三巡，他提筆寫下這四句，字面上是把樂曲捧到天上去的極致讚美，滿座賓客都聽得心花怒放。只有懂他的人才聽得出，這五個字裡藏著一把鈍刀——不是誇好聽，是提醒這種規格的音樂本不該出現在人間，更不該出現在一個將軍家裡。",
