    "poem_notes": "【字詞與白話】\n 渭城：在長安西邊，今陝西咸陽附近。安西：唐代設於西域的安西都護府，在今新疆庫車一帶。陽關：古代通往西域的重要關隘，出陽關即進入異域，此去山長水遠。\n 白話：渭城清晨的雨，打濕了路上的塵土，客舍旁的柳樹被雨洗過，綠得格外清新。再勸你多喝一杯酒吧，出了陽關向西，就再也沒有熟識的老朋友了。\n \n 【背後的小故事】\n 王維的朋友元二奉命出使安西都護府，一路要穿過河西走廊，出陽關之後便是大片異域，少說要走上幾個月，前路吉凶難料。這位朋友的真實身份，後人已經很難考證清楚。送別那天清晨，渭城剛下過一場雨，客舍旁的柳色被雨水洗得發亮。兩人對坐飲酒，話越聊越少，王維把酒杯斟滿推過去，一句看似隨口的勸酒詞，其實壓進了說不出口的擔憂——這頓酒喝完，西出陽關，可能就再沒有能一起說家鄉話的人了。這句勸酒詞後來被譜成陽關三疊，傳唱千年。",
