    "poem_notes": "【字詞與白話】\n 桂魄：指月亮，古人以為月中有桂樹，故以桂魄代稱月。輕羅：輕薄的絲織衣裳。殷勤弄：反覆彈奏，不肯停手。\n 白話：秋夜月亮剛升起，露水微涼，她身上的輕羅衣裳已單薄得擋不住寒氣，卻遲遲沒去添衣。深夜裡她還在反覆彈奏銀箏，是因為心裡害怕，不敢回到那間空蕩蕩的房間。\n \n 【背後的小故事】\n 這是王維以女子口吻代寫的一首閨怨詩。相傳他年輕時常以琵琶技藝出入岐王、寧王等貴族府邸，見過不少深宮或府邸中的樂伎歌女。這首詩的反轉在於，她夜深不肯停手彈箏，表面看是捨不得曲子，其實是捨不得面對那份寂靜，只要箏聲還在，房間就還沒真的空下來，一停手，那份孤獨就要正面撞上來了。",
