    "poem_notes": "【字詞與白話】\n 茱萸：一種有香氣的植物，古人重陽節配戴以驅邪。「遙知兄弟登高處，遍插茱萸少一人」以想像對方的方式表達思念，是全詩最動人之處。\n 白話：獨自在異鄉作客，每逢佳節就格外思念家人。遠遠想到兄弟們今天登高的地方，插滿茱萸時，一定會發現少了我一個人。\n \n 【背後的小故事】\n 王維十五歲離家到長安遊學，這首詩寫於他十七歲那年的重陽節。看著長安街上一家家扶老攜幼登高遊玩，他格外感到孤單，卻沒有直接寫「我好想家」，而是轉念想像故鄉的兄弟們此刻正在登高插茱萸，會在某個瞬間發現少了他一人、為他嘆息。他把自己的孤獨，翻譯成兄弟們對他的惦念——這種迂迴的思念方式，成了千年來每個異鄉遊子在節日裡最熟悉的心情。",
