    "poem_notes": "【字詞與白話】\n 奉帚：拿著掃帚，指宮女清晨的日常灑掃工作。團扇：圓形的扇子，此處化用班婕妤團扇詩秋扇見捐的典故，比喻失寵。昭陽：昭陽殿，漢成帝時趙飛燕姊妹得寵所居之處。\n 白話：清晨掃地時金殿的門剛剛打開，她拿著團扇百無聊賴地徘徊。她的容顏竟比不上一隻寒鴉，因為那烏鴉剛從昭陽殿飛來，身上還沾著那邊的日光。\n \n 【背後的小故事】\n 這首詩借西漢班婕妤失寵退居長信宮的往事寫宮怨。班婕妤原本最受成帝寵愛，後來趙飛燕姊妹入宮專寵，她怕遭陷害，自請退居冷宮侍奉太后。王昌齡一生仕途也屢遭貶謫，從嶺南貶到更遠的龍標，被朝廷徹底冷落。這首詩的反轉在於最後兩句，連烏鴉都能沾到得寵宮殿的一點日光，而她這張臉，卻連烏鴉都不如，寫的是宮女，未必不是他自己的處境。",
