    "poem_notes": "【字詞與白話】\n 龍城飛將：一般認為指漢代威震匈奴的名將李廣，飛將軍是匈奴人給他的稱號；也有學者認為兼指奇襲龍城的名將衛青，說法不一。陰山：今內蒙古一帶山脈，古代中原防禦北方遊牧民族的天然屏障。\n 白話：明月依舊是秦時的明月，關隘依舊是漢時的關隘，萬里出征的將士至今未能歸來。倘若像李廣那樣的良將還在，絕不會讓胡人的騎兵越過陰山。\n \n 【背後的小故事】\n 王昌齡年輕時真的到過河西一帶邊塞，不是憑空想像。他在城頭見過真實的戍卒，聽他們講家鄉在哪、講已經多少年沒能回去，有人講著講著就沉默了，連自己都不確定這輩子回不回得去。他望著同一輪明月，想到秦朝的士兵抬頭看過它，漢朝的士兵也看過它，月亮和關隘從未換過，換的只是一批又一批望月想家、卻等不到歸期的人。他想起漢代威震匈奴的飛將軍李廣，感慨如果當世也有這樣的良將，何至於讓將士白白客死異鄉。這首詩後來被譽為唐人七絕的壓卷之作。",
