    "poem_notes": "【字詞與白話】\n 凝妝：細細地梳妝打扮。陌頭：路邊、街頭。悔教：後悔當初讓（丈夫）去做某件事，教是使、讓的意思。覓封侯：追求靠軍功封爵的功名。\n 白話：閨房裡的年輕妻子本來不知憂愁，春日裡精心打扮後登上翠樓賞景。忽然看見路邊楊柳又抽出新綠，才後悔當初讓丈夫去邊塞追求封侯的功名。\n \n 【背後的小故事】\n 王昌齡長年出入邊塞，深知從軍家庭背後的代價，寫下這位沒有留名的少婦。她丈夫從軍是為了封侯的體面，她當初甚至催他去，毫不覺得離別有多沉重。這天她照常梳妝登樓賞春，目光卻無意間落在路邊的楊柳上——那還是去年送別時的模樣。這一眼讓她忽然想起，丈夫走了這麼多年，功名連個影子都沒有，自己卻獨自熬過了這麼多個春天，才真正懂得當初鼓勵的代價。",
    "zhuyin": "陌(ㄇㄛˋ)(mò)發音同\"末\"， 田間東西向的小路。司馬貞索隱引《風俗通》：「南北曰阡，東西曰陌。",
