    "poem_notes": "【字詞與白話】\n 不護細行：意指行事不夠謹慎檢點，是當時有人用來攻擊王昌齡的說法，並非確有實據。冰心在玉壺：化用前人清如玉壺冰的說法，比喻心地清白純淨，不含一絲雜質。\n 白話：寒雨連夜灑落吳地江面，天亮送別友人時，楚山也顯得格外孤單。洛陽的親友若問起我的近況，就說我的心依然像玉壺裡的冰一樣清白。\n \n 【背後的小故事】\n 王昌齡這些年官場不太順，有人說他不護細行，這種查無實據卻又難以自證清白的閒話，一路跟著他從一個任所傳到另一個任所，甚至傳回了洛陽故舊耳中。他在江寧縣丞任上送別北上洛陽的朋友辛漸，深知辛漸到了洛陽，少不了要面對親友關切又帶著疑慮的探問。他沒有為自己辯解一句具體的事，只在臨別時託辛漸帶一句話回去：不管外頭怎麼傳，他這個人心裡乾淨。這場沒有一句喊冤的送別，後來成了他一生最出名、也最平靜的自白。",
