    "poem_notes": "【字詞與白話】\n 平陽歌舞新承寵：借漢武帝時平陽公主府中歌女衛子夫得寵的故事，暗指詩中新受寵愛的女子。露井桃：井邊種的桃樹。未央：漢代宮殿名，代指宮廷。\n 白話：昨夜宮中起風，吹開了井邊的桃花；未央宮前殿上空，月亮升得格外高。像平陽公主府裡的歌女那樣，有人剛剛得到新的寵愛；簾子外頭春寒未退，宮裡卻已經賜下一件錦袍給她保暖。\n \n 【背後的小故事】\n 王昌齡沒進過皇宮，這首詩借漢武帝與平陽公主家歌女衛子夫得寵的舊典故，寫的其實是眼前的宮廷：一夜之間有人被點名承寵，簾內簾外，冷暖立刻分成兩個世界。王昌齡自己一生詩名滿長安，官運卻始終不順，屢次被外放到偏遠之地。他太清楚，朝廷點名一個人，跟宮裡點名一個舞伎，說到底是同一種邏輯——不是你不夠好，只是那晚的風，有沒有恰好吹向你。",
