    "poem_notes": "【字詞與白話】\n 長雲：連綿的雲層。孤城：指戍守邊疆的孤立城池。金甲：鐵甲、鎧甲，此處代指戍邊將士。\n 白話：青海湖上空的層層烏雲遮暗了雪山，孤城遠遠望著玉門關。將士們在黃沙中身經百戰，鎧甲都被磨穿了，但不打敗樓蘭誓不返鄉。\n \n 【背後的小故事】\n 相傳王昌齡年輕時曾親自遊歷過西北邊塞，見識過戍邊將士的真實日子，不是詩裡常見的壯闊風光，而是實打實的缺水缺糧、年復一年打不完的仗。鎧甲被風沙磨得發亮發薄，是常年征戰留下的痕跡。這首詩的反轉在於，讀者以為重點是戰爭的艱苦，其實王昌齡想寫的是，再艱苦的黃沙也磨不穿將士心裡那句不肯退的誓言。",
