    "poem_notes": "【字詞與白話】\n 亂入：混雜、混入，指採蓮女划船鑽進荷葉深處，和荷葉混在一起。始覺：才察覺、才發現。\n 白話：荷葉和採蓮女的羅裙裁成同一種顏色，芙蓉花貼著她們的臉頰，兩邊都開著；她們混進池子深處，怎麼看都看不出人在哪裡，直到聽見歌聲，才知道原來一直有人在那裡。\n \n 【背後的小故事】\n 相傳王昌齡宦遊江南時，途經一片荷塘，一時竟找不到採蓮女的身影——荷葉與羅裙同色，人臉貼著芙蓉花瓣，活像長在花叢裡。他正疑心自己看錯，忽然聽見塘深處傳出歌聲，才知道人根本沒走，只是藏得太徹底。他後來常說，人可以把自己藏進風景裡，卻藏不住嗓子——這句話聽著像在講採蓮女，其實也像在講他自己那些年想遠離官場是非、卻怎麼也藏不住詩名的處境。",
