    "poem_notes": "【字詞與白話】\n 羌笛：古代羌族的一種樂器，常用於邊塞戍卒吹奏抒發思鄉之情。折楊柳：古曲名，內容多寫離別思鄉，柳諧音留。玉門關：古代通往西域的重要關隘，在今甘肅敦煌西北。\n 白話：黃河向遠方奔流，彷彿一路流進了白雲深處；一座孤城矗立在萬仞高山之間。羌笛何必用哀怨的曲調埋怨楊柳留不住人，要怪就怪這春風根本吹不到玉門關外。\n \n 【背後的小故事】\n 相傳王之渙與王昌齡、高適三人在旗亭小酌，恰逢梨園歌妓在隔壁宴會獻唱，三人便暗中打賭，看誰的詩被唱到的次數最多。前兩輪唱的都是王昌齡和高適的詩，王之渙臉上有點掛不住，便指著在座最出色的一位歌妓說，如果連她唱的都不是我的詩，這輩子甘拜下風。等那位歌妓開口，唱的正是黃河遠上白雲間。王之渙這位一生行事灑脫、現存詩作僅六首的奇人，靠這首寫玉門關外孤城與鄉愁的小詩贏下賭局。千年之後，玉門關外的春風，依然吹不進去。",
