    "poem_notes": "【字詞與白話】\n 夜光杯：傳說中可在夜間發光的珍貴玉杯。「古來征戰幾人回」直言戰爭的殘酷現實。\n 白話：盛滿葡萄美酒的夜光杯，正要暢飲，馬上的琵琶聲已催人出征。就算醉倒在沙場上，你也別笑我，自古以來出征打仗的人，有幾個能活著回來呢？\n \n 【背後的小故事】\n 涼州是唐朝抵禦吐蕃、突厥的西北前線，出征多半有去無回。這首詩寫的是出征前夜軍營裡的一場豪飲——士兵們明知這可能是最後一杯酒，索性把最好的葡萄酒、最珍貴的夜光杯都擺出來，喝得又快又狠。有人醉倒在沙場邊，被人取笑，卻坦然回應：自古出征的人，能活著回來的又有幾個？這句話道出了所有「明知會失敗仍要拚一次」的心情——創業前夜、告白之前、手術之前，我們心裡都曾有過這樣一杯「醉臥沙場」的酒。",
