    "poem_notes": "【字詞與白話】\n 鬢毛衰：鬢邊的頭髮已經稀疏、灰白。「兒童相見不相識，笑問客從何處來」是全詩最令人心酸的一幕。\n 白話：年少時離開家鄉，直到年老才得以回來，家鄉口音沒有改變，鬢邊的頭髮卻已經稀疏灰白。村裡的孩子看見我，沒有一個認識，笑著問我這位客人是從哪裡來的。\n \n 【背後的小故事】\n 賀知章是玄宗身邊的紅人，發掘並提拔了李白，八十六歲那年才獲准辭官返鄉養老，玄宗還親自寫詩相送，場面極為風光。他離家已超過五十年，一路激動地回到出生的村子，走到自家老宅前，卻見院子裡幾個孩童玩耍，沒有一人認得他。一個孩子笑著問他從哪裡來——這句無心的問候，讓他明白自己雖然鄉音未改，卻早已成了故鄉的陌生人。他回鄉不久便與世長辭，這首詩成了千年來每個「近鄉情怯」的遊子最深的共鳴。",
