    "poem_notes": "【字詞與白話】\n 碧玉妝成：像碧玉裝扮而成，形容柳樹嫩綠光潤的樣子。絲絛：絲線編成的帶子，此處比喻柔軟下垂的柳條。裁：裁剪，此處把春風比喻為一把剪刀。\n 白話：高高的柳樹像是用碧玉裝扮而成，千萬條柳枝垂下來像絲帶。不知道這細細的柳葉是誰裁剪出來的，原來是二月的春風，像一把剪刀一樣。\n \n 【背後的小故事】\n 賀知章是盛唐有名的曠達之人，好酒，性情灑脫。相傳他曾在長安讀到還沒什麼名氣的李白所寫的蜀道難，讀完站起來直呼此人是謫仙人下凡，當場解下隨身的金龜換酒，拉著人暢飲一整天，這段忘年交情後來成了長安城裡人人愛講的佳話。這首詠柳詩的反轉在於，全詩沒有一句寫情，卻把抽象的春天寫得像一場具體的裁縫手藝，看不見的風，被他寫成了看得見的剪刀。",
