    "title": "桃花谿",
    "poem_notes": "【字詞與白話】\n 野煙：山野間的雲霧煙靄。石磯：水邊突出的岩石。盡日：整天。\n 白話：一座橋隱隱約約掛在山野的煙霧裡，看不真切；我在石磯西邊，向漁船上的人打聽路。桃花整天整天隨著流水漂去，那個傳說中的山洞，究竟藏在清澈溪水的哪一邊呢。\n \n 【背後的小故事】\n 張旭以狂草聞名於世，喝醉了就提筆瘋寫，人稱張顛，是唐代數一數二的書法家，可是他傳世的詩作全唐詩裡只有六首，首首都跟他寫字時的瘋勁截然相反，安靜得不像同一個人。這首桃花谿化用了陶淵明桃花源記裡武陵漁人誤入世外桃源、出來後再也找不到路的故事，寫他站在溪邊向漁夫打聽那個傳說中的山洞在哪裡。他心裡其實清楚，連當年做了記號的漁人自己回頭去找都找不到，這個問題自古沒有答案，可是他還是問了——這一問，是這位瘋狂書法家最溫柔、也最真實的一面。",
