    "poem_notes": "【字詞與白話】\n 董大：董庭蘭，唐代著名七弦琴演奏家。「莫愁前路無知己，天下誰人不識君」是高適在自己人生低谷時，送給同樣落魄友人的鼓勵。\n 白話：千里黃雲遮蔽了太陽，顯得一片昏暗，北風吹送著大雁南飛，雪花紛紛飄落。不要擔心前方的路上沒有知己，天底下還有誰不認識你呢？\n \n 【背後的小故事】\n 這首詩寫於一個荒涼的冬日，高適當時四十四歲、窮困潦倒，摯友董庭蘭則因靠山房琯被貶而失去依靠，只能帶著琴四處流浪賣藝。兩個同樣落魄的中年人在風雪中喝完最後一杯酒，高適拍著朋友的肩膀說：天下有誰不認識你？其實他自己才是那個「前路無知己」的人，鼓勵朋友的話，也是說給自己聽的。八年後，高適投身軍旅、平步青雲，成為唐代少數封侯的文人；董庭蘭的琴聲也始終備受賞識。那天雪地裡說出口的話，兩人後來都親自兌現了。",
    "zhuyin": "曛(ㄒㄩㄣ)(xūn)發音同\"勳\"，日落的餘暉。",
