    "poem_notes": "【字詞與白話】\n 芳菲盡：花草凋謝、春光消逝。這首詩寫於白居易被貶江州司馬期間，發現山上花期比山下晚的自然現象。\n 白話：人間四月，百花芬芳已經凋盡，山中寺廟裡的桃花才剛剛盛開。我常常遺憾春天已經無處可尋，卻沒想到它竟悄悄轉進了這裡。\n \n 【背後的小故事】\n 白居易被貶江州司馬期間，心情低落，四月本想看春天最後的桃花，江邊卻早已花謝，他失落地爬上廬山散心，行至大林寺，卻意外看見滿院桃花盛開——原來山上海拔高、氣溫低，花期比山下晚了整整一輪。他這才明白：春天沒有走遠，只是換了個地方等他。寫下這首詩時，他的人生後半場才正要展開——此後歷任忠州、杭州、蘇州刺史，政績斐然，晚年官至刑部尚書，人生比前半段更加精彩。",
