    "poem_notes": "【字詞與白話】\n 羅巾：絲質手帕。按歌聲：排演、演奏歌曲。薰籠：宮中冬天用來薰香兼取暖的竹製籠架。\n 白話：絲帕被淚水浸濕，連夢都做不成；深夜裡，前殿隱約傳來排演歌舞的聲音。她的容顏明明還沒老去，皇帝的恩寵卻早已斷絕；她只能斜靠著薰籠，一個人坐到天亮。\n \n 【背後的小故事】\n 白居易在朝為官，見慣了後宮制度的殘酷——皇帝後宮動輒數千女子，能真正見到皇帝一面的卻寥寥無幾，絕大多數人青春年華就耗在深宮高牆之內。這首後宮詞寫的不是某個有名有姓的妃子，而是千千萬萬個這樣的女子的縮影：她容貌未老，恩寵卻早已斷絕，連被真正寵幸過一次的機會都沒有。白居易把這樣的詩歸進他寫給世人看的新樂府一類，替這些連名字都沒有留下的女子，寫下一盞在天亮前始終沒有熄滅的燈。",
