    "poem_notes": "【字詞與白話】\n 借問：客氣的請問，帶著探詢語氣。妾心：古代女子自稱「妾」，指女子的心意。有信：準時、守信用，這裡指潮汐按時漲退。\n 白話：請問江潮和海水啊，你們比得上我情郎的情意和我的心嗎？我怨他還不如潮水守信用，直到現在天天為他思念，才發現海原來沒有我心裡的思念那麼深。\n \n 【背後的小故事】\n 白居易在蘇州當刺史時主張「歌詩合為事而作」，常留意民間真實心聲。相傳這首詩的原型，是他在運河渡口聽見一個等待跑船丈夫的女人邊搗衣邊抱怨：江潮好歹漲退有時辰，你倒好，說好的日子從不準時；她又說本以為大海最深，如今才知道自己的思念比海還深。白居易把這番怨言記下、稍加打磨，寫成了這首流傳千年的閨怨詩。",
