    "poem_notes": "【字詞與白話】\n 淘：沖刷、沖洗。桑田：種桑樹的農田，「滄海變桑田」是古代傳說，指海洋變成陸地，形容變化極大。\n 白話：白色的浪頭茫茫一片，跟大海連成一體；平坦的沙灘遼闊無邊，望不到盡頭。潮水日日夜夜沖刷，沒有一刻停歇，終於把東邊的大海，沖刷成了種桑樹的農田。\n \n 【背後的小故事】\n 白居易在杭州當刺史時，曾親自到江邊督看堤防，看潮水一趟趟沖刷沙洲——去年還在的一片沙洲，今年已被沖進海裡，別處卻又淤出新沙，已有人牽牛去試著犁地。他想起小時候聽過的傳說：仙女麻姑活了幾百年，親眼見過東海三次變成陸地。以前只當是哄小孩的故事，如今站在潮聲裡親眼看沙洲一年就能沖沒又淤出，他才明白，滄海桑田從不是誇張的說法，只是常人等不到那個時間尺度。",
