    "poem_notes": "【字詞與白話】\n 凌寒：冒著寒冷。西樓：泛指女子所居的樓閣，這裡指湘靈居所。\n 白話：眼裡的淚水在寒風中幾乎凍住，流不下來；每次走過高處，都忍不住回頭望一眼。我料想分別之後，你此刻應該正靠在西樓的欄杆上，一個人獨自發愁。\n \n 【背後的小故事】\n 相傳白居易年少時在符離與鄰家女子湘靈相戀，兩人情投意合，卻因家世懸殊，始終得不到母親的同意。他離開符離求學應試那天，天氣冷得連淚水都凝在眼角，走到一處高地，忍不住回頭望向來處。他猜，湘靈此刻大概也正一個人靠在自家樓上的欄杆邊發愁。後來白居易入朝為官、另娶楊氏，湘靈這個名字，卻在他中年以後的詩裡還斷斷續續出現過幾次，像一件收在心底始終沒丟掉的舊物。",
