    "poem_notes": "【字詞與白話】\n 瑟瑟：此處形容未被夕陽照到、仍呈青綠色的江水，是顏色詞而非狀聲詞。真珠：即珍珠。可憐：此處是可愛、討人喜歡的意思，不是憐憫。\n 白話：一道殘陽斜照在江面上，鋪成一片光影，半江碧綠、半江艷紅。多可愛的九月初三夜晚啊，露水像珍珠一樣晶瑩，一彎新月像一把弓掛在天上。\n \n 【背後的小故事】\n 這首詩寫在白居易自請外放杭州刺史、離開長安牛李黨爭漩渦的路上。他在朝廷這些年，兩派人馬鬥得厲害，他兩邊都不想沾，索性主動請調外放。這首詩的反轉在於它單純到近乎奢侈，沒有一句提到朝廷，沒有一句提到黨爭，只是一個終於卸下心防的人，在船頭安安靜靜看一條江。這是他很多年沒有過的心情。",
