    "poem_notes": "【字詞與白話】\n 公子王孫：泛指權貴子弟，此處指婢女被賣入的權貴之家。候門：權貴人家守衛森嚴的大門。蕭郎：本為對心上人的泛稱，此處崔郊以蕭郎自況，意指從此被當作陌生人看待。\n 白話：一群公子王孫跟在她身後，她偷偷落淚，淚水滴濕了手上的絲巾。自從她被賣進那深似海的候門大宅，從此我這個曾經的心上人，也只能被當作路人看待了。\n \n 【背後的小故事】\n 崔郊生平記載很少，這段故事全靠唐代筆記雲溪友議流傳下來，真假難辨，只能以相傳處理。傳說他與姑母家的一名婢女相戀，後來婢女被賣給權貴於頔，兩人音訊斷絕。寒食節那天，崔郊巧遇她，寫下這首詩。這首詩的反轉在於結局，照理說寫詩罵權貴奪人所愛該惹來殺身之禍，於頔看完卻大受感動，把婢女還給了崔郊，成全這段苦戀。",
