    "poem_notes": "【字詞與白話】\n 人面：指代那位女子的容顏。相映紅：桃花與女子的臉龐互相映襯，都是紅色。依舊：還是老樣子，沒有改變。\n 白話：去年的今天，就在這扇門裡，那女孩的臉龐和滿樹桃花互相映襯，紅得動人。今年再來，那張臉龐不知去了哪裡，只有桃花依然對著春風，笑得和去年一樣燦爛。\n \n 【背後的小故事】\n 相傳崔護一年清明到長安城南討水喝，遇見門邊桃花樹下一位女子，兩人相對無言，卻印象深刻。隔年清明他重訪舊地，桃花依舊盛開，門卻深鎖無人應答，他便在門上題下此詩。後世話本還添了女子思念成疾、崔護再訪竟使她甦醒的結局，真假難考，但「人面桃花」四字已成了千古錯過的代名詞。",
