    "poem_notes": "【字詞與白話】\n 龍鐘：原指年老遲緩的樣子，此處形容淚流滿面、狼狽沾濕的模樣，與年紀無關。憑：拜託、託付。傳語：捎口信。\n 白話：向東望向故鄉，只見路途漫漫遙遠，我兩隻袖子沾滿淚水，怎麼擦也擦不乾。在馬上與你相逢，卻沒有紙筆可以寫信，只能拜託你替我捎個口信，就說我一切平安。\n \n 【背後的小故事】\n 這首詩寫岑參第一次出塞前往安西都護府任職途中，在路上偶遇一位東返長安的使者。這首詩的反轉在於，思念最深的那一刻，反而寫不成一封正式的信，兩人都在馬背上，行色匆匆，連停下來找紙筆的時間都沒有。最後岑參只能靠一句口頭的話，把牽掛捎回幾千里外的家。沒有紙筆，反而寫成了最短也最重的一封家書。",
