    "poem_notes": "【字詞與白話】\n 獨憐：特別喜愛，不是可憐的意思。野渡：荒僻無人看管的渡口。橫：船沒人划動，被水流沖得橫在水面上。\n 白話：我特別喜愛澗邊那叢無人在意的幽草，樹林深處傳來黃鸝的叫聲。傍晚春潮夾著雨勢湍急地漲起來，荒僻的渡口沒有船夫，那條船自己橫在水面上。\n \n 【背後的小故事】\n 韋應物年少時是仗著唐玄宗寵信橫行長安的紈袴子弟，賭博、擾民、家裡還窩藏逃犯，安史之亂後失了靠山，才閉門苦讀，脫胎換骨成溫和自省的地方官。做滁州刺史時他在澗邊愛上一叢沒人多看一眼的野草，想起當年自己何曾正眼看過弱小之人，寫下這首詩，也寫下後來「邑有流亡愧俸錢」的自省。",
