    "poem_notes": "【字詞與白話】\n 對愁眠：伴著愁緒難以入睡。寒山寺半夜敲鐘不合常規，正是這首詩最關鍵的細節。\n 白話：月亮西沉，烏鴉啼叫，滿天霜氣。江邊楓樹、漁船燈火，伴著我的愁緒難以入眠。姑蘇城外的寒山寺，半夜的鐘聲傳到了客船上。\n \n 【背後的小故事】\n 張繼生平史書記載不到兩百字，全靠這首詩留名。那年他剛落榜，南下回江南，夜泊蘇州城外，一夜失眠——月落、烏啼、霜寒，他覺得自己的人生大概就這樣了。就在這時，寒山寺不合常規地在半夜敲響了鐘聲，穿過夜色傳進他的船艙。這個意外的聲音被他寫進詩裡，讓一個失眠的落榜生，和一座寺廟，一起被記住了一千兩百年。",
