    "poem_notes": "【字詞與白話】\n 御柳：皇家宮苑裡的柳樹。五侯：本指漢代得寵的權貴外戚，這裡借指唐代得勢的權貴宦官。\n 白話：春天的長安城處處飄著飛花，寒食節東風吹得宮中柳枝傾斜。傍晚時分皇宮裡傳出新的火種，蠟燭點起的輕煙分送出宮，一路飄進那些最得寵的權貴人家。\n \n 【背後的小故事】\n 寒食節按規矩全城禁火，韓翃卻寫出皇宮獨獨賞賜新火給權貴的畫面，暗諷特權不平等。沒想到多年後朝廷要選人補駕部郎中一職，恰好京城有兩個韓翃，唐德宗親自提筆寫下這首詩的第一句指名要哪一個，一首諷刺特權的詩，最後成了詩人自己被皇帝欽點做官的敲門磚。",
