    "poem_notes": "【字詞與白話】\n 闌干：橫斜、縱橫交錯的樣子，這裡形容北斗星座傾斜的姿態。透：穿透、滲入。\n 白話：深夜的月光只照亮半邊院子，北斗星斜斜掛著，南斗也已經偏斜過去。今天晚上特別能感覺到春天的暖意，新的蟲鳴聲透進了綠色的窗紗裡。\n \n 【背後的小故事】\n 劉方平終身沒有做官，生平記載極少，只知道他長年獨居，習慣夜裡不睡，坐在窗邊聽外頭的聲音。這一夜，月光只照亮院子一半，北斗南斗都已經斜過去，他知道已是後半夜。忽然他聽出窗紗外的蟲鳴跟前幾天不一樣了——更密、更透，像是貼著窗紗鑽進來。別人要等到白天看見花開才知道春天到了，他只靠這一夜的蟲聲，就已經確定。這種對細微變化的敏感，大概正是常年獨居、把每個夜晚都聽熟了的人才有的本事。",
