    "poem_notes": "【字詞與白話】\n 金屋：漢武帝劉徹幼時曾對表妹陳阿嬌說若得阿嬌作婦，當作金屋貯之，後世用金屋形容被深藏寵愛的女子，這裡是反用其意，有金屋卻無人。淚痕：不是正在哭，是哭過的痕跡還留在臉上，沒人看見更沒人問。空庭：不是沒有人打掃的院子，是有人住卻無人來的院子，寂寞感更重。\n \n 白話：紗窗外的日光漸漸西沉，天色慢慢轉入黃昏。金屋裡沒有人，只有她臉上乾了的淚痕沒人看見。寂寞的庭院裡，春天快要過去了。滿地的梨花落了，可是那扇門，始終沒有打開。\n \n 【背後的小故事】\n 劉方平終身沒有做官，長年隱居在穎水邊，靠著四處走動、聽人閒談過日子。相傳這首詩寫的是他在洛陽聽聞的一戶人家，屋裡鎖著一個曾被寄予厚望、後來卻被冷落的女子。他借用漢武帝金屋藏嬌的典故，把這份曾經的甜蜜承諾和後來的荒涼並列在一起，寫盡深宮或大宅女子共同的命運，曾經被許諾獨寵，最後卻獨自一人。",
