    "poem_notes": "【字詞與白話】\n 受降城：唐中宗時名將張仁願在黃河北岸築的三座城，用來防禦突厥，是當時最前線的邊防要塞之一。回樂峰：地名，在今寧夏靈武附近，是邊塞常見的地標。蘆管：一種用蘆葦做成的簧管樂器，聲音蒼涼，常見於軍營、邊地。\n \n 白話：回樂峰前的沙地，在月光下白得像雪；受降城外，月色清冷得像結了霜。不知道是從哪裡傳來的蘆管聲，這一夜，所有戍守邊疆的士兵都在想著自己的家鄉。\n \n 【背後的小故事】\n 李益年輕時考中進士，卻不甘於在內地慢慢升遷，主動投身邊塞軍府任職，因此對戍卒生活有第一手的體會。這首詩相傳寫於他在朔方軍中的某個夜晚，他跟士兵一起登城樓，聽見不知從何處傳來的笛聲，看著身邊原本嬉笑的士兵瞬間沉默下來。他自己長年離家，寫的雖是一夜征人，其中也藏著他自己。這首詩後來被譜成曲子在軍中傳唱，成為唐代邊塞詩裡最常被吟唱的一首。",
