    "poem_notes": "【字詞與白話】\n 朱雀橋：金陵城內通往皇城的要道橋樑，當年裝飾有銅雀。烏衣巷：東晉王導、謝安等世族聚居地，因子弟愛穿黑衣得名。堂前燕：築巢在廳堂前的燕子，年年飛回舊地。\n 白話：朱雀橋邊如今只剩野草閒花，烏衣巷口只有一抹夕陽斜照。當年在王導、謝安兩大家族廳堂前築巢的燕子，如今都飛進了普通百姓家的屋簷下。\n \n 【背後的小故事】\n 劉禹錫寫這首詩時未必親臨金陵，是憑史籍記載想像東晉王謝兩大家族從烜赫到沒落的滄桑。燕子認地不認門第，昔日最頂級的門第，如今屋簷下住的只是尋常人家，這個對比讓老友白居易讀後反覆吟誦、讚嘆不已。一千多年後，王謝已成史書上的姓氏，那隻燕子卻還年年飛。",
