    "poem_notes": "【字詞與白話】\n 宜面：脂粉妝容正好襯托臉蛋。玉搔頭：玉製的髮簪，因可用來搔頭癢而得名。\n 白話：剛梳妝好、妝容正合適的她從朱紅樓閣走下來，滿院春光卻鎖不住她一整院子的愁悶。她走到庭院中央，無聊地數著花朵，一隻蜻蜓飛來停在她頭上的玉簪上。\n \n 【背後的小故事】\n 劉禹錫晚年與白居易一起在洛陽過著半退休生活，兩人常以同題詩互相唱和，相傳這首春詞就是他讀了白居易同名作品後提筆回敬的。表面寫深宮女子的寂寞，其實藏著劉禹錫自己的心事，他因永貞革新被貶謫二十三年，才華被困在朝廷看不見的地方，跟困在深院裡的美人，是同一種滋味。",
