    "poem_notes": "【字詞與白話】\n 「曾經滄海難為水，除卻巫山不是雲」是元稹悼念亡妻之作，後世常被誤用為情場浪子語，實則出自真摯的喪妻之痛。\n 白話：見過大海的浩瀚，其他的水便難以稱作水了；除了巫山那如夢似幻的雲霞，其他的雲都算不上雲。就算走過姹紫嫣紅的花叢，我也懶得回頭一顧，一半是因為修道看破了紅塵，一半是因為你。\n \n 【背後的小故事】\n 元稹的妻子韋叢出身名門，卻甘願嫁給當時窮困的他，粗茶淡飯、縫衣賣釵也毫無怨言，婚後七年病逝，年僅二十七歲。這首詩寫於妻子過世後的一個秋夜，他用滄海與巫山雲比喻妻子在他心中無可取代的地位，發誓此生不再動心。然而兩三年後，他先後與另一位女子相戀，又續娶了裴淑。後世常因此質疑他用情不專，但那個秋夜他寫下這些字時，確實是全心全意的——人心會變，不代表當下的深情是假的。",
