    "poem_notes": "【字詞與白話】\n 才思：才華、才情。無才思，指楊花榆莢沒有能力開出艷麗的花色。解：懂得、只會。\n 白話：草木知道春天不會停留太久，於是各種花卉都拼命爭奇鬥艷。楊花跟榆錢沒有那種爭艷的才情，只懂得漫天飛舞，飄得像雪花一樣。\n \n 【背後的小故事】\n 韓愈晚年在長安城郊看見滿街紅紫爭豔的晚春景象，忽然想起自己提拔過的孟郊和賈島——這兩人詩風寒瘦，不像少年才子那樣一亮相就滿座讚嘆，考功名也考得極其艱難。他一向替他們說話：沒有天生艷麗的本錢，不代表沒有本事。眼前那兩棵開不出花的楊樹跟榆樹，索性把僅有的一招使到極致，漫天飄成一片雪。滿街紅紫終究會謝，那場飛雪般的楊花，反倒讓人記得更久——這正是韓愈看人一貫的標準。",
