    "poem_notes": "【字詞與白話】\n 台城：六朝宮城所在，位於建康（今南京）。結綺、臨春：陳後主所建的兩座奢華樓閣。後庭花：陳後主自製的樂曲〈玉樹後庭花〉，後世視為亡國之音的代表。\n 白話：台城歷經六個朝代，一朝比一朝競相奢華，陳後主建造的結綺閣和臨春閣，是其中最奢侈的極致。如今萬戶千門的繁華都已成了荒野雜草，而這一切，只因為那一支〈後庭花〉的曲子。\n \n 【背後的小故事】\n 劉禹錫寫這組懷古詩時，人在外地，離金陵幾百里，自己坦言一個地方都沒去過，全憑史書與傳聞想像下筆。他寫台城，想的是陳後主躲在結綺、臨春兩座樓裡聽自己新編的〈後庭花〉，渾然不覺隋軍已經渡江，城破之時還跟寵妃躲進井裡——六朝的萬戶千門，一夜之間全成了野草。詩傳到白居易手裡，據說白居易讀完沉吟良久，直說這個題目後人不必再寫——一個沒去過的地方，竟被劉禹錫寫得比親眼所見還準。",
