    "poem_notes": "【字詞與白話】\n 前度劉郎：劉郎指劉禹錫自己，前度即上一次，意思是上次來過的那個劉郎，這次又來了，語氣裡帶著自嘲也帶著不服輸的倔強。玄都觀：長安城南的一座道觀，唐代文人常在此賞花、聚會。\n \n 白話：百畝大的院子裡，一半都長滿了青苔。原本滿院的桃花早已凋盡，如今開的是尋常的菜花。當年種桃花的那個道士，如今去了哪裡也沒人知道。只有上次來過的劉郎我，這次又來了。\n \n 【背後的小故事】\n 劉禹錫第一次寫玄都觀桃花詩，是嘲諷那些靠他被貶才爬上高位的新貴，結果這首詩又害他再被貶了十四年。這十四年裡，跟他同年被貶的好友柳宗元病逝柳州，劉禹錫後來接手整理他的遺稿、照顧他的遺孤。十四年後劉禹錫終於回到長安，重遊已經荒涼一片的玄都觀，寫下這首詩。他沒有寫一句委屈，只用今又來三個字，說明自己活著、也還在。",
