    "poem_notes": "【字詞與白話】\n 竹枝：巴渝一帶的民間歌謠，配短笛與鼓演唱。晴：與「情」同音，這裡一語雙關，表面說天氣，實指感情。\n 白話：楊柳青青，江水平緩，聽見江上傳來情郎踏歌而來的歌聲。東邊出著太陽，西邊卻下著雨，說是沒放晴吧，這邊卻又晴了，你說他到底對我有沒有情意呢。\n \n 【背後的小故事】\n 劉禹錫被貶為夔州刺史時，常到江邊聽當地青年男女唱竹枝民歌，覺得比長安宮廷曲子更動人，索性提筆仿寫成詩。這一首寫的是女孩猜不透心上人心意的曖昧，用忽晴忽雨的天氣雙關「情」字。劉禹錫自己被貶二十三年裡起落不定，卻沒把滄桑寫進詩裡，反倒把一整個峽江的民歌採進了唐詩。",
