    "poem_notes": "【字詞與白話】\n 逢秋：遇到秋天。寂寥：冷清、蕭條的感覺。排雲上：衝破雲層往上飛，形容氣勢昂揚。\n 白話：自古以來，人們一到秋天就覺得蕭條冷清、心生悲傷，我卻要說，秋天的景致其實勝過春天。你看那晴朗天空裡一隻仙鶴衝雲直上，這股氣勢，把我的詩興也一路引上了雲霄。\n \n 【背後的小故事】\n 劉禹錫和柳宗元因永貞革新失敗同時被貶，一個到朗州、一個到永州，隔著幾百里書信往來。柳宗元在永州寫下孤獨堅守的江雪，劉禹錫在朗州卻偏要唱反調，看著一隻鶴衝雲而上，寫下秋天勝過春天的昂揚之句。同一種困境，兩個老友用兩種姿態互相撐著，二十多年後才等到召回長安的一天。",
