    "poem_notes": "【字詞與白話】\n 紫陌：京城的道路，因塵土常帶紫色而得名。劉郎：劉禹錫自稱。\n 白話：走在京城的道路上，滿面都是看花人踏起的紅塵，沒有一個人不說自己剛看花回來。玄都觀裡那千株桃樹，全都是我劉某人離開京城之後才栽種的。\n \n 【背後的小故事】\n 劉禹錫與柳宗元同屬永貞革新失敗被貶的「八司馬」之一，分別貶到朗州與永州，一去十年，柳宗元沒能等到平反就死在柳州。劉禹錫十年後終於被召回長安，正逢滿城人爭看玄都觀千株桃花，他一算才發現這些樹全是他被貶之後才栽下的——眼前的盛景跟他這十年的死活毫無關係。他把這口氣寫成一首看似寫景的詩，滿城新貴讀出了諷刺之意，沒多久他又被貶得更遠。十四年後他再回長安，桃樹早已砍盡，他又寫下「劉郎今又來」五字，笑看那些趁他不在時搶著栽花邀寵的人，一個個都已不見。",
