    "poem_notes": "【字詞與白話】\n 巴山：四川一帶的山，此詩寫於李商隱客居四川梓州幕府期間。「何當共剪西窗燭，卻話巴山夜雨時」把此刻的孤獨想像成未來重逢時共同的回憶。\n 白話：你問我什麼時候回家，我還沒有確切的歸期，此刻巴山下著夜雨，秋天的池水都漲滿了。什麼時候才能和你一起在西窗下剪燭夜談，訴說今晚巴山夜雨中，我一個人思念你的心情呢？\n \n 【背後的小故事】\n 李商隱在四川梓州當幕僚，妻子王氏留在長安，兩人相隔千里難以團聚。收到妻子來信詢問歸期，他卻連自己何時能回去都不知道，只能望著窗外連下數日、漲滿池水的秋雨發呆。他沒有訴說此刻的孤獨與思念，而是把這一刻寫成未來重逢時的談資——盼望有一天能與妻子在西窗下一起剪燭夜話，訴說今晚這場雨、這份想念。可惜六年後王氏病逝，兩人終究沒能一起剪過那支西窗燭，這份寫在信裡的「將來」，永遠停留在了紙上。",
