    "poem_notes": "【字詞與白話】\n 金龜婿：唐代官員按品級佩戴金、銀等不同材質的龜形飾物，金龜婿指嫁了個有品級官職的丈夫。辜負：對不起、白白浪費。香衾：熏香的錦被。\n 白話：因為有雲母屏風那樣無限嬌美的家境，鳳城的寒氣剛退，她反而在春夜裡感到害怕。沒想到嫁了個佩金龜的貴官丈夫，卻只能眼看溫暖的錦被落空，天天送他早早上朝。\n \n 【背後的小故事】\n 這是李商隱替一個素不相識的女子寫的心事：外人都羨慕她嫁了個有品級的貴官丈夫，可官越大，早朝越不能遲——丈夫天不亮就得起身趕去候朝，她每天在熏暖的錦被裡，才把丈夫的溫度焐熱，人已經走了。李商隱自己的婚姻也帶著類似的味道：他娶王氏原是牽進牛李兩黨政爭的一環，外人也說他攀了好親家，他卻常年在外奔波當個小幕僚，一年到頭在家的日子屈指可數。他寫得這麼準，大概是因為那張空掉的被窩，他自己家裡也常年鋪著。",
