    "poem_notes": "【字詞與白話】\n 戒嚴：加強戒備防範。九重：指皇宮深處，九重宮闕。障泥：垂掛在馬鞍兩側，遮擋泥土濺上騎者的布飾。\n 白話：隋煬帝乘著興頭南下遊玩，竟連該有的戒備都不放在心上；深宮九重之內，誰又會去理會那些勸諫的奏書？為了這一趟南遊，舉國織出來的錦緞被裁成兩用——一半做成馬鞍邊的障泥，一半直接裁成船帆。\n \n 【背後的小故事】\n 李商隱寫史，其實是寫眼前。他借隋煬帝不顧戒備、不理諫言，執意南遊江都，舉國絲綢拿去鋪排船隊障泥船帆的荒唐事，影射自己身處的晚唐朝廷同樣揮霍無度、聽不進諫言。他活在牛李兩黨鬥爭的邊緣，不敢明著罵當朝天子，只能借兩百多年前那條沉船的教訓，說給看得懂的人聽。真正聽得進諫言的皇帝，史書上向來寥寥無幾——他能做的，只是把那艘船畫清楚，留給後人看。",
