    "poem_notes": "【字詞與白話】\n 瑤池：傳說西王母居住的仙境。黃竹歌：周穆王北巡遇雪，為凍死的百姓所作的悲歌，語出穆天子傳。八駿：周穆王擁有的八匹良馬，傳說能日行三萬里。\n 白話：西王母在瑤池邊打開她華美的窗子盼著穆王前來，卻只聽見那年黃竹歌傳來動地的哀聲。穆王擁有一天能跑三萬里的八匹駿馬，為什麼卻沒有再回來呢。\n \n 【背後的小故事】\n 這首詩表面講周穆王與西王母的神話，西王母在瑤池盼穆王重來，穆王卻一去不返。其實李商隱寫的是眼前事——唐武宗迷信道教方士，大興煉丹求長生，結果沒幾年就因服食丹藥暴斃，才三十出頭。方士的承諾和穆王當年的承諾一樣落空，再快的駿馬、再高的權位，終究換不回一個重來。這是一首借古諷今、卻不敢直說的政治諷刺詩。",
