    "poem_notes": "【字詞與白話】\n 雲母屏風：用雲母石鑲嵌、帶有光澤紋理的屏風。應悔：想必後悔，是詩人的推測語氣。夜夜心：每夜獨守的心情。\n 白話：雲母屏風上燭光幽深晃動，銀河漸漸西沉，天快亮時啟明星也隱沒了。嫦娥想必後悔當初偷吃了那顆長生不死藥，如今只能夜夜獨對碧海青天，承受無邊的孤寂。\n \n 【背後的小故事】\n 相傳李商隱年少時曾在玉陽山學道，與一位女道士互有情愫，卻因觀規森嚴始終無法在一起，這段情事真假摻半，只能從他大量隱晦的無題詩裡推敲。多年後他借嫦娥獨守月宮的傳說，寫下得到長生卻失去陪伴的矛盾，也有人說這其實是他夾在政治夾縫中處境的寫照。他自己從未解釋，這輪月亮因此照了千年。",
