    "poem_notes": "【字詞與白話】\n 折戟：斷裂的戟，一種古代兵器。前朝：這裡指三國時代。東風：指赤壁之戰中助周瑜火攻取勝的關鍵風向。\n 白話：一支斷戟埋在沙裡還沒完全鏽蝕，我把它磨洗乾淨，認出是前朝的兵器。當年若不是東風幫了周瑜的忙，恐怕大喬小喬早就被關進銅雀台，鎖住整個春天了。\n \n 【背後的小故事】\n 杜牧被外放黃州刺史時，在江邊撿到一支三國時代的斷戟，這一帶相傳是赤壁古戰場。他年輕時曾替孫子兵法作注，一心嚮往用兵之道，卻一輩子沒機會帶兵打仗。撿到斷戟後他幻想若當年東風沒有站在周瑜那邊，東吳的兩大美人恐怕就要被曹操鎖進銅雀台，藉這個假設寫盡歷史成敗有時候靠的只是一陣風。",
