    "poem_notes": "【字詞與白話】\n 後庭花：南朝陳後主所作〈玉樹後庭花〉，被視為亡國之音的代表。「商女不知亡國恨」實際上責備的是聽曲的權貴，而非唱曲的歌女。\n 白話：輕煙籠罩著寒冷的江水，月光籠罩著白沙，夜裡把船停泊在秦淮河邊，靠近岸上的酒家。賣唱的歌女不懂得亡國的傷痛，隔著江水依然在唱著〈後庭花〉這首曲子。\n \n 【背後的小故事】\n 杜牧夜泊南京秦淮河，聽見岸邊酒家傳來歌女演唱〈玉樹後庭花〉——這正是兩百多年前南朝陳後主亡國前夜終日聆聽的靡靡之音。他站在船頭，看著對岸依舊笙歌不斷的酒樓，忽然意識到：晚唐的朝廷腐敗、藩鎮割據，跟陳後主當年的處境如出一轍，可台上台下沒人聽得出這段歷史正在重演。他並非責怪唱曲的歌女，而是感嘆那些花錢點曲、渾然不覺的權貴。杜牧終其一生沒能挽救晚唐，六十年後唐朝正式滅亡，但這句「商女不知亡國恨」，成了後世每個看見歷史重演卻無人在意的人，心底最沉的共鳴。",
