    "poem_notes": "【字詞與白話】\n 迢迢：遙遠的樣子。二十四橋：揚州城內一座有二十四個橋洞的名橋，一說指城中二十四座橋。玉人：指代吹簫的美人，也有人解作韓綽本人。\n 白話：青山隱隱約約，江水流向遠方，江南的秋天已到尾聲，草木卻還沒有凋零。二十四橋籠罩在明月之下，不知道那些教人吹簫的美人，如今在何處。\n \n 【背後的小故事】\n 杜牧曾在淮南節度使幕府任職，駐地揚州，與同僚韓綽交好，兩人一起在這座天下最繁華的商埠裡度過一段紙醉金迷的歲月。後來杜牧調回長安任監察御史，官位升了，日子卻板正許多，他寫信給仍留在揚州的韓綽，問候語氣輕鬆，底下藏著的是他捨不得的整座城市，以及還沒被長安磨掉的那個自己。",
