    "poem_notes": "【字詞與白話】\n 落魄：潦倒失意、放浪不羈的樣子。楚腰：泛指身材纖細的美人，典出楚王好細腰。薄倖：薄情、負心。\n 白話：這些年我在江湖間潦倒放浪，載著酒四處遊蕩，身邊常伴著腰肢纖細、輕盈得能在掌心起舞的歌姬。十年像一場夢，一覺醒來揚州的日子已經過去，我到頭來只落得一個在青樓裡負心薄倖的名聲。\n \n 【背後的小故事】\n 杜牧在揚州當幕僚時，夜夜流連秦樓楚館。相傳上司牛僧孺擔心他出事，暗中派人保護、記錄他平安回府的行蹤，等杜牧調任離開時才拿出這疊記錄，杜牧這才知道自己的荒唐一直被人看在眼裡替他兜底。十年後他寫下這首詩，語氣輕鬆自嘲，底下卻是他對辜負的青春最沉的悔意。",
