    "poem_notes": "【字詞與白話】\n 畫屏：繪有圖畫的屏風。輕羅小扇：質地輕薄的絲羅小團扇。天階：宮中的石階。\n 白話：銀白色的蠟燭照著冷清的畫屏，她拿著輕羅小扇，撲打著飛來飛去的螢火蟲。宮中石階上的夜色涼得像水一樣，她獨自坐著，抬頭看牛郎星和織女星。\n \n 【背後的小故事】\n 這是杜牧想像中一位深宮女子的秋夜，沒有真實姓名可考。她的夜晚長得像沒有盡頭，只能拿扇子追打螢火蟲打發時間，抬頭看見一年只能相會一次的牛郎織女，反倒生出羨慕，因為她連一個確定的相會日子都沒有。這首詩寫的不是哪一個人，是千千萬萬個被困在高牆深宮裡、連盼頭都算不上盼頭的女子。",
