    "poem_notes": "【字詞與白話】\n 娉娉嫋嫋：形容體態輕盈柔美的樣子。豆蔻梢頭二月初：以二月初含苞待放的豆蔻花比喻十三四歲少女的青春年華。\n 白話：她體態輕盈，年紀十三歲多一點，像二月初剛冒頭的豆蔻花苞。整條揚州路春風十里，卷起珠簾一個個亮相的美人，沒有一個比得上她。\n \n 【背後的小故事】\n 杜牧在揚州當幕僚那幾年出了名地流連秦樓楚館，多年後他自己都承認那是一場沒醒過來的夢。在數不清的夜晚裡，他記住了一個年紀尚小、身量還沒長開的女孩，覺得她勝過整條揚州路上所有濃妝豔抹的美人。臨別前夕，他把這份心意寫進詩裡，卻不知道自己以為孤身一人的那些夜晚，相傳上司牛僧孺早已暗中派人一路守護。",
