    "poem_notes": "【字詞與白話】\n 樽前：酒杯之前，指飲酒送別的場合。蠟燭有心：雙關語，蠟燭芯稱「心」，這裡借指蠟燭彷彿也有惜別之心。\n 白話：明明情深，卻表現得像是無情，只覺得在離別酒席前怎麼也笑不出來。桌上的蠟燭彷彿也懂得惜別，替人流淚滴蠟，一路滴到天亮。\n \n 【背後的小故事】\n 離開揚州的送別酒席上，杜牧面對心裡真正在意的女孩，卻一句俏皮話都說不出口。也是這一晚，上司牛僧孺交給他一疊記錄，他才知道自己這幾年深夜出行，相傳其實一直被人暗中護送平安。他忽然明白，最深的感情往往長得最不像感情，自己說不出口的不捨，跟牛僧孺說不出口的關照，是同一回事，只有滿桌燒了一夜的蠟燭替他們把眼淚哭完。",
