    "poem_notes": "【字詞與白話】\n 香塵：本指美人步履揚起的香氣塵土，這裡代指昔日的繁華奢靡。墜樓人：指晉代石崇愛妾綠珠，相傳為守節而跳樓身亡。\n 白話：昔日的繁華早已隨著香塵散盡，溪水依舊無情地流淌，春草年年自顧自地生長。黃昏起風，林中鳥鳴像在埋怨著什麼，風裡飄落的花瓣，看起來很像當年那個跳樓的女子。\n \n 【背後的小故事】\n 金谷園原是西晉巨富石崇的私家園林，相傳他寵愛的姬妾綠珠因權臣孫秀逼要，寧可跳樓也不願被奪走。杜牧路過這座荒廢數百年的園子時，想起自己家族也曾顯赫一時卻同樣敗落，寫下繁華易散的感慨。真正讓這首詩流傳千年的，不是石崇鬥富的財富，而是那一片飄落的花瓣，讓人想起那個縱身一躍的女子。",
