    "poem_notes": "【字詞與白話】\n 坐愛：因為喜愛而。「停車坐愛楓林晚，霜葉紅於二月花」寫的是行程中忽然停下、專心欣賞眼前風景的瞬間。\n 白話：沿著蜿蜒的石徑往寒山深處走去，在白雲繚繞的地方隱約可見人家。因為喜愛這片傍晚的楓林美景而停下車來，經霜的楓葉，比二月的春花還要紅豔。\n \n 【背後的小故事】\n 這首詩寫杜牧在山中趕路時，途經一片楓林，被滿樹經霜轉紅的楓葉震住，索性叫車伕停下，坐下來專心欣賞這片比春花更豔麗的紅色。杜牧一生輾轉各地為官，見過長安宮廷、揚州歌舞、秦淮繁華，卻鮮少為風景真正停下腳步。這個晚秋午後，他難得放下趕路的焦急，只為多看一片無人在意的野楓林幾眼。千年後，每個在秋天被一片楓紅震住、願意為此暫時放下行程的人，都在重複杜牧那個下午做過的事。",
