    "poem_notes": "【字詞與白話】\n 繡成堆：形容驪山草木、宮殿層疊如錦繡堆疊。次第：依次、一道接一道。紅塵：快馬奔馳揚起的塵土。\n 白話：從長安回望驪山，草木宮殿層層疊疊像錦繡堆成。山頂上一道接一道的宮門依次打開。一匹快馬揚塵奔來，貴妃看了展顏一笑，沒有人知道，那只是為了送新鮮荔枝來。\n \n 【背後的小故事】\n 華清宮是唐玄宗與楊貴妃的避暑行宮，史書記載貴妃愛吃荔枝，朝廷不惜設置接力快馬，晝夜兼程從嶺南或四川運送，累死無數驛卒與馬匹，只為在荔枝變味前送到長安。安史之亂後幾十年，杜牧行經已成廢墟的華清宮，想起這樁荒唐往事，把滿朝以為是軍情、結果只是荔枝的對比寫成詩，釘住了那段奢靡誤國的歷史。",
