    "poem_notes": "【字詞與白話】\n 尋春：尋訪春天的花，此處暗指尋訪那位女子。去羅遲：去得太遲、耽誤了太久的時間。盪盡：吹得一乾二淨。子滿枝：果實掛滿枝頭，暗指女子已嫁人生子。\n 白話：想去尋訪那年的春光，卻去得太遲了，不必為錯過花開的時節而惆悵。一陣狂風已經把深紅的花瓣吹得一乾二淨，如今綠葉成蔭，枝頭已經結滿了果實。\n \n 【背後的小故事】\n 相傳杜牧年輕時在湖州遇見一名女子，女子母親提出十年之約，十年內若未娶妻便回來迎娶。杜牧因官場調動遲了四年才重回湖州，女子早已嫁人生子。他去看當年那株花樹，花早已被風吹落，只剩滿枝濃綠與果實。這首詩表面寫花，其實寫的是自己遲到十四年的懊悔，故事雖出於唐代筆記相傳，卻與詩意完全吻合。",
