    "poem_notes": "【字詞與白話】\n 丹青手：指擅長繪畫的畫師。金陵：今南京，東晉與南朝宋齊梁陳先後在此建都又先後滅亡，是懷古詩常見題材。\n 白話：浮雲陪著我一起飄回染上暮色的青翠遠山，落日也陪著秋天的風聲一起低垂。世間有那麼多技藝高超的畫師，卻沒有一個人畫得出我心裡這一片傷心。\n \n 【背後的小故事】\n 高蟾出身寒門，沒有家世背景，考了很多年科舉才中進士，落第時還寫詩自比秋天不合時節開花的芙蓉，倔強地不肯埋怨。登上金陵城頭時，他望著這座埋葬過好幾個王朝的古都，想起自己這些年的辛苦起落，覺得那片說不出口的傷心，連天下最厲害的畫師都畫不出來，因為那不只是風景，是好幾百年的興亡疊在一個寒門子弟一輩子的努力裡。",
