    "poem_notes": "【字詞與白話】\n 六幅：指這套題畫詩所題的六幅金陵懷古畫作。故城：此指六朝古都金陵，即今南京。\n 白話：誰說傷心的事情畫不出來，畫家把人心裡的悲傷，融進了世間人共通的情感裡。你看這六幅畫裡的南朝往事，如今只剩下老樹與寒雲，籠罩著這座蒼涼的故城。\n \n 【背後的小故事】\n 韋莊晚唐時親身經歷黃巢之亂，被困長安數年，寫下長詩秦婦吟記錄亂世慘狀，後又輾轉入蜀輔佐建立前蜀。晚年他在金陵看到一套描繪六朝興亡的畫作，看得格外沉默，別人只當那是古畫技藝高明，他卻從畫裡的荒涼認出了自己親眼見過的長安淪陷。這首詩表面題畫，其實是一個親歷過亡國之人，對另一場亡國的無聲共鳴。",
