    "poem_notes": "【字詞與白話】\n 內人：唐代宮中稱呼歌舞伎或女官為內人，是有一定地位卻仍受制於宮牆的女子。禁門：宮廷大門，戒備森嚴，象徵與外界隔絕。剔開紅焰：用簪子把燈火中危險的火苗撥開，救下即將被燒的飛蛾。\n \n 白話：宮門旁的樹梢，月光緩緩移過。她的目光只能望向屋簷下棲息的鷺鳥。深夜燈影邊，她斜斜拔下玉釵，撥開快要燒到飛蛾的火苗，把牠救了下來。\n \n 【背後的小故事】\n 張祜一生仕途不順，考試落第、投靠無門，因此格外能懂困守一地、動彈不得的滋味。相傳他聽聞宮中有這樣一位內人，日日被困在深宮，能看的只有睡鳥，卻在某個深夜，用自己僅有的一根玉釵，救下一隻撲火的飛蛾。張祜把這個瞬間寫成詩，沒有一句直接說她可憐，卻讓所有讀到的人都看見，一個被困住的人，仍然能對另一個更弱小的生命伸出手。",
    "zhuyin": "鷺(ㄌㄨˋ)(lù)發音同\"路\"，動物名。鸛形目鷺科。似鶴略小，羽白，翅寬，頸腳皆長，嘴長而直，頭頂有細長白毛。棲息於水邊，捕魚為食。\n 窠(ㄎㄜ)(kē)發音同\"科\"，鳥、獸、蟲類等棲息的巢穴。\n 剔(ㄊㄧ)(tī)發音同\"梯\"，從縫隙中往外挑。",
