    "poem_notes": "【字詞與白話】\n 集靈臺：借漢代求仙的臺名，實指唐代宮中場所。虢國夫人：楊貴妃之姊，因楊家得寵而封爵。至尊：指皇帝。\n 白話：虢國夫人承受著皇帝的恩寵，天剛亮就騎馬進入宮門。她嫌脂粉會遮蓋自己本來的顏色，只淡淡描了眉毛，就去朝見皇帝。\n \n 【背後的小故事】\n 虢國夫人是楊貴妃的姐姐，天寶年間楊家因貴妃得寵而權傾一時，她天生美貌，不施粉黛騎馬入宮朝見玄宗的傳聞流傳長安多年。張祜生於中晚唐，沒趕上開元盛世，卻從長輩口中拼湊出那個時代的鮮豔與危險——楊家專寵埋下了安史之亂的禍根，長安淪陷，貴妃與虢國夫人都死於逃難途中。這四句寫的是美貌，骨子裡寫的是盛世崩塌前最刺眼的那一瞬。",
