    "poem_notes": "【字詞與白話】\n 津渡：渡口。行人：這裡指在外奔波、寄宿他鄉的旅人，不是普通路人。斜月：偏斜、已過中天的月亮，暗示夜已深。瓜州：長江北岸的渡口，與金陵渡隔江相望。\n \n 白話：金陵渡口邊一座小小的山樓，旅人在這裡投宿一夜，難免生出愁緒。江水正在退潮，斜月照在江面上，對岸隱約可見兩三點星火，那裡就是瓜州。\n \n 【背後的小故事】\n 張祜一生求官不順，索性四處遊歷，晚年幾乎沒有固定住處。相傳這首詩寫於他投宿金陵渡口一座小樓時，深夜望著對岸瓜州的零星燈火，寫下自己那種到不了對岸、也回不去家鄉的漂泊心情。這首詩沒有一句直接說苦，只用兩三星火四個字，把整夜的孤獨都裝了進去，後來成為唐代寫渡口夜泊最有名的一首七絕。",
