    "poem_notes": "【字詞與白話】\n 瓊軒：玉石砌成的欄軒，泛指宮中華美的迴廊。含情：滿懷心事、有話想說。\n 白話：花開時節，院門靜靜關著，兩位宮中美人並肩站在華美的欄軒邊。她們滿懷心事想說出宮裡的種種事情，卻因為前面站著一隻鸚鵡，不敢開口。\n \n 【背後的小故事】\n 朱慶餘曾任秘書省校書郎，出入宮廷附近官署，聽多了深宮裡流傳出來的閒話。這首詩寫兩個宮中姐妹好不容易碰面，滿腹心事卻因為身邊一隻會學話的鸚鵡而不敢出口。可怕的不是宮規森嚴，是連兩個人私下說知心話的空隙，都被一隻鳥填滿了。後人讀來，想起的常常不是深宮，而是自己也曾因為多了一個人在場，把想說的話硬生生吞回去的那個瞬間。",
