    "poem_notes": "【字詞與白話】\n 舅姑：丈夫的父母，即公公婆婆。入時無：是否合乎當下流行的樣式。\n 白話：洞房裡昨晚剛熄了紅燭，天亮前新娘就要到堂前拜見公公婆婆。她梳妝完畢，低聲問丈夫，自己畫的眉毛深淺，合不合現在時興的樣式。\n \n 【背後的小故事】\n 這首詩是朱慶餘考進士前寫給文壇前輩張籍的，他把自己比作即將見公婆的新嫁娘，把張籍比作丈夫，把主考官比作堂前挑剔的公婆，借問眉妝是否入時，委婉問自己的文章合不合考官胃口。張籍收到後回贈一詩，誇他文章早已出眾，不必擔心。這件事被唐代筆記記下流傳，成了科舉場外一段才子問路問得最體貼周到的佳話，朱慶餘後來也確實考中了。",
