    "poem_notes": "【字詞與白話】\n 冰簟：清涼的竹席。十二樓：傳說中神仙居住的樓閣，此處泛指女子居住的樓閣。\n 白話：冰涼的竹席、銀飾的床架，她怎麼也睡不成一個好夢。夜空澄澈如水，幾縷薄雲輕輕飄著。雁群的叫聲遠遠飛過瀟湘一帶，只有十二樓中的月亮，獨自明亮著陪她到天明。\n \n 【背後的小故事】\n 溫庭筠寫這首閨怨詩時，自己也是屢試不第、四處奔波投靠的漂泊之人，深知等待與孤獨的滋味。詩中女子夜裡怎麼也睡不成夢，聽著雁群飛向瀟湘、飛向她思念之人所在的遠方，自己卻只能留在原地，連夢都留不住。這份體會未必只是想像出來的，更像是溫庭筠把自己這些年沒能靠近想要的東西的心情，悄悄放進了這個等人不至的女子身上。",
