    "title": "馬嵬坡",
    "poem_notes": "【字詞與白話】\n 回馬：指玄宗從蜀地返回長安，車駕調頭東歸。雲雨：借宋玉高唐賦典故，代指玄宗與楊貴妃的恩愛情事。景陽宮井：南朝陳後主與寵妃張麗華、孔貴嬪亡國之際躲入景陽宮枯井，被隋兵搜出的典故。\n 白話：玄宗調轉車駕返回長安、楊貴妃卻已賜死馬嵬坡，這段舊日恩愛雖然難忘，可如今大唐總算重見天日。這終究是聖明天子該做的決斷——試問當年躲進景陽宮那口井裡的，又算是什麼樣的人物呢。\n \n 【背後的小故事】\n 安史之亂爆發，玄宗攜楊貴妃倉皇奔蜀，行至馬嵬驛，隨行禁軍嘩變，逼玄宗賜死楊貴妃才肯繼續護駕。鄭畋沒有像多數詩人那樣為楊妃鳴不平，反而拿南朝陳後主對照——國破之際，陳後主抱著寵妃躲進枯井，被隋兵狼狽拖出，成了千古笑柄；玄宗則忍痛割捨所愛，換來社稷重光。多年後，鄭畋自己也在黃巢之亂中身居鳳翔節度使要職，力主抗敵，成了那個在存亡關頭做出艱難抉擇的人，與他筆下稱許的玄宗，隔著百年遙遙相應。",
