    "poem_notes": "【字詞與白話】\n 臺城：南朝時期的皇宮所在地，故址在今南京，此處代指六朝故宮遺址。六朝：指定都南京的東吳、東晉、宋、齊、梁、陳六個朝代。無情：這裡不是說柳樹無情無義，而是反諷手法，正因它不解人事，才顯得對亡國興衰毫不在意。\n 白話：江邊細雨綿綿，江岸的草長得一片齊整；六個朝代的繁華都像一場夢，只剩鳥兒在空蕩的宮牆邊啼叫。最無情的要數臺城邊上的柳樹，如今依然像從前一樣，把煙霧籠罩的堤岸染成十里綠意。\n \n 【背後的小故事】\n 跟你說我朋友端己寫這首詩前幾年，剛親眼看著長安被黃巢的軍隊燒殺一輪，還把那段經歷寫成轟動一時的長詩秦婦吟。後來他在江南翻看一套叫金陵圖的畫冊，畫的是六朝舊都南京，六個朝代輪流在此建都又輪流覆滅。他看著畫裡那排臺城柳，忽然明白，柳樹年年一樣綠，根本不記得誰在這裡稱過帝、誰又亡了國。它的無情不是絕情，是壓根不在乎，而這種不在乎，比任何哭聲都更讓一個親眼見過亡國的人心驚。",
    "zhuyin": "霏(ㄈㄟ)(fēi)發音同\"飛\"，雨雪綿密的樣子。",
