    "poem_notes": "【字詞與白話】\n 貂錦：指鎧甲鮮亮、裝備精良的精銳部隊，出征時貂裘錦繡加身，故稱貂錦軍。無定河：黃河支流，在今陝北一帶，古來是漢胡征戰的邊塞戰場。\n 白話：立誓要掃平匈奴，連自己的性命都可以不顧，結果五千名精銳戰士全數埋骨在異域的沙塵裡。可憐那些橫陳在無定河邊的白骨啊，家裡的妻子卻還把他當成活生生的人，天天在夢裡想念。\n \n 【背後的小故事】\n 陳陶生平史料不多，相傳他屢試不第，索性放下功名，雲遊四方，晚年隱居江西一帶，自稱三教布衣。隴西行寫的是邊塞戰事：五千精銳出征匈奴全軍覆沒，屍骨拋撒在無定河邊，可是戰報傳遞遲緩，遠方的妻子還捧著丈夫幾個月前寄出的家書，夢裡想著他升官還鄉的樣子。詩人沒有正面控訴戰爭殘酷，只是把河邊的白骨和閨中的夢並排放在一起，讓兩個畫面的落差自己說話。",
