    "poem_notes": "【字詞與白話】\n 謝家：不是實指姓謝的人家，是唐詩裡常用來代稱所愛女子家的典故用法，源自東晉才女謝道韞的娘家。依依：形容夢裡依戀、不捨的樣子，帶著反覆纏繞的意味，不只是字面的依依不捨。\n 白話：離別後的夢裡，我一次次依依不捨地走回她家；那條小迴廊繞過去，曲折的欄杆斜斜立在那裡，還是記憶中的模樣。只有春夜庭院裡的月亮還算多情，依然為著遠方思念的人，把清光灑在那片凋落的花瓣上。\n \n 【背後的小故事】\n 跟你說我朋友子澄年輕時，相傳與鄰家女子生出過一段感情，只是家境不允許，兩人一直沒能明說。他後來赴京趕考，一走數年，等回來時對方已經許配他人，一切都定了。從那以後，子澄反覆夢見同一座宅院、同一條迴廊，怎麼樣都夢不完。他寫下這首詩寄給對方，說人回不去了，能回去的只剩夢，而院子裡的月亮，倒是比人多情得多，不管她還住不住在那裡，它照樣為著一個回不去的人，把光灑在滿地落花上。",
    "zhuyin": "闌(ㄌㄢˊ)(lán)發音同\"藍\"，此作欄杆。亦可形容時間將盡（如：夜闌人靜、意興闌珊）。\n 斜(ㄒㄧㄚˊ)(xié)發音同\"峽\"，在古音與詩韻中常讀作ㄒㄧㄚˊ，與末句的「家」字押韻。",
