    "poem_notes": "【字詞與白話】\n 萋萋：草長得茂密的樣子。等是：同樣是、既然是。\n 白話：寒食節前後一連下著雨，路邊的草長得茂密雜亂，風吹著麥苗與河堤上的柳樹。同樣是有家卻回不去的人，已經夠難受了，杜鵑啊，別再在我耳邊啼叫了。\n \n 【背後的小故事】\n 這首詩的作者已經無法考證，只留下無名氏兩個字。相傳是寒食節前後，一個回不了家的旅人在雨中所寫。杜鵑的叫聲在古代傳說裡帶著淒切的意味，像是在說不如歸去，對一個本來就想家的人來說格外刺耳。他忍不住開口拜託那隻鳥別再叫了。沒有留下名字，卻留下了那個雨天站在柳堤邊的畫面，千百年來讓每一個異鄉過節、有家歸不得的人都覺得心有戚戚。",
