    "poem_notes": "【字詞與白話】\n 金縷衣：以金線織成的華貴衣裳，象徵榮華富貴。「花開堪折直須折，莫待無花空折枝」是杜秋娘用一生印證的歌詞。\n 白話：勸你不要只珍惜華貴的金縷衣，勸你更要珍惜自己的青春年少時光。花開得正好時就該把握摘取，不要等到花謝了才對著空枝折取。\n \n 【背後的小故事】\n 杜秋娘年少時被賣為節度使李錡的姬妾，靠這首歌得寵；李錡叛亂被殺後，她淪為宮廷女僕，卻又因為同一首歌打動唐憲宗，從抄家女僕一路躍升為皇帝寵妃，後來又成為皇子的養母。皇子被廢賜死後，她被貶回故鄉，晚年窮困潦倒、鬢髮已白。詩人杜牧路過時見到她，寫下〈杜秋娘詩〉紀念她跌宕起伏的一生。這首她唱了一輩子的歌，到了晚年才顯出最深的重量——她不是在勸別人珍惜青春，而是在替自己的一生做總結：你不摘那朵花，時間終將替你摘去。",
