    "poem_notes": "【字詞與白話】\n 道人：此處泛指同在山中隱居修行的人，不一定是道教徒，唐代常用來稱呼山居的隱士。周情孔思：指周公留下的情理、孔子留下的思想，代稱儒家經典的學問。\n 白話：讀書讀到渾然忘我，不知不覺春天已經快過完了；這一寸一寸流逝的光陰，貴重得像一寸黃金。若不是山裡的道人三不五時跑來逗我笑一下，我大概還埋頭在周公孔子的學問裡追尋不停。\n \n 【背後的小故事】\n 跟你說我朋友有道，年輕時在廬山白鹿洞苦讀，讀書讀到忘記換季，直到發現窗外的樹全綠了才驚覺春天快過完了。他悟出一句話，一寸光陰一寸金，這句話後來變成全天下人惜時的座右銘。可是很少人知道，他寫這句話的當下，其實是被一起隱居的道人硬拉出來透氣、逗他笑一下才想起來的，不是什麼正襟危坐的勵志格言，是一個書呆子被朋友抓包的自嘲。",
