    "poem_notes": "【字詞與白話】\n 「不識廬山真面目，只緣身在此山中」後世常用來比喻「當局者迷」，是蘇軾遊廬山時悟出的哲理。\n 白話：橫著看廬山是連綿的山嶺，側著看又成了聳立的山峰，從遠近高低不同角度看，樣貌各不相同。之所以認不清廬山真正的面目，只是因為自己正身處這座山之中。\n \n 【背後的小故事】\n 蘇軾因「烏臺詩案」被貶黃州四年，反而在困頓中寫出〈赤壁賦〉等傳世之作，真正蛻變為「蘇東坡」。獲調汝州途中，他特地在廬山遊歷近兩週，發現同一座山從不同角度望去，時而是橫嶺，時而是尖峰，樣貌截然不同。他忽然明白：只要自己還身處山中，就永遠看不清廬山的全貌——就像人身處自己的人生裡，也很難看清自己。他把這個體悟題在西林寺牆上，成了千古傳誦的「當局者迷」之喻。可惜他悟出這個道理後，人生仍繼續被貶至惠州、儋州，終究沒能真正「跳出」自己的處境。",
