    "poem_notes": "【字詞與白話】\n 瀲灩：形容水波蕩漾、波光閃動的樣子。空濛：形容雨中山色朦朧、若有若無的樣子。西子：西施，春秋時期越國著名美女，此處蘇軾首創以她比喻西湖，後人便沿用西子湖這個別名至今。\n 白話：晴天時湖面波光粼粼，景色正好；下雨時遠山籠罩在朦朧雨氣裡，別有一番奇妙。若要把西湖比作西施，不論濃妝豔抹還是淡雅素妝，她怎麼打扮都相稱好看。\n \n 【背後的小故事】\n 跟你說我朋友子瞻，因為跟朝中新法主張不合，自請外放到杭州當通判，等於主動離開了權力中心。那天他跟朋友在西湖上喝酒，一開始大晴天波光粼粼，喝著喝著下起雨，遠山朦朧得別有意境。他忽然覺得，這湖不管晴雨怎麼樣都好看，就像西施不管濃妝淡妝都美。這個比喻一喊出來，杭州人從此把西湖叫西子湖，叫了快一千年。子瞻大概沒想到，他失意離京那年隨口喝酒寫的幾句話，會變成一座城市沿用至今的名字。",
