    "poem_notes": "【字詞與白話】\n 惠崇：北宋初年僧人畫家，工詩善畫，真宗年間前後在世，蘇軾寫這首詩時他已過世約六十年。蔞蒿、蘆芽：河邊野生植物，蔞蒿嫩莖、蘆葦嫩芽都是江南人烹煮河豚湯常用的配菜。\n 白話：竹林外斜斜探出兩三枝桃花，江水回暖，水裡的鴨子最先察覺到春天到了。岸邊蔞蒿長得滿地都是，蘆葦才剛冒出短短的嫩芽，正是河豚要洄游上市的季節。\n \n 【背後的小故事】\n 這是蘇軾替僧人畫家惠崇的畫作題的詩，兩人相差近一甲子，從未謀面，是一場跨越六十年的隔代神交。蘇軾當時剛結束黃州貶謫，那幾年他窮困潦倒，卻迷上了江南時令名產河豚，肉質鮮美卻有劇毒，稍有不慎便會中毒身亡，據說他吃的時候曾說這滋味值得一死。看著畫裡回暖的江水與滿地蔞蒿，他想到的不是筆法多高明，而是熟悉的節氣又到了，河豚要上市了。這份劫後餘生仍惦記著人間美味的踏實感，比任何傷春悲秋都更像蘇軾。",
