    "poem_notes": "【字詞與白話】\n 張三影：張先的別號，因他詞中三句寫影字的名句而得名。梨花壓海棠：梨花色白，喻老者白髮；海棠嬌豔，喻年輕女子，後世借此比喻老夫少妻。\n 白話：十八歲的新娘嫁給八十歲的新郎，滿頭蒼蒼白髮對著一身鮮豔的紅妝。往後鴛鴦被裡雙宿雙飛的夜晚，就像一棵開滿白花的梨樹，壓在了嬌豔的海棠花上頭。\n \n 【背後的小故事】\n 北宋詞人張先以張三影聞名，一生風流，年紀越大反而納妾越年輕，八十歲那年又新納一名十八歲小妾，親友紛紛前來道賀，蘇軾也在場。席間眾人起鬨要蘇軾即興賦詩，他便寫下這幾句，拿梨花與海棠的顏色反差調侃老友，滿座賓客哄堂大笑，張先本人也不以為忤。後人考證這首詩是否真出自蘇軾之手仍有爭議，但這段軼事流傳數百年，梨花壓海棠也漸漸成了形容老夫少妻的慣用語。",
