    "poem_notes": "【字詞與白話】\n 翻墨：像打翻的墨汁一樣，形容烏雲濃黑翻滾。跳珠：像跳動的珍珠，形容雨點又急又大。卷地風：從地面捲起的狂風。\n 白話：濃黑的烏雲像打翻的墨汁一樣翻滾而來，還沒遮住對面的山頭，白色的雨點就已經像跳動的珍珠般紛紛落入船中。一陣狂風忽然捲地而來，把烏雲吹得四散，望湖樓下的湖面，雨後平靜得像天空一樣。\n \n 【背後的小故事】\n 蘇軾因反對王安石新法，自請外放到杭州任通判，這是他難得放鬆的一段時期。這天他與友人在西湖邊的望湖樓喝酒，忽遇一場來得又急又猛的暴雨，雨後湖面卻迅速恢復平靜如鏡。他趁著酒意寫下這場雨的來去，心裡想的其實是自己這幾年在朝爭裡的起落——再凶猛的烏雲，終究會被風吹散，水面終究會重新平靜下來。",
