    "title": "泊船瓜洲",
    "poem_notes": "【字詞與白話】\n 京口：今江蘇鎮江，與瓜洲隔江相望。鐘山：在今南京，王安石罷相後的隱居地。綠：此處作動詞用，使變綠的意思，相傳王安石曾反覆推敲，先後試過到、過、入、滿等字，最後才定為綠字。\n 白話：京口與瓜洲只隔著一條江水，鐘山離這裡也只隔著幾重山，算不上遙遠。春風一吹，江南岸邊想必又是一片新綠了，可是這輪明月，什麼時候才能照著我回到家鄉呢。\n \n 【背後的小故事】\n 王安石因變法罷相，退居金陵鐘山幾年後，被神宗重新召回京城拜相。他從江寧出發北上，途經瓜洲停船過夜，望著江對岸想起只隔數重山的鐘山舊居，寫下這首詩。相傳春風又綠江南岸的綠字，他反覆修改了十幾次，才從到、過、入、滿等字裡選定這個字，只為了寫出江南春天鋪滿眼前的畫面感。整首詩前面在算離家鄉多近，最後一句卻是在問一個他自己也沒有答案的問題，這一去，還回得來嗎。",
