    "title": "登飛來峯",
    "poem_notes": "【字詞與白話】\n 千尋：一尋約八尺，形容塔非常高，是誇張的虛指。聞說：聽人說，不是自己驗證過。浮雲：字面是天上的雲，這裡也暗指讒言與各種阻礙。最高層：指塔的最高一層，也暗指自己所站的高度。\n 白話：飛來峰上有一座高聳入雲的塔，聽人說在這裡雞鳴時分能看到太陽升起。不怕層層浮雲遮住我遠望的視線，只因為我站在最高的一層。\n \n 【背後的小故事】\n 這首詩是王安石二十九歲，任滿鄞縣知縣返京途中，登杭州飛來峰所寫，還沒登上宰相高位、還沒推行變法。他借登高望遠的體悟寫下不畏浮雲，二十年後真正主持熙寧變法，面對滿朝反對聲浪依然堅持己見，提出天變不足畏、人言不足恤，跟這首詩裡的精神一脈相承。年輕時的一次登高，竟成了他一生政治性格的預告。",
