    "poem_notes": "【字詞與白話】\n 屠蘇：一種藥酒，除夕夜喝，據說能辟邪防病。曈曈日：形容剛升起的太陽又亮又溫暖。桃符：掛在門上、用桃木做的驅邪牌，後來演變成春聯。\n 白話：爆竹聲中舊的一年過去了，春風送來暖意，人們喝著屠蘇酒迎新年。初升的太陽照著千家萬戶，家家都取下舊的桃符，換上新的。\n \n 【背後的小故事】\n 這首詩寫在王安石剛開始推行熙寧變法那幾年的新年，總把新桃換舊符表面寫民俗，其實藏著他自己的心聲——他正在做的事，就是把舊的法令制度一項項換成新的。當時反對聲浪已經很大，不少人罵他變亂祖宗成法，但他沒有退讓。這首詩後來變成過年最常被引用的詩之一，人們貼春聯時念著這句話，大多不知道背後站著一位跟整個時代較勁的宰相。",
