    "title": "春日",
    "poem_notes": "【字詞與白話】\n 泗水濱：山東泗水河邊，孔子當年講學之地。朱熹寫這首詩時，泗水一帶早已被金國佔領，他終其一生未曾真正到訪，這趟尋芳其實是想像中的神遊，暗喻求聖人之道。\n 白話：在一個晴朗的好日子裡，我來到泗水河邊尋訪春天的蹤跡，眼前無邊無際的風景一時間全都煥然一新。輕易間就認出了東風的面貌，才明白這漫山遍野萬紫千紅的花色，說到底都是同一個春天。\n \n 【背後的小故事】\n 這首詩表面寫遊春，其實是一首哲理詩。南宋時期，泗水一帶早已淪陷金國，理學家朱熹一輩子沒有機會親自到孔子講學的地方朝聖，只能在某個晴好的日子裡，於書齋窗邊神遊千里之外，想像自己走在泗水河邊。詩裡的東風喻指聖人的教化，萬紫千紅則是他讀過的千經萬典，說到底都通向同一個道理。身不能至，心嚮往之，這首連小孩子都會背的春天詩，藏著一個理學家一輩子去不了故鄉聖地的遺憾。",
