    "poem_notes": "【字詞與白話】\n 子聿：陸游的小兒子。躬行：親自去做、親身實踐。\n 白話：古人做學問沒有一個是輕鬆的，年輕時下的工夫，往往要到年老時才真正有所成就。從書本上得來的知識終究是淺薄的，要真正透徹理解一件事，必須靠自己親身去實踐才行。\n \n 【背後的小故事】\n 陸游一生最大的心願是上戰場收復中原，可惜大半輩子只能在詩裡吶喊。四十八歲那年，他曾在四川南鄭投效軍中幕府四十多天，親自騎馬穿甲、望過前線敵營，是他一輩子唯一一段真正躬行的日子，之後便再無機會回到戰場。七十五歲那年冬夜，他把這句得來不易的體悟寫下來教給小兒子子聿，書上讀來的東西終究是淺的，真正弄懂一件事，要靠自己做過才算數。這既是家訓，也是他對自己一生只能在紙上打仗的遺憾與提醒。",
