    "title": "小池",
    "poem_notes": "【字詞與白話】\n 惜細流：捨不得讓水流得太快太急，形容泉水流量細小的樣子。晴柔：晴天裡柔和的光影。\n 白話：泉眼悄悄地滲出細細的水流，好像捨不得讓水流走。樹蔭倒映在水面上，也彷彿喜愛這晴天裡柔和的光線。一片小荷葉才剛剛捲起、露出尖尖的一角，就已經有一隻蜻蜓穩穩地停在了上頭。\n \n 【背後的小故事】\n 楊萬里早年學江西詩派，講究字字有來歷、句句要用典，寫了一千多首這樣的詩，後來忽然覺得不對勁，把這些舊稿一把火全燒了，重新學著寫詩，這次他不再往書本裡找材料，改往自家院子裡找。有一年初夏，他蹲在自家小池邊，看見一片剛冒尖的荷葉，一隻蜻蜓不知何時已經搶先穩穩停在了那個尖角上頭。這個瞬間什麼典故都用不上，卻讓他捨不得移開眼睛，於是原封不動地寫成了這首詩，成了他自成一家誠齋體最動人的代表作之一。",
