    "title": "遊園不值",
    "poem_notes": "【字詞與白話】\n 屐齒：木屐鞋底的齒紋，這裡指走在青苔上留下的鞋印。柴扉：柴門，指簡樸的門扉。\n 白話：大概是主人捨不得讓人的木屐踩壞了滿地的青苔，我輕輕敲了好幾下柴門，等了很久也沒人來開。滿園的春色終究是關不住的，你看，已經有一枝紅色的杏花探出牆頭來了。\n \n 【背後的小故事】\n 葉紹翁生平史料不多，連本姓李、後來過繼給葉家的身世都是後人拼湊而來。相傳這首詩寫的是他去拜訪一位深居簡出的朋友，敲門許久沒有回應，他猜想主人大概是存心不想被打擾，正準備失落地轉身離開，卻在牆頭看見一枝紅杏探出牆外。他站在原地把這個念頭寫成詩，關得住一扇門，卻關不住整個春天。這首因為吃了閉門羹而寫成的詩，流傳了八百多年，後人大多不記得他那天有沒有見到朋友，只記得那枝越牆而出的紅杏。",
