    "poem_notes": "【字詞與白話】\n 若等閒：好像很平常、不當一回事的樣子。清白：字面指石灰的潔白，也雙關做人的清廉高潔。\n 白話：石灰石經過千萬次錘打鑿挖才從深山裡開採出來，就算被烈火焚燒，也像是件稀鬆平常的事。哪怕粉身碎骨也毫不畏懼，為的就是要把一片清白留在人間。\n \n 【背後的小故事】\n 相傳這首詩是于謙十二歲時所作，當時他跟著大人去看石灰窯燒石灰，看著石頭經過千錘萬鑿、烈火焚燒才變成潔白的石灰粉，寫下這幾句少年豪語，旁人只當是孩子口氣大。誰也沒想到，四十多年後，土木堡之變皇帝被俘、朝廷主張南逃之際，正是于謙力主堅守北京，擁立新君，擋住瓦剌大軍保住了大明江山。後來他卻在政變中被誣陷處死，抄家時家中除了皇帝賜的蟒袍寶劍，幾乎一貧如洗。少年時隨口寫下的清白二字，他用一輩子兌現成了事實。",
