    "poem_notes": "【字詞與白話】\n 通謁：遞名帖求見。名紙：寫了姓名的拜年帖。敝廬：自稱自己家的謙詞。世情嫌簡不嫌虛：人情世故裡，大家嫌你禮數不夠周到，卻不嫌你虛情假意。\n 白話：不要求真的見面，只靠遞名帖來往；一早名帖就堆滿了我這簡陋的屋子。我也跟著大家一樣送出幾張名帖——世俗人情，寧可嫌你禮數簡略，也不會嫌你虛情假意。\n \n 【背後的小故事】\n 文徵明是明代蘇州著名的書畫家、文人，晚年名滿江南，登門求字的人絡繹不絕。相傳新年期間，蘇州士紳流行只送名帖不見面拜年的風氣，徵明看穿這種禮數的虛偽，卻仍隨俗投帖——他寫下這首詩，把自己也放進了諷刺對象裡，誠實地承認：看穿一件事的空洞，不代表就能拒絕跟著大家一起做。",
