    "poem_notes": "【字詞與白話】\n 咬定：像用牙齒咬住一樣,形容扎根扎得極其牢固不放鬆。任爾：任憑你。\n 白話：緊緊咬住青山不放鬆,根早已深深扎進破碎的岩石縫裡。經歷了千萬次的磨難打擊,依然堅韌強勁,任憑你從東西南北哪個方向刮來的風,都吹它不倒。\n \n 【背後的小故事】\n 這是鄭板橋(鄭燮)在濰縣當知縣時的心境寫照。當地遇上大饑荒,他不等公文批覆就先開倉放糧救民,卻因此得罪上級,最終被彈劾罷官。相傳彈劾消息傳來那天,他看著衙門後院石縫裡長出的一叢竹子,提筆畫下這幅竹石圖並題詩明志。罷官後他靠賣畫維生,晚年畫的竹子反而比在任時更挺拔——千磨萬擊還堅勁,是他自己一生的寫照,也是所有被打壓過卻不肯低頭的人的心聲。",
