    "title": "己亥雜詩-其五",
    "poem_notes": "【字詞與白話】\n 吟鞭：詩人手裡的馬鞭，這裡代指他離京遠行的動作。落紅：落花，這裡不是單純寫景，是他自比辭官離場的自己。\n 白話：滿懷的離愁在夕陽斜照下更顯浩蕩，馬鞭一指向東，便是天涯遠行的方向。飄落的花瓣並不是無情之物，它們化作春天的泥土，反而更能護持來年綻放的花朵。\n \n 【背後的小故事】\n 跟你說我朋友定盦，在北京做了大半輩子不得志的官，四十八歲那年終於辭官南歸，一句落紅不是無情物，就寫在離京路上看見落花的那一刻。巧的是，同一年他的好友林則徐正南下廣州查禁鴉片，定盦臨行前還寫信替他打氣出主意，這份交情史書上有記載。定盦兩年後就過世了，沒能等到任何一場真正的變法；可是幾十年後，康有為梁啟超這一輩人重新翻出他的文章當作養分。他說中了自己，落花沒有白落，真的變成了土。",
    "zhuyin": "斜(ㄒㄧㄚˊ)(xié)發音同\"峽\"，在古音與詩韻中常讀作ㄒㄧㄚˊ，與下句的「涯」字押韻。",
