    "poem_notes": "【字詞與白話】\n 紙鳶：風箏。這首詩寫的是一位清代鄉間老師觀察孩童放學後放風箏的尋常一景，全詩沒有一句直接抒情。\n 白話：二月天氣裡，青草漸長、黃鶯飛舞，堤岸邊的楊柳在春天的煙靄中輕輕搖曳，彷彿沉醉一般。孩子們放學回家得早，趁著東風正好，忙著把風箏放上天空。\n \n 【背後的小故事】\n 高鼎是清代一位普通的鄉間教書先生，這首詩寫的是他某個初春午後，站在家門口看著放學的孩子們奔向河堤放風箏的畫面——楊柳新綠、東風正好，孩子們滿心只擔心風箏飛不飛得起來，沒有絲毫大人的煩惱。他想起自己也曾這樣天真無憂地奔跑過，如今這種心無罣礙的快樂，是那些正在長大的孩子終將失去、而他自己早已回不去的東西。全詩沒有一句感嘆，只是把畫面老實寫下，讓景色自己說出那份對逝去童年的懷念。",
