    "poem_notes": "【字詞與白話】\n 牧童：放牛牧羊的孩子，此處象徵不知歷史為何物的後人。順風吹起烏江水：字面寫江風，實則暗指當年虞姬與項羽訣別的悲聲彷彿還留在風裡。\n 白話：九里山前曾是古代的戰場，放牛的孩子如今還能在土裡撿到當年遺落的舊刀槍。江風順著烏江水吹來，那聲音聽起來，竟像極了當年虞姬向霸王訣別時的哭聲。\n \n 【背後的小故事】\n 跟你說這首古謠講的是項羽人生最後一夜的事，後來被水滸傳引用。項羽被漢軍圍在垓下，四面楚歌之下軍心徹底崩潰，他與虞姬最後喝了一場訣別酒，相傳虞姬當場自盡，不願拖累他突圍。項羽逃到烏江邊，船夫願意渡他回江東東山再起，他卻覺得無顏面對江東父老，拒絕渡江，力戰而死。多年後，九里山前的舊戰場只剩放牛孩子撿到生鏽的舊兵器，沒人記得那曾是誰的刀。曾經天下第一的強者，最後只留下一把連撿到的孩子都不認得主人的舊刀。",
