    "poem_notes": "【字詞與白話】\n 穹廬：遊牧民族居住的圓頂氈帳，也就是蒙古包，這裡用來比喻天空像一頂罩住四野的大帳篷。見：讀作現，顯露、露出來的意思，不是看見的見。\n 白話：敕勒族生活的大草原，就在陰山腳下。天空像一頂巨大的氈帳，把四面的原野整個籠罩住。天空蒼蒼茫茫，草原也蒼蒼茫茫，風一吹過，牧草伏低下去，藏在草叢裡的牛羊便顯露了出來。\n \n 【背後的小故事】\n 跟你說這首歌背後有一場真實的敗仗。公元五四六年，東魏大將高歡圍攻玉壁城慘敗，軍中甚至謠傳他已經戰死，軍心眼看就要崩潰。高歡抱病硬撐著在軍前露面，還讓敕勒族出身的大將斛律金當眾高唱這首敕勒族世代傳唱的草原老歌。士兵聽著聽著，想起了各自家鄉的草原和牛羊，相傳高歡自己也跟著唱到落淚，軍心竟因此穩住。一千五百年後，沒人記得那場仗打得多慘，這首歌卻留在課本裡，被一代代孩子背誦，沒人知道它當年其實是一支軍隊的救命藥。",
    "zhuyin": "敕勒(ㄔˋ ㄌㄜˋ)(chì lè)發音同\"赤?\"，中國北方的種族之一。\n 穹(ㄑㄩㄥˊ)(qióng)發音同\"窮\"，天空。",
