    "type": "詞",
    "author": "王勃",
    "title": "滕王閣序-僅節錄佳句",
    "poem_notes": "【字詞與白話】\n 「落霞與孤鶩齊飛，秋水共長天一色」是全篇最著名的兩句，出自王勃二十六歲時的即席之作。\n 白話：（節錄）這裡是豫章的舊郡、洪都的新府，物產豐美、天生珍寶……時運有時不順，命運多有坎坷，但年紀越大志氣應當越壯，怎能因白髮而改變壯志？處境越是艱困，意志應當越堅定，不能墜失淩雲的志向……晚霞與孤飛的野鴨一同飛翔，秋水與遼闊的長天連成一片顏色……閣中當年的皇子如今在何處？只剩欄杆外的長江獨自流淌。\n \n 【背後的小故事】\n 王勃因罪被革職，南下探望被貶謫的父親途中，路過南昌，正逢都督閻伯嶼在滕王閣設宴，原本安排讓女婿當場展現文采作序，王勃卻爽快應允代筆，讓閻伯嶼氣得離席。隨著僕人一句句回報寫作進度，閻伯嶼的態度從冷笑漸漸轉為震驚，最終親自衝回宴席，見到「落霞與孤鶩齊飛，秋水共長天一色」時忍不住讚嘆「此真天才，當垂不朽矣」。這場即興演出成了王勃一生最耀眼的高光時刻——隔年他南下探父後渡海北歸，卻不幸溺水身亡，年僅二十六歲，這篇序文成了他留給後世最重要的遺產。",
    "zhuyin": "鶩(ㄨˋ)(wù)發音同\"物\"，鳥類中的游禽類。俗稱為「野鴨」。\n 蠡(ㄌㄧˇ)(lí)發音同\"理\"，彭蠡-湖泊名。在江西省北境，長江以南。即今鄱陽湖。\n 舛(ㄔㄨㄢˇ)(chuǎn)發音同\"喘\"，不順利、困厄。\n 隅(ㄩˊ)(yú)發音同\"魚\"，東隅-東方日出之地。亦指早晨。\n 榆(ㄩˊ)(yú)發音同\"魚\"，桑榆-桑樹及榆樹。日落時陽光照在桑榆間，因借指傍晚。又比喻人的晚年。\n 猖(ㄔㄤ)(chāng)發音同\"昌\"，狂妄橫行、不加約束。\n 纓(ㄧㄥ)(yīng)發音同\"英\"，請纓-比喻自請從軍。\n 愨(ㄑㄩㄝˋ)(què)發音同\"確\"，忠愨-忠誠敬謹。\n 筵(ㄧㄢˊ)(yán)發音同\"言\"，酒席、宴席。\n 梓(ㄗˇ)(zǐ)發音同\"子\"，梓澤-晉 石崇 別墅金谷園的別稱。故址在今河南省孟縣境。\n 墟(ㄒㄩ)(xū)發音同\"虛\"，荒廢的城市。",
