    "title": "清平樂-畫堂晨起",
    "poem_notes": "【字詞與白話】\n 佳瑞：美好的徵兆，這裡指瑞雪，古人認為下雪是豐年的吉兆。天仙狂醉：把眼前雪景想像成天上仙人喝醉了酒，隨手揉碎白雲灑落人間。\n 白話：清晨在畫堂裡醒來，有人來稟報說外頭下雪了。他撐起身子把簾子高高捲起觀看這美好的徵兆，只見潔白的雪光遠遠鋪滿了庭院台階。爐火燒得正旺，煙氣被雪映得格外明亮；結霜的草叢泛著清冷微光，如玉佩一般。這光景，應該是天上的仙人昨夜喝醉了酒，隨手把白雲揉碎灑落下來的吧。\n \n 【背後的小故事】\n 跟你說我朋友太白剛到長安那幾年，被前輩賀知章讀完蜀道難後一句謫仙人定了終生外號，說他根本不像凡人。相傳這首清平樂就寫在他風頭正盛時的一個雪天早晨，他看著滿院瑞雪，想像那是天上仙人醉酒後隨手揉碎白雲灑下人間。這首詞後世學者一直有爭論是不是真的出自他手，畢竟詞這種文體那時才剛起步。但不管真假，這種把雪想像成仙人鬧脾氣的浪漫勁，怎麼看都像那個被封了一輩子謫仙人的男人才寫得出來。",
    "zhuyin": "櫳(ㄌㄨㄥˊ)(lóng)，窗戶、窗牖。\n 揉(ㄖㄡˊ)(róu)發音同\"柔\"，反覆摩擦、搓動。",
