    "title": "菩薩蠻",
    "poem_notes": "【字詞與白話】\n 漠漠：形容煙霧或原野一片迷濛廣闊的樣子。玉階：玉石砌成的臺階,泛指精美的樓臺台階。歸程：回家的路程。\n 白話：平坦的樹林一片迷濛,暮煙籠罩得像織布一樣密。遠山連綿一片,藍得讓人心裡發疼。夜色漸漸爬上高樓,樓上有人正在發愁。她久久站在玉石台階上等待,歸巢的鳥兒急急忙忙飛過。回家的路到底在哪裡呢?一程接一程的長亭,一程接一程的短亭,望不到盡頭。\n \n 【背後的小故事】\n 這首詞的作者是誰,連學者都吵了上千年——它掛著李白的名字流傳下來,可是盛唐時期詞這種文體理論上還沒真正成熟,很多人懷疑是後人假托太白之名寫成,真正身世至今仍是懸案。無論作者是誰,詞裡那個在高樓上等人等到絕望的畫面卻打動了千百年來的讀者。\"何處是歸程,長亭更短亭\"寫的不是地理距離,是每一個異鄉遊子心裡數著驛站、盼著回家的焦灼,這份心情不管作者是不是李白,都是真的。",
