    "poem_notes": "【字詞與白話】\n 咽：嗚咽,形容聲音低沉悲切。音塵絕：音信與蹤跡都斷絕了。陵闕：帝王的陵墓與宮闕。\n 白話：一縷簫聲嗚咽響起,秦娥從夢中驚醒,望著曾經照過秦樓的月亮出神。年年柳色依舊,年年都在灞陵橋頭上演離別。樂遊原上正逢清秋的節日,遊人如織;可是通往咸陽的古道上,音信與蹤跡卻早已斷絕。西邊的風吹著,照著落日的殘光,漢代帝王的陵墓宮闕,空盪盪地立在那裡。\n \n 【背後的小故事】\n 這首詞跟同樣掛在李白名下的菩薩蠻並稱\"百代詞曲之祖\",可是身世同樣成謎——一首詞從兒女私情寫起,幾句話之後鏡頭忽然拉遠到整個王朝的興衰廢墟,轉折之大讓不少學者懷疑它其實是中晚唐人假托太白之名所作。灞陵折柳送別是長安人的習俗,樂遊原是當時的遊覽勝地,詞裡把兒女相思跟帝國衰亡疊在一起,不管出自誰手,那句\"西風殘照,漢家陵闕\"從此變成後世形容繁華落盡最經典的畫面。",
    "zhuyin": "咽(ㄧㄝˋ)(yàn)發音同\"夜\"，聲音悲淒滯塞。\n 咸(ㄒㄧㄢˊ)(xián)發音同\"賢\"，陽 秦朝的首都，位於今陝西省長安市東北。\n 闕(ㄑㄩㄝˋ)(què)發音同\"確\"，泛指帝王居住的地方。",
