    "poem_notes": "【字詞與白話】\n 柏梁：指漢武帝所建的柏梁台，以香柏木為梁柱，是漢代長安著名建築。孀雌：指失去配偶的母燕。寸心：心裡極小卻極深的痛處。\n 白話：一對燕子成雙成對地飛，讓人羨慕；牠們本住在華麗樓閣裡，金窗繡戶，長相廝守。柏梁台失火之後牠們逃到吳王宮，吳宮後來也被燒毀，雛燕跟著巢一起沒了。如今只剩憔悴的母燕獨自留下，想著死去的伴侶，雙飛的日子再也回不來，這件事讓我心裡也隱隱作痛。\n \n 【背後的小故事】\n 雙燕離是漢代就有的樂府舊題，李白借用這個老故事，寫一對燕子接連遭遇兩場大火，最後喪偶失雛的悲劇。相傳這首詩可能寫於他晚年因永王璡事件下獄、流放夜郎的顛沛歲月，也有人認為是他年少時的仿古習作，具體年代難以確考。無論哪個時期，最後那句忽然跳出來的傷我寸心中，讓人感覺這隻不斷躲禍卻躲不掉災難的燕子，寄託的其實是李白自己一生輾轉流離的心境。",
