    "poem_notes": "【字詞與白話】\n 諳：熟悉。江花：江邊的花。勝：勝過。\n 白話：江南真好,那裡的風景我從前就很熟悉。太陽出來的時候,江邊的花紅得勝過火焰;春天來臨,江水綠得像藍草染出的顏色。這樣的地方,叫人怎麼能不想念呢?\n \n 【背後的小故事】\n 白居易年輕時沒到過江南做官,真正跟江南結緣是五十歲以後,他先後當過杭州刺史、蘇州刺史,主持修堤治水,走遍了當地的河道園林。晚年他定居洛陽,跟老友劉禹錫比鄰而居,兩人常聊起江南舊事,索性各自填起同一個詞牌互相唱和。這首詞開頭就是斬釘截鐵的三個字\"江南好\",接著用紅花配綠水兩種最鮮明的顏色,把記憶中的江南寫得比眼前更真實。人已經離開幾千里、幾十年,顏色卻一點都沒褪色。",
    "zhuyin": "諳(ㄢ)(ān)發音同\"安\"，熟悉、知曉。",
