    "poem_notes": "【字詞與白話】\n 全詩沒有一個具體名詞，白居易終生沒解釋這首詩在寫什麼，因此後世有多種揣測。\n 白話：不是花，也不是霧，半夜到來，天亮就離去。來的時候像春夢一樣不知有多久，走的時候像早晨的雲，怎麼找也找不到。\n \n 【背後的小故事】\n 白居易一生寫詩超過三千首，這首卻只有二十六個字，而且到死都沒說過在寫什麼。有人說是寫他年輕時被迫分開的戀人湘靈，有人說是悼念早夭的鄰家女孩簡簡，也有人說寫的是所有抓不住的東西——青春、愛情、盛世。正因為他從不解釋，每個讀者才能把自己失去過的東西填進去。這首詩後來被三十幾位現代作曲家譜成曲，因為它短、抽象又充滿意境，像極了今天的失戀情歌。",
