    "title": "漁歌子-西塞山前白鷺飛",
    "poem_notes": "【字詞與白話】\n 西塞山：地名,在今浙江湖州一帶。箬笠：用箬竹葉編成的斗笠。不須歸：不必回去,指不想回朝廷做官。\n 白話：西塞山前白鷺展翅飛過,桃花花瓣落進水裡隨波漂流,水裡的鱖魚長得肥美。我頭戴青色的箬笠,身披綠色的蓑衣,任憑斜風細雨打在身上,也不必急著回去。\n \n 【背後的小故事】\n 張志和年輕時很風光,十六歲中舉,連名字都是唐肅宗親自賜的,後來卻因故被貶官,從此心灰意冷,乾脆買條船在江湖上漂,自稱煙波釣徒。他跟書法家顏真卿是朋友,顏真卿當湖州刺史時見他的船破舊漏水,想幫他換一艘新船,張志和婉拒了,寫下這首詞回應。詞裡的白鷺、桃花、鱖魚、箬笠、蓑衣全是眼前實景,一句\"斜風細雨不須歸\"看似寫垂釣,其實是回答所有勸他回朝廷做官的人——他不想回去了。",
    "zhuyin": "鱖(ㄍㄨㄟˋ)(guì)發音同\"貴\"，又音(ㄐㄩㄝˊ)(yòu yīn)發音同\"絕\"，魚綱鱸科。體側扁，顏色淡黃帶褐，具不規則的黑色斑紋。口大有細鱗，背鰭具硬棘，為凶猛的魚類。喜食魚蝦，大陸地區各大河流、湖泊均產。肉質鮮嫩美味，為淡水食用魚類之一。\n 箬(ㄖㄨㄛˋ)(ruò)發音同\"若\"，竹皮。「篛」的本字。\n 笠(ㄌㄧˋ)(lì)發音同\"力\"，用竹皮或竹葉編成，可以擋雨遮陽的帽子。\n 蓑(ㄙㄨㄛ)(suō)發音同\"縮\"，用草或棕櫚葉做成的雨具。",
