    "poem_notes": "【字詞與白話】\n 斜橋：橋名,或泛指彎斜的小橋。紅袖：指歌伎、女子,代指樓上招手的美人。翠屏金屈曲：畫著金色花紋、可以折疊的翠綠色屏風。\n 白話：現在回想起來,才覺得當年在江南的日子真是快樂,那時候年紀輕,穿的春衫都還很單薄。騎著馬倚靠在斜橋邊,滿樓的美人探頭向我招手。畫著金色花紋的翠綠屏風後面,喝醉了就地睡下。如今再次看見花開,我發誓白了頭也不再回去了。\n \n 【背後的小故事】\n 韋莊年輕時經歷了黃巢之亂,親眼見過長安城破的慘狀,後來寫下著名長詩秦婦吟。戰亂之後他一路南逃,在江南漂泊多年,靠朋友接濟過著相對浮華的日子,這首詞回憶的就是那段時光。晚年中原持續戰亂,故鄉音信斷絕,他輾轉入蜀投靠割據政權,最終在成都當上宰相,終究沒能再回中原。\"此度見花枝,白頭誓不歸\"表面說的是江南舊事,骨子裡其實是他跟回不去的故鄉徹底道別的一句誓言。",
