    "poem_notes": "【字詞與白話】\n 樽前：酒杯之前,指酒席上。呵呵：笑聲,這裡形容勉強擠出的笑。能幾何：能有多少,指人生短暫。\n 白話：勸你今晚一定要痛快喝醉,不要在酒杯前談論明天的事。承蒙主人一片心意,大家要好好珍惜這份情誼,酒喝得深,情意也深。不要愁著更漏聲短、天快亮了,也別推辭酒杯已經斟得太滿。遇到酒就開懷笑一笑吧,人生能有多少歲月呢?\n \n 【背後的小故事】\n 這是韋莊菩薩蠻組詞的第四首,寫作背景跟前一首一樣,是他親歷黃巢之亂、見過長安淪陷慘狀之後的心境。從一個看過盛世崩塌的人嘴裡說出\"今夜須沉醉,莫話明朝事\",分量跟一般的及時行樂完全不同——明天從來不是理所當然會到來的東西。\"遇酒且呵呵\"這句的笑聲聽起來很輕,底下卻藏著不敢說出口的憂慮,整組詞寫到這裡,追憶江南舊夢和勸人及時行樂,說穿了都是同一種亂世裡抓不住明天的心情。",
