    "poem_notes": "【字詞與白話】\n 才子他鄉老：指自己客居異鄉，漸漸老去。魏王堤：洛陽城外一處種滿柳樹的著名堤岸。淥：形容水清澈。殘暉：快要落盡的夕陽餘光。\n 白話：洛陽城裡春光正好，可洛陽的才子卻在異鄉漸漸老去。魏王堤上柳色深暗，這時候心裡一片迷惘。桃花落在清澈的春水裡，水面上一對鴛鴦正在戲水。我望著殘餘的夕陽，滿心怨恨，想念的人，卻不知道我在想她。\n \n 【背後的小故事】\n 韋莊早年經歷黃巢之亂，四處流離，後半生入蜀輔佐前蜀政權，終老異鄉。相傳他青年時在洛陽一帶，曾與一位女子有過情意，後來這位女子被前蜀王建強行奪走，韋莊終生未能再見到她——這段往事正史沒有確切記載，只是流傳已久的說法。他晚年寫的這組菩薩蠻詞，反覆出現的那種欲言又止的怨懟，讀來確實比單純的思鄉之情更深一層。",
