    "poem_notes": "【字詞與白話】\n 謝娘：唐五代詞中常見的女子代稱，這裡指韋莊年輕時相識、相傳有過感情的一名女子。音塵：音訊消息。異鄉人：不是單純指身在異鄉，這裡暗示兩人都被迫困在各自的處境裡，回不去也見不到。\n \n 白話：記得那一年在花下，深夜裡，第一次認識謝娘的時候。水堂西面的畫簾低垂，兩人牽著手，暗自約定以後要再見面。後來在殘月將盡、曉鶯啼叫時分惆悵地分別，從此音訊斷絕。如今兩人都成了異鄉人，想再見面，卻找不到任何機會。\n \n 【背後的小故事】\n 韋莊年輕時在長安相傳結識過一位名叫謝娘的女子，兩人有過短暫而深刻的情意。後來韋莊歷經黃巢之亂，一路輾轉入蜀，投靠王建，官至宰相，晚年生活相對安穩。但相傳他念念不忘的這位女子，後來也流落蜀地，甚至有一說被王建強行收入身邊，韋莊終其一生都沒能再見到她。這件事真假難以完全考證，但韋莊詞集裡反覆出現類似的心事，讓如今俱是異鄉人，相見更無因這句話，讀來格外沉重。",
