    "poem_notes": "【字詞與白話】\n 臨春：南朝陳後主為寵妃張麗華所建的著名奢華閣名，南唐沿用這個名字。霓裳：唐代宮廷樂曲霓裳羽衣曲。魚貫列：形容宮女一個接一個排隊而立。\n 白話：清晨剛梳妝完的宮女，肌膚在燈下白得像雪，春殿裡一個接一個排列而立。笙簫的樂聲響徹雲霄，重新演奏起霓裳曲，唱得一字不漏。臨春閣裡誰家的香粉飄得最遠？我喝得半醉，拍打欄杆，情意濃得說不完。回去時不要點紅燭，我要踩著月光慢慢走回去。\n \n 【背後的小故事】\n 這首詞描寫南唐宮廷一場通宵的豪奢夜宴，臨春這個閣名，借用的正是一百多年前南朝陳後主為寵妃蓋的名閣——那位陳後主因為夜夜歌舞荒廢朝政，最後亡國被俘。李煜當時大概沒有想太多，只覺得這名字風雅氣派，可日後南唐同樣被宋朝攻滅，他本人也被押往汴京當了幾年俘虜，才客死異鄉。一場寫盛世繁華的詞，回頭看竟像一則提早寫好的預言。",
