    "author": "李煜",
    "title": "菩薩蠻·花明月暗籠輕霧",
    "poem_notes": "【字詞與白話】\n 剗襪：光著腳只穿襪子走路，不穿鞋是為了不出聲。香階：宮中鋪著香氣的石階。金縷鞋：繡了金線的鞋子。奴：古代女子自稱的謙詞。\n 白話：花色明亮，月色卻昏暗，籠著一層薄霧，今晚正好去情郎那邊。我光著襪子走過香階，手裡提著繡金線的鞋子。在畫堂南邊見到了他，一靠近就緊緊依偎著他，抖得厲害。我出來一趟太不容易了，今晚就任你盡情憐愛。\n \n 【背後的小故事】\n 相傳這首詞寫的是李煜與正妻大周后的妹妹——後來的小周后——之間的一段秘密戀情。大周后臥病期間，妹妹常常入宮探病照顧姊姊，卻與李煜漸生情意。這段往事正史沒有詳細記載，只留下這樣的傳聞輪廓。詞中用女子的口吻，寫她赤足提鞋、冒險赴約的緊張與依戀，寫得極為細膩。大周后過世後，李煜正式立這位妹妹為后，兩人後來一起經歷了南唐覆滅、被俘北上的患難歲月。",
