    "title": "虞美人-春花秋月何時了",
    "poem_notes": "【字詞與白話】\n 全詞寫於李煜亡國被俘、囚居汴京第三年，這也是他四十二歲生日兼七夕節當晚寫下的絕命詞。\n 白話：春花秋月要到什麼時候才會終了呢？過往的事又還記得多少。小樓昨夜又吹起了東風，在明月中回想故國，實在讓人不忍。精雕的欄杆、玉砌的台階應該都還在，只是我的容顏已經蒼老。若問我心中能有多少愁，就像一整條春江之水，向東奔流不盡。\n \n 【背後的小故事】\n 南唐後主李煜亡國後被押往汴京，過著俘虜般的囚禁生活。這首詞寫於他四十二歲生日兼七夕之夜，他望著故國方向，想起舊時宮殿的雕欄玉砌，只嘆自己容顏已改、江山已失，把滿腔亡國之痛化為一句「恰似一江春水向東流」。宋太宗聽聞這首詞後，認為其中「故國不堪回首」等句暗藏復國之心，當夜便下令將他毒死——他的生日，成了他的忌日。李煜當皇帝並不成功，寫詞卻寫得比誰都真，從此「愁」有了可以丈量的樣子。",
