    "author": "李煜",
    "title": "浪淘沙令-簾外雨潺潺",
    "poem_notes": "【字詞與白話】\n 羅衾：絲綢做的被子，南方常用的輕薄被子，在寒冷的北方汴京完全不夠禦寒。一晌：片刻、短暫的一段時間。\n 白話：簾外傳來淅淅瀝瀝的雨聲，春意已將消逝，絲綢被子擋不住五更天的寒意。夢裡渾然忘記自己如今是客居異鄉的階下囚，只顧貪戀那片刻的歡愉。獨自一人千萬別去倚著欄杆眺望，那無邊無際的故國江山，離開它的時候那麼容易，如今想再見一面卻難上加難。流水帶走落花，春天就這樣過去了，一邊是回不去的天上，一邊是身處的人間。\n \n 【背後的小故事】\n 跟你說我朋友重光，原是南唐皇帝，九七五年亡國被俘到宋朝京城汴京，還被賜了個羞辱性的封號叫違命侯。汴京冬天比他熟悉的江南冷得多，他從前用慣的絲綢薄被完全擋不住這裡的寒氣，每天快天亮就會被凍醒。夢裡他偶爾能騙過自己，恍惚以為還是從前那個可以隨意享樂的人；可是一清醒，眼前只有回不去的江山和過不完的餘生。這一年他還活著，離那杯真正要他命的毒酒，還有一點點時間。",
    "zhuyin": "潺(ㄔㄢˊ)(chán)發音同\"纏\"，形容流水聲。\n 衾(ㄑㄧㄣ)(qīn)，大被子。\n 晌(ㄕㄤˇ)(shǎng)發音同\"賞\"，一會兒、片刻的時間。",
