    "title": "相見歡-無言獨上西樓",
    "poem_notes": "【字詞與白話】\n 西樓：泛指樓閣，並非確指某座特定的樓，古詩詞裡常用來營造孤寂登高望遠的情境。別是一般：另外是一種，般是量詞種的意思，不是一般般普通的意思。\n 白話：一句話也沒說，獨自登上西邊的樓閣，天上一彎新月像鉤子一樣掛著。梧桐樹寂寞地立在深深的庭院裡，把清冷的秋色鎖在院中。心裡那團愁緒剪也剪不斷，越想理清反而更加雜亂，這就是離別的愁緒；可是這感覺，又跟一般的離愁不太一樣，自成一種說不出的滋味，只能悶在心頭。\n \n 【背後的小故事】\n 跟你說我朋友重光，亡國被俘到汴京之後，有一種心事連他自己都找不到準確的字形容，他失去的不是一個人，是一整個曾經完全屬於他的世界，江山、宮殿、過去三十幾年的人生，一次性全沒了，這種話跟誰說都顯得矯情。有天晚上他一句話沒說，獨自走上西樓，看著一彎細月、一院深秋，心裡的情緒纏成一團理不清。他把這種說不出名字的滋味寫下來，讓千年後同樣說不出心事的讀者，都能在他的西樓找到共鳴。",
