    "poem_notes": "【字詞與白話】\n 胭脂淚：被雨打落的紅花，看起來像女子哭花的胭脂妝，也暗指詞中人的眼淚。相留醉：想留住春光，只能借酒消愁。長恨水長東：人生的遺憾像江水一樣，只會向東流去，不會回頭。\n 白話：林花的春紅凋謝得太快太匆忙，禁不起早上的寒雨、晚上的冷風。那被打落的花瓣像是誰哭花的胭脂淚，想留住春光，只能一醉解愁，不知何時才能再相見。人生的遺憾啊，就像這向東流去的江水，一去不回。\n \n 【背後的小故事】\n 李煜降宋後被封為違命侯，軟禁在汴京。相傳他的妻子小周后常被召入宮中，一去數日，回來時常哭泣。這闋詞裡胭脂淚、相留醉、幾時重，寫的可能就是這樣的夜晚——曾經是皇帝的他，如今連留住身邊的人都做不到。雨打落花，像極了她哭花的妝。兩年後的七夕，他死於宋太宗賜下的毒酒。",
