    "poem_notes": "【字詞與白話】\n 沈腰潘鬢：借南朝沈約清瘦、西晉潘岳早生白髮的典故，形容自己這些年被折磨得又瘦又老。教坊：宮廷樂舞機構。倉皇：匆忙慌亂。\n 白話：四十年來的家國基業，三千里的錦繡山河，巍峨的宮殿連著雲霄，珍貴的花木繞著宮牆，我幾乎從未見識過真正的戰爭。誰知一旦成了亡國的俘虜，身形消瘦、鬢髮早白。最狼狽的是辭別祖廟那天，教坊裡竟然還奏起送別的曲子，我望著宮女們，忍不住掉下眼淚。\n \n 【背後的小故事】\n 九七五年南唐滅亡，李煜肉袒出城投降。史書記載他辭廟出降時倉皇失措，教坊樂工仍奏著離別曲，他看著身邊宮女落淚。後來蘇軾讀到這闋詞，批評他該在祖廟前痛哭謝罪百姓，而不是為宮娥掉淚。這句評語罵得有理，卻也說中了他的本質——他從來不是扛得起社稷的皇帝，只是一個連亡國那一刻都無法掩飾真實情緒的普通人。",
