    "poem_notes": "【字詞與白話】\n 銷魂：悲傷到極點，彷彿魂魄要離開身體。故國：已經滅亡的南唐，即金陵。長記秋晴望：一直記得那年秋天天氣晴朗時登高遠望的情景。\n 白話：人生的憂愁怨恨哪能避免，唯獨我傷心到魂魄彷彿要離開身體，情思沒有窮盡。夢裡又回到了故國，醒來時眼淚已經流了滿臉。那座曾經一起登高的高樓，如今還有誰能陪我一起上去呢，我一直記得那年秋天天氣晴朗時遠望的情景。往事都已經成空，回頭一看，竟像做了一場夢。\n \n 【背後的小故事】\n 李煜降宋後被軟禁在汴京，舊臣不得探望，行動處處受限。他撐得住白天，卻控制不了晚上的夢，夢裡總是回到金陵那座熟悉的高樓，醒來才發現江南早已不是他的。人不會因為哭過一次就不再想家，這正是最折磨人的地方：不是絕望，而是每天早上都要重新抱一次希望，再親手把它捏碎一次。",
