    "poem_notes": "【字詞與白話】\n 嬋娟：指月亮。這闋詞寫於蘇軾四十一歲，與弟弟蘇轍已七年未見的中秋夜。\n 白話：明月從什麼時候開始有的呢？我舉杯遙問青天。不知天上的宮殿，今晚是哪一年。我想乘風歸去，卻又怕瓊樓玉宇太高太冷。不如在人間起舞，看著自己的清影。月光轉過朱紅樓閣，低照著雕花窗戶，照著無法入眠的人。月亮不該對人有什麼怨恨，為何總在人們分別時特別圓？人有悲歡離合，月有陰晴圓缺，自古以來這種事就難以兩全。只願我們都平安長久，即使相隔千里，也能共賞同一輪明月。\n \n 【背後的小故事】\n 蘇軾與弟弟蘇轍感情極深，仕途卻讓兩人長年分隔。這年中秋，蘇軾在密州當太守，已經七年沒見到弟弟，那晚他喝得大醉，對月起舞，忽然明白：天上再美再冷，也比不上人間有弟弟的溫度。他把私人的思念，寫成了對全天下的祝福——但願人長久，千里共嬋娟。這句話原本是說給弟弟聽的，卻在一千年後，成了每個中秋節人人轉發的一句話。",
