    "poem_notes": "【字詞與白話】\n 不思量：不去刻意想。塵滿面,鬢如霜：形容面容風塵僕僕、鬢髮花白,指自己容顏衰老。短松岡：種著矮松樹的山岡,指墳地。\n 白話：十年了,一個陰間一個陽間,兩邊都茫茫然。不刻意去想,卻始終無法忘記。就算相逢了,恐怕你也認不出我——滿臉風塵,兩鬢像霜一樣白。昨夜在夢中忽然回到了故鄉,看見你正對著小軒窗梳妝打扮。兩人相見,說不出話來,只有眼淚千行流下。料想你年年最讓人肝腸寸斷的地方,就是明月照著的那片矮松山岡。\n \n 【背後的小故事】\n 蘇軾的第一任妻子王弗十六歲嫁給他,兩人感情很好,可惜二十七歲就病逝,葬在四川眉山老家,蘇軾親手在墳邊種了三萬棵松樹。十年後他在山東密州當知州,正逢仕途不順、旱災蝗災接連,某個正月二十日的夜裡忽然夢見王弗,夢裡她仍是對鏡梳妝的模樣,他卻已經滿臉風霜。醒來後他把整個夢寫成這首詞,是他悼念亡妻最有名的一篇,也是中國文學史上最著名的夢中重逢。",
