    "poem_notes": "【字詞與白話】\n 秋涼：比喻人生的起落與世態炎涼。酒賤：酒不值錢，暗指自己身分低微、門庭冷落。孤光：獨自照耀的月光，也指自己孤獨的處境。\n 白話：世上的事就像一場大夢，人的一生要經歷幾次這樣蕭索的秋涼。夜裡風吹著葉子在迴廊上作響，看看鏡中自己的眉頭鬢髮都已經蒼老。酒賣得便宜，卻常常沒有客人上門；明月雖亮，卻多半被雲遮住。中秋佳節，又有誰能陪我共賞這孤獨的月光呢，只好端著酒杯，悵然地望向北方。\n \n 【背後的小故事】\n 這闋詞相傳寫於蘇軾貶謫黃州期間的中秋夜。他因烏台詩案下獄百日，貶到黃州做沒有實權的閒官，昔日朋友多不敢往來。中秋夜他一個人喝著便宜的酒，想起遠方的弟弟蘇轍，兩人曾約定將來要一起退隱，共聽一輩子的夜雨。他舉杯向北，那個方向有他的弟弟，也有他回不去的過去。",
