    "poem_notes": "【字詞與白話】\n 老仙翁：指已故的恩師歐陽脩。龍蛇飛動：形容歐陽脩留在牆上的字跡筆勢遒勁，像龍蛇飛舞。文章太守：以文章聞名的地方官，即歐陽脩本人。\n 白話：第三次來到平山堂下，大半生的時光快得像手指彈一下。十年沒見到那位老仙翁了，牆上他留下的字跡還像龍蛇一樣飛舞著。想悼念這位以文章聞名的太守，眼前歌女仍在唱著他當年寫的楊柳詞。不要說萬事到頭來一場空，其實在還沒回頭去看之前，一切早就已經是夢了。\n \n 【背後的小故事】\n 歐陽脩是蘇軾科舉考試時的主考官，當年讀到蘇軾的文章驚為天人，一度誤以為是自己門生曾鞏所寫，為了避嫌反而把名次往下壓，後來知道真相，私下感嘆說再過三十年恐怕沒人記得自己，只記得這個年輕人。蘇軾一生視他為恩師，晚年三次經過歐陽脩所建的平山堂，最後一次是恩師過世十年之後，見牆上遺墨猶在，人已不在，寫下這首詞紀念這段跨越近三十歲差距、卻情深意重的師生緣分。",
