    "title": "定風波",
    "poem_notes": "【字詞與白話】\n 芒鞋：草鞋。「也無風雨也無晴」是全詞的核心體悟——人生的順境與逆境，走過去了其實並無分別。\n 白話：不要理會穿林打葉的雨聲，不妨一邊吟詩長嘯，一邊緩步前行。竹杖與草鞋比騎馬還要輕便，有什麼好怕的？一身蓑衣，任憑這一生的風雨。略帶寒意的春風把酒意吹醒，微微覺得冷，山頭的斜陽卻正迎面而來。回頭望向剛才風雨蕭瑟的地方，一路走回去，也無所謂風雨，也無所謂放晴。\n \n 【背後的小故事】\n 蘇軾被貶黃州第三年，某次與友人出遊途中忽遇大雨，友人狼狽躲雨，他卻拄著竹杖、穿著草鞋，在雨中從容吟詩緩行，毫不在意。雨過天晴後，他回頭望向剛才風雨交加的路，忽然體悟：無論是狂風驟雨還是斜陽相迎，走過去之後其實並無分別，重要的不是外在的順逆，而是自己如何走這條路。這份「也無風雨也無晴」的心境，陪他撐過了此後被貶惠州、儋州的更多風雨。",
