    "poem_notes": "【字詞與白話】\n 故壘：舊時的營壘。羽扇綸巾：手搖羽毛扇子、頭戴青色頭巾,形容周瑜從容儒雅的裝束。酹：把酒灑在地上表示祭奠或敬意。\n 白話：長江浩浩蕩蕩向東流去,淘盡了千古以來風流的人物。舊營壘的西邊,人們說那是三國時周瑜大破曹軍的赤壁。亂石高聳入雲,驚濤拍岸,捲起千萬堆雪一樣的浪花。江山美得像一幅畫,那個時代出了多少英雄豪傑。遙想當年周瑜,小喬剛嫁給他,他英姿煥發。手搖羽扇,頭戴綸巾,談笑之間,曹軍的戰船就在灰飛煙滅中化為烏有。我神遊在這古戰場的往事裡,該笑自己多情善感,以致過早生出滿頭白髮。人生就像一場夢,不如舉起一杯酒,祭奠這江上的明月。\n \n 【背後的小故事】\n 蘇軾因烏臺詩案被貶黃州,常到城外一座赤褐色的山崖遊覽,當地人稱它赤壁磯,但這裡其實未必是三國赤壁之戰的真正戰場——後世特地把它稱作\"文赤壁\",跟湖北另一處\"武赤壁\"分開。蘇軾站在江邊,拿自己四十多歲功業未成的處境,對比二十幾歲就統領大軍、意氣風發的周瑜,越想越覺得反差巨大。這首詞是他借著一個可能認錯的地方,把自己一生的抱負與失落全部傾倒進長江裡。",
    "zhuyin": "樽(ㄗㄨㄣ)(zūn)發音同\"尊\"，古代的酒器，常見於「酒樽」、「金樽」。\n 酹(ㄌㄟˋ)(lèi)發音同\"淚\"，將酒灑在地上，用作祭奠神靈、鬼神或先烈，亦可表示立誓。",
