    "poem_notes": "【字詞與白話】\n 章臺路：漢代長安城裡的花街，後世泛指男子尋歡作樂的地方。堆煙：形容楊柳枝葉濃密得像堆起的煙霧。亂紅：指凌亂飄落的花瓣。\n 白話：庭院一層又一層，深得數不清有幾重。楊柳濃密得像堆起的煙霧，簾幕重重疊疊。丈夫騎馬佩玉，常往花街那邊去，樓再高也看不見那條路。三月將盡的一個黃昏，風狠雨急，把院門關上，春天留也留不住。我含淚問花，花卻不回答，只有凌亂的花瓣被風吹過鞦韆架飄走了。\n \n 【背後的小故事】\n 這首詞的作者歸屬歷來有爭議，一說是歐陽脩所作，一說更接近五代詞人馮延巳的舊作，兩種說法爭論了幾百年沒有定論。詞裡寫一位被困在深宅裡、連丈夫身影都看不到的女子，對著落花無處訴說的心情。一百多年後，南宋女詞人李清照特別喜愛庭院深深深幾許這一句，接連寫了好幾首詞都用這句開頭——她未必清楚這首詞作者的爭議，但那句話，穿越了一百多年，依然打中了另一個被困在深院裡的靈魂。",
