    "title": "浣溪紗",
    "poem_notes": "【字詞與白話】\n 舊亭臺：舊時熟悉的亭台樓閣。無可奈何：沒有辦法,無法挽回。似曾相識：好像曾經見過。\n 白話：聽一支新填的詞,配一杯酒,天氣還是去年這個時候的天氣,亭台樓閣也還是舊時那些。夕陽每天都會西下,可是什麼時候才會再回來呢?花謝了,一點辦法都沒有;那燕子飛回來了,似乎是曾經見過的舊相識。我獨自一人在灑滿花香的小徑上來回徘徊。\n \n 【背後的小故事】\n 晏殊一輩子官運亨通,做到北宋宰相,詞裡卻常帶著一種說不清的空虛感。相傳\"無可奈何花落去\"這一句他自己很滿意,可是對句想了一年多都不滿意。有一次跟幕僚王琪飲酒聊天,隨口念出這句上聯求對,王琪幾乎沒想就接出\"似曾相識燕歸來\",晏殊聽了拍案叫絕,當場採用。一句話卡了一年多,另一句話一秒鐘就有了答案,兩句合在一起,精準地說中了人生裡\"留不住\"與\"繞回來\"這兩種說不清的感覺。",
