    "poem_notes": "【字詞與白話】\n 飛星傳恨：流星劃過天際，彷彿在傳遞離別的怨恨。金風玉露：秋風白露，指秋天，也借指牛郎織女七夕相會的清冷美好。朝朝暮暮：天天相聚，形容朝夕相處。\n 白話：纖薄的雲彩在天上變幻出巧妙的花樣，流星劃過彷彿在傳遞離別的怨恨，牛郎織女悄悄渡過那條遙遠的銀河相會。在秋風白露的時節裡這一次相逢，勝過人間無數次平凡的相聚。兩人的柔情像水一樣綿長，這樣的相會卻美好得像一場夢，怎麼捨得回頭看那條鵲鳥搭成的歸路。如果兩人的感情能夠長長久久，又何必在乎是不是天天都能廝守在一起呢。\n \n 【背後的小故事】\n 秦觀一生因新舊黨爭屢遭貶謫，從汴京被貶到杭州、處州，再到更偏遠的郴州，常年與家人分隔兩地。七夕牛郎織女一年一會的傳說，對旁人是浪漫故事，對他卻更像自己生活的寫照，比一年一會更常見的，是他甚至說不準下次能不能見到家人。這首詞最後兩句，是他用自己半生的離散換來的答案：距離從來不是感情的量尺。",
