    "type": "詞",
    "author": "秦觀",
    "title": "江城子-西城楊柳弄春柔",
    "poem_notes": "【字詞與白話】\n 弄春柔：在春風裡輕輕擺動，展現柔美的姿態。繫歸舟：把準備返航的船繫在岸邊，這裡指停留不走。韶華：美好的青春年華。便做：即使、就算。\n 白話：西城的柳樹在春風裡輕輕搖擺，勾起我心中離別的憂愁，眼淚怎麼也止不住。我還記得當年多情的自己，曾經在這裡把要回家的船繫在柳樹上。綠色的原野、朱紅的橋樑，還是當年那個模樣，可是那個人已經看不見了，只剩下河水白白流著。美好的青春年華，從來不會為了年輕人而特意停留，這份遺憾悠悠盪盪，不知道什麼時候才能真正結束。飛絮落花的時節，我又一次登上城樓，就算把整條春江都變成眼淚，也流不盡我心裡這麼多的愁緒。\n \n 【背後的小故事】\n 這闋詞相傳寫的是秦觀年輕時在家鄉高郵一帶的一段感情往事，詞中的橋、柳、歸舟都是具體的實景，但對象是誰，後世已難以確考。秦觀後來成為蘇軾門下的「蘇門四學士」之一，仕途一度有起色，卻在紹聖年間新舊黨爭中因與蘇軾同一陣營，被一貶再貶，從郴州、橫州一路貶到極南的雷州。徽宗即位後下詔赦還，他北歸途中病逝於藤州，終究沒能回到故鄉。這闋詞裡「便做春江都是淚，流不盡，許多愁」的少年遺憾，後來被他人生中更大的顛沛流離狠狠蓋過。",
