    "title": "雨霖铃·寒蝉凄切",
    "poem_notes": "【字詞與白話】\n 都門帳飲：在京城城門外搭起帳篷擺酒送別。蘭舟：對船隻的美稱，這裡指送別用的船。凝噎：喉嚨哽住，話說不出口。\n 白話：秋蟬叫得淒切，面對著長亭，一場驟雨剛剛停歇。在京城門外搭起帳篷擺酒送別，卻沒有心思暢飲，正依依不捨時，船伕已經催著要出發。兩人拉著手互相看著，滿眼淚水，竟一句話也說不出口，喉嚨哽咽。這一去前路千里煙波茫茫，傍晚時分楚地的天空低垂著沉沉暮靄。自古以來多情人就對離別特別傷感，何況又遇上這樣冷落淒清的秋天。今晚酒醒時人會在哪裡？大概是楊柳岸邊，面對拂曉的寒風與一彎殘月。這一去經年累月，就算遇到良辰美景，也等於虛設；就算心裡有千般情意，又能說給誰聽。\n \n 【背後的小故事】\n 柳三變年輕時愛混跡秦樓楚館，寫的詞紅遍市井，卻屢考不中，被仁宗一句話打發回去填詞，他索性自稱奉旨填詞柳三變。這首詞相傳寫在他又一次離開汴京、與心愛歌姬長亭送別的傍晚，兩人執手相看淚眼卻一句話都說不出來。他後來窮死異鄉，是幾個交好的歌妓湊錢才把他安葬。所有的千言萬語，到了分別那一刻，都變成了沉默。",
