    "poem_notes": "【字詞與白話】\n 卷簾人：捲起窗簾的丫鬟。「知否，知否？應是綠肥紅瘦」是李清照少女時代幸福生活裡細膩心思的寫照。\n 白話：昨夜雨勢稀疏、風勢急驟，沉沉睡去也沒能消去殘留的酒意。試著問正在捲簾的丫鬟，她卻說海棠花還跟昨天一樣。你知道嗎，你知道嗎？應該是綠葉更加繁茂，紅花更加凋零了呀。\n \n 【背後的小故事】\n 李清照出身書香門第，十八歲嫁給志趣相投的趙明誠，這首詞寫於她婚後生活幸福美滿的少婦時期。某夜與丈夫小酌後帶著醉意沉睡，一夜疏雨狂風都未曾察覺，隔日醒來便惦記院中海棠是否被打落，隨口一問丫鬟，得到的卻是敷衍的「海棠依舊」。她心裡明白：真正關心一朵花的人，才會留意雨後花瓣凋零、綠葉轉盛的細微變化。這份幸福時光裡才有的細膩心思，與她日後國破夫亡、獨自漂泊南宋的晚年形成強烈對比，讓這個宿醉的早晨顯得格外珍貴。",
    "zhuyin": "驟(ㄗㄡˋ)(zhòu)發音同\"奏\"，急速。",
