    "poem_notes": "【字詞與白話】\n 沉醉：飲酒到心神陶醉，忘了時間。誤入：不小心走錯或划錯方向。爭渡：奮力划槳想找到出路。\n 白話：常常記得那次在溪邊亭子裡玩到日暮時分，喝得盡興忘了回家的路。玩夠了，天色已晚才划船回去，卻不小心划進了一片密密的荷花深處。奮力划呀划，想找到出路，卻驚起了一整灘棲息的鷗鷺，撲翅飛起。\n \n 【背後的小故事】\n 李清照晚年因國破家亡、喪夫再嫁被虐等際遇，被後人記成一個寫愁的詞人。這首小令卻是她少女時期的作品。她的父親李格非治學嚴謹，卻難得地縱容女兒讀書寫詩、出門遊玩。一個微醺的傍晚，她划船划錯了方向，划進滿池荷花裡，笑著跟朋友搶槳，驚起一灘鷗鷺，這是她後來所有沈重之前，一段被父親縱容出來的自由歲月。",
