    "poem_notes": "【字詞與白話】\n 蹴罷鞦韆：盪完鞦韆下來。蹴，踏、盪的意思。襪剗：襪子沒穿好、鬆垮著。和羞走：帶著害羞的樣子跑開。\n 白話：盪完鞦韆走下來，兩隻手懶懶地不想再動，花上凝著露水，開得又嬌又瘦，她身上的薄衣已被汗水浸透。忽然看見有客人進了院子，她慌得襪子都沒穿好，頭上的金釵也鬆脫滑落，帶著羞怯就往回跑。跑到門邊卻又停下，靠著門回頭望了一眼，假裝聞著旁邊那株青梅，其實眼角悄悄瞄向來人那方。\n \n 【背後的小故事】\n 李清照少女時代住在濟南官宦人家，早慧貪玩，一次盪完鞦韆滿頭是汗，忽然有客來訪，她慌張逃回，鞋襪未穿妥、金釵鬆脫，卻又忍不住倚門回頭，假裝聞青梅偷看來人。相傳來客即是後來的丈夫趙明誠，兩人確實在相近年紀訂親，但此說並無確證。詩眼是那個又想看又不敢看的少女瞬間，一千年後讀來仍讓人會心一笑。",
