    "poem_notes": "【字詞與白話】\n 蘭舟：對小船的美稱。錦書：用錦緞織成或裝飾精美的書信，泛指書信。才下眉頭卻上心頭：愁緒剛從眉間散去，轉眼又湧上心裡，形容思念無法擺脫。\n 白話：紅色的荷花香氣已經消殘，竹蓆也添了秋涼，我輕輕解下絲裙，獨自登上小船。雲層裡有誰會為我捎來書信呢，等到大雁排成行列飛回的時候，月光正灑滿西邊的樓閣。花自顧自地飄落，水自顧自地流去，一種相思，分隔兩地，各自都添了閒愁。這種情思無法排解，剛從眉頭消散，卻又爬上了心頭。\n \n 【背後的小故事】\n 李清照與趙明誠新婚不久便常常分離，一個愛好金石書畫的伴侶，卻總是外出讀書、訪碑。相傳這首詞就寫於丈夫外出期間。她一個人划船解悶，盼著雁字傳書，盼著月滿西樓。最後兩句最動人：她想了很多辦法讓自己別再想他，好不容易皺著的眉頭鬆開，那個念頭卻已經自己搬進了心裡，一步都沒少走。",
