    "poem_notes": "【字詞與白話】\n 瑞腦金獸：瑞腦是名貴香料，金獸是獸形銅香爐，合指焚香的爐具與香氣。玉枕紗廚：玉石枕頭與紗帳，指精緻卻略顯清冷的臥室陳設。黃花：菊花。\n 白話：稀薄的霧氣、濃重的雲層，讓人整天發愁，銅獸香爐裡的名貴香料也快燒完了。又到了重陽佳節，半夜裡涼意透過玉枕紗帳襲來。在黃昏後於東邊籬笆邊飲酒賞菊，清淡的香氣沾滿了衣袖。別說這不讓人傷神，西風捲起簾子的時候，才發現自己比籬邊的菊花還要瘦。\n \n 【背後的小故事】\n 這闋詞相傳是李清照重陽節寫給外出未歸的丈夫趙明誠。相傳趙明誠收到後不服氣，自己的太太寫得比自己好，閉門三天填了五十闋詞，把妻子這首混在裡面，請友人陸德夫評賞。陸德夫看了半天，只挑出三句最好，正是李清照的莫道不銷魂，簾卷西風，人比黃花瘦。這個故事出自後人筆記，真假難考，卻說明了一件事：這對夫妻的較量裡，誰寫得更好，從來沒有懸念。",
