    "poem_notes": "【字詞與白話】\n 金猊：獅子形狀的香爐。寶奩：梳妝用的鏡匣。武陵人：借桃花源記的典故，泛指遠行離去的人。秦樓：暗用蕭史弄玉的傳說，這裡指自己所居的樓閣，也暗示孤獨清冷。\n 白話：香爐裡的香已經冷了，被子亂翻著像紅色的浪，起床也懶得梳頭。梳妝盒任它積灰，太陽已經照到簾鉤那麼高了。就怕離別的痛苦要來了，好多話想說，又說不出口。最近瘦了，不是因為喝多了酒，也不是因為秋天悲傷。罷了罷了，這一趟他終究要走，就算唱一萬遍陽關曲也留不住。想著他像武陵人一樣越走越遠，而我像被雲霧鎖住的秦樓一樣，只能守在這裡。只有樓前的流水會記得我，天天望著同一個方向，望著的地方，從此又添了一段新愁。\n \n 【背後的小故事】\n 這首詞相傳寫於李清照的丈夫趙明誠即將遠行赴任之際。兩人感情極深，一起收藏鑑賞金石書畫、共同編纂金石錄，尋常夫妻少有這樣的默契。這次分別前她連梳頭都懶得動手，連日消瘦，都是這份深情的側面證明。後來趙明誠病逝在外，李清照獨自帶著兩人畢生收藏的文物，在戰亂中輾轉逃難——回頭看這次離別，其實已是兩人所能擁有的、最溫柔的一次分離。",
