    "type": "詞",
    "author": "李清照",
    "title": "聲聲慢-尋尋覓覓",
    "poem_notes": "【字詞與白話】\n 將息：調養休息。這次第：這種情形、這般光景。怎一個愁字了得：一個愁字哪裡能概括得盡這一切。\n 白話：尋尋覓覓地想抓住點什麼，四周卻只有冷清清的空虛，心裡淒慘悲戚。忽冷忽熱的天氣裡，最難好好將養身體。喝了兩三杯淡酒，怎麼抵擋得住傍晚急促的寒風呢。大雁飛過，正讓人傷心，牠們卻是我從前就認識的老相識了。滿地的菊花堆積，枯萎凋零，如今還有誰會來採摘呢。守著窗子，獨自一人要怎麼捱到天黑。梧桐葉上又下起細雨，到了黃昏時分，一滴一滴地落著。這般光景，一個愁字哪裡說得盡。\n \n 【背後的小故事】\n 靖康之難後，李清照與趙明誠攜帶收藏的金石書畫南逃，大半散失於戰亂。趙明誠病逝後，她一度再嫁又因遭虐待告官離異，晚年孤身漂泊。這首詞裡飛過的雁，是她年輕時盼望丈夫寄信的那群雁，如今只是舊時相識；滿地的黃花，是她曾自比人比黃花瘦的那種菊，如今無人再心疼採摘。當年寫下的詩句意象，多年後全部飛回來找她算帳。",
