    "poem_notes": "【字詞與白話】\n 塵香：飄散在塵土中的落花香氣。舴艋舟：形狀像小蚱蜢一樣的小船，泛指輕巧的小船。載不動：裝載不下，形容愁緒沉重得連船都承受不了。\n 白話：風終於停了，塵土裡還飄著落花的香氣，可花已經全部凋盡，天色已晚，我連梳頭的力氣都提不起。風景依舊而人事已非，一切都完了，話還沒說出口，眼淚已經先流了下來。聽說雙溪那邊春色還很美好，我也曾想去划划小船。只怕雙溪那小小的船兒，載不動我心裡這麼多的哀愁。\n \n 【背後的小故事】\n 這首詞相傳寫於李清照避難浙江金華期間，丈夫趙明誠已病逝數年，她一路南逃，行李與心境都所剩無幾。聽人說雙溪春色正好，她難得地動了想去划船散心的念頭，轉念卻想到，自己這些年積攢的喪夫之痛、逃難之苦、文物散失之憾，恐怕連一艘小船都裝不下。她把抽象的哀愁秤出了重量，秤出來的答案是，整條雙溪都載不動。",
