    "poem_notes": "【字詞與白話】\n 人傑：人中的豪傑。鬼雄：鬼中的英雄，指死得壯烈。不肯過江東：項羽兵敗烏江，江東父老願意渡船助他逃生，他卻自覺無顏見人，寧死不渡。\n 白話：活著就該做人中的豪傑，就算死了也要做鬼中的英雄。到現在人們還在思念項羽，因為他寧可自刎，也不肯獨自逃過江東苟活。\n \n 【背後的小故事】\n 建炎三年金兵南下，時任江寧知府的趙明誠遇兵變竟連夜縋城逃跑，棄城不顧，事後被撤職，這成了他與李清照婚姻裡再也抹不去的裂痕。相傳夫妻南逃途經烏江，李清照觸景生情，想起項羽兵敗寧死不渡江東的骨氣，當著丈夫的面寫下這四句詩，一字未罵卻字字誅心。詩眼是她用古人的氣節，無聲質問身邊那個轉身逃跑的人。",
