    "author": "辛棄疾",
    "title": "青玉案-元夕",
    "poem_notes": "【字詞與白話】\n 元夕：元宵節。「眾裡尋他千百度，驀然回首，那人卻在，燈火闌珊處」是全詞最著名的一句，後世常用來比喻苦尋不得、忽然發現近在眼前。\n 白話：東風一夜之間吹開滿城如花的燈火，又像吹落漫天星雨。裝飾華美的寶馬雕車滿路飄香，鳳簫聲悠揚響起，玉壺般的明月流轉光華，一整夜魚龍花燈舞動不停。女子們頭戴蛾兒、雪柳、黃金縷的飾品，笑語盈盈地走過，留下陣陣暗香。我在人群中找了她千百遍，忽然回頭一看，那人卻站在燈火稀疏冷清的角落。\n \n 【背後的小故事】\n 辛棄疾二十二歲曾率五十騎衝入五萬金兵大營生擒叛徒，名震江南，卻此後始終未被朝廷真正重用，只能輾轉擔任地方官職。這首詞寫於南宋都城臨安一個元宵之夜，滿城燈火通明、車水馬龍，他卻在熱鬧人群中尋找一個說不清是誰的身影——那個不隨波逐流的靈魂，最終在燈火最冷清的角落找到。辛棄疾晚年被貶江西鄉間，六十八歲臨終前仍高喊「殺賊」，一生未能真正上陣殺敵北伐，但這首詞替所有在人群中格格不入、卻始終不肯隨俗的人，留下了一處安身之所。",
    "zhuyin": "縷(ㄌㄩˇ)(lǚ)發音同\"旅\"，線、麻線，量詞（計算纖細條狀物，如：一縷煙）\n 驀(ㄇㄛˋ)(mò)發音同\"末\"，忽然。\n 闌(ㄌㄢˊ)(lán)發音同\"藍\"，珊 形容燈光稀落、微暗的樣子。",
