    "title": "醜奴兒-書博山道中壁",
    "poem_notes": "【字詞與白話】\n 「少年不識愁滋味」與「而今識盡愁滋味」形成強烈對比，全詞最後以「卻道天涼好個秋」道出真正的愁苦反而說不出口。\n 白話：年少時不懂得什麼是真正的愁滋味，喜歡登上高樓。喜歡登上高樓，為了寫一首新詞，硬是要說些愁苦的話。如今真正嚐盡了愁的滋味，想說卻又說不出口。想說卻又說不出口，只好說一句「天涼了，好一個秋天啊」。\n \n 【背後的小故事】\n 辛棄疾二十二歲時曾率五十騎衝入五萬金兵大營生擒叛徒，名震一時，此後卻一生輾轉地方官職，未能真正領兵北伐。這首詞寫於他五十歲被罷官、閒居江西帶湖期間，經過博山道旁一面白牆時，隨從備好筆墨等他題字，他卻久久不能下筆。少年時為了寫詞而勉強擠出的「愁」，如今他真正嚐盡了——北方未收復、當年並肩作戰的兄弟死的死散的散，這些話堵在喉嚨裡一個字也吐不出來，最後只寫下一句顧左右而言他的「天涼好個秋」。真正的愁苦，往往連說出口的力氣都沒有了。",
