    "poem_notes": "【字詞與白話】\n 麾下炙：軍旗下分食的烤肉。的盧：一種額頭有白點、傳說會妨主的快馬，相傳曾馱劉備躍過檀溪逃生。霹靂弦驚：弓弦拉開的聲音像打雷一樣響。\n 白話：喝醉了挑亮燈芯看著寶劍，夢裡回到號角連響的軍營。八百里連營下分食著烤肉，五十弦的瑟奏出塞外的曲調，秋天的沙場上正在點兵。戰馬像的盧一樣飛奔，弓弦拉開的聲音如雷驚人。一心想替君王完成收復天下的大業，也博得生前身後的美名，可憐的是，夢醒之後，只剩自己滿頭白髮。\n \n 【背後的小故事】\n 辛棄疾早年曾單騎闖敵營擒殺叛徒張安國，名震一時，南渡後卻屢被主和派排擠，隱居帶湖近二十年，劍掛牆上無人問津。摯友陳亮來訪，兩人徹夜長談北伐壯志，別後辛棄疾寫下此詞相寄，把滿心豪情寫成一場沙場夢，卻在最後一句急轉直下，夢醒只剩白髮。詩眼是那個夢裡打贏酣暢一仗、醒來卻空無一物的巨大落差。",
