    "title": "滿江紅",
    "poem_notes": "【字詞與白話】\n 賀蘭山缺：賀蘭山的隘口，象徵北方失地。「靖康恥，猶未雪」指北宋徽、欽二帝被金兵擄走的靖康之難，是岳飛終生未能洗雪的恨事。\n 白話：滿腔怒火衝得頭髮豎起，獨自憑靠欄杆，一場急雨剛剛停歇。抬頭遠望，仰天長嘯，心中的壯志激盪難平。三十年來的功名如同塵土般微不足道，八千里征戰路途只伴著雲彩與月光。不要輕易蹉跎，等白了少年的頭髮，才徒然悲傷後悔。靖康年間的恥辱，至今仍未洗雪；作為臣子的悲憤，何時才能消滅。我要駕著戰車，踏破賀蘭山的關隘。壯志激昂時，餓了就吃敵人的肉；談笑之間，渴了就喝敵人的血。等到收復舊日山河的那一天，再重新回朝拜謁天子。\n \n 【背後的小故事】\n 岳飛率領的岳家軍令金兵聞風喪膽，但他心中始終掛念的是靖康之難中被擄往北方、從此再未歸來的徽、欽二帝。這首詞寫於他站在鄂州城樓、雨後憑欄遠眺北方的一個下午，滿腔壯志與國仇家恨一齊湧上心頭，寫下「待從頭，收拾舊山河」的誓言。可惜三十九歲那年，他被秦檜以莫須有的罪名下獄冤殺，終究沒能踏破賀蘭山、洗雪靖康之恥。八百多年後，每一個眼見不公卻無力扭轉的人，心裡都還憋著岳飛那天仰天長嘯的那口氣。",
