    "type": "詞",
    "author": "蔣捷",
    "title": "虞美人-聽雨",
    "poem_notes": "【字詞與白話】\n 星星：形容鬢髮花白稀疏，像點點星光。斷雁：離群的孤雁。僧廬：僧人居住的簡陋房舍。\n 白話：年少時在歌樓上聽雨，紅燭搖曳，羅帳低垂，身邊盡是歡笑；壯年時在漂泊的客船上聽雨，江面遼闊，雲層低垂，西風裡傳來孤雁的哀鳴；如今年老，在僧廬下聽雨，兩鬢已經花白稀疏。人生的悲歡離合終究無法挽留，也不必再多說什麼，就任由階前的雨，一滴一滴下到天亮。\n \n 【背後的小故事】\n 蔣捷生於南宋末年，考中進士沒幾年宋朝就滅亡，他終身不仕元朝，四處漂泊隱居。這首詞用一生聽過的三場雨，串起少年歌樓的浮華、壯年亂世漂泊的孤獨、老年僧廬下的心如止水，其實是把整個南宋覆滅的時代，濃縮進了同一種聲音裡。詩眼是同一場雨，年輕時只是背景音，到了老年卻成了唯一的陪伴。",
