    "author": "唐婉",
    "title": "釵頭鳳-世情薄",
    "poem_notes": "【字詞與白話】\n 世情薄，人情惡：不是感嘆世界本身壞，是她親身經歷過被拆散之後才懂，人心比想像中更薄更狠。箋：寫信、寫下來的意思。斜闌：斜靠著的欄杆。鞦韆索：形容心情像鞦韆一樣晃來晃去，穩不下來，常用來形容重病或心神不寧。瞞瞞瞞：重複三次，表示拚命隱藏、假裝沒事。\n 白話：世道太薄，人心太狠，一場雨把黃昏送來，花也跟著容易凋落。早晨的風把眼淚吹乾了，可是淚痕還留著沒完全消。想寫下滿腹心事，卻只能一個人靠在欄杆邊自言自語。難啊，難啊，難啊。人各自散了，今天已經不是從前那個今天。生病的心神常常像鞦韆一樣晃盪不定。號角聲聽起來格外冷，夜深了睡不著。怕被人問起，只能把眼淚吞下去，裝出開心的樣子。瞞著，瞞著，瞞著。\n \n 【背後的小故事】\n 唐婉是陸游的原配，兩人感情極深，卻被陸游的母親逼著和離，各自改嫁。相傳多年後兩人在紹興沈園偶然重逢，陸游在園牆上題了釵頭鳳紅酥手，唐婉見到後，依韻寫下這首世情薄作為回應。不久之後，據說她便鬱鬱而終，確切年份史書沒有留下記載。陸游活到八十五歲高齡，晚年多次重寫沈園之事，足見這段感情在他心裡從未真正放下。這兩首隔著園牆的詞，一問一答，成了中國文學史上最讓人心疼的重逢。",
