    "poem_notes": "【字詞與白話】\n 汀洲：水邊的沙洲。南樓：指武昌安遠樓，因居高臨江，宋人習稱南樓。斷磯頭：黃鶴山突出江邊的岩石渡口，斷指陡峭突出的樣子。\n 白話：蘆葦長滿了水邊的沙洲，帶著寒意的沙灘連著淺淺的水流。二十年過去了，我又重新登上南樓。柳樹下繫著船，繩子還沒繫穩，眼看沒幾天又要到中秋了。黃鶴磯頭啊，當年的老朋友還有誰來過這裡？舊時的江山還是那片江山，心裡卻裝滿了新添的憂愁。就算買來桂花、載上一船酒，也終究比不上年少時那樣痛快地出遊了。\n \n 【背後的小故事】\n 劉過一輩子沒有功名，屢試不第，布衣終老江湖，與辛棄疾、陸游等人交好。這首詞是他二十年後重遊武昌南樓，在酒席上被歌姬索詞而寫。二十年前他初到此地時還年輕，懷著考取功名的希望；二十年後故人多半不在，江山依舊，人事全非。結尾終不似、少年遊道破一個真相：錢能買酒買花，買不回那個曾經相信明天會更好的自己。",
