    "poem_notes": "【字詞與白話】\n 這首小令全篇沒有動詞（除最後一句），純用九種意象並列，被譽為「秋思之祖」。斷腸人：形容思鄉愁苦到極點的旅人。\n 白話：枯藤纏繞著老樹，樹上停著黃昏歸巢的烏鴉。小橋下流水潺潺，橋邊住著人家。荒涼古道上，西風呼嘯，一匹瘦馬緩緩前行。夕陽正緩緩西下，漂泊天涯、愁腸寸斷的遊子，還在遠方奔波。\n \n 【背後的小故事】\n 馬致遠一生輾轉各地謀生，始終未能真正得志。這首小令描繪的是他某個黃昏牽著瘦馬走在古道上，遠遠望見小橋流水人家，卻明白那不是自己的家、也回不去的心情。全曲僅用二十八個字，串起枯藤、老樹、昏鴉、小橋、流水、人家、古道、西風、瘦馬九種意象，不著一個情緒字眼，卻把天涯遊子的孤獨與鄉愁寫到了極致，被後世譽為「秋思之祖」。",
