    "poem_notes": "【字詞與白話】\n 這闋詞出自楊慎編寫的《廿一史彈詞》開場，後被毛宗崗父子收錄為《三國演義》卷首詞，因而廣為人知。\n 白話：滾滾長江向東奔流而去，浪花淘盡了古今多少英雄人物。是非成敗轉眼之間都成了空。青山依然矗立在那裡，看過了多少次夕陽的殷紅。江邊白髮蒼蒼的漁夫樵夫，早已習慣了秋月春風。一壺濁酒，欣然與老友相逢。古往今來多少大事，都化作閒談笑語之中。\n \n 【背後的小故事】\n 楊慎二十四歲高中狀元，是大明才子，卻因反對嘉靖皇帝追封生父之事，在「左順門事件」中遭受廷杖重刑，被判永久流放雲南，一去就是三十多年，父親過世也只能短暫回京奔喪。晚年他在江邊遇見一對漁夫樵夫，兩人並不知他曾是狀元，只邀他共飲一壺濁酒、閒聊家常。看著江水東流、青山依舊，他忽然明白：自己一輩子以為站在舞台中央，其實早已成了江邊看戲的旁觀者。這闋詞後來被收入《三國演義》卷首，成了千古以來最著名的開場詞。",
