    "poem_notes": "【字詞與白話】\n 齷齪：這裡不是骯髒的意思，指拘謹、侷促、不得志的處境。放蕩：這裡指心境放縱舒展，不受拘束，並非負面意思。\n 白話：以前那些拘束憋屈的日子，不值得一提；今天終於可以放縱心情，思緒無邊無際。春風得意，馬蹄踏得又輕又快，一天之內，就把整座長安城的花都看遍了。\n \n 【背後的小故事】\n 孟郊考進士考了二十幾年，屢考屢敗，日子過得拮据憋屈，幸虧一路有小他十幾歲的韓愈四處揄揚、接濟鼓勵，始終沒放棄他。四十六歲終於及第，他按捺不住多年的委屈，翻身上馬，一個下午跑遍長安看盡繁花。詩眼是二十幾年的憋屈，只用一天的縱情揮霍殆盡，那份暢快背後，其實是被人一路撐住才走到這天的辛酸。",
