    "poem_notes": "【字詞與白話】\n 德馨：品德的芳香，馨指散播很遠的香氣。鴻儒：學問淵博的大學者，白丁：沒有功名、學識淺的平民，此處泛指粗俗之人。案牘：官府的公文。\n 白話：山不在於多高，有仙人居住就有名氣。水不在於多深，有龍潛藏就有靈氣。這是間簡陋的屋子，只因我的品德而散發芳香。苔痕爬上台階一片翠綠，草色映入竹簾也是青翠。談笑往來的都是博學的人，沒有粗鄙的俗人。可以彈奏不加裝飾的琴，可以閱讀佛經。沒有嘈雜的音樂擾亂耳朵，沒有官府公文勞累身心。就像南陽諸葛亮的草廬，西蜀揚子雲的亭子。孔子說過，有什麼簡陋的呢。\n \n 【背後的小故事】\n 相傳劉禹錫被貶到和州當刺史時，被當地知縣故意刁難，住處從三間屋一路被縮減到只剩一間半的小屋。他沒有抗爭，找石匠刻了這篇銘文立在門前明志。當時他心裡其實還記掛著另一件事，摯友柳宗元819年病逝前，把遺稿和孩子都託付給他，他一直在幫忙照應。一個被逼到半間屋子的人，心裡裝著的責任，比誰的房子都大，惟吾德馨四個字，就是他給那個刁難他的知縣最漂亮的回答。",
